// Define a structure to hold the thread-safe memory pool
typedef struct {
    int size;
    char **data;
} mempool_t;

void parse_input(const char *filename, const char *output_filename) {
    // Open the input file for reading and create an output file for writing
    FILE *in = fopen(filename, "r");
    FILE *out = fopen(output_filename, "w");

    if (!in || !out) {
        // Handle I/O error gracefully
        perror("Error opening input or output file");
        return;
    }

    // Initialize the memory pool with a default size of 1MB
    mempool_t *mempool = (mempool_t *)malloc(sizeof(mempool_t));
    mempool->size = 1024*1024;
    mempool->data = (char **)malloc(mempool->size * sizeof(char *));

    // Read the input file in chunks and parse its contents
    while (!feof(in)) {
        char *buf = malloc(sizeof(char) * 1024);
        size_t len = fread(buf, 1, 1024, in);

        // If the buffer is full, allocate a new memory pool with twice the size
        if (len == 1024) {
            mempool->size *= 2;
            mempool->data = (char **)realloc(mempool->data, mempool->size * sizeof(char *));
        }

        // Parse the contents of the buffer and write to the output file
        for (int i = 0; i < len; i++) {
            char c = buf[i];
            if (c == ' ') {
                continue;
            } else if (c >= 'a' && c <= 'z') {
                // Apply the transformation rules to the current character
                for (int j = 0; j < mempool->size; j++) {
                    char *ptr = mempool->data[j];
                    if (!ptr) {
                        continue;
                    }
                    fwrite(ptr, strlen(ptr), 1, out);
                }
            } else {
                // Write the current character to the output file as is
                fputc(c, out);
            }
        }

        free(buf);
    }

    // Close the input and output files
    fclose(in);
    fclose(out);
}

