    const char *output_filename = argv[2];
    const char *rules = argv[3];
    int parallel = atoi(argv[4]);
    size_t threshold = atoi(argv[5]);

    // Initialize the transformation rules and their corresponding functions
    rule_t rules[] = {
        {"rule1", apply_transformation1},
        {"rule2", apply_transformation2},
        {"rule3", apply_transformation3}
    };

    // Check if the input file size exceeds a certain limit and switch to batch processing mode if necessary
    struct stat st;
    stat(input_filename, &st);
    long filesize = st.st_size;
    if (filesize > 20*1024*1024) { // 20GB limit
        parallel = false;
    }

    if (parallel) {
        // Divide the input file into segments smaller than the specified threshold size
        int num_segments = filesize / threshold;
        char **segments = (char **)malloc(num_segments * sizeof(char *));

        // Create a thread-safe memory pool for each segment
        mempool_t *mempools = (mempool_t *)malloc(num_segments * sizeof(mempool_t));
        for (int i = 0; i < num_segments; i++) {
            segments[i] = malloc(threshold);
            mempools[i].size = threshold;
            mempools[i].data = (char **)malloc(mempools[i].size * sizeof(char *));
        }

        // Create a semaphore to synchronize access to the memory pool
        sem_t *sem = sem_open("mempool", O_CREAT, 0644, num_segments);
        if (sem == SEM_FAILED) {
            perror("Error creating semaphore");
            return 1;
        }

        // Create a thread for each segment and apply the transformation rules
        pthread_t threads[num_segments];
        for (int i = 0; i < num_segments; i++) {
            int err = pthread_create(&threads[i], NULL, thread_func, &segments[i]);
            if (err) {
                perror("Error creating thread");
                return 1;
            }
        }

        // Wait for all threads to complete and merge the output files
        for (int i = 0; i < num_segments; i++) {
            pthread_join(threads[i], NULL);
        }
        sem_close(sem);
    } else {
        // Apply the transformation rules in a single thread
        parse_input(input_filename, output_filename);
    }

    return 0;
}
