#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/types.h>
#include <unistd.h>
#include <syslog.h>
#include <errno.h>
#include <limits.h>

#define LOG_LEVELS (6)

// Logging levels
typedef enum {
  LOG_TRACE = 0,
  LOG_DEBUG = 1,
  LOG_INFO = 2,
  LOG_WARN = 3,
  LOG_ERROR = 4,
  LOG_FATAL = 5
} LogLevel;

// Message format
typedef enum {
  FORMAT_DEFAULT = 0,
  FORMAT_JSON = 1,
  FORMAT_CUSTOM = 2
} LogFormat;

// Logging targets
typedef enum {
  TARGET_CONSOLE = 0,
  TARGET_FILE = 1,
  TARGET_SYSLOG = 2
} LogTarget;

// External logging configuration file
#include "logging_config.h"

// Thread-safe buffer for message formatting and storage
typedef struct {
  char *message;
  size_t length;
} MessageBuffer;

MessageBuffer messageBuffers[LOG_LEVELS];

// Function to log a message at the specified level
void log(LogLevel level, const char* format, ...) {
  // Check if the current thread is holding a lock on the buffer
  // If not, acquire one and release it after formatting the message
  int acquiredLock = 0;
  if (pthread_mutex_trylock(&messageBuffers[level].mutex) != 0) {
    acquiredLock = 1;
    pthread_mutex_lock(&messageBuffers[level].mutex);
  }

  // Format the message according to the specified format and level
  char buffer[4096];
  va_list args;
  va_start(args, format);
  vsnprintf(buffer, sizeof(buffer), format, args);
  va_end(args);

  // Store the formatted message in the appropriate buffer for the level
  MessageBuffer *messageBuffer = &messageBuffers[level];
  size_t length = strlen(buffer);
  if (length > messageBuffer->length) {
    // Reallocate memory to ensure there is enough space for the message
    char *newMessage = realloc(messageBuffer->message, length + 1);
    if (newMessage == NULL) {
      perror("Failed to allocate memory for log message");
      return;
    }
    messageBuffer->message = newMessage;
    messageBuffer->length = length + 1;
  }
  strcpy(messageBuffer->message, buffer);

  // Release the lock if it was acquired earlier
  if (acquiredLock) {
    pthread_mutex_unlock(&messageBuffers[level].mutex);
  }
}

// Function to flush all buffers and write their contents to the logging targets
void flushLogs() {
  // Acquire locks on each buffer to ensure thread-safe access
  for (int i = 0; i < LOG_LEVELS; ++i) {
    pthread_mutex_lock(&messageBuffers[i].mutex);
  }

  // Write the contents of each buffer to the appropriate logging target
  for (int i = 0; i < LOG_LEVELS; ++i) {
    switch (LOGGING_TARGET) {
      case TARGET_CONSOLE:
        printf("%s\n", messageBuffers[i].message);
        break;
      case TARGET_FILE:
        fprintf(stdout, "%s\n", messageBuffers[i].message);
        break;
      case TARGET_SYSLOG:
        syslog(LOG_INFO, "%s", messageBuffers[i].message);
        break;
    }
  }

  // Release locks on each buffer
  for (int i = 0; i < LOG_LEVELS; ++i) {
    pthread_mutex_unlock(&messageBuffers[i].mutex);
  }
}
