import time
from collections import defaultdict

def process_log_file(file_path):
    start_time = time.time()
    unique_errors = set()
    error_frequencies = defaultdict(int)
    error_messages = []
    with open(file_path, "r") as log_file:
        for line in log_file:
            if "ERROR" in line:
                error_message = line.split("]")[1].strip()
                unique_errors.add(error_message)
                error_frequencies[error_message] += 1
                error_messages.append((error_message, line))
    end_time = time.time()
    print(f"Processed {len(unique_errors)} unique errors in {end_time - start_time:.2f} seconds")
    return {"unique_errors": unique_errors, "error_frequencies": error_frequencies, "error_messages": error_messages}

def filter_common_errors(error_dict):
    common_errors = ["Connection refused", "No such file or directory"]
    filtered_errors = {}
    for error, frequency in error_dict.items():
        if error not in common_errors:
            filtered_errors[error] = frequency
    return filtered_errors

def categorize_errors(error_dict):
    error_categories = {"Database connection": [], "File system errors": []}
    for error, message in error_dict.items():
        if "Database" in message:
            error_categories["Database connection"].append((error, message))
        elif "file" in message or "filesystem" in message:
            error_categories["File system errors"].append((error, message))
    return error_categories

def identify_patterns(error_messages):
    patterns = {}
    for error, messages in error_messages.items():
        pattern = [m.split("]")[1].strip() for m in messages]
        if len(set(pattern)) == 1:
            patterns[error] = pattern[0]
        else:
            patterns[error] = " ".join(sorted(set(pattern)))
    return patterns

def main():
    error_dict = process_log_file("large_log_file.txt")
    filtered_errors = filter_common_errors(error_dict)
    categorized_errors = categorize_errors(filtered_errors)
    patterns = identify_patterns(categorized_errors)
    print(f"Unique errors: {len(error_dict['unique_errors'])}")
    print(f"Frequent errors: {len(error_dict['error_frequencies'])}")
    print(f"Error patterns: {len(patterns)}")
    for error, pattern in sorted(patterns.items(), key=lambda x: x[1]):
        print(f"{error}: {pattern}")

if __name__ == "__main__":
    main()
']

