public class PokemonCompatibility {
    private static final Map<String, List<String>> TYPE_WEAKNESS = new HashMap<>();
    private static final Map<String, List<String>> TYPE_ADVANTAGE = new HashMap<>();
    private static final Map<String, Integer> TEAM_COMPATIBILITY = new HashMap<>();

    public static void init() {
        // Initialize type weakness and advantage maps
        TYPE_WEAKNESS.put("Fire", List.of("Water"));
        TYPE_WEAKNESS.put("Water", List.of("Fire"));
        TYPE_ADVANTAGE.put("Fire", List.of("Grass"));
        TYPE_ADVANTAGE.put("Water", List.of("Fire"));
    }

    public static String getPokemonName(Pokemon pokemon) {
        return pokemon.getName();
    }

    public static CompatibilityReport evaluateCompatibility(Pokemon pokemon, List<Pokemon> team) {
        // Retrieve the Pokemon's name using a reliable library function
        String name = getPokemonName(pokemon);

        // Determine the weaknesses and advantages using a dynamic algorithm that accounts for updates to the Pokemon's type data
        List<String> weaknesses = TYPE_WEAKNESS.getOrDefault(name, new ArrayList<>());
        List<String> advantages = TYPE_ADVANTAGE.getOrDefault(name, new ArrayList<>());

        // Implement a custom compatibility evaluation algorithm that considers not only the Pokemon's individual strengths and weaknesses but also potential team synergies
        int totalCompatibility = 0;
        for (Pokemon member : team) {
            String memberName = getPokemonName(member);
            if (weaknesses.contains(memberName)) {
                totalCompatibility -= 10;
            } else if (advantages.contains(memberName)) {
                totalCompatibility += 10;
            }
        }

        // Handle cases where the Pokemon type is unknown or invalid gracefully, providing a default message and logging the issue for further analysis
        if (totalCompatibility == 0) {
            return new CompatibilityReport("Unknown Type", "This Pokemon's type could not be determined.");
        } else if (totalCompatibility < 0) {
            return new CompatibilityReport("Weaknesses", "This Pokemon has weaknesses against some members of the team.");
        } else if (totalCompatibility > 0) {
            return new CompatibilityReport("Advantages", "This Pokemon has advantages against some members of the team.");
        } else {
            return new CompatibilityReport("Balanced", "This Pokemon has a balanced compatibility with the team.");
        }
    }
}
