['```c
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define struct for semaphore management
typedef struct {
    int value; // Current value of the semaphore
    bool acquired; // Indicates whether the semaphore is currently held
    pthread_mutex_t mutex; // Mutex to protect access to the semaphore
} Semaphore;

// Define struct for semaphore pool management
typedef struct {
    Semaphore *semaphores; // Array of semaphores in the pool
    int num_semaphores; // Number of semaphores in the pool
    pthread_mutex_t mutex; // Mutex to protect access to the pool
} SemaphorePool;

// Define global variables for logging and error handling
bool log_enabled = true; // Flag to enable/disable logging
FILE *log_file = NULL; // File handle for logging output

// Function to create a new semaphore in the pool
Semaphore* create_semaphore(int value) {
    Semaphore *new_semaphore = (Semaphore*) malloc(sizeof(Semaphore));
    if (new_semaphore == NULL) {
        // Log error message and return NULL on failure
        printf("Failed to create new semaphore: Out of memory\n");
        return NULL;
    }

    new_semaphore->value = value;
    new_semaphore->acquired = false;
    pthread_mutex_init(&new_semaphore->mutex, NULL);

    // Log semaphore creation event and return the new semaphore
    if (log_enabled) {
        char log_message[1024];
        sprintf(log_message, "Semaphore created with value %d\n", value);
        fputs(log_message, log_file);
    }
    return new_semaphore;
}

// Function to delete a semaphore from the pool
void delete_semaphore(Semaphore *semaphore) {
    if (semaphore == NULL) {
        // Log error message and return on failure
        printf("Failed to delete semaphore: Invalid input\n");
        return;
    }

    pthread_mutex_destroy(&semaphore->mutex);
    free(semaphore);

    // Log semaphore deletion event
    if (log_enabled) {
        char log_message[1024];
        sprintf(log_message, "Semaphore deleted\n");
        fputs(log_message, log_file);
    }
}

// Function to acquire a semaphore in the pool
bool acquire_semaphore(SemaphorePool *pool, int index) {
    Semaphore *semaphore = &pool->semaphores[index];
    if (semaphore == NULL) {
        // Log error message and return false on failure
        printf("Failed to acquire semaphore: Invalid input\n");
        return false;
    }

    pthread_mutex_lock(&semaphore->mutex);
    if (semaphore->value <= 0) {
        // Log error message and unlock mutex on failure
        printf("Failed to acquire semaphore: Value is less than or equal to zero\n");
        pthread_mutex_unlock(&semaphore->mutex);
        return false;
    }

    semaphore->value--;
    semaphore->acquired = true;

    // Log semaphore acquisition event
    if (log_enabled) {
        char log_message[1024];
        sprintf(log_message, "Semaphore acquired at index %d\n", index);
        fputs(log_message, log_file);
    }

    pthread_mutex_unlock(&semaphore->mutex);
    return true;
}

// Function to release a semaphore in the pool
bool release_semaphore(SemaphorePool *pool, int index) {
    Semaphore *semaphore = &pool->semaphores[index];
    if (semaphore == NULL) {
        // Log error message and return false on failure
        printf("Failed to release semaphore: Invalid input\n");
        return false;
    }

    pthread_mutex_lock(&semaphore->mutex);
    if (!semaphore->acquired) {
        // Log error message and unlock mutex on failure
        printf("Failed to release semaphore: Semaphore is not acquired\n");
        pthread_mutex_unlock(&semaphore->mutex);
        return false;
    }

    semaphore->value++;
    semaphore->acquired = false;

    // Log semaphore release event
    if (log_enabled) {
        char log_message[1024];
        sprintf(log_message, "Semaphore released at index %d\n", index);
        fputs(log_message, log_file);
    }

    pthread_mutex_unlock(&semaphore->mutex);
    return true;
}

// Function to add a new semaphore to the pool
bool add_semaphore(SemaphorePool *pool, int value) {
    // Check if the pool is full before adding a new semaphore
    if (pool->num_semaphores >= pool->max_semaphores) {
        // Log error message and return false on failure
        printf("Failed to add semaphore: Pool is full\n");
        return false;
    }

    // Create a new semaphore with the specified value
    Semaphore *new_semaphore = create_semaphore(value);
    if (new_semaphore == NULL) {
        // Log error message and return false on failure
        printf("Failed to add semaphore: Out of memory\n");
        return false;
    }

    // Add the new semaphore to the pool
    pool->semaphores[pool->num_semaphores++] = new_semaphore;

    // Log semaphore addition event
    if (log_enabled) {
        char log_message[1024];
        sprintf(log_message, "Semaphore added with value %d\n", value);
        fputs(log_message, log_file);
    }

    return true;
}

// Function to remove a semaphore from the pool
bool remove_semaphore(SemaphorePool *pool, int index) {
    // Check if the specified index is valid before removing a semaphore
    if (index >= pool->num_semaphores || index < 0) {
        // Log error message and return false on failure
        printf("Failed to remove semaphore: Invalid index\n");
        return false;
    }

    // Remove the semaphore from the pool
    delete_semaphore(pool, index);

    // Log semaphore removal event
    if (log_enabled) {
        char log_message[1024];
        sprintf(log_message, "Semaphore removed at index %d\n", index);
        fputs(log_message, log_file);
    }

    return true;
}
```

This is a simple implementation of a semaphore pool using mutexes. The `acquire` and `release` functions are used to lock and unlock the specified semaphore in the pool. The `add` and `remove` functions are used to add and remove semaphores from the pool. The `max_semaphores` variable is used to set the maximum number of semaphores that can be added to the pool, and the `num_semaphores` variable is used to track the current number of semaphores in the pool.

You can use this pool to implement a system where multiple threads can access a shared resource by acquiring a semaphore before accessing it, and then releasing the semaphore once they are finished. This will ensure that only one thread can access the resource at a time, which can help prevent race conditions.

For example:
```
SemaphorePool pool;
pool.max_semaphores = 10;
pool.num_semaphores = 0;

// Add semaphores to the pool
for (int i = 0; i < 5; i++) {
    pool.add(1);
}

// Acquire a semaphore from the pool
if (pool.acquire(3)) {
    // Use the shared resource
    // ...

    // Release the semaphore back to the pool
    pool.release(3);
}
```']

