```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;

public class CustomRequestQueue
{
    private readonly HttpClient _client = new HttpClient();
    private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(0, int.MaxValue);
    private readonly Queue<HttpRequestMessage> _queue = new Queue<HttpRequestMessage>();
    private readonly HashSet<string> _urls = new HashSet<string>();
    private readonly Dictionary<string, HttpResponseMessage> _responses = new Dictionary<string, HttpResponseMessage>();

    public CustomRequestQueue(int maxConcurrency)
    {
        _client.DefaultRequestHeaders.Accept.Clear();
        _client.DefaultRequestHeaders.Accept.Add(new MediaTypeWithQualityHeaderValue("application/json"));
        _semaphore = new SemaphoreSlim(maxConcurrency, int.MaxValue);
    }

    public async Task<IEnumerable<CustomResponse>> EnqueueAsync(List<string> urls)
    {
        foreach (var url in urls)
        {
            if (_urls.Contains(url)) continue;
            _urls.Add(url);
            var request = new HttpRequestMessage(HttpMethod.Get, url);
            _queue.Enqueue(request);
        }

        return await ProcessQueueAsync();
    }

    private async Task<IEnumerable<CustomResponse>> ProcessQueueAsync()
    {
        while (_queue.Count > 0)
        {
            var request = _queue.Dequeue();
            using (var cancellationTokenSource = new CancellationTokenSource())
            {
                try
                {
                    await _semaphore.WaitAsync(cancellationTokenSource.Token);
                    if (_responses.ContainsKey(request.RequestUri.AbsolutePath))
                    {
                        continue;
                    }
                    var response = await _client.SendAsync(request, HttpCompletionOption.ResponseHeadersRead);
                    if (response.IsSuccessStatusCode)
                    {
                        var content = await response.Content.ReadAsStringAsync();
                        _responses.Add(request.RequestUri.AbsolutePath, response);
                    }
                    else
                    {
                        LogError($"Failed to process request: {request.RequestUri.AbsolutePath}", response.StatusCode);
                    }
                }
                catch (Exception ex) when (!(ex is OperationCanceledException))
                {
                    LogError($"Failed to process request: {request.RequestUri.AbsolutePath}", ex.Message);
                }
                finally
                {
                    _semaphore.Release();
                }
            }
        }

        return _responses.Select(r => new CustomResponse()
        {
            Url = r.Key,
            StatusCode = r.Value.StatusCode,
            Content = r.Value.Content.ReadAsStringAsync().Result.Substring(0, 100)
        });
    }

    private void LogError(string url, HttpStatusCode statusCode)
    {
        Console.WriteLine($"Failed to process request: {url} - Status Code: {statusCode}");
    }

    private void LogError(string url, string message)
    {
        Console.WriteLine($"Failed to process request: {url} - Error Message: {message}");
    }

    public class CustomResponse
    {
        public string Url { get; set; }
        public HttpStatusCode StatusCode { get; set; }
        public string Content { get; set; }
    }
}
```

This code block implements a custom request queue that can handle high-throughput scenarios and provide efficient processing of asynchronous HTTP requests. The `CustomRequestQueue` class has the following features:

* It uses a `HttpClient` instance to send HTTP requests asynchronously.
* It uses a `SemaphoreSlim` object to manage concurrency and prevent resource exhaustion.
* It maintains a queue of pending requests, which are processed one at a time to ensure that no two requests are sent simultaneously.
* It stores the responses for each URL in a dictionary to reduce the number of duplicate requests.
* It logs any errors or exceptions encountered during request processing.
* It provides a `ProcessQueueAsync` method that processes the pending requests in the queue one at a time, and returns a collection of results for each processed request.

The `CustomResponse` class is used to store the results of each processed request. The `Url`, `StatusCode`, and `Content` properties are used to represent the URL, HTTP status code, and response content, respectively.

This implementation makes trade-offs between the speed of request handling and the accuracy of logging to ensure that the system performs well under all conditions. It prioritizes efficiency in processing requests and managing concurrency, while also providing a robust mechanism for logging errors and exceptions.']

