function userAccountManagement($_REQUEST) {
    // validate request data
    $name = $_REQUEST['name'];
    $email = $_REQUEST['email'];
    $password = $_REQUEST['password'];
    $sub_action = isset($_REQUEST['sub_action']) ? $_REQUEST['sub_action'] : null;
    $id = isset($_REQUEST['id']) ? $_REQUEST['id'] : null;

    // handle case where neither sub_action nor id are present
    if (!$sub_action && !$id) {
        return createUserAccount($name, $email, $password);
    }

    // handle update operation
    if ($sub_action == 'update') {
        if ($id) {
            return updateUserAccount($id, $name, $email, $password);
        } else {
            return createUserAccount($name, $email, $password);
        }
    }

    // handle delete operation
    if ($sub_action == 'delete') {
        if ($id) {
            return deleteUserAccount($id);
        } else {
            return errorMessage('Invalid request: missing ID');
        }
    }

    // handle invalid sub_action value
    if (!in_array($sub_action, ['update', 'delete'])) {
        return errorMessage('Invalid sub_action value: ' . $sub_action);
    }
}

function createUserAccount($name, $email, $password) {
    // validate data
    if (!validateName($name)) {
        return errorMessage('Invalid name');
    }
    if (!validateEmail($email)) {
        return errorMessage('Invalid email');
    }
    if (!validatePassword($password)) {
        return errorMessage('Invalid password');
    }

    // create user account
