    if (!$user) {
        return errorMessage('User not found');
    }

    // update user account
    $user->name = $name;
    $user->email = $email;
    $user->password = hash_password($password);

    // save user to database
    try {
        $user->save();
    } catch (Exception $e) {
        return errorMessage('Failed to update user account: ' . $e->getMessage());
    }

    return successMessage('User account updated successfully');
}

function deleteUserAccount($id) {
