const renderFooterScripts = (scripts) => {
  const html = [];

  // Defer non-critical scripts and prioritize critical ones
  scripts.sort((a, b) => (a.type === 'text/javascript' ? -1 : b.type === 'text/javascript' ? 1 : 0));

  // Generate HTML for each script
  html.push('<script data-key="', scripts[i].key, '" src="', scripts[i].sourceUrl || '', '" type="', scripts[i].type || 'text/javascript', '"></script>');

  return html.join('');
};
