function refreshDialogFields(resourceIds, urlMapping) {
  // Initialize a forward list to manage the list of resource IDs to refresh
  const resourceIdList = new ForwardList();

  // Iterate through all dialog fields and check if each field's resource ID exists in the provided list
  for (const field of dialogFields) {
    const fieldId = field.resourceId;
    const url = urlMapping[fieldId];

    // If the field's resource ID is in the list, send a request to the corresponding URL and wait for a response
    if (resourceIdList.contains(fieldId)) {
      fetch(url)
        .then((response) => response.json())
        .then((data) => {
          // Update the field's value with the received data
          field.value = data;
        })
        .catch((error) => {
          console.log(`Error refreshing dialog field: ${fieldId}`);
          // Log the status of each request for debugging purposes
          resourceIdList.add(fieldId);
        });
    } else {
      // Add the field's resource ID to the list if it is not already present
      resourceIdList.add(fieldId);
    }
  }

  // Clear the list of resource IDs to refresh dynamically during runtime
  function clearResourceIdsToRefresh() {
    resourceIdList.clear();
  }
}
