import java.util.*;
import java.time.*;

class AnomalyDetection {
    private static final int BUFFER_SIZE = 100; // adjust as needed
    private static final Duration MIN_ANOMALY_WINDOW = Duration.ofMinutes(30);

    public static void main(String[] args) throws InterruptedException {
        List<LogEntry> logEntries = new ArrayList<>();
        Map<Long, UserActivity> userActivities = new HashMap<>();

        // simulate incoming log entries from a continuous stream
        for (int i = 0; i < 1000; i++) {
            long timestamp = System.currentTimeMillis();
            int userId = ThreadLocalRandom.current().nextInt(1, 100);

            LogEntry logEntry = new LogEntry(timestamp, userId);
            logEntries.add(logEntry);

            UserActivity userActivity = userActivities.getOrDefault(userId, new UserActivity());
            userActivity.addLogEntry(logEntry);
            userActivities.put(userId, userActivity);
        }

        // process the log entries and identify potential anomalies
        for (LogEntry logEntry : logEntries) {
            long processingTime = System.currentTimeMillis() - logEntry.getTimestamp();

            int userId = logEntry.getUserId();
            UserActivity userActivity = userActivities.get(userId);

            if (userActivity != null && !userActivity.hasConsecutiveAnomalies()) {
                boolean isAnomaly = false;

                for (LogEntry previousLogEntry : userActivity.getPreviousLogEntries()) {
                    Duration durationSincePrevious = Duration.between(previousLogEntry.getTimestamp(), logEntry.getTimestamp());

                    if (durationSincePrevious.compareTo(MIN_ANOMALY_WINDOW) < 0) {
                        isAnomaly = true;
                        break;
                    }
                }

                if (isAnomaly) {
                    System.out.println("Potential anomaly detected: " + logEntry);
                } else {
                    userActivity.addLogEntry(logEntry);
                }
            } else {
                userActivities.put(userId, new UserActivity(logEntry));
            }
        }
    }
}

class LogEntry {
    private long timestamp;
    private int userId;

    public LogEntry(long timestamp, int userId) {
        this.timestamp = timestamp;
        this.userId = userId;
    }

    public long getTimestamp() {
        return timestamp;
    }

    public int getUserId() {
        return userId;
    }
}

class UserActivity {
    private List<LogEntry> previousLogEntries = new ArrayList<>();
    private boolean hasConsecutiveAnomalies = false;

    public UserActivity(LogEntry logEntry) {
        this.previousLogEntries.add(logEntry);
    }

    public void addLogEntry(LogEntry logEntry) {
        previousLogEntries.add(logEntry);
        hasConsecutiveAnomalies = false;
    }

    public boolean hasConsecutiveAnomalies() {
        return hasConsecutiveAnomalies;
    }

    public List<LogEntry> getPreviousLogEntries() {
        return previousLogEntries;
    }
}
