package theme_caching;

import java.io.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * Manages theme caching for a mobile application.
 */
public class ThemeCaching {
    private static final String DEFAULT_THEME_DIR = "default-theme-dir";
    private static final int MAX_CONCURRENT_PARSING = 5;
    private static final long RECYCLING_THRESHOLD = 1024 * 1024 * 5; // 5 MB

    private ConcurrentHashMap<String, Theme> themes;
    private ExecutorService parsingExecutor;

    public ThemeCaching() {
        this.themes = new ConcurrentHashMap<>();
        this.parsingExecutor = Executors.newFixedThreadPool(MAX_CONCURRENT_PARSING);
    }

    /**
     * Recycles a theme bitmap if it is below the recycling threshold.
     * @param theme The theme to recycle.
     */
    private void recycleThemeBitmap(Theme theme) {
        long usedMemory = Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory();
        if (usedMemory > RECYCLING_THRESHOLD && !theme.isDirty()) {
            theme.recycleBitmap();
        }
    }

    /**
     * Returns the theme with the given name, or null if it does not exist.
     * @param name The name of the theme to retrieve.
     * @return The theme with the given name, or null if it does not exist.
     */
    public Theme getTheme(String name) {
        return themes.get(name);
    }

    /**
     * Adds a new theme to the cache and returns it. If a theme with the same name already exists, it is returned instead.
     * @param name The name of the new theme.
     * @return The newly created theme, or the existing theme with the given name.
     */
    public Theme addTheme(String name) {
        Theme theme = themes.get(name);
        if (theme == null) {
            theme = new Theme(name);
            themes.put(name, theme);
        }
        return theme;
    }

    /**
     * Removes a theme from the cache and recycles its bitmap if necessary.
     * @param name The name of the theme to remove.
     */
    public void removeTheme(String name) {
        Theme theme = themes.remove(name);
        if (theme != null) {
            recycleThemeBitmap(theme);
        }
    }

    /**
     * Asynchronously parses a PNG file located in the cache root directory and adds it to the cache as a new theme.
     * @param file The PNG file to parse.
     */
    public void asyncParsePngFile(File file) {
        parsingExecutor.execute(() -> {
            try {
                Theme theme = addTheme(file.getName());
                theme.parseBitmap(file);
            } catch (IOException e) {
                // Handle error
            }
        });
    }

    /**
     * Sets the default theme directory to the specified value, if it is not null or empty.
     * @param dir The new default theme directory.
     */
    public void setDefaultThemeDir(String dir) {
        if (dir != null && !dir.isEmpty()) {
            DEFAULT_THEME_DIR = dir;
        }
    }

    /**
     * Returns the current default theme directory, or null if it has not been set.
     * @return The current default theme directory, or null if it has not been set.
     */
    public String getDefaultThemeDir() {
        return DEFAULT_THEME_DIR;
    }
}

/**
 * A theme in the cache, with a name and a bitmap representation.
 */
class Theme {
    private final String name;
    private Bitmap bitmap;
    private boolean dirty;

    public Theme(String name) {
        this.name = name;
    }

    /**
     * Returns the name of the theme.
     * @return The name of the theme.
     */
    public String getName() {
        return name;
    }

    /**
     * Returns the bitmap representation of the theme, or null if it has not been set.
     * @return The bitmap representation of the theme, or null if it has not been set.
     */
    public Bitmap getBitmap() {
        return bitmap;
    }

    /**
     * Sets the bitmap representation of the theme to the specified value.
     * @param bitmap The new bitmap representation of the theme.
     */
    public void setBitmap(Bitmap bitmap) {
        this.bitmap = bitmap;
        dirty = true;
    }

    /**
     * Recycles the bitmap representation of the theme if it is not null.
     */
    public void recycleBitmap() {
        if (bitmap != null) {
            bitmap.recycle();
            bitmap = null;
        }
    }

    /**
     * Returns whether the theme has been modified and needs to be saved to disk.
     * @return Whether the theme has been modified and needs to be saved to disk.
     */
    public boolean isDirty() {
        return dirty;
    }

    /**
     * Sets whether the theme has been modified and needs to be saved to disk to the specified value.
     * @param dirty Whether the theme has been modified and needs to be saved to disk.
     */
    public void setDirty(boolean dirty) {
        this.dirty = dirty;
    }
}']

