import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class Service {
    private static final int MAX_CONCURRENT_REQUESTS = 20;
    private static final int CONFIGURATION_POLLING_INTERVAL = 10; // seconds
    private static final int GRACEFUL_SHUTDOWN_TIMEOUT = 60; // seconds

    private ScheduledExecutorService executor;
    private Configuration configuration;
    private RequestHandler requestHandler;

    public Service() {
        executor = Executors.newScheduledThreadPool(MAX_CONCURRENT_REQUESTS);
        requestHandler = new RequestHandler();
    }

    public void start() {
        configuration = fetchConfiguration();
        updateRequestHandlerWithConfiguration();

        executor.scheduleAtFixedRate(() -> {
            try {
                updateConfiguration();
            } catch (Exception e) {
                // handle error
            }
        }, CONFIGURATION_POLLING_INTERVAL, CONFIGURATION_POLLING_INTERVAL, TimeUnit.SECONDS);
    }

    public void stop() {
        executor.shutdown();

        try {
            executor.awaitTermination(GRACEFUL_SHUTDOWN_TIMEOUT, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            // handle error
        }
    }

    private void updateConfiguration() {
        configuration = fetchConfiguration();
        updateRequestHandlerWithConfiguration();
    }

    private Configuration fetchConfiguration() {
        // fetch configuration from external API
    }

    private void updateRequestHandlerWithConfiguration() {
        requestHandler.setMaxConcurrentRequests(configuration.getMaxConcurrentRequests());
    }

    public void handleRequest(String request) {
        executor.execute(() -> requestHandler.handleRequest(request));
    }
}

class Configuration {
    private int maxConcurrentRequests;

    public Configuration(int maxConcurrentRequests) {
        this.maxConcurrentRequests = maxConcurrentRequests;
    }

    public int getMaxConcurrentRequests() {
        return maxConcurrentRequests;
    }
}

class RequestHandler {
    private int maxConcurrentRequests;
    private Queue<String> requestsQueue;

    public RequestHandler(int maxConcurrentRequests) {
        this.maxConcurrentRequests = maxConcurrentRequests;
        requestsQueue = new LinkedList<>();
    }

    public void handleRequest(String request) {
        // handle request
    }
}
