["```
async function generatePEMCertificate(oauthRequest) {
  // Parse the OAuth request to determine the paths to the private key and certificate files
  const { privateKeyPath, certificatePath } = oauthRequest;

  // Create a buffer to store the collected data from the network stream
  let buffer = [];

  // Set up asynchronous read operations for the private key and certificate files
  const readPrivateKey = fs.createReadStream(privateKeyPath).on('data', chunk => {
    buffer.push(chunk);
  }).on('error', error => {
    console.log(`Error reading private key: ${error}`);
  });
  const readCertificate = fs.createReadStream(certificatePath).on('data', chunk => {
    buffer.push(chunk);
  }).on('error', error => {
    console.log(`Error reading certificate: ${error}`);
  });

  // Handle potential errors and timeouts by checking for the presence of data in the buffer
  readPrivateKey.pause();
  readCertificate.pause();
  while (!buffer.length) {
    await new Promise(resolve => setTimeout(resolve, 100));
  }
  readPrivateKey.resume();
  readCertificate.resume();

  // Concatenate the collected data into a single PEM certificate string
  const pemString = buffer.join('');

  // Return the generated PEM certificate string
  return pemString;
}
```"]

