using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class TiffMetadata {
    public int BitsPerSample { get; set; }
    public int SamplePerPixel { get; set; }
    public int ExtraSamplesCount { get; set; }
    public string[] ExtraSamples { get; set; }
    public byte[] MD5Hash { get; set; }
}

public class TiffProcessor {
    private static readonly Dictionary<string, TiffMetadata> _cache = new Dictionary<string, TiffMetadata>();

    public static async Task<TiffMetadata> ProcessAndHashTiff(string path) {
        var fileInfo = new FileInfo(path);
        if (!fileInfo.Exists) {
            throw new FileNotFoundException($"The file '{path}' does not exist.");
        }

        // Check if the file is a TIFF image and if it supports 16 bits per sample
        var isTiff = fileInfo.Extension == ".tif";
        var isSupportedBitsPerSample = BitsPerSample <= 16;
        if (!isTiff || !isSupportedBitsPerSample) {
            Console.WriteLine($"The file '{path}' is not a valid TIFF image with a supported bit depth.");
            return null;
        }

        // Check if the file is already cached
        var cacheKey = path + BitsPerSample.ToString();
        if (_cache.ContainsKey(cacheKey)) {
            return _cache[cacheKey];
        }

        // Parse the TIFF image metadata and extract detailed information about the bits per sample, sample per pixel, and any additional samples
        var reader = new TiffBitmapDecoder(new Uri(path), BitmapCreateOptions.None, BitmapCacheOption.Default);
        var frame = reader.Frames[0];
        var bitsPerSample = frame.BitsPerPixel / frame.Channels;
        var samplePerPixel = frame.Channels;
        var extraSamplesCount = 0;
        var extraSamples = new string[] { };

        if (samplePerPixel > 1) {
            extraSamplesCount = samplePerPixel - 1;
            extraSamples = new string[extraSamplesCount];
            for (var i = 0; i < extraSamplesCount; i++) {
                extraSamples[i] = frame.GetPropertyItem(PropertyTagExtraSamples).Value[i].ToString();
            }
        }

        // Compute the MD5 hash of the TIFF file's content using a standard library cryptographic hash function
        var md5Hash = MD5.Create().ComputeHash(File.ReadAllBytes(path));

        // Cache the processed image metadata and return the results
        _cache[cacheKey] = new TiffMetadata {
            BitsPerSample = bitsPerSample,
            SamplePerPixel = samplePerPixel,
            ExtraSamplesCount = extraSamplesCount,
            ExtraSamples = extraSamples,
            MD5Hash = md5Hash
        };
        return _cache[cacheKey];
    }
}
```
This code defines a `TiffMetadata` class to store the detailed information about the TIFF image, and a `TiffProcessor` class with a static `ProcessAndHashTiff` method that accepts a string representing the path to a TIFF image file. The method first checks if the file exists, then checks if it's a valid TIFF image and has a supported bit depth. If not, it logs a warning and returns null.

If the file is valid, it tries to retrieve its metadata from a cache of previously processed images. If the metadata is not in the cache, it parses the TIFF image using `TiffBitmapDecoder` and extracts detailed information about the bits per sample, sample per pixel, and any additional samples. It then computes the MD5 hash of the file's content using `MD5.Create().ComputeHash(File.ReadAllBytes(path))`.

The method returns an instance of the `TiffMetadata` class with the parsed image information and the computed MD5 hash, which is cached for future use. If the file has extra samples, it stores them in the `ExtraSamples` property of the `TiffMetadata` object. The method also incorporates caching mechanisms to improve performance by reducing the number of times the TIFF image needs to be parsed.

This implementation ensures that the function is designed for scalability and maintainability, considering future extensions such as adding support for additional image formats.']

