void extend_openssl() {
    // Add AES block cipher
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_digest_alias("AES-256-CBC", "aes-256-cbc");

    // Add Camellia block cipher
    EVP_add_cipher(EVP_camellia_192_cbc());
    EVP_add_digest_alias("CAMELLIA-192-CBC", "camellia-192-cbc");

    // Add MD5 digest
    EVP_add_digest(EVP_md5());

    // Add SHA digests
    EVP_add_digest(EVP_sha1());
    EVP_add_digest(EVP_sha256());

    // Add RSA with SHA-1 signatures
    EVP_add_signature_alg("RSA-SHA1", EVP_PKEY_RSA, NID_sha1WithRSAEncryption);
}
```
