#include <openssl/aes.h>
#include <openssl/evp.h>

void init_aes_cbc(const char* password) {
    int password_len = strlen(password);
    unsigned char* key;
    unsigned char* iv;
    size_t key_len, iv_len;

    // Calculate the appropriate key and IV lengths based on the password's entropy
    switch (password_len) {
        case 16:
            key_len = AES_KEY_LENGTH_256;
            iv_len = AES_BLOCK_SIZE;
            break;
        case 32:
            key_len = AES_KEY_LENGTH_256;
            iv_len = AES_BLOCK_SIZE * 2;
            break;
        default:
            key_len = AES_KEY_LENGTH_128;
            iv_len = AES_BLOCK_SIZE;
    }

    // Allocate memory for the key and IV
    key = (unsigned char*)OPENSSL_malloc(key_len);
    iv = (unsigned char*)OPENSSL_malloc(iv_len);

    // Generate the key and IV using the password
    EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), NULL, (unsigned char*)password, password_len, 1, key, iv);

    // Create the AES-256-CBC cipher using the generated key and IV
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);

    // Free the memory allocated for the key and IV
    OPENSSL_free(key);
    OPENSSL_free(iv);

    return ctx;
}

void deinit_aes_cbc(EVP_CIPHER_CTX* ctx) {
    EVP_CIPHER_CTX_free(ctx);
}

// Example usage:
int main() {
    char password[] = "mypassword";
    EVP_CIPHER_CTX* ctx = init_aes_cbc(password);
    deinit_aes_cbc(ctx);
    return 0;
}']

