class FileConverter {
 public:
  // Constructor to set the path of the ImageConverter tool
  FileConverter(const std::string& imageConverterPath) : imageConverterPath_(imageConverterPath) {}

  // Method to convert JPEG images to PDF files
  void convertJPEGToPDF(const std::string& inputFile, const std::string& outputFile) {
    // Check if the input file exists and is a valid JPEG image
    if (!std::filesystem::exists(inputFile)) {
      throw std::invalid_argument("Input file does not exist");
    } else if (getExtension(inputFile) != "jpg" && getExtension(inputFile) != "jpeg") {
      throw std::invalid_argument("Input file is not a valid JPEG image");
    }

    // Check if the output file exists and create it if necessary
    if (!std::filesystem::exists(outputFile)) {
      try {
        std::ofstream ofs(outputFile, std::ios_base::out | std::ios_base::binary);
      } catch (const std::exception& e) {
        throw std::runtime_error("Failed to create output file: " + e.what());
      }
    } else if (!std::filesystem::is_regular_file(outputFile)) {
      throw std::invalid_argument("Output file is not a regular file");
    }

    // Create a temporary directory for the conversion process
    const auto tmpDir = createTmpDir();

    // Convert the JPEG image to a PDF file using the ImageConverter tool
    try {
      system(imageConverterPath_ + " -i " + inputFile + " -o " + tmpDir + "/output.pdf");
    } catch (const std::exception& e) {
      throw std::runtime_error("Failed to convert JPEG image: " + e.what());
    }

    // Copy the PDF file to the output directory and delete the temporary directory
    try {
      std::ifstream ifs(tmpDir + "/output.pdf", std::ios_base::in | std::ios_base::binary);
      std::ofstream ofs(outputFile, std::ios_base::out | std::ios_base::binary);
      ofs << ifs.rdbuf();
    } catch (const std::exception& e) {
      throw std::runtime_error("Failed to copy PDF file: " + e.what());
    }
    try {
      std::filesystem::remove(tmpDir);
    } catch (const std::exception& e) {
      throw std::runtime_error("Failed to delete temporary directory: " + e.what());
    }
  }

 private:
  // Function to get the file extension of a given filename
  std::string getExtension(const std::string& filename) {
    return filename.substr(filename.find_last_of(".") + 1);
  }

  // Function to create a temporary directory for the conversion process
  std::string createTmpDir() {
    const auto tmpDir = std::filesystem::temp_directory_path().append("image-converter");
    try {
      std::filesystem::create_directories(tmpDir);
    } catch (const std::exception& e) {
      throw std::runtime_error("Failed to create temporary directory: " + e.what());
    }
    return tmpDir;
  }

  // Path of the ImageConverter tool
  const std::string imageConverterPath_;
};
```
The `FileConverter` class has a constructor that takes in the path of the third-party `ImageConverter` tool as an argument. The `convertJPEGToPDF` method is responsible for converting a JPEG image to a PDF file using the `ImageConverter` tool. It first checks if the input file exists and is a valid JPEG image, then creates a temporary directory for the conversion process. It converts the JPEG image to a PDF file using the `ImageConverter` tool and copies the resulting PDF file to the output directory. Finally, it deletes the temporary directory.

The class also includes error handling that logs any issues encountered during the conversion process without terminating the program. The error messages provide enough context for debugging but should not expose sensitive information.

The `getExtension` function is used to get the file extension of a given filename, while the `createTmpDir` function creates a temporary directory for the conversion process and returns its path.

This implementation assumes that the third-party `ImageConverter` tool is installed in the system and can be accessed using the provided path. It also assumes that the input file is a valid JPEG image and the output file should be a PDF file.']

