#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>
#include <pthread.h>

#define MAX_PROCESSES 10
#define PROCESS_NAME_MAX_LEN 32
#define TIMEOUT_DEFAULT 60
#define LOG_FILE "processes.log"

typedef struct Process {
    char name[PROCESS_NAME_MAX_LEN];
    int pid;
    unsigned long start_time, end_time;
    int timeout;
} Process;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
static Process processes[MAX_PROCESSES];
static int num_processes = 0;
static int is_running = 1;

int startProcess(const char* name, unsigned long timeout) {
    // Check if there are any free slots in the array
    if (num_processes == MAX_PROCESSES) {
        return -1;
    }

    // Create a new process with the given command and timeout
    Process* proc = &processes[num_processes];
    strcpy(proc->name, name);
    proc->pid = fork();
    if (proc->pid == 0) {
        // Child process
        execlp(name, NULL);
        return -1;
    } else if (proc->pid < 0) {
        perror("fork");
        return -1;
    }

    // Set the timeout for the process
    proc->timeout = timeout;

    // Log the start time of the process
    pthread_mutex_lock(&mutex);
    proc->start_time = time(NULL);
    pthread_mutex_unlock(&mutex);

    // Increment the number of processes
    num_processes++;

    return 1;
}

int stopProcess(const char* name) {
    // Find the process with the given name
    Process* proc = NULL;
    for (int i = 0; i < MAX_PROCESSES; i++) {
        if (strcmp(processes[i].name, name) == 0) {
            proc = &processes[i];
            break;
        }
    }

    // Check if the process exists
    if (proc == NULL) {
        return -1;
    }

    // Stop the process and wait for it to complete
    kill(proc->pid, SIGTERM);
    int status = 0;
    waitpid(proc->pid, &status, 0);

    // Log the end time of the process
    pthread_mutex_lock(&mutex);
    proc->end_time = time(NULL);
    pthread_mutex_unlock(&mutex);

    // Decrement the number of processes
    num_processes--;

    return 1;
}

void cleanupProcesses() {
    // Clean up any running processes
    for (int i = 0; i < num_processes; i++) {
        Process* proc = &processes[i];
        kill(proc->pid, SIGTERM);
        waitpid(proc->pid, NULL, 0);
    }
}

void handleSignal(int sig) {
    // Handle signal interruptions by cleaning up the processes
    if (sig == SIGINT || sig == SIGTERM) {
        is_running = 0;
        cleanupProcesses();
    }
}

void* logProcessInfo(void* args) {
    // Log process information in a separate thread
    while (is_running) {
        for (int i = 0; i < num_processes; i++) {
            Process* proc = &processes[i];
            pthread_mutex_lock(&mutex);
            FILE* logfile = fopen(LOG_FILE, "a");
            fprintf(logfile, "%s: started at %lu seconds, ended at %lu seconds\n",
                    proc->name, proc->start_time, proc->end_time);
            fclose(logfile);
            pthread_mutex_unlock(&mutex);
        }
        sleep(1);
    }
}

int main() {
    // Set up signal handling for interruptions
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handleSignal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return -1;
    }

    // Start a separate thread to log process information
    pthread_t log_thread;
    if (pthread_create(&log_thread, NULL, logProcessInfo, NULL) != 0) {
        perror("pthread_create");
        return -1;
    }

    // Loop until the user terminates the program
    while (is_running) {
        char cmd[256];
        printf("Enter command (or \"stop\" to stop): ");
        fgets(cmd, 256, stdin);

        // Handle user input
        if (strcmp(cmd, "stop") == 0) {
            is_running = 0;
        } else {
            char* token = strtok(cmd, " ");
            unsigned long timeout = TIMEOUT_DEFAULT;
            while (token != NULL) {
                if (strcmp(token, "-t") == 0 || strcmp(token, "--timeout") == 0) {
                    // Set the timeout for the process
                    token = strtok(NULL, " ");
                    if (token == NULL) {
                        fprintf(stderr, "Invalid timeout value\n");
                        break;
                    }
                    int t = atoi(token);
                    if (t > 0 && t <= TIMEOUT_DEFAULT) {
                        timeout = t;
                    } else {
                        fprintf(stderr, "Invalid timeout value\n");
                        break;
                    }
                } else {
                    // Start the process with the given command and timeout
                    int status = startProcess(token, timeout);
                    if (status == -1) {
                        fprintf(stderr, "Failed to start process\n");
                    }
                }
                token = strtok(NULL, " ");
            }
        }
    }

    // Clean up any running processes and close the log file
    cleanupProcesses();
    FILE* logfile = fopen(LOG_FILE, "a");
    if (logfile != NULL) {
        fclose(logfile);
    }
    return 0;
}
```
This code implements a dynamic set of background processes that can handle up to ten concurrent processes, each with customizable timeout settings. The `startProcess` function takes the command and timeout as input parameters and starts a new process using `fork`. It logs the start time of the process in a separate thread. If the process fails to start within its specified timeout, it is terminated and the function returns -1 for failure. Otherwise, the function returns 1 for successful starts. The `logProcessInfo` function logs process information every second until the user terminates the program. The main function sets up signal handling for interruptions using `sigaction`, starts a separate thread to log process information, and loops until the user terminates the program or stops all processes.']

