using System.Threading;

namespace MyProject {
    public static class WebsiteManager {
        private const int MAX_PROCESS_LIMIT = 50; // adjustable limit for maximum number of concurrent processes
        private static ConcurrentDictionary<string, Process> _processes = new(); // dictionary to store active processes

        public static void AddWebsite(string directoryPath, string siteName) {
            try {
                if (!Directory.Exists(directoryPath)) {
                    throw new DirectoryNotFoundException($"The directory at '{directoryPath}' does not exist.");
                }

                // verify web.config file exists in the specified directory
                if (!File.Exists(Path.Combine(directoryPath, "web.config"))) {
                    return null;
                }

                // ensure valid directory structure and non-empty directory path
                var directoryInfo = new DirectoryInfo(directoryPath);
                var directoryStructure = Path.GetFullPath(directoryInfo.Parent.ToString());
                if (!directoryInfo.Name.Equals("websites", StringComparison.OrdinalIgnoreCase)) {
                    throw new Exception($"The directory at '{directoryPath}' does not have the expected structure (e.g., 'websites').");
                }

                // handle exceptions during process creation and execution
                ProcessStartInfo startInfo = new ProcessStartInfo("cmd", $"/c \"{Path.Combine(directoryPath, "web.config")}\"");
                startInfo.UseShellExecute = false;
                startInfo.RedirectStandardOutput = true;
                startInfo.CreateNoWindow = true;

                var process = new Process { StartInfo = startInfo };
                process.Start();
                _processes.Add(siteName, process);

                Console.WriteLine($"Successfully started website '{siteName}' at '{directoryPath}'.");
            } catch (Exception ex) {
                Console.WriteLine($"Failed to start website '{siteName}': {ex.Message}");
            }
        }

        public static void RemoveWebsite(string siteName) {
            if (_processes.TryGetValue(siteName, out var process)) {
                try {
                    process.Kill();
                    _processes.Remove(siteName);
                    Console.WriteLine($"Successfully stopped website '{siteName}'.");
                } catch (Exception ex) {
                    Console.WriteLine($"Failed to stop website '{siteName}': {ex.Message}");
                }
            } else {
                Console.WriteLine($"Website '{siteName}' is not running.");
            }
        }

        public static void StartAllWebsites() {
            foreach (var site in _processes) {
                var process = site.Value;
                if (!process.HasExited) {
                    try {
                        process.Start();
                    } catch (Exception ex) {
                        Console.WriteLine($"Failed to start website '{site.Key}': {ex.Message}");
                    }
                }
            }
        }

        public static void StopAllWebsites() {
            foreach (var site in _processes) {
                var process = site.Value;
                if (!process.HasExited) {
                    try {
                        process.Kill();
                        _processes.Remove(site.Key);
                    } catch (Exception ex) {
                        Console.WriteLine($"Failed to stop website '{site.Key}': {ex.Message}");
                    }
                }
            }
        }

        public static void UpdateWebsites() {
            foreach (var site in _processes) {
                var process = site.Value;
                if (!process.HasExited) {
                    try {
                        process.Refresh();
                        Console.WriteLine($"Successfully updated website '{site.Key}'.");
                    } catch (Exception ex) {
                        Console.WriteLine($"Failed to update website '{site.Key}': {ex.Message}");
                    }
                }
            }
        }

        public static void MonitorWebsites() {
            foreach (var site in _processes) {
                var process = site.Value;
                if (!process.HasExited) {
                    try {
                        process.Refresh();
                        Console.WriteLine($"Successfully monitored website '{site.Key}'.");
                    } catch (Exception ex) {
                        Console.WriteLine($"Failed to monitor website '{site.Key}': {ex.Message}");
                    }
                }
            }
        }

        public static void LogWebsites() {
            foreach (var site in _processes) {
                var process = site.Value;
                if (!process.HasExited) {
                    try {
                        process.Refresh();
                        Console.WriteLine($"Successfully logged website '{site.Key}'.");
                    } catch (Exception ex) {
                        Console.WriteLine($"Failed to log website '{site.Key}': {ex.Message}");
                    }
                }
            }
        }
    }
}
