import java.io.BufferedReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;

public class DiskUsageChecker {
  private static final long CACHE_TIMEOUT = TimeUnit.MINUTES.toMillis(10); // Cache timeout in milliseconds
  private static final int MAX_CACHE_SIZE = 1024; // Maximum number of cached disk usage results

  public static void main(String[] args) {
    if (args.length != 1) {
      System.err.println("Usage: java DiskUsageChecker <directory>");
      System.exit(1);
    }

    String directory = args[0];
    try {
      List<String> diskUsageResults = getDiskUsage(directory);
      System.out.println("Disk usage of " + directory + ":");
      for (String result : diskUsageResults) {
        System.out.println(result);
      }
    } catch (IOException | InterruptedException e) {
      System.err.println("Error while checking disk usage: " + e.getMessage());
    }
  }

  private static List<String> getDiskUsage(String directory) throws IOException, InterruptedException {
    // Check if the directory exists and is readable
    if (!new java.io.File(directory).exists() || !new java.io.File(directory).canRead()) {
      throw new IOException("Directory does not exist or is not readable: " + directory);
    }

    // Check if the current user has permission to access the directory
    if (!new java.io.File(directory).canExecute()) {
      throw new IOException("User does not have permission to access directory: " + directory);
    }

    // Check if the system supports the required shell commands
    String[] shellCommands = {"du", "-sh", directory};
    boolean duCommandAvailable = isShellCommandAvailable(shellCommands);

    if (duCommandAvailable) {
      return executeDiskUsageCommand(directory);
    } else {
      // Fallback to using the "df" command if "du" is not available
      shellCommands[0] = "df";
      boolean dfCommandAvailable = isShellCommandAvailable(shellCommands);

      if (dfCommandAvailable) {
        return executeDiskUsageCommand(directory, false);
      } else {
        throw new IOException("No suitable shell command available for checking disk usage");
      }
    }
  }

  private static List<String> executeDiskUsageCommand(String directory, boolean useDu) throws IOException, InterruptedException {
    Process process = Runtime.getRuntime().exec(useDu ? "du -sh" : "df", new String[]{"-P", directory});
    try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
      List<String> diskUsageResults = new ArrayList<>();
      String line;
      while ((line = reader.readLine()) != null) {
        diskUsageResults.add(line);
      }
      return diskUsageResults;
    } finally {
      process.destroy();
    }
  }

  private static boolean isShellCommandAvailable(String[] command) {
    try {
      Process process = Runtime.getRuntime().exec(command, null, new java.io.File("."));
      process.waitFor(100, TimeUnit.MILLISECONDS);
      return process.exitValue() == 0;
    } catch (IOException | InterruptedException e) {
      return false;
    }
  }
}
