int authenticate_user(struct auth_params* params) {
  if (params == NULL || params->password == NULL || params->config == NULL || params->callback == NULL) {
    return -1;
  }

  // validate the Base64-encoded password
  if (!is_base64_valid(params->password)) {
    return -2;
  }

  // ensure database connection settings are valid and up-to-date
  if (!is_db_config_valid(params->config)) {
    return -3;
  }

  // confirm that the callback function is properly initialized
  if (params->callback == NULL) {
    return -4;
  }

  // handle concurrent access to shared resources and prevent race conditions
  pthread_mutex_lock(&auth_mutex);

  // decrypt the password using Triple DES encryption with a provided key and IV
  unsigned char* plaintext = NULL;
  int ret = tripledes_decrypt(params->password, &plaintext, params->key, params->iv);
  if (ret != 0) {
    // invoke the callback with the appropriate failure reason
    params->callback(ret, "Triple DES decryption failed");
    return -5;
  }

  // free any allocated memory
  free(plaintext);

  pthread_mutex_unlock(&auth_mutex);

  return 0;
}
