// Define the schema for the JSON configuration file
const char* CONFIG_SCHEMA = "{\"type\": \"object\",\"properties\": {\"api_base_url\": {\"type\": \"string\"},\"client_id\": {\"type\": \"string\"},\"client_secret\": {\"type\": \"string\"},\"timeout\": {\"type\": \"integer\",\"minimum\": 0},\"proxy_settings\": {\"type\": \"object\",\"properties\": {\"host\": {\"type\": \"string\"},\"port\": {\"type\": \"integer\",\"minimum\": 1}}}},\"required\": [\"api_base_url\",\"client_id\",\"client_secret\"]}";

// Define the function to parse and validate the JSON configuration file
bool parse_config(const char* config_file, struct Config* config) {
    // Open the configuration file
    FILE* fp = fopen(config_file, "r");
    if (fp == NULL) {
        printf("Error: unable to open configuration file %s\n", config_file);
        return false;
    }

    // Load the entire JSON document into memory
    char* json_str = malloc(1024 * 1024);
    size_t length = fread(json_str, 1, 1024 * 1024, fp);
    if (length == 0) {
        printf("Error: unable to read from configuration file %s\n", config_file);
        fclose(fp);
        return false;
    }

    // Validate the JSON document against the schema
    cJSON* json = cJSON_Parse(json_str);
    if (json == NULL) {
        printf("Error: unable to parse configuration file %s\n", config_file);
        fclose(fp);
        return false;
    }

    // Ensure that all required fields are present and valid
    cJSON* api_base_url = cJSON_GetObjectItemCaseSensitive(json, "api_base_url");
    if (cJSON_IsString(api_base_url) && (strlen(api_base_url->valuestring) > 0)) {
        config->api_base_url = strdup(api_base_url->valuestring);
    } else {
        printf("Error: missing or invalid 'api_base_url' in configuration file %s\n", config_file);
        cJSON_Delete(json);
        fclose(fp);
        return false;
    }

    cJSON* client_id = cJSON_GetObjectItemCaseSensitive(json, "client_id");
    if (cJSON_IsString(client_id) && (strlen(client_id->valuestring) > 0)) {
        config->client_id = strdup(client_id->valuestring);
    } else {
        printf("Error: missing or invalid 'client_id' in configuration file %s\n", config_file);
        cJSON_Delete(json);
        fclose(fp);
        return false;
    }

    cJSON* client_secret = cJSON_GetObjectItemCaseSensitive(json, "client_secret");
    if (cJSON_IsString(client_secret) && (strlen(client_secret->valuestring) > 0)) {
        config->client_secret = strdup(client_secret->valuestring);
    } else {
        printf("Error: missing or invalid 'client_secret' in configuration file %s\n", config_file);
        cJSON_Delete(json);
        fclose(fp);
        return false;
    }

    // Validate the optional fields
    if (cJSON_HasObjectItem(json, "timeout")) {
        int timeout = cJSON_GetObjectItemCaseSensitive(json, "timeout")->valueint;
        if (timeout > 0) {
            config->timeout = timeout;
        } else {
            printf("Error: invalid 'timeout' in configuration file %s\n", config_file);
            cJSON_Delete(json);
            fclose(fp);
            return false;
        }
    }

    if (cJSON_HasObjectItem(json, "proxy_settings")) {
        cJSON* proxy_settings = cJSON_GetObjectItemCaseSensitive(json, "proxy_settings");
        if (cJSON_IsObject(proxy_settings)) {
            cJSON* host = cJSON_GetObjectItemCaseSensitive(proxy_settings, "host");
            if (cJSON_IsString(host) && (strlen(host->valuestring) > 0)) {
                config->proxy_host = strdup(host->valuestring);
            } else {
                printf("Error: missing or invalid 'host' in proxy settings\n");
                cJSON_Delete(json);
                fclose(fp);
                return false;
            }

            int port = cJSON_GetObjectItemCaseSensitive(proxy_settings, "port")->valueint;
            if (port > 0) {
                config->proxy_port = port;
            } else {
                printf("Error: invalid 'port' in proxy settings\n");
                cJSON_Delete(json);
                fclose(fp);
                return false;
            }
        } else {
            printf("Error: invalid 'proxy_settings' in configuration file %s\n", config_file);
            cJSON_Delete(json);
            fclose(fp);
            return false;
        }
    }

    // Close the configuration file
    fclose(fp);

    // Clean up memory allocation for JSON string
    free(json_str);

    // Clean up cJSON memory allocation for JSON object
    cJSON_Delete(json);

    return true;
}

// Define the struct to hold the parsed configuration data
struct Config {
    char* api_base_url;
    char* client_id;
    char* client_secret;
    int timeout;
    char* proxy_host;
    int proxy_port;
};

int main() {
    // Load the configuration file from disk
    const char* config_file = "/path/to/config.json";
    struct Config config;
    bool success = parse_config(config_file, &config);
    if (!success) {
        printf("Error: unable to load configuration file %s\n", config_file);
        return 1;
    }

    // Use the parsed configuration data
    printf("API base URL: %s\n", config.api_base_url);
    printf("Client ID: %s\n", config.client_id);
    printf("Client Secret: %s\n", config.client_secret);
    printf("Timeout: %d\n", config.timeout);
    if (config.proxy_host != NULL) {
        printf("Proxy settings:\n");
        printf("  Host: %s\n", config.proxy_host);
        printf("  Port: %d\n", config.proxy_port);
    }

    // Clean up memory allocation for configuration struct
    free(config.api_base_url);
    free(config.client_id);
    free(config.client_secret);
    if (config.proxy_host != NULL) {
        free(config.proxy_host);
    }

    return 0;
