import json
from typing import Dict, Callable

class DynamicObject:
    def __init__(self, data: dict):
        self._data = data

    @staticmethod
    def from_json(json_str: str) -> 'DynamicObject':
        return DynamicObject(json.loads(json_str))

    def to_json(self) -> str:
        return json.dumps(self._data, ensure_ascii=False)

    def update_attributes(self, data: dict):
        self._data.update(data)

class DynamicObjectRegistry:
    def __init__(self):
        self._registry = {}

    def register_factory(self, id: str, factory: Callable[[str], 'DynamicObject']):
        if id in self._registry:
            raise ValueError("ID already exists")
        self._registry[id] = factory

    def create_instance(self, id: str) -> 'DynamicObject':
        factory = self._registry.get(id)
        if not factory:
            raise ValueError("Factory not found")
        return factory(id)

class ExternalDependency:
    def __init__(self):
        # Initialize external dependency library

    def process_data(self, data: str) -> str:
        # Process data using external dependency library
        return processed_data

class DynamicObjectWithExternalDependency(DynamicObject):
    def __init__(self, data: dict, external_dependency: ExternalDependency):
        super().__init__(data)
        self._external_dependency = external_dependency

    def to_json(self) -> str:
        return json.dumps(self._data, ensure_ascii=False)

