    int rnti;
    int crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to read a list of integers from standard input and store them in an array
int read_integers(NFAPI_CRC_INDICATION_PDU_T **array, int *count) {
    // Initialize the array size to 0
    *count = 0;

    // Read the first integer from standard input
    int num;
    if (scanf("%d", &num) != 1) {
        return -1;
    }

    // Allocate memory for the array of structures
    *array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) {
        return -2;
    }

    // Store the first integer in the array
    (*array)[*count].rx_ue_information_tag = num;
    (*array)[*count].rnti = 0;
    (*array)[*count].crc_indication_rel8_tag = 0;

    // Generate a random CRCFLAG value for the first structure
    srand(time(NULL));
    int crcflag = rand() % 2;
    (*array)[*count].crcflag = (bool)crcflag;

    // Increment the array size and continue reading integers until EOF is reached
    while (!feof(stdin)) {
        *count += 1;
        (*array) = realloc(*array, *count);
        if (*array == NULL) {
            return -2;
        }

        // Read the next integer from standard input
        if (scanf("%d", &num) != 1) {
            break;
        }

        // Store the next integer in the array
        (*array)[*count].rx_ue_information_tag = num;
        (*array)[*count].rnti = 0;
        (*array)[*count].crc_indication_rel8_tag = 0;

        // Generate a random CRCFLAG value for the next structure
        srand(time(NULL));
        crcflag = rand() % 2;
        (*array)[*count].crcflag = (bool)crcflag;
    }

    return *count;
}

// Function to find and print the largest integer in an array of structures
int get_largest(NFAPI_CRC_INDICATION_PDU_T *array, int count) {
    // Initialize the largest integer to 0
    int largest = 0;

    for (int i = 0; i < count; i++) {
        if (array[i].rx_ue_information_tag > largest) {
            largest = array[i].rx_ue_information_tag;
        }
    }

    return largest;
}
