#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>

// Define the structure for holding RRC transport PDUs
typedef struct {
    NFAPI_RRC_MESSAGE_TYPE_TAG messageType;
    NFAPI_RRC_TRANSPORT_CHANNEL_TAG transportChannel;
    uint16_t pdcpSn;
    uint16_t rnti;
} RrcTransportPdu;

// Define the array to hold the RRC transport PDUs
static RrcTransportPdu *rrcTransportPdus = NULL;

// Define the size of the RRC transport PDU array
static uint32_t rrcTransportPduSize = 0;

// Define the mutex for thread-safe access to the RRC transport PDU array
static pthread_mutex_t rrcTransportPduMutex = PTHREAD_MUTEX_INITIALIZER;

void initializeRrcTransportPdus(uint32_t size) {
    // Validate the input size and return if invalid
    if (size == 0) {
        printf("Invalid array size for RRC transport PDUs\n");
        return;
    }

    // Lock the mutex to ensure thread-safe access to the array
    pthread_mutex_lock(&rrcTransportPduMutex);

    // Reallocate the memory for the array if necessary
    if (rrcTransportPdus == NULL || rrcTransportPduSize < size) {
        rrcTransportPdus = realloc(rrcTransportPdus, sizeof(RrcTransportPdu) * size);
        rrcTransportPduSize = size;
    }

    // Initialize the RRC transport PDUs in the array
    for (uint32_t i = 0; i < rrcTransportPduSize; i++) {
        rrcTransportPdus[i].messageType = NFAPI_RRC_MESSAGE_TYPE_TAG_INITIAL;
        rrcTransportPdus[i].transportChannel = NFAPI_RRC_TRANSPORT_CHANNEL_TAG_PDCP_SN(0);
        rrcTransportPdus[i].pdcpSn = 0;
        rrcTransportPdus[i].rnti = 0;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&rrcTransportPduMutex);
}

// Define a function to add an RRC transport PDU to the array
void addRrcTransportPdu(NFAPI_RRC_MESSAGE_TYPE_TAG messageType, NFAPI_RRC_TRANSPORT_CHANNEL_TAG transportChannel, uint16_t pdcpSn, uint16_t rnti) {
    // Lock the mutex to ensure thread-safe access to the array
    pthread_mutex_lock(&rrcTransportPduMutex);

    // Validate that the PDCP SN does not exceed the maximum value allowed by the protocol
    if (pdcpSn > NFAPI_RRC_MAX_PDCP_SN) {
        printf("Invalid PDCP SN for RRC transport PDU\n");
        pthread_mutex_unlock(&rrcTransportPduMutex);
        return;
    }

    // Validate that the RNTI is within the valid range for the system
    if (rnti > NFAPI_RRC_MAX_RNTI) {
        printf("Invalid RNTI for RRC transport PDU\n");
        pthread_mutex_unlock(&rrcTransportPduMutex);
        return;
    }

    // Reallocate the memory for the array if necessary
    if (rrcTransportPdus == NULL || rrcTransportPduSize < 1) {
        rrcTransportPdus = realloc(rrcTransportPdus, sizeof(RrcTransportPdu));
        rrcTransportPduSize = 1;
    }

    // Increment the PDCP SN if it has wrapped around
    if (pdcpSn == NFAPI_RRC_MAX_PDCP_SN) {
        pdcpSn = 0;
    } else {
        pdcpSn++;
    }

    // Add the RRC transport PDU to the array
    rrcTransportPdus[rrcTransportPduSize - 1].messageType = messageType;
    rrcTransportPdus[rrcTransportPduSize - 1].transportChannel = transportChannel;
    rrcTransportPdus[rrcTransportPduSize - 1].pdcpSn = pdcpSn;
    rrcTransportPdus[rrcTransportPduSize - 1].rnti = rnti;

    // Unlock the mutex
    pthread_mutex_unlock(&rrcTransportPduMutex);
}

// Define a function to remove an RRC transport PDU from the array
void removeRrcTransportPdu(uint32_t index) {
    // Lock the mutex to ensure thread-safe access to the array
    pthread_mutex_lock(&rrcTransportPduMutex);

    // Validate that the index is within the range of the array
    if (index >= rrcTransportPduSize) {
        printf("Invalid index for RRC transport PDU\n");
        pthread_mutex_unlock(&rrcTransportPduMutex);
        return;
    }

    // Shift all the elements in the array to the left of the specified index
    for (uint32_t i = index; i < rrcTransportPduSize - 1; i++) {
        rrcTransportPdus[i].messageType = rrcTransportPdus[i + 1].messageType;
        rrcTransportPdus[i].transportChannel = rrcTransportPdus[i + 1].transportChannel;
        rrcTransportPdus[i].pdcpSn = rrcTransportPdus[i + 1].pdcpSn;
        rrcTransportPdus[i].rnti = rrcTransportPdus[i + 1].rnti;
    }

    // Reallocate the memory for the array if necessary
    if (rrcTransportPduSize == 1) {
        free(rrcTransportPdus);
        rrcTransportPdus = NULL;
        rrcTransportPduSize = 0;
    } else {
        rrcTransportPdus = realloc(rrcTransportPdus, sizeof(RrcTransportPdu) * (rrcTransportPduSize - 1));
        rrcTransportPduSize--;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&rrcTransportPduMutex);
}

// Define a function to get the number of RRC transport PDUs in the array
uint32_t getRrcTransportPduCount() {
    // Lock the mutex to ensure thread-safe access to the array
    pthread_mutex_lock(&rrcTransportPduMutex);

    // Return the number of RRC transport PDUs in the array
    uint32_t count = rrcTransportPduSize;

    // Unlock the mutex
    pthread_mutex_unlock(&rrcTransportPduMutex);

    return count;
}

// Define a function to get an RRC transport PDU from the array by index
RrcTransportPdu getRrcTransportPdu(uint32_t index) {
    // Lock the mutex to ensure thread-safe access to the array
    pthread_mutex_lock(&rrcTransportPduMutex);

    // Validate that the index is within the range of the array
    if (index >= rrcTransportPduSize) {
        printf("Invalid index for RRC transport PDU\n");
        pthread_mutex_unlock(&rrcTransportPduMutex);
        return NULL;
    }

    // Return the specified RRC transport PDU from the array
    RrcTransportPdu rrcTransportPdu = rrcTransportPdus[index];

    // Unlock the mutex
    pthread_mutex_unlock(&rrcTransportPduMutex);

    return rrcTransportPdu;
}

// Define a function to get all RRC transport PDUs in the array as an array of structs
RrcTransportPdu* getAllRrcTransportPdus() {
    // Lock the mutex to ensure thread-safe access to the array
    pthread_mutex_lock(&rrcTransportPduMutex);

    // Allocate memory for an array of structs that can hold all the RRC transport PDUs in the array
    RrcTransportPdu* rrcTransportPdusArray = malloc(sizeof(RrcTransportPdu) * rrcTransportPduSize);

    // Copy all the RRC transport PDUs from the array to the allocated memory
    for (uint32_t i = 0; i < rrcTransportPduSize; i++) {
        rrcTransportPdusArray[i] = rrcTransportPdus[i];
    }

    // Unlock the mutex
    pthread_mutex_unlock(&rrcTransportPduMutex);

    return rrcTransportPdusArray;
}
