// Define a custom allocator for managing memory more effectively
struct MemoryAllocator {
  void* pool;
  size_t pool_size;
  size_t used_memory;
};

// Define a function to allocate memory from the custom allocator
void* allocate(struct MemoryAllocator* alloc, size_t size) {
  // Check if there is enough memory available in the pool
  if (alloc->pool_size - alloc->used_memory < size) {
    // If not, reallocate the pool to a larger size and copy the existing data
    void* new_pool = realloc(alloc->pool, alloc->pool_size * 2);
    if (new_pool == NULL) {
      return NULL;
    }
    alloc->pool = new_pool;
    alloc->pool_size = alloc->pool_size * 2;
  }

  // Allocate memory from the pool and update the used memory counter
  void* ptr = (void*)((uint8_t*)alloc->pool + alloc->used_memory);
  alloc->used_memory += size;
  return ptr;
}

// Define a function to deallocate memory from the custom allocator
void deallocate(struct MemoryAllocator* alloc, void* ptr) {
  // Find the index of the pointer in the pool
  size_t index = (uint8_t*)ptr - (uint8_t*)alloc->pool;

  // Update the used memory counter and reallocate the pool if necessary
  if (index + sizeof(NFAPI_RRC_CCO_REQUEST) > alloc->used_memory) {
    size_t new_size = index * 2;
    void* new_pool = realloc(alloc->pool, new_size);
    if (new_pool == NULL) {
      return;
    }
    alloc->pool = new_pool;
    alloc->pool_size = new_size;
  }

  // Update the used memory counter and free the memory
  alloc->used_memory -= sizeof(NFAPI_RRC_CCO_REQUEST);
  free((void*)((uint8_t*)alloc->pool + index));
}

// Define a function to insert a new structure into the list
int insert(struct MemoryAllocator* alloc, NFAPI_RRC_CCO_REQUEST* request) {
  // Allocate memory for the structure and initialize it with the given data
  void* ptr = allocate(alloc, sizeof(NFAPI_RRC_CCO_REQUEST));
  if (ptr == NULL) {
    return -1;
  }

  memcpy(ptr, request, sizeof(NFAPI_RRC_CCO_REQUEST));

  // Insert the structure into the list and update the size counter
  NFAPI_RRC_CCO_REQUEST* list = (NFAPI_RRC_CCO_REQUEST*)ptr;
  list->next = NULL;
  if (alloc->size == 0) {
    alloc->head = list;
  } else {
    alloc->tail->next = list;
  }
  alloc->size++;

  return 0;
}

// Define a function to delete a structure from the list by its UE_ID
int delete(struct MemoryAllocator* alloc, uint32_t ue_id) {
  // Find the structure in the list and update the size counter if found
  NFAPI_RRC_CCO_REQUEST* current = alloc->head;
  while (current != NULL) {
    if (current->ue_id == ue_id) {
      // Update the next pointer of the previous structure in the list
      if (current == alloc->head) {
        alloc->head = current->next;
      } else {
        current->prev->next = current->next;
      }

      // Deallocate the memory and update the used memory counter
      deallocate(alloc, current);
      alloc->size--;

      return 0;
    }

    current = current->next;
  }

  // If not found, return an error code
  return -1;
}

// Define a function to lookup a structure in the list by its UE_ID
NFAPI_RRC_CCO_REQUEST* lookup(struct MemoryAllocator* alloc, uint32_t ue_id) {
  // Find the structure in the list and return it if found
  NFAPI_RRC_CCO_REQUEST* current = alloc->head;
  while (current != NULL) {
    if (current->ue_id == ue_id) {
      return current;
    }

    current = current->next;
  }

  // If not found, return a null pointer
  return NULL;
}

// Define a function to print the contents of the list for debugging purposes
void print(struct MemoryAllocator* alloc) {
  printf("List size: %zu\n", alloc->size);
  NFAPI_RRC_CCO_REQUEST* current = alloc->head;
