EVP_CIPHER* get_cipher(const char* config) {
  // Parse the configuration string and extract the cipher mode, key length, and initialization vector (IV).
  const char* cipher_mode = NULL;
  size_t key_length = 0;
  unsigned char iv[EVP_MAX_IV_LENGTH] = {0};
  size_t iv_len = 0;

  // Check if the configuration is valid.
  if (!config || strlen(config) == 0) {
    return NULL;
  }

  // Parse the configuration string and extract the cipher mode, key length, and initialization vector (IV).
  char* token = strtok((char*)config, " ");
  while (token != NULL) {
    if (strcmp(token, "-cipher") == 0) {
      // Get the next token as the cipher mode.
      token = strtok(NULL, " ");
      if (!token || strlen(token) == 0) {
        return NULL;
      }
      cipher_mode = token;
    } else if (strcmp(token, "-key") == 0) {
      // Get the next token as the key length.
      token = strtok(NULL, " ");
      if (!token || strlen(token) == 0) {
        return NULL;
      }
      key_length = atoi(token);
    } else if (strcmp(token, "-iv") == 0) {
      // Get the next token as the initialization vector (IV).
      token = strtok(NULL, " ");
      if (!token || strlen(token) == 0) {
        return NULL;
      }
      iv_len = atoi(token);
    }
    token = strtok(NULL, " ");
  }

  // Check if the cipher mode is valid.
  if (!cipher_mode || strcmp(cipher_mode, "DES") != 0 && strcmp(cipher_mode, "Triple DES (EDE)") != 0 && strcmp(cipher_mode, "Triple DES (EDE3)") != 0 && strcmp(cipher_mode, "CFB") != 0) {
    return NULL;
  }

  // Check if the key length is valid.
  if (!key_length || key_length < 56 || key_length > 168) {
    return NULL;
  }

  // Check if the initialization vector (IV) is valid.
  if (!iv_len || iv_len > EVP_MAX_IV_LENGTH) {
    return NULL;
  }

  // Initialize the cipher.
  EVP_CIPHER* evp_cipher = NULL;
  if (strcmp(cipher_mode, "DES") == 0) {
    evp_cipher = EVP_des_cbc();
  } else if (strcmp(cipher_mode, "Triple DES (EDE)") == 0) {
    evp_cipher = EVP_des_ede3_cbc();
  } else if (strcmp(cipher_mode, "Triple DES (EDE3)") == 0) {
    evp_cipher = EVP_des_ede3_cbc();
  } else if (strcmp(cipher_mode, "CFB") == 0) {
    evp_cipher = EVP_cfb64();
  }

  // Set the key length and IV.
  int ret = EVP_CIPHER_CTX_set_key_length(evp_cipher, key_length);
  if (ret != 1) {
    return NULL;
  }

  ret = EVP_CIPHER_CTX_ctrl(evp_cipher, EVP_CTRL_INIT, iv_len, iv);
  if (ret != 1) {
    return NULL;
  }

  // Return the initialized cipher.
  return evp_cipher;
}
