```
use reqwest::blocking::get;
use std::collections::HashMap;
use retry::Retry;

fn main() {
    let url = "https://example.com";
    let headers = HashMap::new();
    headers.insert("User-Agent", "My Custom User Agent");
    let timeout = 5000; // milliseconds

    let mut retry_strategy = Retry::<()>::default();
    retry_strategy.max_retries = 3;
    retry_strategy.retry_interval = Duration::from_millis(100);

    let response = get(url, headers).timeout(Duration::from_millis(timeout))
        .unwrap_or_else(|e| {
            eprintln!("Error making GET request: {}", e);
            retry_strategy.retry(&mut || get(url, headers).timeout(Duration::from_millis(timeout)))
        });
}
