class InterfaceTable {
public:
    virtual std::string FindVmUuidFromMetadataIp(const std::string& ip) = 0;
};

class ModularSandeshClient {
public:
    ModularSandeshClient(io_context& io, const std::vector<NFAPI_CRC_INDICATION_PDU_T>& pduList, InterfaceTable* interfaceTable);

    void SendGetRequests();

private:
    io_context& mIo;
    const std::vector<NFAPI_CRC_INDICATION_PDU_T>& mPduList;
    InterfaceTable* mInterfaceTable;
};

ModularSandeshClient::ModularSandeshClient(io_context& io, const std::vector<NFAPI_CRC_INDICATION_PDU_T>& pduList, InterfaceTable* interfaceTable)
: mIo{io}, mPduList{pduList}, mInterfaceTable{interfaceTable} {}

void ModularSandeshClient::SendGetRequests() {
    std::unordered_set<std::string> vmUuids;

    for (const auto& pdu : mPduList) {
        const auto& ip = boost::get<std::string>(pdu.RX_UE_INFORMATION_TAG);
        if (!vmUuids.count(ip)) {
            vmUuids.insert(mInterfaceTable->FindVmUuidFromMetadataIp(ip));
        }
    }

    for (const auto& ip : vmUuids) {
        // Create a new HTTP GET request for each IP address in the set
        http::request<http::string_body> req{http::verb::get, "/"};
        req.set(http::field::host, ip);
        mIo.run();
    }
}

