    boost::asio::io_context io;

    // Define a list of NFAPI_CRC_INDICATION_PDU_T structures with sample data
    std::vector<NFAPI_CRC_INDICATION_PDU_T> pduList = {
        {"10.0.0.1", 0x1234, 0x5678, false},
        {"10.0.0.2", 0x90ab, 0xcdef, true}
    };

    // Create a new instance of the InterfaceTable class and override the FindVmUuidFromMetadataIp function to simulate a diverse network environment
    InterfaceTable interfaceTable;
    interfaceTable.FindVmUuidFromMetadataIp = [](const std::string& ip) {
        if (ip == "10.0.0.1") {
            return "vm_uuid_1";
        } else if (ip == "10.0.0.2") {
            return "vm_uuid_2";
        }
    };

    // Create a new instance of the ModularSandeshClient class and send GET requests to all unique virtual machine UUIDs in the list of PDU structures
    ModularSandeshClient sandeshClient{io, pduList, &interfaceTable};
