    list->capacity = 16; // Start with a default capacity of 16 elements
    list->requests = malloc(sizeof(struct NFAPI_RRC_CCO_REQUEST *) * list->capacity);
    if (!list->requests) {
        fprintf(stderr, "Failed to allocate memory for requests in NFAPI_RRC_CCO_REQUEST_LIST\n");
        free(list);
        return NULL;
    }

