        return -1;
    }

    // Remove the NFAPI_RRC_CCO_REQUEST from the list
    list->size--;
    memmove(list->requests + i, list->requests + i + 1, (list->size - i) * sizeof(struct NFAPI_RRC_CCO_REQUEST *));

    return 0;
}

// Function to clean up the list of NFAPI_RRC_CCO_REQUESTs
void nfapi_rrc_cco_request_list_cleanup(struct NFAPI_RRC_CCO_REQUEST_LIST *list) {
    if (!list) {
        return;
    }

    // Free the memory used by the list and its elements
    for (int i = 0; i < list->size; i++) {
        free(list->requests[i]);
    }
    free(list->requests);
    free(list);
}
