typedef struct {
    int key;
    char status_message[256];
} record;

void initialize_records(record** records, long offset_range_min, long offset_range_max, int key_range_min, int key_range_max) {
    // Dynamically allocate memory for the arrays
    *records = (record*)malloc((offset_range_max - offset_range_min + 1) * sizeof(record));
    if (*records == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for records\n");
        return;
    }

    // Initialize the arrays with random values within the specified ranges
    long offset = offset_range_min;
    int key = key_range_min;
    for (int i = 0; i < (offset_range_max - offset_range_min + 1); i++) {
        (*records)[i].key = rand() % (key_range_max - key_range_min + 1) + key_range_min;
        sprintf((*records)[i].status_message, "Initialized record %ld with key %d", offset++, (*records)[i].key);
    }
}

int main() {
    // Test the function by initializing an array of records with random values within a specified range
    long offset_range_min = 10;
    long offset_range_max = 20;
    int key_range_min = 1;
    int key_range_max = 10;
    record* records = NULL;
    initialize_records(&records, offset_range_min, offset_range_max, key_range_min, key_range_max);

    // Print the initialized records
    printf("Initialized records:\n");
    for (int i = 0; i < (offset_range_max - offset_range_min + 1); i++) {
        printf("%ld: %d\n", (*records)[i].key, (*records)[i].status_message);
    }

    // Free the memory allocated for the records
    free(records);

    return 0;
}
