typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
    uint16_t CRC_INDICATION_REL8_TAG;
    int64_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

int process_rx_ue_information(const uint32_t* rx_info, size_t num_elements) {
    if (num_elements == 0) {
        return 0;
    }

    // Validate input data
    for (size_t i = 0; i < num_elements; ++i) {
        if (rx_info[i] > UINT16_MAX) {
            printf("Error: integer %lu is out of range\n", i);
            continue;
        }
    }

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu_list == NULL) {
        printf("Error: failed to allocate memory for structure list\n");
        return -1;
    }

    // Populate the structure list with the input data
    size_t valid_count = 0;
    for (size_t i = 0; i < num_elements; ++i) {
        pdu_list[valid_count].RX_UE_INFORMATION_TAG = 0x80000000 | rx_info[i];
        pdu_list[valid_count].RNTI = rx_info[i] & 0xffff;
        pdu_list[valid_count].CRCFLAG = (uint8_t)((rx_info[i] >> 16) & 0xff);
        pdu_list[valid_count].CRC_INDICATION_REL8_TAG = rx_info[i] & 0xffff;
        pdu_list[valid_count].timestamp = (int64_t)time(NULL);
        valid_count++;
    }

    // Find the largest integer in the array
    int64_t max_value = INT64_MIN;
    for (size_t i = 0; i < valid_count; ++i) {
        if (pdu_list[i].RX_UE_INFORMATION_TAG > max_value) {
            max_value = pdu_list[i].RX_UE_INFORMATION_TAG;
        }
    }

    // Print the largest integer and free memory
    printf("Largest integer: %ld\n", max_value);
    free(pdu_list);

    return valid_count;
}
