#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef struct Packet {
  unsigned char protocol_version;
  unsigned char packet_type;
  unsigned int sequence_number;
} Packet;

Packet* create_packet_array(int num_packets) {
  // Dynamically allocate memory for the packet array
  Packet* packet_array = (Packet*)malloc(num_packets * sizeof(Packet));
  if (!packet_array) {
    fprintf(stderr, "Failed to allocate memory for packet array\n");
    return NULL;
  }

  // Initialize each packet in the array with default values
  for (int i = 0; i < num_packets; ++i) {
    packet_array[i].protocol_version = 1;
    packet_array[i].packet_type = 0;
    packet_array[i].sequence_number = 0;
  }

  return packet_array;
}

void free_packet_array(Packet* packet_array) {
  // Free the memory allocated for the packet array
  free(packet_array);
}

void handle_new_packet(Packet* packet_array, int num_packets, Packet new_packet) {
  // Check if the packet array has enough space to store the new packet
  if (num_packets >= MAX_PACKETS) {
    fprintf(stderr, "Maximum number of packets reached. Discarding new packet.\n");
    return;
  }

  // Add the new packet to the array and update the sequence number
  packet_array[num_packets] = new_packet;
  packet_array[num_packets].sequence_number = num_packets + 1;

  // Increment the number of packets in the array
  num_packets++;
}

void handle_duplicate_sequence(Packet* packet_array, int num_packets, unsigned int sequence_number) {
  // Check if the given sequence number is already present in the packet array
  for (int i = 0; i < num_packets; ++i) {
    if (packet_array[i].sequence_number == sequence_number) {
      fprintf(stderr, "Duplicate sequence number detected. Discarding new packet.\n");
      return;
    }
  }
}

void handle_new_packets(Packet* packet_array, int num_packets, Packet new_packets[], int num_new_packets) {
  // Loop through the new packets and add them to the array
  for (int i = 0; i < num_new_packets; ++i) {
    handle_new_packet(packet_array, num_packets, new_packets[i]);
  }
}

void update_packet_array(Packet* packet_array, int num_packets, unsigned char protocol_version, unsigned char packet_type, unsigned int sequence_number) {
  // Check if the given sequence number is already present in the packet array
  for (int i = 0; i < num_packets; ++i) {
    if (packet_array[i].sequence_number == sequence_number) {
      // Update the protocol version, packet type, and sequence number of the existing packet
      packet_array[i].protocol_version = protocol_version;
      packet_array[i].packet_type = packet_type;
      packet_array[i].sequence_number = sequence_number;
      break;
    }
  }
}

void handle_sequential_updates(Packet* packet_array, int num_packets, unsigned char protocol_version, unsigned char packet_type, unsigned int sequence_number) {
  // Check if the given sequence number is already present in the packet array
  for (int i = 0; i < num_packets; ++i) {
    if (packet_array[i].sequence_number == sequence_number - 1) {
      update_packet_array(packet_array, num_packets, protocol_version, packet_type, sequence_number);
      break;
    }
  }
}

void handle_burst_updates(Packet* packet_array, int num_packets, unsigned char protocol_version, unsigned char packet_type, unsigned int sequence_number) {
  // Check if the given sequence number is already present in the packet array
  for (int i = 0; i < num_packets; ++i) {
    if (packet_array[i].sequence_number == sequence_number) {
      fprintf(stderr, "Burst of updates detected. Discarding new packet.\n");
      return;
    } else if (packet_array[i].sequence_number > sequence_number) {
      // Update the protocol version, packet type, and sequence number of all packets with a higher sequence number
      for (int j = i; j < num_packets; ++j) {
        packet_array[j].protocol_version = protocol_version;
        packet_array[j].packet_type = packet_type;
        packet_array[j].sequence_number = sequence_number;
      }
      break;
    }
  }
}

void handle_sequential_deletes(Packet* packet_array, int num_packets, unsigned int sequence_number) {
  // Check if the given sequence number is already present in the packet array
  for (int i = 0; i < num_packets; ++i) {
    if (packet_array[i].sequence_number == sequence_number) {
      // Delete all packets with a higher sequence number than the given one
      for (int j = i + 1; j < num_packets; ++j) {
        packet_array[j - 1] = packet_array[j];
      }
      break;
    }
  }
}

void handle_burst_deletes(Packet* packet_array, int num_packets, unsigned int sequence_number) {
  // Check if the given sequence number is already present in the packet array
  for (int i = 0; i < num_packets; ++i) {
    if (packet_array[i].sequence_number == sequence_number) {
      fprintf(stderr, "Burst of deletes detected. Discarding new packet.\n");
      return;
    } else if (packet_array[i].sequence_number > sequence_number) {
      // Delete all packets with a higher sequence number than the given one
      for (int j = i; j < num_packets; ++j) {
        packet_array[j - 1] = packet_array[j];
      }
      break;
    }
  }
}
