struct InterfaceTable {
    vector<string> metadataIpList;
    int latency;
    bool connectivityState;

    InterfaceTable() {}

    // Function to find the VM UUID from the metadata IP
    bool FindVmUuidFromMetadataIp(string metadataIp) {
        return this->metadataIpList.contains(metadataIp);
    }
};

// Define the filtering and analysis tool
class LogFilter {
public:
    vector<NFAPI_CRC_INDICATION_PDU_T> log;

    // Function to add a new entry to the log
    void AddEntry(NFAPI_CRC_INDICATION_PDU_T pdu) {
        this->log.push_back(pdu);
    }

    // Function to query the log based on specific criteria
    vector<NFAPI_CRC_INDICATION_PDU_T> QueryLog(int requestType, int responseStatus, time_t startTime) {
        vector<NFAPI_CRC_INDICATION_PDU_T> filteredLog;

        for (auto pdu : this->log) {
            if (pdu.RX_UE_INFORMATION_TAG == requestType &&
                pdu.CRCFLAG == responseStatus &&
                pdu.timeStamp >= startTime) {
                filteredLog.push_back(pdu);
            }
        }

        return filteredLog;
    }
};

// Define the main function
int main() {
    // Initialize the interface table and log filter
    InterfaceTable it;
    LogFilter lf;

    // Load the metadata IP list from a file or other source
    string metadataIpListFile = "metadata_ip_list.txt";
    ifstream ipListFile(metadataIpListFile);
    string line;
    while (getline(ipListFile, line)) {
        it.metadataIpList.push_back(line);
    }

    // Initialize the random seed for generating CRCFLAG values
    srand(time(0));

    // Generate a list of NFAPI_CRC_INDICATION_PDU_T structures using standard library functions
    vector<NFAPI_CRC_INDICATION_PDU_T> pduList;
    for (int i = 0; i < 100; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 2 + 1;
        pdu.RNTI = rand() % 1000;
        pdu.CRCFLAG = rand() % 2;
        pduList.push_back(pdu);
    }

    // Populate the log filter with the generated structures
    for (auto pdu : pduList) {
        lf.AddEntry(pdu);
    }

    // Query the log based on specific criteria and print the results
    vector<NFAPI_CRC_INDICATION_PDU_T> queryResults = lf.QueryLog(1, 0, time(0));
    for (auto pdu : queryResults) {
        cout << "RX_UE_INFORMATION_TAG: " << pdu.RX_UE_INFORMATION_TAG << endl;
        cout << "RNTI: " << pdu.RNTI << endl;
        cout << "CRCFLAG: " << pdu.CRCFLAG << endl;
