// Structure to hold a CRC indication PDU
typedef struct {
  uint32_t rx_ue_information_tag;
  uint16_t rnti;
  uint8_t crc_indication_rel8_tag;
  uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// List of CRC indication PDUs
static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu_list = NULL;
static size_t crc_indication_pdu_count = 0;

// Semaphore for controlling access to the list
static sem_t list_semaphore;

// Function to add a new CRC indication PDU to the list
void add_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
  pthread_mutex_lock(&list_lock);
  crc_indication_pdu_list = realloc(crc_indication_pdu_list, (crc_indication_pdu_count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
  memcpy(&crc_indication_pdu_list[crc_indication_pdu_count], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
  crc_indication_pdu_count++;
  pthread_mutex_unlock(&list_lock);
}

// Function to remove a CRC indication PDU from the list by RNTI
void remove_crc_indication_pdu(uint16_t rnti) {
  pthread_mutex_lock(&list_lock);
  size_t i;
  for (i = 0; i < crc_indication_pdu_count; i++) {
    if (crc_indication_pdu_list[i].rnti == rnti) {
      memcpy(&crc_indication_pdu_list[i], &crc_indication_pdu_list[crc_indication_pdu_count - 1], sizeof(NFAPI_CRC_INDICATION_PDU_T));
      crc_indication_pdu_count--;
    }
  }
  pthread_mutex_unlock(&list_lock);
}

// Function to retrieve a CRC indication PDU from the list by RNTI
NFAPI_CRC_INDICATION_PDU_T *get_crc_indication_pdu(uint16_t rnti) {
  pthread_mutex_lock(&list_lock);
  size_t i;
  for (i = 0; i < crc_indication_pdu_count; i++) {
    if (crc_indication_pdu_list[i].rnti == rnti) {
      return &crc_indication_pdu_list[i];
    }
  }
  pthread_mutex_unlock(&list_lock);
}

// Function to initialize the list and semaphore
void init_crc_indication_pdu_list() {
  crc_indication_pdu_list = NULL;
  crc_indication_pdu_count = 0;
  sem_init(&list_semaphore, 1, 1);
}

// Function to deinitialize the list and semaphore
void deinit_crc_indication_pdu_list() {
  free(crc_indication_pdu_list);
  crc_indication_pdu_list = NULL;
  crc_indication_pdu_count = 0;
  sem_destroy(&list_semaphore);
}
