    record* records;
} array_container;

array_container* allocate_memory(int num_offsets, int num_keys, int num_records) {
    // Check if the input parameters are valid and handle errors gracefully
    if (num_offsets <= 0 || num_keys <= 0 || num_records <= 0) {
        return NULL;
    }

    array_container* container = malloc(sizeof(array_container));
    if (!container) {
        // Memory allocation failed, handle error and free any allocated memory
        free(container);
        return NULL;
    }

    // Allocate memory for the offsets array
    long* offsets = malloc(num_offsets * sizeof(long));
    if (!offsets) {
        // Memory allocation failed, handle error and free any allocated memory
        free(container);
        return NULL;
    }
    container->offsets = offsets;

    // Allocate memory for the keys array
    int* keys = malloc(num_keys * sizeof(int));
    if (!keys) {
        // Memory allocation failed, handle error and free any allocated memory
        free(container);
        return NULL;
    }
    container->keys = keys;

    // Allocate memory for the records array
    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        // Memory allocation failed, handle error and free any allocated memory
        free(container);
        return NULL;
    }
    container->records = records;

    // Initialize the offsets array with values from the file "offsets.txt"
    FILE* fp = fopen("offsets.txt", "r");
    if (!fp) {
        // File could not be opened, handle error and free any allocated memory
        free(container);
        return NULL;
    }
    for (int i = 0; i < num_offsets; i++) {
        fscanf(fp, "%ld", &offsets[i]);
    }
    fclose(fp);

    // Initialize the keys array with random values within the range [0, 10000]
    srand(time(NULL));
    for (int i = 0; i < num_keys; i++) {
        keys[i] = rand() % 10000;
    }

    // Initialize the records array with random values within the range [0, 100000]
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 100000;
    }

    // Check if any of the allocations failed and handle errors gracefully
    if (!container->offsets || !container->keys || !container->records) {
        free(container);
        return NULL;
    }

    return container;
}
