// Define graph structure for storing offset values, keys, and records
typedef struct {
  long* offsets;
  int* keys;
  record* records;
} graph_t;

// Function to initialize graph with dynamic data
graph_t* initializeGraphWithDynamicData(int num_offsets, int num_keys, int num_records, int range) {
  // Allocate memory for graph structure
  graph_t* graph = (graph_t*)malloc(sizeof(graph_t));
  if (graph == NULL) {
    fprintf(stderr, "Error: failed to allocate memory for graph.\n");
    return NULL;
  }

  // Allocate memory for offset values
  graph->offsets = (long*)calloc(num_offsets, sizeof(long));
  if (graph->offsets == NULL) {
    fprintf(stderr, "Error: failed to allocate memory for offsets.\n");
    free(graph);
    return NULL;
  }

  // Allocate memory for key values
  graph->keys = (int*)calloc(num_keys, sizeof(int));
  if (graph->keys == NULL) {
    fprintf(stderr, "Error: failed to allocate memory for keys.\n");
    free(graph->offsets);
    free(graph);
    return NULL;
  }

  // Allocate memory for record structures
  graph->records = (record*)calloc(num_records, sizeof(record));
  if (graph->records == NULL) {
    fprintf(stderr, "Error: failed to allocate memory for records.\n");
    free(graph->keys);
    free(graph->offsets);
    free(graph);
    return NULL;
  }

  // Initialize offset values
  srand(time(NULL));
  for (int i = 0; i < num_offsets; i++) {
    graph->offsets[i] = rand() % range + 1;
  }

  // Initialize key values
  for (int i = 0; i < num_keys; i++) {
    graph->keys[i] = rand() % range + 1;
  }

  // Fill record structures with random integer values within specified range
  for (int i = 0; i < num_records; i++) {
    graph->records[i].value = rand() % range + 1;
  }

  return graph;
}
