    // Find the slot in the list for the given UE_ID
    for (int i = 0; i < list->size; i++) {
        if (list->data[i].UE_ID == UE_ID) {
            // Set the values of the structure to -1 to indicate it is deleted
            list->data[i].UE_ID = -1;
            list->data[i].receivedSignalStrength = -1;
            list->data[i].configuredAntennaPorts = -1;
