    // Define a temporary array for storing the sorted data
    LTE_PHY_RX_STRUCT temp[list->size];
    // Copy the data from the list to the temporary array
    memcpy(temp, list->data, sizeof(LTE_PHY_RX_STRUCT) * list->size);
    // Sort the data in the temporary array based on signal strength and UE_ID
    qsort(temp, list->size, sizeof(LTE_PHY_RX_STRUCT), compareStructs);
    // Update the list with the sorted data
