    NFAPI_RRC_CU_TRANSPORT_PDU_T* pdu_array = (NFAPI_RRC_CU_TRANSPORT_PDU_T*)malloc(n * sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T));
