    uint16_t rnti = rand() % (MAX_RNTIS - 1);

    // Check if the RNTI is unique across all calls to the function
    for (uint16_t i = 0; i < MAX_RNTIS; i++) {
        if (rnti == rntis[i]) {
            return generate_rnti(); // Recursively call the function if the RNTI is not unique
        }
