#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <sys/time.h>
#include "nfa_api.h"
#include "hashlib.h"

#define MAX_RNTI_COUNT 1024
#define HASH_BUFFER_SIZE 4096

struct NFAPI_CRC_INDICATION_PDU {
    RX_UE_INFORMATION_TAG *rxUeInformationTag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
    bool crcflag;
};

struct NFAPI_CRC_INDICATION_PDU_LIST {
    struct NFAPI_CRC_INDICATION_PDU *head;
    struct NFAPI_CRC_INDICATION_PDU *tail;
    uint32_t count;
};

struct NFAPI_UE_INFORMATION_TAG {
    RNTI_VALUE rntiValue;
    bool isValid;
};

struct NFAPI_CRCFLAG_MAP {
    struct NFAPI_CRC_INDICATION_PDU_LIST *pduList;
    uint32_t count;
};

struct NFAPI_FILE_HASH {
    FILE *fileHandle;
    off_t fileSize;
    MD5_CTX md5Ctx;
    bool isInitialized;
};

static struct NFAPI_UE_INFORMATION_TAG nfaUeInformation[MAX_RNTI_COUNT];
static struct NFAPI_CRCFLAG_MAP nfaCrcFlagMap[MAX_RNTI_COUNT];
static struct NFAPI_FILE_HASH fileHash;

/*
 * Initialize the UE information and CRC flag map.
 */
void initializeUEInformation() {
    for (uint32_t i = 0; i < MAX_RNTI_COUNT; i++) {
        nfaUeInformation[i].rntiValue = INVALID_RNTI_VALUE;
        nfaUeInformation[i].isValid = false;
    }

    for (uint32_t i = 0; i < MAX_RNTI_COUNT; i++) {
        nfaCrcFlagMap[i].pduList = NULL;
        nfaCrcFlagMap[i].count = 0;
    }
}

/*
 * Read the UE information from an external data source.
 */
void readUEInformation() {
    // Implement reading the UE information from an external data source.
    // For demonstration purposes, we'll use a static file with pre-defined UE information.
    FILE *fileHandle = fopen("ue_information.txt", "r");
    if (fileHandle == NULL) {
        printf("Error: Unable to open the UE information file.\n");
        return;
    }

    // Read the UE information from the file and populate the UE information map.
    char line[256];
    while (fgets(line, sizeof(line), fileHandle) != NULL) {
        // Parse the line to extract the RNTI value and CRC flag.
        int rntiValue = -1;
        bool crcflag = false;
        sscanf(line, "%d,%d", &rntiValue, &crcflag);

        if (rntiValue == -1 || crcflag == -1) {
            continue;
        }

        // Update the UE information map.
        nfaUeInformation[rntiValue].rntiValue = rntiValue;
        nfaUeInformation[rntiValue].isValid = true;
        nfaCrcFlagMap[rntiValue].count++;
    }
}

/*
 * Calculate the MD5 hash of a file.
 */
void calculateFileHash(FILE *fileHandle) {
    if (fileHandle == NULL) {
        return;
    }

    char buffer[HASH_BUFFER_SIZE];
    size_t bytesRead = 0;
    while ((bytesRead = fread(buffer, sizeof(char), HASH_BUFFER_SIZE, fileHandle)) > 0) {
        MD5_Update(&fileHash.md5Ctx, buffer, bytesRead);
