    struct NFAPI_CRC_INDICATION_PDU_LIST *pduList = nfaCrcFlagMap[rntiValue].pduList;
    if (pduList == NULL) {
        pduList = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_LIST));
        pduList->head = NULL;
        pduList->tail = NULL;
        pduList->count = 0;
    }

    // Create a new CRC indication PDU and append it to the list.
    struct NFAPI_CRC_INDICATION_PDU *pdu = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU));
    pdu->rntiValue = rntiValue;
    pdu->crcflag = crcflag;

    if (pduList->head == NULL) {
        // This is the first PDU in the list.
        pduList->head = pdu;
    } else {
        // Append the PDU to the end of the list.
        pduList->tail->next = pdu;
    }

    pduList->tail = pdu;
    pduList->count++;
}

/*
 * Generate a list of CRC indication PDUs for all UEs with the given CRC flag.
 */
void generateCrcIndicationPduListForAllUes(bool crcflag) {
    initializeUEInformation();
    readUEInformation();

    for (uint32_t i = 0; i < MAX_RNTI_COUNT; i++) {
        if (nfaUeInformation[i].isValid && nfaCrcFlagMap[i].count > 0) {
            generateCrcIndicationPduList(i, crcflag);
        }
    }
}

/*
