    printf("Sent %d CRC indication PDUs to the NFAPI.\n", fileHash.count);
}

int main() {
    initializeUEInformation();
    readUEInformation();

    bool crcflag = false;
    generateCrcIndicationPduListForAllUesAndSendToNfapi(crcflag);

    return 0;
}
