  uint8_t crcFlag;
} ue_info_t;

// Define a linked list node for storing UE information
typedef struct {
  ue_info_t *data;
  struct ue_list_node *next;
} ue_list_node_t;

// Define the linked list head to store all UE information
static ue_list_node_t *ue_list = NULL;

// Mutex for protecting concurrent access to the linked list
static pthread_mutex_t ue_list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new UE information entry to the linked list
void add_ue_info(uint32_t rnti, uint8_t crcFlag) {
  // Create a new node for the UE information
  ue_list_node_t *new_node = malloc(sizeof(ue_list_node_t));
  new_node->data = malloc(sizeof(ue_info_t));
  new_node->data->rnti = rnti;
  new_node->data->crcFlag = crcFlag;

  // Lock the mutex to prevent concurrent access
  pthread_mutex_lock(&ue_list_mutex);

  // Add the node to the linked list
  if (ue_list == NULL) {
    ue_list = new_node;
  } else {
    ue_list->next = new_node;
    ue_list = new_node;
  }

  // Unlock the mutex
  pthread_mutex_unlock(&ue_list_mutex);
}

// Function to remove a UE information entry from the linked list
void remove_ue_info(uint32_t rnti) {
  // Lock the mutex to prevent concurrent access
  pthread_mutex_lock(&ue_list_mutex);

  // Find the node containing the UE information to be removed
  ue_list_node_t *prev = NULL;
  ue_list_node_t *current = ue_list;
  while (current != NULL && current->data->rnti != rnti) {
    prev = current;
    current = current->next;
  }

  // Remove the node from the linked list
  if (prev == NULL) {
    ue_list = current->next;
  } else {
    prev->next = current->next;
  }

  // Free the node and its data
  free(current->data);
  free(current);

  // Unlock the mutex
  pthread_mutex_unlock(&ue_list_mutex);
}

// Function to retrieve a UE information entry from the linked list
ue_info_t *get_ue_info(uint32_t rnti) {
  // Lock the mutex to prevent concurrent access
  pthread_mutex_lock(&ue_list_mutex);

  // Find the node containing the UE information to be retrieved
  ue_list_node_t *current = ue_list;
  while (current != NULL && current->data->rnti != rnti) {
    current = current->next;
  }

  if (current == NULL) {
    // Unlock the mutex and return null
    pthread_mutex_unlock(&ue_list_mutex);
    return NULL;
  } else {
    // Unlock the mutex and return a copy of the UE information
    ue_info_t *result = malloc(sizeof(ue_info_t));
    memcpy(result, current->data, sizeof(ue_info_t));
    pthread_mutex_unlock(&ue_list_mutex);
    return result;
  }
}

// Function to validate the UE information entry
bool is_valid_ue_info(ue_info_t *ue_info) {
  // Validate that the RNTI is unique within the list
  ue_list_node_t *current = ue_list;
  while (current != NULL && current->data->rnti != ue_info->rnti) {
    current = current->next;
  }

  if (current == NULL) {
    return true;
  } else {
    return false;
  }
}

// Function to validate the CRCFlag value within a specified range
bool is_valid_crc_flag(uint8_t crcFlag, uint8_t minValue, uint8_t maxValue) {
