void init_library() {
    // Initialize OpenSSL library
    ERR_load_crypto_strings();
    EVP_add_cipher(EVP_aes_128_cbc(), "AES");
    EVP_add_cipher(EVP_camellia_128_cbc(), "Camellia");
    EVP_add_digest(EVP_md5(), "MD5");
    EVP_add_digest(EVP_sha1(), "SHA");
    EVP_add_digest(EVP_rsa(), "RSA");
}

void free_library() {
    // Free OpenSSL library resources
    ERR_free_strings();
}

struct record {
    int key;
};

int main() {
    init_library();

    // Allocate memory for long and int arrays
    long *long_array = (long *)malloc(sizeof(long) * 1000);
    if (!long_array) {
        free_library();
        return -1;
    }

    int *int_array = (int *)malloc(sizeof(int) * 100);
    if (!int_array) {
        free_library();
        return -1;
    }

    // Allocate memory for record array
    struct record *records = (struct record *)malloc(sizeof(struct record) * 100);
    if (!records) {
        free_library();
        free(long_array);
        return -1;
    }

    // Fill record array with random values
    for (int i = 0; i < 100; ++i) {
        records[i].key = RAND_bytes(sizeof(int), NULL);
    }

    // Ensure sum of int values in records does not exceed 1000
    long total = 0;
    for (int i = 0; i < 100; ++i) {
        total += records[i].key;
        if (total > 1000) {
            records[i].key -= total - 1000;
            break;
        }
    }

    // Free memory allocated for long and int arrays
    free(long_array);
    free(int_array);

    // Print record array
    for (int i = 0; i < 100; ++i) {
        printf("%d\n", records[i].key);
    }

    // Free memory allocated for record array
    free(records);

    free_library();
    return 0;
}
