// Define a structure to hold the pointers to the three arrays
struct array_pointers {
    long *offsets;
    int *unique_keys;
    record *database_records;
};

// Function to dynamically manage memory for the three arrays
struct array_pointers* allocate_arrays(int num_offsets, int num_keys, int num_records) {
    // Check if the input parameters are valid
    if (num_offsets <= 0 || num_keys <= 0 || num_records <= 0) {
        return NULL;
    }

    // Open the file containing the offsets
    FILE *offsets_file = fopen("offsets.txt", "r");
    if (!offsets_file) {
        // Handle error condition: file could not be opened
        return NULL;
    }

    // Read the number of valid offsets from the file
    int num_valid_offsets = 0;
    while (fscanf(offsets_file, "%ld", &num_valid_offsets) == 1) {
        // Increment the counter for each valid offset read from the file
        ++num_valid_offsets;
    }

    // Close the file and check if any errors occurred while reading it
    int error = fclose(offsets_file);
    if (error == EOF) {
        // Handle error condition: file could not be closed properly
        return NULL;
    }

    // Calculate the minimum of num_offsets and the number of valid offsets
    int min_num_offsets = num_offsets < num_valid_offsets ? num_offsets : num_valid_offsets;

    // Allocate memory for the three arrays
    long *offsets = (long *)malloc(min_num_offsets * sizeof(long));
    int *unique_keys = (int *)malloc(num_keys * sizeof(int));
    record *database_records = (record *)malloc(num_records * sizeof(record));

    // Check if the memory allocation was successful
    if (!offsets || !unique_keys || !database_records) {
        // Handle error condition: memory could not be allocated
        free(offsets);
        free(unique_keys);
        free(database_records);
        return NULL;
    }

    // Initialize the three arrays with random values
    for (int i = 0; i < min_num_offsets; ++i) {
        offsets[i] = rand() % 10000;
    }
    for (int i = 0; i < num_keys; ++i) {
        unique_keys[i] = rand() % 10000;
    }
    for (int i = 0; i < num_records; ++i) {
        database_records[i].value = rand() % 100000;
    }

    // Create a structure to hold the pointers to the three arrays
    struct array_pointers *array_pointers = malloc(sizeof(struct array_pointers));
    array_pointers->offsets = offsets;
    array_pointers->unique_keys = unique_keys;
    array_pointers->database_records = database_records;

    return array_pointers;
}
