#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Struct to represent network traffic statistics
struct TrafficStat {
    int packet_count;
    long byte_count;
    time_t timestamp;
};

// Dynamic array of structs for storing network traffic statistics
struct TrafficStat *stats = NULL;
size_t stats_capacity = 0; // current capacity of the dynamic array
size_t stats_len = 0; // current length of the dynamic array (number of elements)

// Initialize the dynamic array with a specified number of elements
void init_array(size_t num_elements) {
    // Allocate memory for the structs
    stats = malloc(sizeof(struct TrafficStat) * num_elements);
    if (!stats) {
        fprintf(stderr, "Error: Failed to allocate memory for network traffic statistics array\n");
        exit(EXIT_FAILURE);
    }
    // Initialize the timestamp of each struct
    for (size_t i = 0; i < num_elements; i++) {
        stats[i].timestamp = time(NULL);
    }
    // Set the capacity and length of the array
    stats_capacity = num_elements;
    stats_len = num_elements;
}

// Populate the dynamic array with incremental timestamps starting from the current time
void populate_array() {
    for (size_t i = 0; i < stats_len; i++) {
        stats[i].timestamp = time(NULL);
    }
}

// Update each statistical record based on incoming network data packets
void update_stats(struct TrafficStat *packet) {
    // Increment the packet count and byte count of the current struct
    stats[0].packet_count++;
    stats[0].byte_count += packet->len;
}

// Resize the dynamic array if the initial capacity is exceeded
void resize_array() {
    size_t new_capacity = stats_capacity * 2;
    struct TrafficStat *new_stats = realloc(stats, sizeof(struct TrafficStat) * new_capacity);
    if (!new_stats) {
        fprintf(stderr, "Error: Failed to resize network traffic statistics array\n");
        return;
    }
    stats = new_stats;
    stats_capacity = new_capacity;
}

// Error handling for memory allocation failures
void handle_alloc_failure() {
    fprintf(stderr, "Error: Failed to allocate memory for network traffic statistics array\n");
    exit(EXIT_FAILURE);
}

int main() {
    // Initialize the dynamic array with a specified number of elements
    init_array(1024);
    populate_array();

    // Update each statistical record based on incoming network data packets
    struct TrafficStat packet = { 0 };
    while (1) {
        update_stats(&packet);
        // Resize the dynamic array if the initial capacity is exceeded
        if (stats_len == stats_capacity) {
            resize_array();
        }
    }

    return 0;
}
```
This C function manages a dynamic array of custom data structures representing network traffic statistics. It has the following features:

* Initialization with a specified number of elements, using `init_array()`
* Population of each struct with incremental timestamps starting from the current time, using `populate_array()`
* Update each statistical record based on incoming network data packets, using `update_stats()`
