void init_logging(int num_loggers, int max_entries) {
  // Initialize arrays of offsets and keys with user-defined values
  long* offsets = (long*)malloc(num_loggers * sizeof(long));
  int* keys = (int*)malloc(num_loggers * sizeof(int));
  for (int i = 0; i < num_loggers; i++) {
