  pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
  pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

  // Loop forever, waiting for log requests and processing them concurrently
  while (true) {
    // Wait for a log request to arrive
    pthread_mutex_lock(&mutex);
    while (offsets[num_loggers - 1] >= max_entries - 1) {
      pthread_cond_wait(&cond, &mutex);
    }
    int logger = num_loggers - 1;
    long offset = offsets[logger];
    int key = keys[logger];
    pthread_mutex_unlock(&mutex);

    // Allocate memory for the log message and assign a unique ID
    char* message = (char*)malloc(sizeof(char) * max_entries);
    sprintf(message, "%d", key);

    // Validate and uniquify the log message if necessary
