// Structure definition for a list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} ListNode;

// Function to add a new element to the list
void addElement(ListNode** head, const NFAPI_CRC_INDICATION_PDU_T* data) {
    // Allocate memory for the new node
    ListNode* new_node = (ListNode*) malloc(sizeof(ListNode));
    if (!new_node) {
        // Handle memory allocation failure gracefully
        return;
    }

    // Copy the data into the new node
    memcpy(&new_node->data, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Insert the new node at the head of the list
    new_node->next = *head;
    *head = new_node;
}

// Function to remove an element from the list by index
void removeElement(ListNode** head, size_t index) {
    ListNode* current = *head;
    ListNode* previous = NULL;
    while (index > 0 && current != NULL) {
        previous = current;
        current = current->next;
        --index;
    }

    // If the index is invalid, return immediately
    if (current == NULL) {
        return;
    }

    // Remove the element from the list
    if (previous == NULL) {
        *head = (*head)->next;
    } else {
        previous->next = current->next;
    }

    // Free the memory for the removed node
    free(current);
}

// Function to iterate over the list in both forward and reverse order
void iterateOverList(ListNode* head, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    // Iterate over the list in forward order
    for (ListNode* current = head; current != NULL; current = current->next) {
        callback(&current->data);
    }

    // Iterate over the list in reverse order
    for (ListNode* current = head; current != NULL; current = current->next) {
        callback(&current->data);
    }
}
```
