typedef struct log_entry {
    time_t timestamp;
    int level;
    char message[256];
} log_entry_t;

log_entry_t* log_entries = NULL;
int num_log_entries = 0;
int max_log_entries = MAX_LOG_ENTRIES;
int export_freq = DEFAULT_EXPORT_FREQ;

void log(time_t timestamp, int level, const char* message) {
    // allocate new entry if necessary
    if (num_log_entries == max_log_entries) {
        max_log_entries *= 2;
        log_entry_t* new_entries = realloc(log_entries, max_log_entries);
        if (new_entries == NULL) {
            // handle error
            return;
        }
        log_entries = new_entries;
    }

    // add new entry to end of list
    log_entry_t* new_entry = &log_entries[num_log_entries++];
    new_entry->timestamp = timestamp;
    new_entry->level = level;
    strncpy(new_entry->message, message, 256);

    // check for duplicate timestamps and suppress if necessary
    int i = 0;
    while (i < num_log_entries) {
        if (log_entries[i].timestamp == timestamp) {
            // suppress duplicate entry
            log_entries[i] = log_entries[--num_log_entries];
            continue;
        }
        i++;
    }

    // export logs to external data store if necessary
    time_t current_time = time(NULL);
    if (current_time - export_freq >= timestamp) {
        // export logs here
        export_freq += DEFAULT_EXPORT_FREQ;
    }
}

void search_logs(time_t start_timestamp, time_t end_timestamp) {
