// Pool of available structures to manage
static NFAPI_CRC_INDICATION_PDU_T* pool = NULL;

// Mutex for synchronizing access to the pool
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize a new structure
NFAPI_CRC_INDICATION_PDU_T* init_structure(void) {
    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&mutex);

    // Check if there is an available structure in the pool
    if (pool == NULL || pool->next == NULL) {
        // No available structures, create a new one
        NFAPI_CRC_INDICATION_PDU_T* new_structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_structure == NULL) {
            // Memory allocation failed, return NULL
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        // Initialize the new structure
        new_structure->rnti = rand() % 65535 + 1;
        new_structure->rx_ue_information_tag = rand() % 256;

        // Set CRCFLAG to a random value
        CRC_INDICATION_REL8_T* crcflag = malloc(sizeof(CRC_INDICATION_REL8_T));
        if (crcflag == NULL) {
            // Memory allocation failed, free the new structure and return NULL
            pthread_mutex_unlock(&mutex);
            free(new_structure);
            return NULL;
        }
        crcflag->crcflag = rand() % 65535 + 1;
        crcflag->rx_ue_information_tag = new_structure->rx_ue_information_tag;

        // Add the structure to the pool
        if (pool == NULL) {
            pool = new_structure;
        } else {
            pool->next = new_structure;
        }

        // Unlock the mutex and return the newly created structure
        pthread_mutex_unlock(&mutex);
        return new_structure;
    } else {
        // There is an available structure in the pool, use it
        NFAPI_CRC_INDICATION_PDU_T* structure = pool->next;
        pool->next = structure->next;

        // Initialize the structure with a unique RNTI value and associated RX_UE_INFORMATION_TAG
        structure->rnti = rand() % 65535 + 1;
        structure->rx_ue_information_tag = rand() % 256;

        // Set CRCFLAG to a random value and associate it with the RX_UE_INFORMATION_TAG
        CRC_INDICATION_REL8_T* crcflag = malloc(sizeof(CRC_INDICATION_REL8_T));
        if (crcflag == NULL) {
            // Memory allocation failed, free the structure and return NULL
            pthread_mutex_unlock(&mutex);
            free(structure);
            return NULL;
        }
        crcflag->crcflag = rand() % 65535 + 1;
        crcflag->rx_ue_information_tag = structure->rx_ue_information_tag;

        // Unlock the mutex and return the newly created structure
        pthread_mutex_unlock(&mutex);
        return structure;
    }
}
