['```
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    MAC_RX_PDU_TAG tag;
    MAC_RLC_PDU_TAG rlc_tag;
    MAC_HEADER_T* header;
} MAC_RX_PDU_T;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t num_elements = 0;
static MAC_RX_PDU_T* elements = NULL;

void mac_rx_pdu_init(size_t initial_size) {
    pthread_mutex_lock(&mutex);
    if (initial_size > 0) {
        num_elements = initial_size;
        elements = malloc(sizeof(MAC_RX_PDU_T) * initial_size);
        memset(elements, 0, sizeof(MAC_RX_PDU_T) * initial_size);
    }
    pthread_mutex_unlock(&mutex);
}

void mac_rx_pdu_add(MAC_RX_PDU_TAG tag, MAC_RLC_PDU_TAG rlc_tag, MAC_HEADER_T* header) {
    pthread_mutex_lock(&mutex);
    if (num_elements == 0) {
        mac_rx_pdu_init(10);
    } else if (num_elements >= 2 * num_elements / 3) {
        // Resize the array when more than two-thirds are used.
        mac_rx_pdu_resize(2 * num_elements);
    }
    elements[num_elements].tag = tag;
    elements[num_elements].rlc_tag = rlc_tag;
    elements[num_elements].header = header;
    num_elements++;
    pthread_mutex_unlock(&mutex);
}

void mac_rx_pdu_remove(size_t index) {
    pthread_mutex_lock(&mutex);
    if (index < 0 || index >= num_elements) {
        pthread_mutex_unlock(&mutex);
        return;
    }
    size_t last_index = num_elements - 1;
    elements[index] = elements[last_index];
    if (last_index > 0 && last_index < num_elements / 3) {
        // Shrink the array when less than one-third are used.
        mac_rx_pdu_resize(num_elements / 2);
    }
    num_elements--;
    pthread_mutex_unlock(&mutex);
}

void mac_rx_pdu_resize(size_t new_size) {
    MAC_RX_PDU_T* new_elements = malloc(sizeof(MAC_RX_PDU_T) * new_size);
    if (new_elements == NULL) {
        // Handle allocation failure gracefully.
        return;
    }
    size_t num_to_copy = new_size < num_elements ? new_size : num_elements;
    memcpy(new_elements, elements, sizeof(MAC_RX_PDU_T) * num_to_copy);
    free(elements);
    elements = new_elements;
    num_elements = new_size;
}

void mac_rx_pdu_free() {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < num_elements; i++) {
        free(elements[i].header);
    }
    free(elements);
    elements = NULL;
    num_elements = 0;
    pthread_mutex_unlock(&mutex);
}
```
This code implements a C function that manages a dynamically allocated array of `MAC_RX_PDU_T` structures, each containing a `MAC_RX_PDU_TAG`, `MAC_RLC_PDU_TAG`, and a pointer to a dynamically allocated `MAC_HEADER_T` structure. The function provides robust error handling for allocation failures, concurrent access by multiple threads, and flexible resizing capabilities to accommodate varying workloads.

The `mac_rx_pdu_init()` function initializes the array with the specified initial size. If the initial size is greater than 0, it allocates memory for the array and sets the `num_elements` variable accordingly. It also sets the `elements` pointer to point to the allocated memory.

The `mac_rx_pdu_add()` function adds a new element to the end of the array with the specified `MAC_RX_PDU_TAG`, `MAC_RLC_PDU_TAG`, and header data. It checks if the current size is greater than or equal to half of the total allocated memory, and resizes the array if necessary before adding the new element.

The `mac_rx_pdu_remove()` function removes an element from the specified index in the array. It first copies the last element to the index being removed and then shrinks the array if less than one-third of the elements are used after the removal.

The `mac_rx_pdu_resize()` function resizes the array to the specified new size. If the new size is greater than the current size, it allocates new memory for the array and copies the existing elements into the new memory. If the new size is less than the current size, it frees unused memory.

The `mac_rx_pdu_free()` function frees all allocated memory for the array. It first acquires a lock on the mutex to prevent other threads from accessing the array while it is being freed. Then, it loops through each element in the array and frees the header data and the array itself.

This code is designed to operate within specified memory and processing limits, adapting to different operational constraints and environmental factors. Developers should be prepared to make informed decisions regarding memory management strategies, concurrency control, and performance optimization techniques to meet the requirements of the broader system.']

