typedef struct {
  NFAPI_CRC_INDICATION_PDU_T* data;
  size_t capacity;
  size_t count;
  pthread_mutex_t mutex;
} DynamicList;

DynamicList* dynamicListCreate(size_t initialCapacity) {
  DynamicList* list = malloc(sizeof(DynamicList));
  assert(list != NULL);
  list->data = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
  assert(list->data != NULL);
  list->capacity = initialCapacity;
  list->count = 0;
  pthread_mutex_init(&list->mutex, NULL);
  return list;
}

void dynamicListDestroy(DynamicList* list) {
  assert(list != NULL);
  free(list->data);
  pthread_mutex_destroy(&list->mutex);
  free(list);
}

bool dynamicListPush(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
  assert(list != NULL);
  bool success = false;
  pthread_mutex_lock(&list->mutex);
  if (list->count < list->capacity) {
    list->data[list->count] = data;
    list->count++;
    success = true;
  }
  pthread_mutex_unlock(&list->mutex);
  return success;
}

NFAPI_CRC_INDICATION_PDU_T* dynamicListPop(DynamicList* list) {
  assert(list != NULL);
  NFAPI_CRC_INDICATION_PDU_T* data = NULL;
  pthread_mutex_lock(&list->mutex);
  if (list->count > 0) {
    data = &list->data[list->count - 1];
    list->count--;
  }
  pthread_mutex_unlock(&list->mutex);
  return data;
}

void dynamicListClear(DynamicList* list) {
  assert(list != NULL);
  pthread_mutex_lock(&list->mutex);
  list->count = 0;
  pthread_mutex_unlock(&list->mutex);
}

bool dynamicListResize(DynamicList* list, size_t newCapacity) {
  assert(list != NULL);
  bool success = false;
  pthread_mutex_lock(&list->mutex);
  if (newCapacity > 0 && newCapacity >= list->count) {
    NFAPI_CRC_INDICATION_PDU_T* newData = malloc(newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    assert(newData != NULL);
    memcpy(newData, list->data, list->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    free(list->data);
    list->data = newData;
    list->capacity = newCapacity;
    success = true;
  }
  pthread_mutex_unlock(&list->mutex);
  return success;
}

bool dynamicListReallocate(DynamicList* list, size_t newCount) {
  assert(list != NULL);
  bool success = false;
  pthread_mutex_lock(&list->mutex);
  if (newCount > 0 && newCount <= list->capacity) {
    NFAPI_CRC_INDICATION_PDU_T* newData = realloc(list->data, newCount * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    assert(newData != NULL);
    memcpy(newData, list->data, newCount * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    free(list->data);
    list->data = newData;
    list->count = newCount;
    success = true;
  }
  pthread_mutex_unlock(&list->mutex);
  return success;
}
