void allocate_and_manage_crc_indications(int N) {
  // Allocate an array of size N for storing CRC indication PDUs
  NFAPI_CRC_INDICATION_PDU* pdu_array = (NFAPI_CRC_INDICATION_PDU*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU));

