    pdu_array[i].crc_rnti = RNTI(rand());
    pdu_array[i].crcf = CRCFLAG(rand());
  }

  // Dynamically resize the array based on external data feeds
  while (true) {
    // Handle periodic updates to the CRC flag values
    for (int i = 0; i < N; i++) {
      pdu_array[i].crcf = CRCFLAG(rand());
    }

    // Periodically re-evaluate the allocated memory usage and adjust the size of the array if necessary
    int current_size = N;
    while (true) {
      // Check if there is enough memory to allocate a new PDU
      int required_size = current_size + 1;
      if (required_size <= current_size) {
        break;
      }

      // Reallocate the array with a larger size
      NFAPI_CRC_INDICATION_PDU* new_array = (NFAPI_CRC_INDICATION_PDU*)realloc(pdu_array, required_size * sizeof(NFAPI_CRC_INDICATION_PDU));
      if (new_array == NULL) {
        break;
      }

      // Update the pointer and size variables
      pdu_array = new_array;
      current_size = required_size;
    }
  }

  // Free the memory allocated for the array
  free(pdu_array);
}']

