typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned long long RNTI;
    unsigned short CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct NFAPI_CRC_INDICATION_LIST {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    struct NFAPI_CRC_INDICATION_LIST *next;
};

typedef struct NFAPI_CRC_INDICATION_LIST_HEADER {
    pthread_mutex_t mutex;
    int size;
    struct NFAPI_CRC_INDICATION_LIST *head;
} NFAPI_CRC_INDICATION_LIST_HEADER;

int nfapi_crc_indication_list_init(NFAPI_CRC_INDICATION_LIST_HEADER *header) {
    if (!header) return -1;
    header->mutex = PTHREAD_MUTEX_INITIALIZER;
    header->size = 0;
    header->head = NULL;
    return 0;
}

int nfapi_crc_indication_list_append(NFAPI_CRC_INDICATION_LIST_HEADER *header, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!header || !pdu) return -1;

    // Acquire mutex to prevent race conditions
    pthread_mutex_lock(&(header->mutex));

    // Allocate memory for the new PDU
    NFAPI_CRC_INDICATION_LIST *new = malloc(sizeof(NFAPI_CRC_INDICATION_LIST));
    if (!new) {
        pthread_mutex_unlock(&(header->mutex));
        return -1;
    }

    // Initialize the new PDU and link it to the end of the list
    new->pdu = pdu;
    new->next = NULL;
    if (header->head) {
        header->tail->next = new;
        header->tail = new;
    } else {
        header->head = new;
        header->tail = new;
    }

    // Increment the size of the list
    header->size++;

    // Release mutex
    pthread_mutex_unlock(&(header->mutex));

    return 0;
}

int nfapi_crc_indication_list_clear(NFAPI_CRC_INDICATION_LIST_HEADER *header) {
    if (!header) return -1;

    // Acquire mutex to prevent race conditions
    pthread_mutex_lock(&(header->mutex));

    // Release all resources associated with the list
    NFAPI_CRC_INDICATION_LIST *curr = header->head;
    while (curr) {
        NFAPI_CRC_INDICATION_LIST *next = curr->next;
        free(curr);
        curr = next;
    }

    // Reset the list size and head/tail pointers
    header->size = 0;
    header->head = NULL;
    header->tail = NULL;

    // Release mutex
    pthread_mutex_unlock(&(header->mutex));

    return 0;
}
