// Function to dynamically allocate memory for and initialize arrays of long and int offsets and keys
void init_metadata(long *offset_array, int *key_array, int num_records) {
    // Generate a unique temporary directory name
    GENERATE_TMP_DIR("tempdir-");

    // Allocate memory for the offset array
    offset_array = malloc(num_records * sizeof(long));

    // Initialize each offset value to 0
    long i;
    for (i = 0; i < num_records; i++) {
        offset_array[i] = 0L;
    }

    // Allocate memory for the key array
    key_array = malloc(num_records * sizeof(int));

    // Initialize each key value randomly within a specified range using a provided seed for reproducibility
    srand(1234); // Replace with a suitable seed value
    int j;
    for (j = 0; j < num_records; j++) {
        key_array[j] = rand() % 100;
    }
}

// Function to clean up the temporary directory and free memory allocated by init_metadata
void cleanup(long *offset_array, int *key_array) {
    // Remove the temporary directory created for storing metadata
    rmdir(getenv("TMPDIR"));

    // Free the memory allocated for the offset array
    free(offset_array);

    // Free the memory allocated for the key array
