void removeElement(NFAPI_CRC_INDICATION_PDU_T *elem) {
    // Acquire the mutex
    pthread_mutex_lock(&mutex);

    // If the list is empty, return immediately
    if (head == NULL) {
        pthread_mutex_unlock(&mutex);
        return;
    }

    // If the element is at the head of the list, set the new head and release the mutex
    if (head->data == elem) {
        ListNode *newHead = head->next;
        free(head);
        head = newHead;
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Search for the element in the list and remove it if found
    ListNode *currNode = head;
    while (currNode->next != NULL) {
        if (currNode->next->data == elem) {
            ListNode *prevNode = currNode;
            ListNode *delNode = currNode->next;
            prevNode->next = delNode->next;
            free(delNode);
            pthread_mutex_unlock(&mutex);
            return;
        }
        currNode = currNode->next;
    }

    // If the element was not found in the list, release the mutex and log an error
    fprintf(stderr, "Element %p not found in list\n", elem);
    pthread_mutex_unlock(&mutex);
}

// Define a function to get the size of the list
size_t getSize() {
    // Acquire the mutex
    pthread_mutex_lock(&mutex);

