        std::string::size_type dotPos = inputPath.rfind('.');
        if (dotPos == std::string::npos) {
            return "";
        }

        std::string extension = inputPath.substr(dotPos + 1);
        std::transform(extension.begin(), extension.end(), extension.begin(), ::tolower);
        if (supportedFormats.find(extension) != supportedFormats.end()) {
            return extension;
        } else {
            return "";
        }
    }

    // Read the contents of a file into a byte array
    std::vector<unsigned char> readFile(std::string inputPath) {
        // Check if the input path is valid
        if (!inputPath.length()) {
            return {};
        }

        // Open the file and read its contents into a vector of bytes
        int fd = open(inputPath.c_str(), O_RDONLY);
        if (fd < 0) {
            return {};
        }

        std::vector<unsigned char> buffer;
        size_t fileSize = lseek(fd, 0, SEEK_END);
        buffer.resize(fileSize);
        lseek(fd, 0, SEEK_SET);
        ssize_t bytesRead = read(fd, buffer.data(), buffer.size());
        close(fd);
        if (bytesRead < 0) {
            return {};
        }

        return buffer;
    }
};
