// Define the record structure
typedef struct {
    long offset;
    int key;
    int value;
} record_t;

// Define the hash map to track memory usage
typedef struct {
    size_t capacity;
    size_t count;
    record_t **records;
} hashmap_t;

// Initialize the hash map
void initialize_hashmap(hashmap_t *hashmap) {
    // Allocate memory for the hash map
    hashmap->capacity = 1000;
    hashmap->count = 0;
    hashmap->records = malloc(sizeof(record_t*) * hashmap->capacity);
}

// Add a new record to the hash map
void add_record_to_hashmap(hashmap_t *hashmap, long offset, int key, int value) {
    // Check if the hash map needs to be resized
    if (hashmap->count == hashmap->capacity) {
        // Resize the hash map by 10%
        hashmap->capacity += hashmap->capacity / 10;
        hashmap->records = realloc(hashmap->records, sizeof(record_t*) * hashmap->capacity);
    }

    // Allocate memory for the new record
    record_t *new_record = malloc(sizeof(record_t));
    new_record->offset = offset;
    new_record->key = key;
    new_record->value = value;

    // Add the new record to the hash map
    hashmap->records[hashmap->count++] = new_record;
}

// Free the resources of a record
void free_record(record_t *record) {
    free(record);
}

// Free the resources of all records in the hash map
void free_all_records(hashmap_t *hashmap) {
    for (size_t i = 0; i < hashmap->count; i++) {
        record_t *record = hashmap->records[i];
        free_record(record);
    }
}

// Find a record in the hash map
void find_record(hashmap_t *hashmap, long offset, int key) {
    // Iterate over the records in the hash map
    for (size_t i = 0; i < hashmap->count; i++) {
        record_t *record = hashmap->records[i];
        if (record->offset == offset && record->key == key) {
            // Found the record, return it
            printf("Found record with offset %ld and key %d\n", record->offset, record->key);
            return;
        }
    }

    // Record not found, print an error message
    printf("Record not found\n");
}

// Update a record in the hash map
void update_record(hashmap_t *hashmap, long offset, int key, int value) {
    // Iterate over the records in the hash map
    for (size_t i = 0; i < hashmap->count; i++) {
        record_t *record = hashmap->records[i];
        if (record->offset == offset && record->key == key) {
            // Found the record, update its value
            record->value = value;
            return;
        }
    }

    // Record not found, print an error message
    printf("Record not found\n");
}

// Delete a record from the hash map
void delete_record(hashmap_t *hashmap, long offset, int key) {
    // Iterate over the records in the hash map
    for (size_t i = 0; i < hashmap->count; i++) {
        record_t *record = hashmap->records[i];
        if (record->offset == offset && record->key == key) {
            // Found the record, delete it
            free(record);
            hashmap->count--;
            return;
        }
    }

    // Record not found, print an error message
    printf("Record not found\n");
}

// Allocate and initialize the records array
void allocate_and_initialize_records(size_t N) {
    // Initialize the hash map for memory usage tracking
    hashmap_t *hashmap = malloc(sizeof(hashmap_t));
    initialize_hashmap(hashmap);

    // Allocate memory for the records array
    record_t **records = malloc(sizeof(record_t*) * N);

    // Initialize each record with a random key and value
    srand(time(NULL));
    for (size_t i = 0; i < N; i++) {
        record_t *record = malloc(sizeof(record_t));
        record->offset = rand() % 10000;
        record->key = rand() % 10000;
        record->value = rand() % 10000;
        records[i] = record;
    }

    // Add each record to the hash map
    for (size_t i = 0; i < N; i++) {
        add_record_to_hashmap(hashmap, records[i]->offset, records[i]->key, records[i]->value);
    }
}
```
