#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <assert.h>
#include <stdbool.h>

// Define the item structure
typedef struct {
    char *str;
    unsigned int id;
} item_t;

// Define a hash set for quick duplicate checks
typedef struct {
    item_t **items;
    size_t capacity;
    size_t count;
} hash_set_t;

// Define the collection structure
typedef struct {
    item_t *items;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} collection_t;

// Initialize a new hash set with a given capacity
hash_set_t *hash_set_init(size_t capacity) {
    hash_set_t *hs = malloc(sizeof(hash_set_t));
    hs->items = calloc(capacity, sizeof(item_t*));
    hs->capacity = capacity;
    hs->count = 0;
    return hs;
}

// Add an item to the hash set
void hash_set_add(hash_set_t *hs, item_t *item) {
    size_t index = hash_code(item->str);
    while (hs->items[index]) {
        if (strcmp(hs->items[index]->str, item->str) == 0) {
            // Duplicate string, do nothing
            return;
        }
        index = (index + 1) % hs->capacity;
    }
    hs->items[index] = malloc(sizeof(item_t));
    memcpy(hs->items[index], item, sizeof(item_t));
    hs->count++;
}

// Check if an item exists in the hash set
bool hash_set_contains(hash_set_t *hs, const char *str) {
    size_t index = hash_code(str);
    while (hs->items[index]) {
        if (strcmp(hs->items[index]->str, str) == 0) {
            // Match found
            return true;
        }
        index = (index + 1) % hs->capacity;
    }
    // No match found
    return false;
}

// Free the hash set and all associated items
void hash_set_free(hash_set_t *hs) {
    for (size_t i = 0; i < hs->count; i++) {
        free(hs->items[i]);
    }
    free(hs->items);
    free(hs);
}

// Initialize a new collection with a given capacity
collection_t *collection_init(size_t capacity) {
    collection_t *c = malloc(sizeof(collection_t));
    c->items = calloc(capacity, sizeof(item_t));
    c->capacity = capacity;
    c->count = 0;
    pthread_mutex_init(&c->mutex, NULL);
    return c;
}

// Add an item to the collection
void collection_add(collection_t *c, const char *str, unsigned int id) {
    size_t index = 0;
    while (index < c->count && strcmp(c->items[index].str, str) != 0) {
        index++;
    }
    if (index == c->count) {
        // New item
        pthread_mutex_lock(&c->mutex);
        if (c->count < c->capacity) {
            item_t *item = malloc(sizeof(item_t));
            item->str = strdup(str);
            item->id = id;
            c->items[index] = item;
            c->count++;
        } else {
            // Capacity reached, reallocate the collection
            size_t new_capacity = c->capacity * 2;
            item_t *new_items = calloc(new_capacity, sizeof(item_t));
            for (size_t i = 0; i < index; i++) {
                new_items[i] = c->items[i];
            }
            free(c->items);
            c->items = new_items;
            c->capacity = new_capacity;
            item_t *item = malloc(sizeof(item_t));
            item->str = strdup(str);
            item->id = id;
            c->items[index] = item;
            c->count++;
        }
        pthread_mutex_unlock(&c->mutex);
    } else {
        // Item already exists, update the ID
        item_t *item = &c->items[index];
        item->id = id;
    }
}

// Get an item from the collection by its ID
item_t *collection_get(collection_t *c, unsigned int id) {
    for (size_t i = 0; i < c->count; i++) {
        if (c->items[i].id == id) {
            return &c->items[i];
        }
    }
    // Item not found
    return NULL;
}

// Free the collection and all associated items
void collection_free(collection_t *c) {
    for (size_t i = 0; i < c->count; i++) {
        free(c->items[i].str);
    }
    pthread_mutex_destroy(&c->mutex);
    free(c->items);
    free(c);
}

// Generate a random alphanumeric string of the given length
char *random_string(size_t length) {
    char *str = malloc(length + 1);
    for (size_t i = 0; i < length; i++) {
        str[i] = 'A' + ((unsigned int)rand() % ('Z' - 'A'));
    }
    str[length] = '\0';
    return str;
}

// Main function for populating the collection with random strings
int main() {
    // Initialize the hash set and the collection
    size_t capacity = 16;
    hash_set_t *hs = hash_set_init(capacity);
    collection_t *c = collection_init(capacity);

    // Populate the collection with random strings
    for (size_t i = 0; i < capacity; i++) {
        char *str = random_string((unsigned int)rand() % 32);
        unsigned int id = rand();
        if (!hash_set_contains(hs, str)) {
            item_t item = { str, id };
            hash_set_add(hs, &item);
            collection_add(c, str, id);
        } else {
            // Duplicate string, try again
            i--;
        }
    }

    // Free the hash set and the collection
    hash_set_free(hs);
    collection_free(c);

    return 0;
}"]

