#include "DataPacket.h"

// Structure for holding the data packets
struct DataPacket {
    int packetID;
    char* payload;
    time_t timestamp;
};

// Array to hold the data packets
static struct DataPacket** dataPackets = NULL;

// Lock for protecting access to the data packets array
static pthread_mutex_t dataPacketsLock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize and populate an array of data packets
void initDataPackets(int numPackets) {
    // Allocate memory for the array of data packets
    dataPackets = malloc(numPackets * sizeof(struct DataPacket*));
    if (!dataPackets) {
        fprintf(stderr, "Error: failed to allocate memory for data packets\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the array of data packets with null pointers
    int i;
    for (i = 0; i < numPackets; i++) {
        dataPackets[i] = NULL;
    }
}

// Function to add a new data packet to the array
void addDataPacket(int packetID, char* payload, time_t timestamp) {
    // Lock the data packets array to prevent concurrent access
    pthread_mutex_lock(&dataPacketsLock);

    // Check if the packet ID is already in use
    int i;
    for (i = 0; i < numPackets; i++) {
        if (dataPackets[i] && dataPackets[i]->packetID == packetID) {
            fprintf(stderr, "Error: packet ID %d is already in use\n", packetID);
            exit(EXIT_FAILURE);
        }
    }

    // Allocate memory for the new data packet
    struct DataPacket* newPacket = malloc(sizeof(struct DataPacket));
    if (!newPacket) {
        fprintf(stderr, "Error: failed to allocate memory for new data packet\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the new data packet with the given values
    newPacket->packetID = packetID;
    newPacket->payload = payload;
    newPacket->timestamp = timestamp;

    // Add the new data packet to the array
    int i;
    for (i = 0; i < numPackets; i++) {
        if (!dataPackets[i]) {
            dataPackets[i] = newPacket;
            break;
        }
    }

    // Unlock the data packets array to allow other threads to access it
    pthread_mutex_unlock(&dataPacketsLock);
}

// Function to retrieve a data packet from the array by its ID
struct DataPacket* getDataPacket(int packetID) {
    // Lock the data packets array to prevent concurrent access
    pthread_mutex_lock(&dataPacketsLock);

    // Find the data packet with the given ID
    int i;
    for (i = 0; i < numPackets; i++) {
        if (dataPackets[i] && dataPackets[i]->packetID == packetID) {
            break;
        }
    }

    // Return the data packet, or NULL if not found
    struct DataPacket* packet = NULL;
    if (i < numPackets) {
        packet = dataPackets[i];
    }

    // Unlock the data packets array to allow other threads to access it
    pthread_mutex_unlock(&dataPacketsLock);

    return packet;
}

// Function to free the memory of a data packet
void freeDataPacket(struct DataPacket* packet) {
    // Lock the data packets array to prevent concurrent access
    pthread_mutex_lock(&dataPacketsLock);

    // Find the data packet in the array and remove it
    int i;
    for (i = 0; i < numPackets; i++) {
        if (dataPackets[i] == packet) {
            dataPackets[i] = NULL;
            break;
        }
    }

    // Free the memory of the data packet
    free(packet);

    // Unlock the data packets array to allow other threads to access it
    pthread_mutex_unlock(&dataPacketsLock);
}
```
This code creates an array of `DataPacket` structures, which can be accessed and modified concurrently by multiple threads. The `addDataPacket` function adds a new data packet to the array, while the `getDataPacket` function retrieves a data packet from the array by its ID. The `freeDataPacket` function frees the memory of a data packet that is no longer needed.

The code uses a lock on the data packets array to ensure thread safety during packet creation and retrieval. This ensures that multiple threads can access the array simultaneously without conflicting with each other.

The `initDataPackets` function initializes the array of data packets by allocating memory for it and setting all elements to null pointers. The `addDataPacket` function adds a new data packet to the array by first checking if the packet ID is already in use, then allocating memory for the new data packet, initializing its fields, and adding it to the array. The `getDataPacket` function retrieves a data packet from the array by finding the element with the given ID and returning its pointer. The `freeDataPacket` function frees the memory of a data packet that is no longer needed by removing it from the array and freeing its memory.

The code uses dynamic allocation to manage memory for the data packets, which allows for efficient memory management and minimizes cache locality issues. The `numPackets` variable tracks the total number of packets created, which can be accessed externally for monitoring purposes.

Overall, this code design is scalable and efficient, with low latency during frequent read and write operations due to its use of locks and dynamic allocation. It also provides easy integration with existing logging and monitoring systems.']

