void populate_crc_indications(uint32_t pseudo_seed) {
    // Initialize the array of structures with unique RX_UE_INFORMATION_TAG values
    for (int i = 0; i < N; i++) {
        crc_indications[i].RX_UE_INFORMATION_TAG = i + 1;
    }

    // Generate the RNTI values using a custom hash function
    uint32_t rnti_seed = pseudo_seed;
    for (int i = 0; i < N; i++) {
        crc_indications[i].RNTI = generate_rnti(rnti_seed);
    }

    // Populate the CRCFLAG field using a non-linear distribution of values
    for (int i = 0; i < N; i++) {
        crc_indications[i].CRCFLAG = generate_crcflag(i, N);
    }
}

uint32_t generate_rnti(uint32_t seed) {
    // Use a custom hash function to generate the RNTI value
    uint32_t rnti;
    do {
        rnti = (seed * 1664525 + 1013904223) % 281474976710656;
        seed++;
    } while (rnti >= N);
    return rnti;
}

bool generate_crcflag(uint32_t index, uint32_t size) {
    // Use a custom hash function to generate the CRCFLAG value
    uint32_t crcflag;
    do {
        crcflag = (index * 1664525 + 1013904223) % 281474976710656;
        index++;
    } while (crcflag >= size);
    return crcflag % 2 == 0 ? true : false;
}

void cleanup_crc_indications() {
    // Free the memory allocated for the array of structures
    free(crc_indications);
}
