#include <stdlib.h>
#include <stdio.h>
#include <string.h>

// Custom memory pool to minimize fragmentation and optimize performance under high-throughput conditions
struct MemoryPool {
    struct MemoryBlock *head;
    size_t used_memory;
};

struct MemoryBlock {
    struct MemoryBlock *next;
    void *data;
};

// Initialize the memory pool with a predefined capacity
void mempool_init(struct MemoryPool *pool, size_t capacity) {
    // Allocate memory for the memory pool and its header
    pool->head = (struct MemoryBlock *) malloc(sizeof(struct MemoryBlock) + capacity);
    if (!pool->head) {
        printf("Error: Failed to allocate memory for the memory pool\n");
        return;
    }
    pool->used_memory = 0;
}

// Allocate a block of memory from the memory pool
void *mempool_alloc(struct MemoryPool *pool, size_t size) {
    // Check if there is enough space in the memory pool to allocate the requested size
    if (pool->used_memory + size > capacity) {
        printf("Error: Not enough space in the memory pool\n");
        return NULL;
    }
    // Allocate a block of memory from the memory pool and update the used memory
    struct MemoryBlock *block = (struct MemoryBlock *) malloc(sizeof(struct MemoryBlock) + size);
    if (!block) {
        printf("Error: Failed to allocate memory for the new block\n");
        return NULL;
    }
    block->next = pool->head;
    pool->head = block;
    pool->used_memory += size;
    return (void *) ((char *) block + sizeof(struct MemoryBlock));
}

// Free a block of memory from the memory pool
void mempool_free(struct MemoryPool *pool, void *data) {
    // Find the block of memory that corresponds to the given data pointer
    struct MemoryBlock *block = (struct MemoryBlock *) ((char *) data - sizeof(struct MemoryBlock));
    if (!block) {
        printf("Error: Failed to find the block of memory\n");
        return;
    }
    // Free the block of memory and update the used memory
    free(block);
    pool->used_memory -= block->size;
}

// Custom RX buffer structure to store received packets
struct RxBuffer {
    struct MemoryPool *pool;
    size_t capacity;
    size_t count;
};

// Initialize the RX buffer with a predefined capacity
void rxbuffer_init(struct RxBuffer *buffer, size_t capacity) {
    // Allocate memory for the RX buffer and its header
    buffer->pool = (struct MemoryPool *) malloc(sizeof(struct MemoryPool));
    if (!buffer->pool) {
        printf("Error: Failed to allocate memory for the RX buffer\n");
        return;
    }
    mempool_init(buffer->pool, capacity);
    buffer->capacity = capacity;
    buffer->count = 0;
}

// Add a new packet to the RX buffer
void rxbuffer_add(struct RxBuffer *buffer, struct MAC_RX_PDU_T *pdu) {
    // Allocate memory for the new packet and copy its data
    void *data = mempool_alloc(buffer->pool, sizeof(struct MAC_RX_PDU_T));
    if (!data) {
        printf("Error: Failed to allocate memory for the new packet\n");
        return;
    }
    struct MAC_RX_PDU_T *new_pdu = (struct MAC_RX_PDU_T *) data;
    memcpy(new_pdu, pdu, sizeof(struct MAC_RX_PDU_T));
    // Add the new packet to the RX buffer and update its count
    buffer->count++;
}

// Remove a packet from the RX buffer
void rxbuffer_remove(struct RxBuffer *buffer) {
    // Find the oldest packet in the RX buffer and remove it
    struct MemoryBlock *block = buffer->pool->head;
    while (block) {
        if (block->next == NULL) {
            break;
        }
        block = block->next;
    }
    // Free the memory of the removed packet and update the used memory
    mempool_free(buffer->pool, block->data);
    buffer->count--;
}

