// Function to initialize the cryptographic context
int init_crypt(crypt_context_t *ctx, int cipher_mode, int backend_library) {
    // Check if the requested cipher mode and backend library are supported
    if (cipher_mode < MODE_ECB || cipher_mode > MODE_CFB) {
        printf("Invalid cipher mode specified\n");
        return -1;
    }
    if (backend_library != BACKEND_OPENSSL && backend_library != BACKEND_INTERNAL) {
        printf("Invalid backend library specified\n");
        return -2;
    }

    // Initialize the context with the requested cipher mode and backend library
    ctx->cipher_mode = cipher_mode;
    ctx->backend_library = backend_library;
    if (ctx->backend_library == BACKEND_OPENSSL) {
        ctx->evp_ctx = EVP_CIPHER_CTX_new();
    } else {
        // Initialize the internal library for the requested cipher mode
        if (cipher_mode == MODE_ECB) {
            // ECB mode uses a single round of encryption
            int rounds = 1;
            init_internal(ctx, &rounds);
        } else {
            // EDE and EDE3 modes use multiple rounds of encryption
            int rounds = cipher_mode == MODE_EDE ? 2 : 3;
            init_internal(ctx, &rounds);
        }
    }

    return 0;
}

// Function to encrypt or decrypt data using the cryptographic context
int crypt(crypt_context_t *ctx, unsigned char *input, int input_len, unsigned char *output) {
    // Check if the input length is valid
    if (input_len < 0 || input_len > 16384) {
        printf("Invalid input length\n");
        return -1;
    }

    // Allocate memory for the output buffer
    int output_len = input_len + 16;
    unsigned char *output_buf = (unsigned char *)malloc(output_len);
    if (!output_buf) {
        printf("Failed to allocate memory for output buffer\n");
        return -2;
    }

    // Perform the encryption or decryption operation
    int ret = 0;
    if (ctx->backend_library == BACKEND_OPENSSL) {
        // Use OpenSSL for encryption and decryption
        ret = EVP_Cipher(ctx->evp_ctx, output, input, input_len);
    } else {
        // Use the internal library for encryption and decryption
        int rounds = ctx->cipher_mode == MODE_ECB ? 1 : ctx->cipher_mode;
        ret = encrypt_decrypt(ctx, output, input, input_len, rounds);
    }
    if (ret < 0) {
        printf("Cryptographic operation failed\n");
        free(output_buf);
        return -3;
    }

    // Copy the output buffer to the user-supplied buffer
    memcpy(output, output_buf, ret);
    free(output_buf);

    return ret;
}

// Function to finalize the cryptographic context and release resources
int fini_crypt(crypt_context_t *ctx) {
    // Check if the context is valid
    if (!ctx) {
        printf("Invalid cryptographic context\n");
        return -1;
    }

    // Finalize the OpenSSL cipher context if it exists
    if (ctx->backend_library == BACKEND_OPENSSL && ctx->evp_ctx) {
