// C code to manage a dynamic list of TCP connection events

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for a TCP connection event
typedef struct {
    int id;
    long timestamp;
    char* event_type;
} TCPConnectionEvent;

// Define the list data structure to hold the TCP connection events
typedef struct {
    int size;
    int capacity;
    TCPConnectionEvent* events;
} TCPConnectionEventList;

// Function to initialize a new TCP connection event list
void tcp_event_list_init(TCPConnectionEventList* list) {
    list->size = 0;
    list->capacity = 16; // initial capacity of 16 events
    list->events = (TCPConnectionEvent*)malloc(sizeof(TCPConnectionEvent) * list->capacity);
}

// Function to add a new TCP connection event to the list
void tcp_event_list_add(TCPConnectionEventList* list, int id, long timestamp, char* event_type) {
    // Check if we need to resize the list
    if (list->size == list->capacity) {
        list->capacity *= 2; // double the capacity
        TCPConnectionEvent* new_events = (TCPConnectionEvent*)malloc(sizeof(TCPConnectionEvent) * list->capacity);
        memcpy(new_events, list->events, sizeof(TCPConnectionEvent) * list->size);
        free(list->events);
        list->events = new_events;
    }

    // Add the event to the list
    TCPConnectionEvent* event = &list->events[list->size];
    event->id = id;
    event->timestamp = timestamp;
    strcpy(event->event_type, event_type);
    list->size++;
}

// Function to remove a TCP connection event from the list by ID
void tcp_event_list_remove(TCPConnectionEventList* list, int id) {
    // Find the index of the event with the specified ID
    int i;
    for (i = 0; i < list->size; i++) {
        if (list->events[i].id == id) {
            break;
        }
    }

    // If the event was found, remove it from the list
    if (i < list->size) {
        TCPConnectionEvent* event = &list->events[i];
        memmove(event, event + 1, sizeof(TCPConnectionEvent) * (list->size - i));
        list->size--;
    }
}

// Function to free the memory used by a TCP connection event list
void tcp_event_list_free(TCPConnectionEventList* list) {
    if (list->events != NULL) {
        free(list->events);
    }
}

// Thread-safe wrapper function for adding a new TCP connection event to the list
void tcp_event_add(int id, long timestamp, char* event_type) {
    pthread_mutex_lock(&tcp_event_list.mutex);
    tcp_event_list_add(&tcp_event_list, id, timestamp, event_type);
    pthread_mutex_unlock(&tcp_event_list.mutex);
}

// Thread-safe wrapper function for removing a TCP connection event from the list by ID
void tcp_event_remove(int id) {
    pthread_mutex_lock(&tcp_event_list.mutex);
    tcp_event_list_remove(&tcp_event_list, id);
    pthread_mutex_unlock(&tcp_event_list.mutex);
}

// Function to handle a TCP connection event and log it
void tcp_event_handle(int id, long timestamp, char* event_type) {
    // Add the event to the list
    tcp_event_add(id, timestamp, event_type);

    // Log the event
    printf("TCP Connection Event: %d, %ld, %s\n", id, timestamp, event_type);
}

// Function to integrate with an existing logging framework
void tcp_event_log(int id, long timestamp, char* event_type) {
    // Handle the event and log it
    tcp_event_handle(id, timestamp, event_type);

    // Update the number of events logged and the total time spent processing events
    pthread_mutex_lock(&tcp_event_log.mutex);
    tcp_event_log.num_events++;
    tcp_event_log.total_time += (get_time() - timestamp);
    pthread_mutex_unlock(&tcp_event_log.mutex);
}

// Function to handle TCP connection events and log them using the logging framework
void tcp_event_handle_and_log(int id, long timestamp, char* event_type) {
    // Handle the event
    tcp_event_handle(id, timestamp, event_type);

    // Log the event using the existing logging framework
    log_event(id, timestamp, event_type);
}

// Function to handle TCP connection events and update the monitoring system with periodic updates of processed events
void tcp_event_handle_and_update_monitoring(int id, long timestamp, char* event_type) {
    // Handle the event
    tcp_event_handle(id, timestamp, event_type);

    // Update the monitoring system with periodic updates of processed events
    if (get_time() % 10 == 0) { // update every 10 seconds
        update_monitoring_system(tcp_event_list.num_events, tcp_event_log.total_time);
    }
}

// Function to handle TCP connection events and update the monitoring system with periodic updates of processed events in a thread-safe manner
void tcp_event_handle_and_update_monitoring_thread_safe(int id, long timestamp, char* event_type) {
    // Handle the event
    pthread_mutex_lock(&tcp_event_list.mutex);
    tcp_event_handle(id, timestamp, event_type);
    pthread_mutex_unlock(&tcp_event_list.mutex);

    // Update the monitoring system with periodic updates of processed events in a thread-safe manner
    if (get_time() % 10 == 0) { // update every 10 seconds
        pthread_mutex_lock(&monitoring_system.mutex);
        monitoring_system.num_events = tcp_event_list.num_events;
        monitoring_system.total_time = tcp_event_log.total_time;
        pthread_mutex_unlock(&monitoring_system.mutex);
    }
}
```
