void manageList(struct NFAPI_CRC_INDICATION_PDU_T* newElement) {
    // Lock the list mutex to prevent concurrent access
    pthread_mutex_lock(&listMutex);

    if (newElement == NULL) {
        pthread_mutex_unlock(&listMutex);
        return;
    }

    // If the list is empty, allocate memory for the new element
    if (list == NULL) {
        list = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
        if (list == NULL) {
            pthread_mutex_unlock(&listMutex);
