        struct NFAPI_CRC_INDICATION_PDU_T* current = list;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
        if (current->next == NULL) {
            pthread_mutex_unlock(&listMutex);
            // Log error message and release allocated resources
            return;
        }
    }

    // Copy data from the new element to the list
    struct NFAPI_CRC_INDICATION_PDU_T* current = list;
    while (current != NULL) {
        if (current->next == NULL) {
            break;
        }
        current = current->next;
    }
    memcpy(current, newElement, sizeof(struct NFAPI_CRC_INDICATION_PDU_T));

    // Unlock the list mutex and release allocated resources
    pthread_mutex_unlock(&listMutex);
}

void* retrieveList() {
