        // Log error message and release allocated resources
        return NULL;
    }
    memcpy(newElement, current, sizeof(struct NFAPI_CRC_INDICATION_PDU_T));

    // Unlock the list mutex and return the new element
    pthread_mutex_unlock(&listMutex);
    return newElement;
}

void updateList() {
    // Lock the list mutex to prevent concurrent access
    pthread_mutex_lock(&listMutex);

    if (list == NULL) {
        // Unlock the list mutex and return
        pthread_mutex_unlock(&listMutex);
        return;
    }

    // Release memory allocated for the list
    struct NFAPI_CRC_INDICATION_PDU_T* current = list;
    while (current != NULL) {
