#define MAX_GRANTS 1000
#define MAX_CONNECTIONS 1000
#define TBS_LIMIT 50000000 // Total TBS limit per grant

typedef struct LTE_Uplink_Scheduling_GRANT_t {
    int RRC_Connection_ID;
    int TBS;
} LTE_Uplink_Scheduling_GRANT;

int initialize_uplink_grants(LTE_Uplink_Scheduling_GRANT **grants, int *connection_ids, int num_connections) {
    // Check input parameters
    if (grants == NULL || connection_ids == NULL || num_connections < 1 || num_connections > MAX_CONNECTIONS) {
        return -1;
    }

    // Allocate memory for grants array and individual structures
    *grants = malloc(sizeof(LTE_Uplink_Scheduling_GRANT) * num_connections);
    if (*grants == NULL) {
        fprintf(stderr, "Failed to allocate memory for uplink grant array: %s\n", strerror(errno));
        return -1;
    }

    // Initialize RRC connection IDs and TBS values based on provided array of connection IDs
    int i = 0;
    while (i < num_connections) {
        (*grants)[i].RRC_Connection_ID = connection_ids[i];
        (*grants)[i].TBS = calculate_tbs((*grants)[i].RRC_Connection_ID);
        i++;
    }

    // Calculate total TBS limit per grant based on predefined mapping table
    int total_tbs = 0;
    for (i = 0; i < num_connections; i++) {
        total_tbs += (*grants)[i].TBS;
    }
    if (total_tbs > TBS_LIMIT) {
        fprintf(stderr, "Total TBS limit exceeded: %d > %d\n", total_tbs, TBS_LIMIT);
        free(*grants);
        return -1;
    }

    // Initialize unique index for each grant
    int index = 0;
    for (i = 0; i < num_connections; i++) {
        (*grants)[i].index = index++;
    }

    return num_connections;
}

int calculate_tbs(int connection_id) {
    // Predefined mapping table to calculate TBS based on RRC connection ID
    int tbs_map[][2] = {
        {1, 500}, {2, 1000}, {3, 1500}, {4, 2000}, {5, 2500}, {6, 3000}, {7, 3500}, {8, 4000}, {9, 4500}, {10, 5000}
    };

    // Calculate TBS based on predefined mapping table and RRC connection ID
    int tbs = -1;
    for (int i = 0; i < sizeof(tbs_map) / sizeof(tbs_map[0]); i++) {
        if (connection_id >= tbs_map[i][0] && connection_id <= tbs_map[i][1]) {
            tbs = tbs_map[i][2];
            break;
        }
    }

    return tbs;
}

void free_uplink_grants(LTE_Uplink_Scheduling_GRANT **grants) {
    // Free memory for grants array and individual structures
    if (*grants != NULL) {
        free(*grants);
        *grants = NULL;
    }
}
```
