    } else if (strcmp(argv[1], "CFB") == 0) {
        ctx.mode = CFB_MODE;
    } else {
        printf("Invalid mode specified\n");
        return 2;
    }

    // Handle the input data based on the specified mode
    if (strcmp(argv[2], "-f") == 0) {
        encrypt_file(&ctx, argv[3]);
    } else if (strcmp(argv[2], "-s") == 0) {
        encrypt_stream(&ctx, argv[3], atoi(argv[4]));
    } else if (strcmp(argv[2], "-b") == 0) {
        uint8_t *buffer = (uint8_t *)argv[3];
        size_t len = strlen((const char *)buffer);
        encrypt_buffer(&ctx, buffer, len);
    } else {
        printf("Invalid input specified\n");
        return 3;
    }

    // Clean up the encryption context and return success
