// Structure for holding received RLC messages
typedef struct {
  uint16_t valid; // Valid flag
  uint32_t rx_ue_information_tag; // RX UE information tag
  uint32_t rnti; // RNTI
  uint8_t crc_indication_rel8_tag[sizeof(NFAPI_CRC_INDICATION_PDU)]; // CRC indication REL8 tag
} NFAPI_CRC_INDICATION_PDU_T;

// Array for storing received RLC messages
static NFAPI_CRC_INDICATION_PDU_T* rlc_message_array = NULL;

// Lock for protecting access to the array of received RLC messages
static pthread_mutex_t rlc_message_array_lock = PTHREAD_MUTEX_INITIALIZER;

// Custom garbage collection mechanism for freeing unused structures periodically
void garbage_collection(void) {
  // Lock the array of received RLC messages
  pthread_mutex_lock(&rlc_message_array_lock);

  // Iterate through the array and check if any structures are unused
  for (int i = 0; i < MAX_NUM_RLC_MESSAGES; i++) {
    if (!rlc_message_array[i].valid) {
      free(rlc_message_array[i]);
      rlc_message_array[i] = NULL;
    }
  }

  // Unlock the array of received RLC messages
  pthread_mutex_unlock(&rlc_message_array_lock);
