} mem_pool_t;

mem_pool_t* create_mem_pool(size_t capacity) {
    mem_pool_t* pool = malloc(sizeof(mem_pool_t));
    if (!pool) return NULL;

    // Allocate a single block of memory for the pool
    pool->block_size = sizeof(void*) * capacity;
    pool->mem_block = calloc(1, pool->block_size);
    if (!pool->mem_block) {
        free(pool);
        return NULL;
    }

    return pool;
}

void destroy_mem_pool(mem_pool_t* pool) {
    if (pool) {
        free(pool->mem_block);
        free(pool);
    }
}

// Custom memory allocation function that uses a memory pool
void* mem_alloc(size_t size, mem_pool_t* pool) {
    void* ptr = NULL;
    if (size > 0 && pool && pool->block_size - pool->mem_block.used < size) {
        return NULL;
    }

    // Allocate memory from the pool, and update the used memory counter
    ptr = malloc(size);
    if (ptr) {
        pool->mem_block.used += size;
    } else {
        // Handle allocation failure gracefully by attempting to allocate a reduced-size buffer
        ptr = realloc(pool->mem_block, pool->mem_block.used + size);
