    NFAPI_RRC_CU_TRANSPORT_PDU_T* tmp = (NFAPI_RRC_CU_TRANSPORT_PDU_T*)realloc(*pdu_array, new_size * sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T));
