void serialize(NFAPI_RRC_CU_TRANSPORT_PDU_T* pdu, char** serialized) {
    // Check if the PDU is valid and not null
    if (!pdu || !serialized) {
        return;
    }

    // Allocate memory for the serialized data
    size_t length = sizeof(uint8_t) + sizeof(uint16_t) + sizeof(uint16_t) + sizeof(uint32_t);
    *serialized = (char*)malloc(length);

    // Serialize the PDU data into the serialized buffer
    char* cursor = *serialized;
    memcpy(cursor, &pdu->RRC_MESSAGE_TYPE_TAG, sizeof(uint8_t));
    cursor += sizeof(uint8_t);
    memcpy(cursor, &pdu->RRC_TRANSPORT_CHANNEL_TAG, sizeof(uint16_t));
    cursor += sizeof(uint16_t);
    memcpy(cursor, &pdu->PDCP_SN, sizeof(uint16_t));
    cursor += sizeof(uint16_t);
