    char* cursor = serialized;
    memcpy(&pdu->RRC_MESSAGE_TYPE_TAG, cursor, sizeof(uint8_t));
    cursor += sizeof(uint8_t);
    memcpy(&pdu->RRC_TRANSPORT_CHANNEL_TAG, cursor, sizeof(uint16_t));
