  // Check if REST API socket file descriptor is valid
  if (socket_fd == -1) {
    return FAILURE;
  }

  int bytes = send(socket_fd, message, strlen(message), MSG_WAITALL);

  if (bytes < 0) {
    // Log error for failed message send
    printf("Failed to send message: %s\n", strerror(errno));

    return FAILURE;
  } else if (bytes != strlen(message)) {
    // Log error for partial message send
    printf("Partial message send: %d/%d bytes.\n", bytes, strlen(message));

    return FAILURE;
  }

  return SUCCESS;
}

