  // Check if message length is valid
  if (strlen(message) > MAX_API_PARAMS) {
    return FAILURE;
  }

  // Check if message contains only alphanumeric characters and spaces
  for (int i = 0; i < strlen(message); ++i) {
    char c = message[i];

    if (!isalnum(c) && c != ' ') {
      return FAILURE;
    }
  }

  return SUCCESS;
}
