typedef struct {
    int size;
    int capacity;
    nfapi_crc_indication_pdu_t** elements;
} nfapi_crc_indication_list_t;

// Initialize the list with a given initial capacity
void init_nfapi_crc_indication_list(nfapi_crc_indication_list_t* list, int initial_capacity) {
    assert(initial_capacity > 0);
    list->size = 0;
    list->capacity = initial_capacity;
    list->elements = (nfapi_crc_indication_pdu_t**)malloc(sizeof(nfapi_crc_indication_pdu_t*) * initial_capacity);
}

// Add a new element to the list
void add_to_nfapi_crc_indication_list(nfapi_crc_indication_list_t* list, nfapi_crc_indication_pdu_t* element) {
    if (list->size == list->capacity) {
        // Double the capacity of the list if it's full
        int new_capacity = list->capacity * 2;
        nfapi_crc_indication_pdu_t** new_elements = (nfapi_crc_indication_pdu_t**)malloc(sizeof(nfapi_crc_indication_pdu_t*) * new_capacity);
        memcpy(new_elements, list->elements, sizeof(nfapi_crc_indication_pdu_t*) * list->size);
        free(list->elements);
        list->elements = new_elements;
        list->capacity = new_capacity;
    }
    list->elements[list->size++] = element;
}

// Remove an element from the list
void remove_from_nfapi_crc_indication_list(nfapi_crc_indication_list_t* list, int index) {
    assert(index >= 0 && index < list->size);
    for (int i = index; i < list->size - 1; i++) {
        list->elements[i] = list->elements[i + 1];
    }
    list->size--;
}

// Dynamic management of NFAPI_CRC_INDICATION_PDU_T structures
void manage_nfapi_crc_indication(nfapi_crc_indication_list_t* list, int rx_ue_info, RNTI rnti, CRC_INDICATION_REL8_TAG crc_ind_rel8) {
    // Check if the RX_UE_INFORMATION_TAG and RNTI are valid
    if (rx_ue_info < 0 || rx_ue_info >= NUMBER_OF_RX_UE_INFORMATION_TAGS || rnti < 0) {
        return;
    }

    // Check if the CRC_INDICATION_REL8_TAG is valid
    if (crc_ind_rel8 < 0 || crc_ind_rel8 >= NUMBER_OF_CRC_INDICATION_REL8_TAGS) {
        return;
    }

    // Create a new NFAPI_CRC_INDICATION_PDU_T structure and add it to the list
    nfapi_crc_indication_pdu_t* element = (nfapi_crc_indication_pdu_t*)malloc(sizeof(nfapi_crc_indication_pdu_t));
    element->rx_ue_info = rx_ue_info;
    element->rnti = rnti;
    element->crc_ind_rel8 = crc_ind_rel8;
    element->crcf = CRCFLAG_RANDOM; // Set the CRCFLAG to a random value
    add_to_nfapi_crc_indication_list(list, element);
