// Thread-safe implementation of manage_nfapi_crc_indication() using locks
void managed_nfapi_crc_indication(nfapi_crc_indication_list_t* list, int rx_ue_info, RNTI rnti, CRC_INDICATION_REL8_TAG crc_ind_rel8) {
    pthread_mutex_lock(&list->mutex);
    manage_nfapi_crc_indication(list, rx_ue_info, rnti, crc_ind_rel8);
    pthread_mutex_unlock(&list->mutex);
}

// Implement validation checks to ensure all fields are correctly initialized before returning the list
nfapi_crc_indication_list_t* get_nfapi_crc_indications(nfapi_crc_indication_list_t* list) {
    // Check if all elements in the list have been properly initialized
    for (int i = 0; i < list->size; i++) {
        nfapi_crc_indication_pdu_t* element = list->elements[i];
        if (element->rx_ue_info == -1 || element->rnti == -1 || element->crc_ind_rel8 == -1) {
            return NULL;
        }
    }
    return list;
