// Implementation of a thread-safe queue for storing UE information tags
typedef struct Queue_t {
  pthread_mutex_t mutex;
  pthread_cond_t cond;
  int size;
  void** data;
} Queue_t;

// Create a new queue with the specified capacity
Queue_t* createQueue(int capacity) {
  Queue_t* q = malloc(sizeof(Queue_t));

  // Initialize the mutex and condition variable for synchronizing access to the queue
  pthread_mutexattr_t attr;
  pthread_mutexattr_init(&attr);
  pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
  pthread_mutex_init(&q->mutex, &attr);
  pthread_cond_init(&q->cond, NULL);

  // Allocate memory for the queue data
  q->data = malloc(sizeof(void*) * capacity);
  q->size = 0;
  q->capacity = capacity;

  return q;
}

// Enqueue an element to the end of the queue
void enqueue(Queue_t* q, void* data) {
  pthread_mutex_lock(&q->mutex);

  // Wait until there is space available in the queue
  while (q->size == q->capacity) {
    pthread_cond_wait(&q->cond, &q->mutex);
  }

  // Add the new element to the end of the queue
  q->data[q->size] = data;
  q->size++;

  // Notify any waiting threads that there is space available in the queue
  pthread_cond_signal(&q->cond);

  pthread_mutex_unlock(&q->mutex);
}

// Dequeue an element from the front of the queue
void* dequeue(Queue_t* q) {
  pthread_mutex_lock(&q->mutex);

  // Wait until there is an element available in the queue
  while (q->size == 0) {
    pthread_cond_wait(&q->cond, &q->mutex);
  }

  // Remove the first element from the queue
  void* data = q->data[0];
  for (int i = 1; i < q->size; i++) {
    q->data[i - 1] = q->data[i];
  }
  q->size--;

  // Notify any waiting threads that there is space available in the queue
  pthread_cond_signal(&q->cond);

  pthread_mutex_unlock(&q->mutex);

  return data;
}

// Destroy a queue and free its resources
void destroyQueue(Queue_t* q) {
  pthread_mutex_lock(&q->mutex);

  // Wait until all threads have released the queue before destroying it
  while (q->size > 0) {
    pthread_cond_wait(&q->cond, &q->mutex);
  }

  // Destroy the mutex and condition variable
  pthread_mutex_destroy(&q->mutex);
  pthread_cond_destroy(&q->cond);

  // Free the queue data
  free(q->data);

  pthread_mutex_unlock(&q->mutex);
}

// Fetch the next available UE information tag from an external data source
void* fetchUEInformationTag(Queue_t* ueInfoQueue) {
  // Fetch the next available UE information tag from the external data source
  void* nextUETag = retrieveNextUEInfoTag();

  if (nextUETag) {
    // Enqueue the UE information tag to be used later
    enqueue(ueInfoQueue, nextUETag);
  }

  return nextUETag;
}

// Free a UE information tag and remove it from the queue
void freeUEInformationTag(void* ueInfoTag) {
  // Remove the UE information tag from the queue
  dequeue(ueInfoQueue);

  // Free the UE information tag
  freeUEInformationTag(ueInfoTag);
}

// Retrieve the RNTI value from a given UE information tag
uint16_t getRNTIFromUEInfo(void* ueInfoTag) {
  // Retrieve the RNTI value from the UE information tag
  return retrieveRNTIValue();
}

