struct STATE_LIST {
    struct NFAPI_CRC_INDICATION_PDU_T *pdu;
    int size;
    int max_size;
};

static void create_state_list(int *states, int num_states, NFAPI_FSA_T *fsa, int last_state, int max_size) {
    struct STATE_LIST list = {NULL, 0, max_size};
    for (int i = 0; i < num_states; i++) {
        int state = states[i];
        // Check if the current state is a dead end or a cycle
        if (is_dead_end(state) || is_cycle(state)) {
            continue;
        }
        // Traverse the FSA from the current state
        traverse_fsa(fsa, state);
    }
    // Populate the list with valid RX_UE_INFORMATION_TAGs and CRCFLAGs
    for (int i = 0; i < fsa->num_states; i++) {
        int state = fsa->states[i];
        if (is_valid(state)) {
            struct NFAPI_CRC_INDICATION_PDU_T *pdu = (struct NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
            pdu->rx_ue_information_tag = 0; // Set to a random value for demonstration purposes
            pdu->rnti = state;
            pdu->crc_indication_rel8_tag = 0; // Set to a random value for demonstration purposes
            list.pdu[list.size++] = pdu;
        }
    }
    free(fsa);
}

int is_dead_end(int state) {
    return state == -1;
}

int is_cycle(int state) {
    return state == 0;
}

int is_valid(int state) {
    // Check if the current state is valid and not a dead end or cycle
    return state >= 0 && !is_dead_end(state) && !is_cycle(state);
}

void traverse_fsa(NFAPI_FSA_T *fsa, int state) {
    // Traverse the FSA from the current state
    for (int i = 0; i < fsa->num_states; i++) {
        if (fsa->transitions[state][i] == -1) {
            continue;
        }
        int next_state = fsa->transitions[state][i];
        // Check if the next state is a dead end or cycle
        if (is_dead_end(next_state) || is_cycle(next_state)) {
            continue;
        }
        traverse_fsa(fsa, next_state);
    }
}
