// Hash table for fast lookups of network interfaces by IP address
typedef struct {
    char *ip_address;
    int subnet_mask;
    char *gateway;
} interface_t;

interface_t *interfaces = NULL;
int num_interfaces = 0;

// Doubly linked list to maintain order of interfaces
typedef struct {
    interface_t *data;
    struct node *prev, *next;
} node_t;

node_t *interface_list = NULL;

// Function to process a single network configuration command
void process_command(char *cmd) {
    // Tokenize the command string into individual arguments
    char *args[3];
    int argc = 0;
    for (int i = 0; i < strlen(cmd); ++i) {
        if (cmd[i] == ' ') {
            args[argc++] = cmd + i + 1;
        }
    }

    // Validate the number of arguments and their formats
    if (argc != 3) {
        fprintf(stderr, "Invalid command format: %s\n", cmd);
        return;
    }

    int op = args[0][0];
    char *ip_address = args[1];
    int subnet_mask = atoi(args[2]);
    if (op == 'A' || op == 'M') {
        // Validate the IP address format and ensure the subnet mask is compatible with the IP version
        struct sockaddr_storage addr;
        int result = inet_pton(AF_INET, ip_address, &addr);
        if (result < 0) {
            fprintf(stderr, "Invalid IP address: %s\n", ip_address);
            return;
        } else if (result == 0) {
            fprintf(stderr, "IP version not supported: %s\n", ip_address);
            return;
        }

        // Calculate and store the network and broadcast addresses for this interface
        char *network = malloc(strlen(ip_address));
        char *broadcast = malloc(strlen(ip_address));
        calculate_network_and_broadcast(network, broadcast, ip_address, subnet_mask);

        // Add or modify the interface in the hash table and doubly linked list
        if (op == 'A') {
            add_interface(network, ip_address, subnet_mask, gateway, broadcast);
        } else if (op == 'M') {
            modify_interface(network, ip_address, subnet_mask, gateway, broadcast);
        }
    }
}

// Function to add a new interface with specified IP address, subnet mask, and gateway
void add_interface(char *network, char *ip_address, int subnet_mask, char *gateway, char *broadcast) {
    // Create a new node for the interface in the doubly linked list
    node_t *new_node = malloc(sizeof(node_t));
    new_node->data = malloc(sizeof(interface_t));
    new_node->data->ip_address = ip_address;
    new_node->data->subnet_mask = subnet_mask;
    new_node->data->gateway = gateway;
    new_node->data->network = network;
    new_node->data->broadcast = broadcast;

    // Add the interface to the hash table and doubly linked list
    interfaces[ip_address] = new_node->data;
    if (interface_list == NULL) {
        interface_list = new_node;
    } else {
        node_t *tmp = interface_list;
        while (tmp->next != NULL) {
            tmp = tmp->next;
        }
        tmp->next = new_node;
        new_node->prev = tmp;
    }
}

// Function to modify an existing interface's configuration
void modify_interface(char *network, char *ip_address, int subnet_mask, char *gateway, char *broadcast) {
    // Find the node for this interface in the doubly linked list
    node_t *node = interfaces[ip_address];
    if (node == NULL) {
        fprintf(stderr, "Interface %s does not exist\n", ip_address);
        return;
    }

    // Update the interface's configuration in the hash table and doubly linked list
    node->data->subnet_mask = subnet_mask;
    node->data->gateway = gateway;
    node->data->network = network;
    node->data->broadcast = broadcast;
}

// Function to calculate the network and broadcast addresses for an interface
void calculate_network_and_broadcast(char *network, char *broadcast, char *ip_address, int subnet_mask) {
    struct sockaddr_storage addr;
    int result = inet_pton(AF_INET, ip_address, &addr);
    if (result < 0) {
        fprintf(stderr, "Invalid IP address: %s\n", ip_address);
        return;
    } else if (result == 0) {
        fprintf(stderr, "IP version not supported: %s\n", ip_address);
        return;
    }

    // Calculate the network and broadcast addresses for this interface
    uint32_t netmask = htonl(subnet_mask);
    uint32_t host = ntohl(*((uint32_t *)addr.sin_addr.s_addr));
    uint32_t network = host & netmask;
    uint32_t broadcast = network | (~netmask);

    // Store the network and broadcast addresses for this interface
    sprintf(network, "%d", network);
    sprintf(broadcast, "%d", broadcast);
}

// Function to generate a summary report of the network configuration
