typedef struct connection *Connection;

// Hash table to store all connections
static Connection* connections = NULL;

// Mutex for synchronizing access to the hash table
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Initialize the hash table with the given initial size and growth increment
void initialize(int initial_size, int growth_increment) {
    connections = (Connection*) malloc(sizeof(Connection) * initial_size);
    assert(connections != NULL);
    memset(connections, 0, sizeof(Connection) * initial_size);
}

// Add a new connection to the hash table
void add_connection(uint64_t session_id, char* address) {
    pthread_mutex_lock(&mutex);
    if (connections == NULL || connections->session_id == 0) {
        initialize(INITIAL_SIZE, GROWTH_INCREMENT);
    }
    Connection connection = (Connection) malloc(sizeof(struct connection));
    assert(connection != NULL);
    memset(connection, 0, sizeof(struct connection));
    connection->session_id = session_id;
    connection->address = address;
    connections[session_id % MAX_CONNECTIONS] = connection;
    pthread_mutex_unlock(&mutex);
}

// Remove a connection from the hash table
void remove_connection(uint64_t session_id) {
    pthread_mutex_lock(&mutex);
    if (connections != NULL && connections[session_id % MAX_CONNECTIONS] != NULL) {
        free(connections[session_id % MAX_CONNECTIONS]);
        connections[session_id % MAX_CONNECTIONS] = NULL;
    }
    pthread_mutex_unlock(&mutex);
}

