void update_status(uint64_t session_id, int new_status) {
    pthread_mutex_lock(&mutex);
    if (connections != NULL && connections[session_id % MAX_CONNECTIONS] != NULL) {
        connections[session_id % MAX_CONNECTIONS]->status = new_status;
    }
    pthread_mutex_unlock(&mutex);
}

// Get the status of a connection in the hash table
int get_status(uint64_t session_id) {
    int ret = -1;
    pthread_mutex_lock(&mutex);
    if (connections != NULL && connections[session_id % MAX_CONNECTIONS] != NULL) {
        ret = connections[session_id % MAX_CONNECTIONS]->status;
    }
    pthread_mutex_unlock(&mutex);
    return ret;
}

// Get the session ID of a connection in the hash table by its address
uint64_t get_session_id(char* address) {
    uint64_t ret = 0;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (connections[i] != NULL && strcmp(connections[i]->address, address) == 0) {
            ret = connections[i]->session_id;
            break;
        }
    }
