    list->measurements = calloc(capacity, sizeof(struct LTE_MEASUREMENT_RESULTS_T));
    if (list->measurements == NULL) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void measurement_results_list_destroy(MeasurementResultsList* list) {
    if (list != NULL) {
        free(list->measurements);
        pthread_mutex_destroy(&list->mutex);
        free(list);
    }
}

int32_t measurement_results_list_add(MeasurementResultsList* list, uint64_t measurement_id, uint32_t cell_id, int32_t rsrp_measurement) {
    if (list == NULL || list->count >= list->capacity) {
        return -1;
    }

    pthread_mutex_lock(&list->mutex);

    struct LTE_MEASUREMENT_RESULTS_T* measurement = &list->measurements[list->count++];
    measurement->measurement_id = measurement_id;
    measurement->cell_id = cell_id;
    measurement->rsrp_measurement = rsrp_measurement;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int32_t measurement_results_list_find(MeasurementResultsList* list, uint64_t measurement_id) {
    if (list == NULL) {
        return -1;
    }

    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->count; ++i) {
        struct LTE_MEASUREMENT_RESULTS_T* measurement = &list->measurements[i];
        if (measurement->measurement_id == measurement_id) {
            pthread_mutex_unlock(&list->mutex);
            return i;
        }
    }

    pthread_mutex_unlock(&list->mutex);
    return -1;
}

int32_t measurement_results_list_remove(MeasurementResultsList* list, uint64_t measurement_id) {
    if (list == NULL) {
        return -1;
    }

    pthread_mutex_lock(&list->mutex);

    int32_t index = measurement_results_list_find(list, measurement_id);
    if (index < 0) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    struct LTE_MEASUREMENT_RESULTS_T* measurement = &list->measurements[index];
    memcpy(measurement, measurement + 1, (list->count - index - 1) * sizeof(*measurement));
    --list->count;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}
