            free(frames);
            free(cells);
            free(records);
            free(names);
            return NULL;
        }
        for (size_t j = 0; j < 10; j++) {
            name[j] = 'a' + rand() % 26;
        }
        names[i] = name;
    }

    // Create a structure to store the data
    struct LTEPHYCH_INDICATION_PDU_T* data = malloc(sizeof(struct LTEPHYCH_INDICATION_PDU_T));
    if (data == NULL) {
        free(frames);
        free(cells);
        free(records);
        free(names);
        return NULL;
    }
    data->frame_number = frames;
    data->cell_id = cells;
    data->record = records;
    data->cell_name = names;

    // Return the structure with the allocated memory
    return data;
}
