typedef struct NFAPI_CRC_INDICATION_PDU_T {
  uint32_t rx_ue_information_tag;
  uint16_t rnti;
  uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CRC_INDICATION_LIST {
  NFAPI_CRC_INDICATION_PDU_T* pdu;
  size_t size;
} CRC_INDICATION_LIST;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication(uint16_t rnti) {
  // Check if the RNTI is valid
  if (rnti == 0) {
    return NULL;
  }

  NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
  if (!pdu) {
    return NULL;
  }

  // Set the RX_UE_INFORMATION_TAG and RNTI
  pdu->rx_ue_information_tag = 0;
  pdu->rnti = rnti;

  // Set a random CRCFLAG for the CRC_INDICATION_REL8_TAG
  srand(time(NULL));
  uint8_t crcflag = rand() % 256;
  pdu->crc_indication_rel8_tag = crcflag;

  // Set the timestamp for the last update
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  uint32_t timestamp = (uint32_t)ts.tv_sec * 1000 + (uint32_t)(ts.tv_nsec / 1e6);
  pdu->timestamp = timestamp;

  return pdu;
}

CRC_INDICATION_LIST* create_crc_indication_list(size_t size) {
  CRC_INDICATION_LIST* list = malloc(sizeof(CRC_INDICATION_LIST));
  if (!list) {
    return NULL;
  }

  list->pdu = calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
  if (!list->pdu) {
    free(list);
    return NULL;
  }

  list->size = size;

  return list;
}

void add_crc_indication_to_list(CRC_INDICATION_LIST* list, uint16_t rnti) {
  // Check if the RNTI is valid
  if (rnti == 0) {
    return;
  }

  // Create a new CRC indication PDU for the given RNTI
  NFAPI_CRC_INDICATION_PDU_T* pdu = create_crc_indication(rnti);
  if (!pdu) {
    return;
  }

  // Add the new CRC indication PDU to the list
  if (list->size >= 1024) {
    free(pdu);
    return;
  }
  list->pdu[list->size++] = *pdu;
}

void update_crc_indication_list(CRC_INDICATION_LIST* list, uint32_t timestamp) {
  // Iterate through the CRC indications and update their timestamps
  for (size_t i = 0; i < list->size; i++) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = &list->pdu[i];

    // Check if the timestamp is within the valid range
    if (timestamp - pdu->timestamp > 1000) {
      continue;
    }

    // Update the CRC indication with the new timestamp
    pdu->timestamp = timestamp;
  }
}

void delete_crc_indication_list(CRC_INDICATION_LIST* list) {
  free(list->pdu);
  free(list);
}
