    newElement->rnti = rnti;
    newElement->crc_indication_rel8_tag = crc_indication_rel8_tag;

    // Add the new element to the list
    if (list->size < list->capacity) {
        list->list[list->size++] = newElement;
    } else {
        fprintf(stderr, "Maximum capacity of %zu elements reached\n", list->capacity);
        free(newElement);
