    if (pdu_list == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for the list\n");
        return NULL;
    }

    // Initialize each structure in the list with a unique RNTI value and a randomly set CRCFLAG
    uint16_t rnti = 0;
    bool crcflag = false;
    for (uint16_t i = 0; i < num_elements; i++) {
        pdu_list[i].RX_UE_INFORMATION_TAG = 0xABCD; // Use a fixed value for the RX UE Information Tag
        pdu_list[i].RNTI = rnti++; // Increment the RNTI value
        crcflag ^= true; // Flip the CRCFLAG bit
        pdu_list[i].CRC_INDICATION_REL8_TAG = 0xAB; // Use a fixed value for the CRC Indication REL8 Tag
        pdu_list[i].CRCFLAG = crcflag; // Set the CRCFLAG bit to the current value
    }

    return pdu_list;
}

// Function to validate the consistency of the CRC flag across all structures in the list
bool nfapi_validate_crc_flag(NFAPI_CRC_INDICATION_PDU_T* pdu_list, uint16_t num_elements) {
    // Check if the input is valid
    if (pdu_list == NULL || num_elements == 0) {
        fprintf(stderr, "Error: The list or number of elements is invalid\n");
        return false;
    }

    // Initialize a flag to indicate if any inconsistencies are found
    bool inconsistent = false;

    // Validate the consistency of the CRC flag across all structures in the list
    for (uint16_t i = 0; i < num_elements - 1; i++) {
        if (pdu_list[i].CRCFLAG != pdu_list[i + 1].CRCFLAG) {
            inconsistent = true;
            break;
        }
    }

    return !inconsistent;
}

// Function to clean up the memory allocated for the list
void nfapi_free_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T* pdu_list) {
    // Check if the input is valid
    if (pdu_list == NULL) {
        fprintf(stderr, "Error: The list is invalid\n");
        return;
    }

    free(pdu_list);
}
