#include <pthread.h>

#define MAX_LIST_SIZE 1000

typedef struct {
    uint32_t rnti;
    bool crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

// Linked list node
struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
};

// Linked list head
struct linked_list {
    struct node* head;
    pthread_mutex_t lock; // for thread safety
    size_t count; // current number of elements in the list
};

void flush_list(struct linked_list* list) {
    if (list->count >= 10000) {
        printf("WARNING: list size exceeds threshold\n");
        return;
    }
    struct node* current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T data = current->data;
        if (data.rnti < 0x0001 || data.rnti > 0xFFFF) {
            printf("ERROR: RNTI out of range\n");
            return;
        }
        // persistent storage mechanism goes here
        current = current->next;
    }
}

void add_element(struct linked_list* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    struct node* new_node = (struct node*) malloc(sizeof(struct node));
    if (new_node == NULL) {
        printf("ERROR: memory allocation failed\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    if (list->count >= 1000) {
        flush_list(list);
    }
    pthread_mutex_unlock(&list->lock);
}

void delete_element(struct linked_list* list, uint32_t rnti) {
    pthread_mutex_lock(&list->lock);
    struct node** current = &list->head;
    while (*current != NULL) {
        if ((*current)->data.rnti == rnti) {
            struct node* tmp = *current;
            *current = (*current)->next;
            free(tmp);
            list->count--;
            break;
        } else {
            current = &(*current)->next;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void print_list(struct linked_list* list) {
    struct node* current = list->head;
    while (current != NULL) {
        printf("RNTI: %d, CRCFlag: %d\n", current->data.rnti, current->data.crc_flag);
        current = current->next;
    }
}

int main() {
    struct linked_list list;
    list.head = NULL;
    list.count = 0;
    pthread_mutex_init(&list.lock, NULL); // initialize lock for thread safety

    NFAPI_CRC_INDICATION_PDU_T data1 = {
        .rnti = 0x0001,
        .crc_flag = false
    };
    add_element(&list, data1);

    NFAPI_CRC_INDICATION_PDU_T data2 = {
        .rnti = 0x0002,
        .crc_flag = true
    };
    add_element(&list, data2);

    print_list(&list);

    delete_element(&list, 0x0001);

    print_list(&list);

    return 0;
}
