// Declare global variables to store the list of UE contexts and their associated MeasurementReports
struct UeContext {
    uint16_t rnti;
    struct MeasurementReport *reports;
};
struct UeContext *ueContextList = NULL;
size_t numUeContexts = 0;

// Initialize the list with M initial MeasurementReports for each UE context
void initUeContextList(uint16_t m) {
    ueContextList = (struct UeContext *)malloc(m * sizeof(struct UeContext));
    numUeContexts = 0;
    for (uint16_t i = 0; i < m; i++) {
        struct UeContext *context = &ueContextList[numUeContexts++];
        context->rnti = i + 1;
        context->reports = (struct MeasurementReport *)malloc(sizeof(struct MeasurementReport) * m);
    }
}

// Update the signal strength for a specific UE context without altering other data associated with that context
void updateSignalStrength(uint16_t rnti, int newSignalStrength) {
    struct UeContext *context = NULL;
    size_t i;
    // Find the index of the UE context with the specified RNTI
    for (i = 0; i < numUeContexts && context == NULL; i++) {
        if (ueContextList[i].rnti == rnti) {
            context = &ueContextList[i];
        }
    }
    // Update the signal strength for the found UE context
    if (context != NULL) {
        context->reports[0].signalStrength = newSignalStrength;
    } else {
        // If the specified RNTI is not found, print an error message and return
        printf("Error: Could not find UE context with RNTI %d\n", rnti);
        return;
    }
}

// Add a new MeasurementReport to the list for a specific UE context
void addMeasurementReport(uint16_t rnti, struct MeasurementReport *report) {
    struct UeContext *context = NULL;
    size_t i;
    // Find the index of the UE context with the specified RNTI
    for (i = 0; i < numUeContexts && context == NULL; i++) {
        if (ueContextList[i].rnti == rnti) {
            context = &ueContextList[i];
        }
    }
    // Add the new MeasurementReport to the found UE context's list of reports
    if (context != NULL) {
        struct MeasurementReport *newReport = malloc(sizeof(struct MeasurementReport));
        memcpy(newReport, report, sizeof(struct MeasurementReport));
        newReport->next = context->reports;
        context->reports = newReport;
    } else {
        // If the specified RNTI is not found, print an error message and return
        printf("Error: Could not find UE context with RNTI %d\n", rnti);
        return;
    }
}

// Free all memory associated with the list of UE contexts
void freeUeContextList() {
    for (size_t i = 0; i < numUeContexts; i++) {
        struct UeContext *context = &ueContextList[i];
        free(context->reports);
    }
    free(ueContextList);
}
```
