        records[i].value = rand() % 100;
        records[i].pointer = NULL;
        records[i].status_flag = 0;
    }

    // Ensure that the function is thread-safe by using RAII principles or similar techniques
    #pragma omp parallel for schedule(static) num_threads(8) default(none) shared(records)
    for (size_t i = 0; i < num_records; ++i) {
