static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new node to the linked list
void nfapi_crc_indication_list_add(RX_UE_INFORMATION_TAG *rx_ue_information, RNTI rnti, CRC_INDICATION_REL8_TAG *crc_indication) {
  // Allocate memory for the new node
  nfapi_crc_indication_node_t* new_node = malloc(sizeof(nfapi_crc_indication_node_t));
  if (!new_node) {
    return;
  }

  // Initialize the fields of the new node
  new_node->rx_ue_information = rx_ue_information;
  new_node->rnti = rnti;
  new_node->crc_indication = crc_indication;
  new_node->next = NULL;

  // Lock the list for writing
  pthread_mutex_lock(&list_lock);

  // Add the new node to the end of the linked list
  if (crc_indication_list) {
    nfapi_crc_indication_node_t* current = crc_indication_list;
    while (current->next) {
      current = current->next;
    }
    current->next = new_node;
  } else {
    crc_indication_list = new_node;
  }

  // Unlock the list
  pthread_mutex_unlock(&list_lock);
}

// Function to remove a node from the linked list
void nfapi_crc_indication_list_remove(RX_UE_INFORMATION_TAG *rx_ue_information, RNTI rnti) {
  // Lock the list for writing
  pthread_mutex_lock(&list_lock);

  // Search for the node to be removed
  nfapi_crc_indication_node_t* current = crc_indication_list;
  while (current) {
    if (current->rx_ue_information == rx_ue_information && current->rnti == rnti) {
      // Remove the node from the linked list
      nfapi_crc_indication_node_t* previous = NULL;
      while (current->next) {
        if (previous) {
          previous->next = current->next;
        } else {
          crc_indication_list = current->next;
        }
        current = current->next;
      }

      // Free the memory allocated for the node
      free(current);

      break;
    }
    previous = current;
    current = current->next;
  }

  // Unlock the list
  pthread_mutex_unlock(&list_lock);
}

