// Function to dynamically construct a state list from a given FSA
void constructStateList(struct StateList *state_list, int *fsa, int num_states, int last_state, int max_size) {
    // Initialize the state list with the initial state
    state_list->states = (int *)malloc(sizeof(int) * max_size);
    state_list->crc_indication_pdus = (struct NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T) * max_size);
    state_list->max_size = max_size;
    state_list->size = 0;
    state_list->states[state_list->size++] = 0; // initial state

    // Traverse the FSA using a depth-first search strategy
    int current_state = 0;
    while (current_state != last_state) {
        // Get the next state from the FSA
        int next_state = fsa[current_state];

        // Check if the next state is already in the list
        bool found = false;
        for (int i = 0; i < state_list->size; i++) {
            if (state_list->states[i] == next_state) {
