void checkFSA(int *fsa, int num_states) {
    // Iterate through each state in the FSA
    for (int i = 0; i < num_states; i++) {
        // Get the current state's outgoing transitions
        int num_transitions = fsa[i];

        // Check if any of the outgoing transitions are invalid
        bool found_invalid_transition = false;
        for (int j = 0; j < num_transitions; j++) {
            if (fsa[i + 1 + j] >= num_states) {
                found_invalid_transition = true;
                break;
            }
        }

        // If an invalid transition is found, report it
        if (found_invalid_transition) {
            printf("Invalid transition in state %d\n", i);
        }
    }
}

