// Structure definitions
typedef struct {
    int RRCConnectionInfo;
    int PCI;
    int CQI;
} UEStatusUpdate;

typedef struct {
    UEStatusUpdate* entries;
    size_t capacity;
    size_t size;
} DynamicUEArray;

// Function declarations
void dynamicUeArrayInit(DynamicUEArray* array);
void dynamicUeArrayAdd(DynamicUEArray* array, UEStatusUpdate update);
void dynamicUeArrayUpdate(DynamicUEArray* array, int PCI, UEStatusUpdate update);
void dynamicUeArrayFree(DynamicUEArray* array);

// Function definitions
void dynamicUeArrayInit(DynamicUEArray* array) {
    assert(array != NULL);
    array->entries = (UEStatusUpdate*) malloc(sizeof(UEStatusUpdate) * 1024);
    array->capacity = 1024;
    array->size = 0;
}

void dynamicUeArrayAdd(DynamicUEArray* array, UEStatusUpdate update) {
    assert(array != NULL);
    if (array->size >= array->capacity) {
        // Reallocate memory
        array->entries = (UEStatusUpdate*) realloc(array->entries, sizeof(UEStatusUpdate) * (array->capacity + 1024));
        array->capacity += 1024;
    }
    array->entries[array->size++] = update;
}

void dynamicUeArrayUpdate(DynamicUEArray* array, int PCI, UEStatusUpdate update) {
    assert(array != NULL);
    for (int i = 0; i < array->size; i++) {
        if (array->entries[i].PCI == PCI) {
            // Update entry
            array->entries[i] = update;
            return;
        }
    }
    dynamicUeArrayAdd(array, update);
}

void dynamicUeArrayFree(DynamicUEArray* array) {
    assert(array != NULL);
    free(array->entries);
    array->entries = NULL;
    array->capacity = 0;
    array->size = 0;
}
```
