    State *to;
} Transition;

// Function to read integers from a file and store them in a dynamically allocated array
int* read_integers(FILE* file, int size) {
    // Allocate memory for the integer array
    int* integers = malloc(size * sizeof(int));
    if (!integers) {
        fprintf(stderr, "Failed to allocate memory for integer array\n");
        return NULL;
    }

    // Read integers from the file and store them in the array
    int i = 0;
    while (fscanf(file, "%d", &integers[i]) == 1) {
        i++;
    }

    // If the number of integers read is less than the size of the array,
    // resize the array to match the actual number of integers read
    if (i < size) {
        integers = realloc(integers, i * sizeof(int));
        if (!integers) {
            fprintf(stderr, "Failed to resize integer array\n");
            return NULL;
        }
    }

    // Return the integer array
    return integers;
}

// Function to traverse a finite state automaton (FSA) represented as a directed graph
// and return a list of states that the FSA reaches after processing all integers
State** traverse_fsa(int* integers, int size, State* fsa, int initial_state, int max_size) {
    // Allocate memory for the state list
    State** states = malloc(max_size * sizeof(State));
    if (!states) {
        fprintf(stderr, "Failed to allocate memory for state list\n");
        return NULL;
    }

    // Initialize the state list with the initial state
    int i = 0;
    states[i++] = initial_state;

    // Traverse the FSA and add each visited state to the state list
    for (int j = 0; j < size; j++) {
        State* current_state = fsa + integers[j];

        // If the current state has not been visited before, mark it as visited
        if (!current_state->visited) {
            current_state->visited = 1;
            states[i++] = current_state->id;
        }

        // If the current state is a dead end or a cycle, break from the loop
        if (current_state->dead_end || current_state->cycle) {
            break;
        }
    }

    // If the number of states visited exceeds the maximum size of the list,
    // shrink the state list to match the actual number of states visited
    if (i > max_size) {
        states = realloc(states, i * sizeof(State));
        if (!states) {
            fprintf(stderr, "Failed to resize state list\n");
            return NULL;
        }
    }

    // Return the state list
    return states;
}

