} NFAPI_RRC_CCO_REQUEST_LIST;

// Function to initialize and manage a list of NFAPI_RRC_CCO_REQUEST structures
void init_nfapi_rrc_cco_request_list(NFAPI_RRC_CCO_REQUEST_LIST* list) {
    // Allocate memory for the requests array
    list->requests = (NFAPI_RRC_CCO_REQUEST*)malloc(sizeof(NFAPI_RRC_CCO_REQUEST)*INITIAL_NUM_REQS);
    if (!list->requests) {
        printf("Error: Could not allocate memory for NFAPI_RRC_CCO_REQUEST structures\n");
        return;
    }
    list->num_requests = INITIAL_NUM_REQS;
}

void add_nfapi_rrc_cco_request(NFAPI_RRC_CCO_REQUEST_LIST* list, uint32_t ue_id, uint8_t num_freq_bands, uint16_t freq_bands[], uint32_t ta_len, uint8_t* ta) {
    // Check if the list is full and needs to be resized
    if (list->num_requests == MAX_NUM_REQS) {
        // Reallocate memory for the requests array
        NFAPI_RRC_CCO_REQUEST* new_reqs = (NFAPI_RRC_CCO_REQUEST*)realloc(list->requests, sizeof(NFAPI_RRC_CCO_REQUEST)*MAX_NUM_REQS);
        if (!new_reqs) {
            printf("Error: Could not resize NFAPI_RRC_CCO_REQUEST structures\n");
            return;
        }
        list->requests = new_reqs;
    }
    // Add the new request to the end of the array
    list->requests[list->num_requests].ue_id = ue_id;
    list->requests[list->num_requests].num_freq_bands = num_freq_bands;
    for (int i = 0; i < num_freq_bands; ++i) {
        list->requests[list->num_requests].freq_bands[i] = freq_bands[i];
    }
    list->requests[list->num_requests].ta_len = ta_len;
    list->requests[list->num_requests].ta = ta;
    ++list->num_requests;
}

void get_nfapi_rrc_cco_request(NFAPI_RRC_CCO_REQUEST_LIST* list, uint32_t index) {
    // Check if the index is valid
    if (index >= list->num_requests) {
        printf("Error: Invalid request index\n");
        return;
    }
    NFAPI_RRC_CCO_REQUEST* req = &list->requests[index];
    // Print the UE ID and frequency bands
    printf("UE ID: %u, Frequency Bands: ", req->ue_id);
    for (int i = 0; i < req->num_freq_bands; ++i) {
        printf("%u ", req->freq_bands[i]);
    }
    // Print the timing advance length and data
    if (req->ta_len > 0) {
        printf(", Timing Advance: ");
        for (int i = 0; i < req->ta_len; ++i) {
            printf("%c", req->ta[i]);
        }
    }
    printf("\n");
}

// Function to handle external frequency band updates from an external data source
void update_frequency_bands(NFAPI_RRC_CCO_REQUEST_LIST* list, uint8_t num_freq_bands, uint16_t freq_bands[]) {
    // Check if the list is empty
    if (list->num_requests == 0) {
        return;
    }
    // Update the frequency bands for each request in the list
    for (int i = 0; i < list->num_requests; ++i) {
        NFAPI_RRC_CCO_REQUEST* req = &list->requests[i];
        req->num_freq_bands = num_freq_bands;
        for (int j = 0; j < num_freq_bands; ++j) {
            req->freq_bands[j] = freq_bands[j];
        }
    }
}
