#include <forward_list>
#include <string>
#include <mutex>
#include <vector>
#include <algorithm>

using namespace std;

void insertAfterFirstOccurrence(const std::forward_list<std::string>& list, const std::string& searchStr, const std::string& newStr) {
    // Pre-allocate a buffer for the modified list
    vector<std::string> modifiedList;
    modifiedList.reserve(list.size() + 1);

    mutex lock;
    bool found = false;

    // Iterate through the original list and insert the new string after the first occurrence of searchStr
    for (auto it = list.begin(); it != list.end(); ++it) {
        if (!found && *it == searchStr) {
            modifiedList.emplace_back(newStr);
            found = true;
        }
        // If the first occurrence of searchStr is not found, append the new string to the end of the list
        modifiedList.emplace_back(*it);
    }

    if (!found) {
        modifiedList.emplace_back(newStr);
    }

    // Verify that all elements in the modified list meet the specified constraints
    for (auto it = modifiedList.begin(); it != modifiedList.end(); ++it) {
        if (*it != searchStr && *it != newStr) {
            throw std::invalid_argument("Invalid element found in modified list");
        }
    }

    // If the original list is not empty, update it with the modified list
    if (!list.empty()) {
        lock.lock();
        list = modifiedList;
        lock.unlock();
    } else {
        // If the original list is empty, simply assign the modified list to it
        list = move(modifiedList);
    }
}
