NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_pdu(const NFAPI_CRC_INDICATION_CONFIG* config, NFAPI_CRC_INDICATION_LOG* log) {
    // Validate the configuration object
    if (config == NULL || config->max_num_pdu == 0 || config->rnti_range_start > config->rnti_range_end) {
        return NULL;
    }

    // Initialize the log structure
    memset(log, 0, sizeof(NFAPI_CRC_INDICATION_LOG));

    // Allocate memory for the PDUs
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * config->max_num_pdu);
    if (pdu == NULL) {
        return NULL;
    }

    // Initialize the PDUs with random values within the specified range
    uint32_t rnti = 0;
    for (uint16_t i = 0; i < config->max_num_pdu; i++) {
