        pdu[i].rx_ue_information_tag = 0x1234;
        pdu[i].rnti = rnti;
        pdu[i].crc_indication_rel8_tag = rand() % (UINT8_MAX - 1) + 1;
        pdu[i].crcflag = ((rand() % 2) == 0) ? true : false;
    }

    // Return the allocated memory and log the number of PDUs successfully populated
    log->num_allocated_pdu = config->max_num_pdu;
    return pdu;
}

// Define a function to free the memory allocated by the allocation function
void free_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu, const NFAPI_CRC_INDICATION_CONFIG* config, NFAPI_CRC_INDICATION_LOG* log) {
    // Validate the parameters
    if (pdu == NULL || config == NULL || log == NULL) {
        return;
    }

    // Free the memory allocated by the allocation function
    free(pdu);

    // Log the number of PDUs successfully populated and the number of failed allocations
    log->num_populated_pdu = config->max_num_pdu - log->num_failed_allocations;
}
