// Function to insert a new node into the doubly linked list
void insert_node(NFAPI_CRC_INDICATION_PDU_T *data) {
    // Acquire the mutex lock for thread-safe operations on the linked list
    pthread_mutex_lock(&mutex);

    // Create a new node and assign its data field to the input data pointer
    node_t *new_node = malloc(sizeof(node_t));
    assert(new_node != NULL);
    new_node->data = data;

    // If the linked list is empty, set the head node to the new node and return
    if (head == NULL) {
        head = new_node;
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Iterate over each node in the linked list until a node with an equal RNTI value is found
    node_t *cur = head;
    while (cur != NULL) {
        if (data->rnti == cur->data->rnti) {
            break;
        }
        cur = cur->next;
    }

    // If no equal RNTI value is found, insert the new node at the end of the linked list and return
    if (cur == NULL) {
        head->prev->next = new_node;
        new_node->prev = head->prev;
        head->prev = new_node;
        new_node->next = head;
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Insert the new node before the node with an equal RNTI value and update the linked list
    new_node->prev = cur->prev;
    new_node->next = cur;
    cur->prev->next = new_node;
    cur->prev = new_node;

    // Release the mutex lock for thread-safe operations on the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to traverse the doubly linked list and print each node's data field
void print_list() {
    // Acquire the mutex lock for thread-safe operations on the linked list
    pthread_mutex_lock(&mutex);

    // Iterate over each node in the linked list and print its data field
    node_t *cur = head;
    while (cur != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG.crcFlag: %d\n", cur->data->rx_ue_information_tag, cur->data->rnti, cur->data->crc_indication_rel8_tag.crcFlag);
        cur = cur->next;
    }

    // Release the mutex lock for thread-safe operations on the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to release memory allocated to a doubly linked list of NFAPI_CRC_INDICATION_PDU_T structures
void free_list() {
    // Acquire the mutex lock for thread-safe operations on the linked list
    pthread_mutex_lock(&mutex);

    // Iterate over each node in the linked list and release its memory allocation
    node_t *cur = head;
    while (cur != NULL) {
        free(cur->data);
        cur = cur->next;
    }

    // Release the mutex lock for thread-safe operations on the linked list
    pthread_mutex_unlock(&mutex);
}
