mac_pdu_t* alloc_and_populate_mac_pdus(size_t n, const char* data) {
    // Validate input parameters
    if (n == 0 || data == NULL) {
        MAC_ERROR("Invalid arguments");
    }

    // Allocate memory for the array of MAC PDUs
    mac_pdu_t *mac_pdus = malloc(sizeof(mac_pdu_t) * n);
    if (mac_pdus == NULL) {
        MAC_ERROR("Failed to allocate memory for MAC PDUs");
    }

    // Populate the array of MAC PDUs
    size_t i;
    for (i = 0; i < n; i++) {
        mac_pdu_t *mac_pdu = &mac_pdus[i];

        // Validate input data
        if (data[i] == NULL) {
            MAC_ERROR("Invalid data for MAC PDU");
        }

        // Initialize the MAC header and trailer
        mac_header_t *mac_header = &mac_pdu->header;
        mac_trailer_t *mac_trailer = &mac_pdu->trailer;
        mac_header->length = data[i].length;
        mac_header->type = data[i].type;
