        if (mac_sdus == NULL) {
            MAC_ERROR("Failed to allocate memory for MAC SDUs");
        }

        // Populate the array of MAC SDUs
        size_t j;
        for (j = 0; j < sdu_count; j++) {
            mac_sdu_t *mac_sdu = &mac_sdus[j];
            mac_sdu->data = data[i].sdu[j].data;
            mac_sdu->length = data[i].sdu[j].length;
        }

        // Set the array of MAC SDUs in the MAC PDU
        mac_pdu->sdus = mac_sdus;
        mac_pdu->sdu_count = sdu_count;
    }

    return mac_pdus;
}
