#include <iostream>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>
#include <atomic>
#include <unordered_map>

using namespace std;

// Define the data structures for the MAC frame header
struct MAC_FRAME_HEADER_T {
    unsigned char MAC_PDU_TYPE;
    unsigned short SEQUENCE_NUMBER;
    unsigned char TRANSMISSION_POWER_LEVEL;
    atomic<unsigned int> TRANSMISSION_STATUS;
};

// Define the class to manage the dynamic list of MAC frame headers
class MacFrameHeaderList {
public:
    // Constructor to initialize the list and mutexes
    MacFrameHeaderList() : _list(), _mutex(), _condVar(), _threadPool() { }

    // Add a new MAC frame header to the list
    void addMACFrameHeader(const MAC_FRAME_HEADER_T &header) {
        unique_lock<mutex> lock(_mutex);
        _list.push_back(header);
        _condVar.notify_all();
    }

    // Remove a MAC frame header from the list
    void removeMACFrameHeader(const MAC_FRAME_HEADER_T &header) {
        unique_lock<mutex> lock(_mutex);
        auto it = find(_list.begin(), _list.end(), header);
        if (it != _list.end()) {
            _list.erase(it);
        }
    }

    // Get the list of MAC frame headers
    vector<MAC_FRAME_HEADER_T> getList() {
        unique_lock<mutex> lock(_mutex);
        return _list;
    }

    // Set the update frequency for the list
    void setUpdateFrequency(int frequency) {
        unique_lock<mutex> lock(_mutex);
        _updateFrequency = frequency;
    }

    // Get the update frequency for the list
    int getUpdateFrequency() {
        unique_lock<mutex> lock(_mutex);
        return _updateFrequency;
    }

    // Set the maximum number of threads that can access the list concurrently
    void setMaxThreads(int maxThreads) {
        unique_lock<mutex> lock(_mutex);
        _maxThreads = maxThreads;
    }

    // Get the maximum number of threads that can access the list concurrently
    int getMaxThreads() {
        unique_lock<mutex> lock(_mutex);
        return _maxThreads;
    }

    // Set the maximum number of elements in the list
    void setMaxElements(int maxElements) {
        unique_lock<mutex> lock(_mutex);
        _maxElements = maxElements;
    }

    // Get the maximum number of elements in the list
    int getMaxElements() {
        unique_lock<mutex> lock(_mutex);
        return _maxElements;
    }

private:
    vector<MAC_FRAME_HEADER_T> _list; // The list of MAC frame headers
    mutex _mutex; // Mutex to protect the list from concurrent access
    condition_variable _condVar; // Condition variable to signal changes to the list
    thread_pool _threadPool; // Thread pool for managing the threads that access the list
    int _updateFrequency; // The update frequency for the list
    int _maxThreads; // The maximum number of threads that can access the list concurrently
    int _maxElements; // The maximum number of elements in the list
};

// Define the function to handle updates to the MAC frame headers
void handleUpdates(MacFrameHeaderList &list) {
    while (true) {
        unique_lock<mutex> lock(list._mutex);
        if (!list._condVar.wait_for(lock, chrono::milliseconds(3), [&]{ return list._updateFrequency > 0; })) {
            break;
        }
        // Handle the updates to the MAC frame headers
        for (int i = 0; i < list._updateFrequency; i++) {
            // Update the sequence number and transmission status of each MAC frame header
            for (auto &header : list._list) {
                header.SEQUENCE_NUMBER++;
                if (header.TRANSMISSION_STATUS == 0) {
                    header.TRANSMISSION_STATUS = 1;
                } else {
                    header.TRANSMISSION_STATUS = 0;
                }
            }
        }
    }
}

// Define the function to handle updates from an external radio interface layer
void handleExternalUpdates(MacFrameHeaderList &list) {
    while (true) {
        unique_lock<mutex> lock(list._mutex);
        // Wait for the condition variable to be notified
        list._condVar.wait(lock, [&]{ return list._updateFrequency > 0; });
        // Handle the updates from the external radio interface layer
        for (auto &header : list._list) {
            header.SEQUENCE_NUMBER++;
            if (header.TRANSMISSION_STATUS == 0) {
                header.TRANSMISSION_STATUS = 1;
            } else {
                header.TRANSMISSION_STATUS = 0;
            }
        }
    }
}

// Define the function to handle real-time processing of updates to the MAC frame headers
void handleRealTimeUpdates(MacFrameHeaderList &list) {
    while (true) {
        unique_lock<mutex> lock(list._mutex);
        // Wait for the condition variable to be notified
        list._condVar.wait(lock, [&]{ return list._updateFrequency > 0; });
        // Handle the real-time updates to the MAC frame headers
        for (auto &header : list._list) {
            header.SEQUENCE_NUMBER++;
            if (header.TRANSMISSION_STATUS == 0) {
                header.TRANSMISSION_STATUS = 1;
            } else {
                header.TRANSMISSION_STATUS = 0;
            }
        }
    }
}

// Define the function to handle logging of the MAC frame headers
void handleLogging(MacFrameHeaderList &list) {
    while (true) {
        unique_lock<mutex> lock(list._mutex);
        // Wait for the condition variable to be notified
        list._condVar.wait(lock, [&]{ return list._updateFrequency > 0; });
        // Log the MAC frame headers
        for (auto &header : list._list) {
            cout << "Sequence number: " << header.SEQUENCE_NUMBER << endl;
            if (header.TRANSMISSION_STATUS == 1) {
                cout << "Transmission status: ON" << endl;
            } else {
                cout << "Transmission status: OFF" << endl;
            }
        }
    }
}

int main() {
    MacFrameHeaderList list; // Create an instance of the MAC frame header list class
    thread updatesThread(handleUpdates, ref(list)); // Start a thread to handle updates to the MAC frame headers
    thread externalUpdatesThread(handleExternalUpdates, ref(list)); // Start a thread to handle updates from an external radio interface layer
    thread realTimeUpdatesThread(handleRealTimeUpdates, ref(list)); // Start a thread to handle real-time processing of updates to the MAC frame headers
    thread loggingThread(handleLogging, ref(list)); // Start a thread to handle logging of the MAC frame headers
    updatesThread.join(); // Wait for the updates thread to finish
    externalUpdatesThread.join(); // Wait for the external updates thread to finish
    realTimeUpdatesThread.join(); // Wait for the real-time updates thread to finish
    loggingThread.join(); // Wait for the logging thread to finish
    return 0;
}
```

The above code defines a `MacFrameHeaderList` class that stores a list of MAC frame headers and provides methods for adding, removing, and accessing the elements in the list. The `handleUpdates`, `handleExternalUpdates`, `handleRealTimeUpdates`, and `handleLogging` functions are used to handle updates to the MAC frame headers, process real-time updates, and log the MAC frame headers, respectively.

In the `main` function, we create an instance of the `MacFrameHeaderList` class, start four threads: one for handling updates to the MAC frame headers, another for handling updates from an external radio interface layer, a third for handling real-time processing of updates to the MAC frame headers, and a fourth for logging the MAC frame headers. We then wait for all the threads to finish before exiting the program.

Note that in this example, we use a `thread_pool` object to manage the threads that access the `MacFrameHeaderList`. The `thread_pool` ensures that only a certain number of threads are allowed to access the list at any given time, which helps prevent race conditions and improves performance.']

