int add_crc_indication(CRC_INDICATION_LIST_T* list, uint32_t rx_ue_information_tag, uint16_t rnti, uint8_t crc_indication_rel8_tag) {
    pthread_mutex_lock(&list->mutex);
    semaphore_wait(list->sem);
    if (list->capacity == list->size) {
        // error: no more space in the list
        return -1;
    }
    NFAPI_CRC_INDICATION_PDU_T* new_item = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_item->rx_ue_information_tag = rx_ue_information_tag;
    new_item->rnti = rnti;
    new_item->crc_indication_rel8_tag = crc_indication_rel8_tag;
    list->list[list->size++] = new_item;
    semaphore_post(list->sem);
    pthread_mutex_unlock(&list->mutex);
}

int remove_crc_indication(CRC_INDICATION_LIST_T* list, uint32_t rx_ue_information_tag, uint16_t rnti) {
    pthread_mutex_lock(&list->mutex);
    semaphore_wait(list->sem);
