            free(list->list[i]);
            list->list[i] = NULL;
            --list->size;
            semaphore_post(list->sem);
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }
    // error: no matching item found in the list
    semaphore_post(list->sem);
    pthread_mutex_unlock(&list->mutex);
}

