int read_temperature(TemperatureReading *readings, int max_readings) {
    // Read a floating-point number from standard input
    float temperature;
    scanf("%f", &temperature);

    // Check if the temperature is within the specified range
    if (temperature < -50 || temperature > 120) {
        printf("Warning: Temperature reading %f out of range\n", temperature);
        return 0;
    }

    // Get the current timestamp using a high-resolution system clock function
    time_t timestamp = time(NULL);

