    reading->id = 1; // TODO: Replace with a unique ID for each temperature reading
    reading->timestamp = timestamp;
    reading->temperature = temperature;

    // Add the new reading to the linked list of TemperatureReadings
    readings[reading->id] = reading;

    // Increment the number of valid temperature readings processed
    return 1;
}

int process_temperature_readings(TemperatureReading *readings, int max_readings) {
    // Calculate the average temperature and the highest temperature recorded
    float sum = 0;
    float highest = -50;
    for (int i = 1; i <= max_readings; i++) {
        TemperatureReading *reading = readings[i];
        sum += reading->temperature;
        if (reading->temperature > highest) {
            highest = reading->temperature;
        }
    }
    float average = sum / max_readings;

    // Print the results to standard output
    printf("Average temperature: %f\n", average);
    printf("Highest recorded temperature: %f\n", highest);

    // Integrate with an external weather service API for additional environmental data
    char *response = NULL;
    if (readings != NULL) {
        response = send_weather_request(WEATHER_API_URL, readings);
        printf("External API call status: %s\n", response);
    }

    // Clean up memory resources
    free(response);
    for (int i = 1; i <= max_readings; i++) {
        TemperatureReading *reading = readings[i];
        free(reading);
    }

    return 0;
}

int main() {
    // Set the maximum number of temperature readings to store
    int max_readings = 10;

    // Create a linked list of TemperatureReading structures
    TemperatureReading *readings = malloc(sizeof(TemperatureReading) * max_readings);

    // Read and process temperature readings from standard input
    int valid_readings = 0;
    while (valid_readings < max_readings) {
        valid_readings += read_temperature(readings, max_readings);
    }

    // Process the temperature readings and calculate the average temperature
    process_temperature_readings(readings, max_readings);

    return 0;
}
