// Function to insert a record into the hash table
void insert_record(HashTable *ht, int key, long offset) {
    // Check if the hash table needs to be resized
    if (ht->size == ht->capacity) {
        // Resize the hash table by 50%
        ht->capacity += ht->capacity / 2;
        ht->records = realloc(ht->records, sizeof(Record *) * ht->capacity);
        if (!ht->records) {
            fprintf(stderr, "Failed to resize hash table\n");
            return;
