    Record *record = ht->records[i];
    for (size_t j = i; j < ht->size; j++) {
        ht->records[j] = ht->records[j + 1];
    }
    free(record);
}

// Function to handle concurrent access from multiple threads
void handle_concurrent_access(HashTable *ht) {
