typedef struct {
    int rrc_message_type;
    int transport_channel;
    unsigned long pdcp_sn;
    unsigned char rnti;
} NFAPI_RRC_CU_TRANSPORT_PDU_T;

EVP_CIPHER *init_crypto(const char *cipher) {
    EVP_CIPHER *evp = NULL;
    if (strcmp(cipher, "des") == 0) {
        evp = EVP_des_ecb();
    } else if (strcmp(cipher, "ede") == 0) {
        evp = EVP_des_ede();
    } else if (strcmp(cipher, "ede3") == 0) {
        evp = EVP_des_ede3();
    } else if (strcmp(cipher, "cfb") == 0) {
        evp = EVP_des_cfb();
    } else {
        printf("Invalid cipher selection.\n");
    }
    return evp;
}

NFAPI_RRC_CU_TRANSPORT_PDU_T *populate_array(int num, const char *cipher) {
    NFAPI_RRC_CU_TRANSPORT_PDU_T *arr = NULL;
    EVP_CIPHER *evp = init_crypto(cipher);
    if (evp == NULL) {
        printf("Error initializing cipher.\n");
        return NULL;
    }
    arr = malloc(num * sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T));
    if (arr == NULL) {
        printf("Memory allocation error.\n");
        EVP_CIPHER_free(evp);
        return NULL;
    }
    for (int i = 0; i < num; ++i) {
        arr[i].rrc_message_type = i % 2 ? RRC_MESSAGE_TYPE_TAG_1 : RRC_MESSAGE_TYPE_TAG_2;
        arr[i].transport_channel = (i * 7) % 4 + 1;
        arr[i].pdcp_sn = i << 8 | 0xff;
        arr[i].rnti = i & 0xf;
        DES_KEY_SCHEDULE des_key_schedule;
        DES_crypt_ecb(evp, &des_key_schedule, &arr[i].pdcp_sn, &arr[i].pdcp_sn);
    }
    EVP_CIPHER_free(evp);
    return arr;
}
```
