    { 1, 2 }, // Associate CRC indication 1 with UE information 2
    { 2, 3 }, // Associate CRC indication 2 with UE information 3
};

// Define the function to populate the array of CRC indications
void populate_crc_indications(NFAPI_CRC_INDICATION_PDU_T **crc_indications, size_t num_threads) {
    // Initialize the mutex for thread-safe access to the mapping table
    pthread_mutex_t crc_mapping_mutex = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for the array of CRC indications
    *crc_indications = malloc(num_threads * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    assert(*crc_indications != NULL);

    // Initialize the CRCFLAG values in each structure to 0
    for (size_t i = 0; i < num_threads; i++) {
        (*crc_indications)[i].CRCFLAG = 0;
    }

    // Lock the mutex before accessing the mapping table
    pthread_mutex_lock(&crc_mapping_mutex);

    // Populate the array of CRC indications with random CRCFLAG values
    for (size_t i = 0; i < num_threads; i++) {
        uint32_t rx_ue_information_tag = rand() % crc_mapping_table[i].RX_UE_INFORMATION_TAG;
