        (*crc_indications)[i].RX_UE_INFORMATION_TAG = rx_ue_information_tag;
        (*crc_indications)[i].RNTI = rnti;
    }

    // Unlock the mutex after accessing the mapping table
    pthread_mutex_unlock(&crc_mapping_mutex);
}
