#include <stdio.h>

typedef struct {
    S1AP_INITIU_MESSAGE_RRC_INST *message;
    UE_CONTEXT_T *context;
    DL_CCCH_MESSAGE_TRANSPORT *transport;
} MAC_RX_PACKET_T;

typedef struct {
    uint32_t mme_ue_s1ap_id;
    uint32_t enb_ue_s1ap_id;
} UE_CONTEXT_T;

typedef struct {
    uint32_t pagging_indication;
    UE_CONTEXT_T *context;
} PAGGING_INDICATION_T;

#define MAX_MAC_RX_PACKETS 10000
#define MAX_UE_CONTEXTS 5000
#define MAX_PAGGING_INDICATIONS 5000

// Mapping table for UE contexts and paging indications
static UE_CONTEXT_T *ue_contexts[MAX_UE_CONTEXTS];
static PAGGING_INDICATION_T *paging_indications[MAX_PAGGING_INDICATIONS];

// Semaphores for synchronizing access to the mapping table and data structures
static sem_t ue_contexts_sem;
static sem_t paging_indications_sem;

// Function for managing creation and population of MAC RX packets under dynamic network load conditions
void mac_rx_packet_manager(MAC_RX_PACKET_T *mac_rx_packet) {
    // Acquire semaphore to access mapping table
    sem_wait(&ue_contexts_sem);

    // Check if the UE context already exists in the mapping table
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (ue_contexts[i] != NULL && ue_contexts[i]->mme_ue_s1ap_id == mac_rx_packet->message->mme_ue_s1ap_id) {
            // UE context already exists, update the paging indication for this context
            PAGGING_INDICATION_T *paging_indication = (PAGGING_INDICATION_T *) malloc(sizeof(PAGGING_INDICATION_T));
            paging_indication->pagging_indication = mac_rx_packet->transport->pagging_indication;
            paging_indication->context = ue_contexts[i];
            // Add the paging indication to the mapping table
            sem_wait(&paging_indications_sem);
            paging_indications[paging_indication->context->enb_ue_s1ap_id] = paging_indication;
            sem_post(&paging_indications_sem);
            // Release semaphore to access mapping table
            sem_post(&ue_contexts_sem);
            return;
        }
    }

    // Create a new UE context and add it to the mapping table
    UE_CONTEXT_T *ue_context = (UE_CONTEXT_T *) malloc(sizeof(UE_CONTEXT_T));
    ue_context->mme_ue_s1ap_id = mac_rx_packet->message->mme_ue_s1ap_id;
    ue_context->enb_ue_s1ap_id = mac_rx_packet->transport->enb_ue_s1ap_id;
    // Add the UE context to the mapping table
    sem_wait(&ue_contexts_sem);
    ue_contexts[ue_context->mme_ue_s1ap_id] = ue_context;
    sem_post(&ue_contexts_sem);

    // Create a new paging indication for this UE context and add it to the mapping table
    PAGGING_INDICATION_T *paging_indication = (PAGGING_INDICATION_T *) malloc(sizeof(PAGGING_INDICATION_T));
