            pthread_mutex_unlock(&list->mutex);
            return -1;
        }

        // Update the capacity and data pointer
        list->data = new_data;
        list->capacity *= 2;
    }

    // Copy the element to the next available position in the list
    memcpy(&list->data[list->size], element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size++;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Define the function to remove an element from the list
int nfapi_crc_indication_list_remove(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Find the element in the list and remove it
    for (size_t i = 0; i < list->size; i++) {
        if (memcmp(&list->data[i], element, sizeof(NFAPI_CRC_INDICATION_PDU_T)) == 0) {
            // Remove the element by shifting all subsequent elements to its position
            for (size_t j = i + 1; j < list->size; j++) {
                memcpy(&list->data[j - 1], &list->data[j], sizeof(NFAPI_CRC_INDICATION_PDU_T));
            }

            // Decrement the size of the list and return
            list->size--;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }

    // If the element was not found, unlock the mutex and return an error
    pthread_mutex_unlock(&list->mutex);
    return -1;
}

// Define the function to clear the list of elements
void nfapi_crc_indication_list_clear(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Clear the list by setting its size to zero
    list->size = 0;

    pthread_mutex_unlock(&list->mutex);
}

// Define the function to free the memory allocated for the list
void nfapi_crc_indication_list_free(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Free the data array and unlock the mutex
    free(list->data);
    list->data = NULL;
    pthread_mutex_unlock(&list->mutex);
}
