        printf("Invalid number of records: %d\n", num_records);
        return;
    }

    // Dynamically allocate memory for the array of records
    Record* records = (Record*) malloc(num_records * sizeof(Record));
    if (!records) {
        printf("Failed to allocate memory for %d records\n", num_records);
        return;
    }

    // Initialize each record with a random value within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 100 + 1;
    }

    // Set the long pointer in each record to a calculated offset value
    for (int i = 0; i < num_records; i++) {
        records[i].ptr = mmap(NULL, sizeof(long), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (records[i].ptr == MAP_FAILED) {
            printf("Failed to map memory for record %d\n", i);
            return;
