    // Initialize the status flag in each record to a random value
    for (int i = 0; i < num_records; i++) {
        records[i].status = rand() % 2;
    }

    // Log initialization parameters and any errors encountered during execution
    printf("Initialized %d records with values between 1 and 100\n", num_records);

    // Free all allocated memory when the function exits, even if an error occurs
    atexit(free_records);
