#define MAX_ARRAY_SIZE 1024 // maximum size of the transport PDU array
#define POOL_SIZE 64 // size of the RNTI pool
#define TIMEOUT 5 // timeout in seconds for acquiring an RNTI from the pool
#define MIN_RNTI 1 // minimum value of an RNTI
#define MAX_RNTI 63 // maximum value of an RNTI

// structure to represent a transport PDU
typedef struct {
    NFAPI_RRC_CU_TRANSPORT_PDU_T pdu;
} TransportPDU;

// pool of available RNTIs
struct RNTIPool {
    int size; // number of available RNTIs in the pool
    int head; // index of the first available RNTI in the pool
};

// function to initialize an array of transport PDUs
void initialize_transport_pdu_array(TransportPDU **pduArray, int *size) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // mutex for thread safety
    struct RNTIPool rntiPool; // pool of available RNTIs
    bool isInitialized = false; // flag to indicate if the array is initialized

    // acquire a lock on the mutex
    pthread_mutex_lock(&mutex);

    // check if the array has already been initialized
    if (!isInitialized) {
        // dynamically allocate memory for the transport PDU array
        *pduArray = (TransportPDU*) malloc(sizeof(TransportPDU) * MAX_ARRAY_SIZE);
        memset(*pduArray, 0, sizeof(TransportPDU) * MAX_ARRAY_SIZE);

        // initialize the RNTI pool
        rntiPool.size = POOL_SIZE;
        rntiPool.head = 0;

        // mark the array as initialized
        isInitialized = true;
    }

    // acquire an RNTI from the pool
    int rnti = acquireRNTI(&rntiPool);

    // check if an RNTI was acquired
    if (rnti != -1) {
        // initialize the transport PDU
        (*pduArray)[*size].pdu.messageTypeTag = RRC_MESSAGE_TYPE_TAG;
        (*pduArray)[*size].pdu.transportChannel = RRC_TRANSPORT_CHANNEL_TAG;
        (*pduArray)[*size].pdu.pdcpSN = generatePDCPSN(rnti);
        (*pduArray)[*size].pdu.rnti = rnti;

        // increment the size of the array
        *size = *size + 1;
    } else {
        // log a message indicating that no RNTI was acquired
        printf("Unable to acquire an RNTI from the pool\n");
    }

    // release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// function to generate a PDCP sequence number using an RNTI
int generatePDCPSN(int rnti) {
    return (rnti - MIN_RNTI) * 256 + 1;
}

// function to acquire an RNTI from the pool
int acquireRNTI(struct RNTIPool *pool) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // mutex for thread safety
    bool isAvailable = false; // flag to indicate if an RNTI is available in the pool
    int rnti = -1; // variable to store the acquired RNTI

    // acquire a lock on the mutex
    pthread_mutex_lock(&mutex);

    // check if there are any available RNTIs in the pool
    if (pool->size > 0) {
        // get the first available RNTI from the head of the pool
        rnti = pool->head;

        // increment the head of the pool
        pool->head++;

        // check if the head is past the end of the pool, and wrap around if necessary
        if (pool->head == pool->size) {
            pool->head = 0;
        }
    } else {
        printf("RNTI pool is exhausted\n");
    }

    // release the lock on the mutex
    pthread_mutex_unlock(&mutex);

    return rnti;
}

// function to deallocate memory for a transport PDU array
void deallocateTransportPDUArray(TransportPDU **pduArray) {
    // check if the array is null
    if (*pduArray != NULL) {
        free(*pduArray);
        *pduArray = NULL;
    }
}
