// Structure to store a dynamic array of NFAPI_RX_FRAME_T structures
typedef struct {
    nfapi_rx_frame_t **frames;
    size_t num_frames;
} nfapi_rx_frames_t;

// Initialize an empty RX frame structure
static inline void init_nfapi_rx_frame(nfapi_rx_frame_t *frame) {
    frame->rrc_pdu = NULL;
    frame->rnti = 0;
    frame->frame_number = 0;
}

// Allocate and initialize a new RX frame structure
static inline nfapi_rx_frame_t *allocate_nfapi_rx_frame() {
    nfapi_rx_frame_t *frame = (nfapi_rx_frame_t *)malloc(sizeof(nfapi_rx_frame_t));
    init_nfapi_rx_frame(frame);
    return frame;
}

// Free a RX frame structure and its associated resources
static inline void free_nfapi_rx_frame(nfapi_rx_frame_t *frame) {
    if (frame->rrc_pdu) {
        free(frame->rrc_pdu);
    }
    free(frame);
}

// Initialize an empty RX frames structure
static inline void init_nfapi_rx_frames(nfapi_rx_frames_t *frames) {
    frames->frames = NULL;
    frames->num_frames = 0;
}

// Allocate and initialize a new RX frames structure with a given capacity
static inline nfapi_rx_frames_t *allocate_nfapi_rx_frames(size_t capacity) {
    nfapi_rx_frames_t *frames = (nfapi_rx_frames_t *)malloc(sizeof(nfapi_rx_frames_t));
    init_nfapi_rx_frames(frames);
    frames->frames = (nfapi_rx_frame_t **)calloc(capacity, sizeof(nfapi_rx_frame_t *));
    return frames;
}

// Free a RX frames structure and its associated resources
static inline void free_nfapi_rx_frames(nfapi_rx_frames_t *frames) {
    for (size_t i = 0; i < frames->num_frames; i++) {
        if (frames->frames[i]) {
            free_nfapi_rx_frame(frames->frames[i]);
        }
    }
    free(frames->frames);
    free(frames);
