    char *new_filename = strdup(filename);
    new_filename = strtok(new_filename, pattern);

    // Limit the total length of the new filename to 255 characters
    if (strlen(new_filename) > 255) {
        // If the filename is too long, truncate it
        new_filename[255] = '\0';
    }

    // Determine the number of digits to include in the new file extension
    size_t num_vowels = 0;
    for (size_t i = 0; i < strlen(new_filename); i++) {
        if (new_filename[i] == 'A' || new_filename[i] == 'E' || new_filename[i] == 'I' || new_filename[i] == 'O' || new_filename[i] == 'U') {
            num_vowels++;
        }
    }
    size_t max_digits = 3;
    if (num_vowels > max_digits) {
        // If there are more than three vowels in the filename, truncate the number of digits to three
        num_vowels = max_digits;
    }
    size_t new_extension_length = num_vowels + 1; // Include the period character

    // Build a new file extension based on the vowel count
    char *new_extension = (char *)malloc(new_extension_length);
    for (size_t i = 0; i < num_vowels; i++) {
        new_extension[i] = 'A' + i;
    }
    // Append a default extension if necessary
    if (num_vowels == 0) {
        new_extension[0] = 'X';
    }
    new_extension[num_vowels] = '\0';

    // Build the final filename by concatenating the basename and the new extension
    size_t total_length = strlen(new_filename) + strlen(new_extension);
    char *final_filename = (char *)malloc(total_length + 1);
    strcpy(final_filename, new_filename);
    strcat(final_filename, ".");
    strcat(final_filename, new_extension);

    free(new_filename);
    free(new_extension);

    return final_filename;
}

