#include <thread>
#include <mutex>
#include <condition_variable>
#include <stdexcept>

// External dependencies
#include <ImageConverter.h>

class DynamicFileConverter {
public:
    DynamicFileConverter(const std::string& imageFormat, const std::string& pdfFormat) :
        imageFormat_(imageFormat), pdfFormat_(pdfFormat) {}

    void convert(const std::string& inputPath, const std::string& outputPath) {
        // Load the necessary tools for the conversion at runtime.
        loadTools();

        // Check if the input file exists and is readable.
        if (!std::filesystem::exists(inputPath)) {
            throw std::invalid_argument("Input file does not exist.");
        } else if (!std::filesystem::is_regular_file(inputPath)) {
            throw std::invalid_argument("Input path is not a regular file.");
        } else if (!std::filesystem::can_read(inputPath)) {
            throw std::invalid_argument("Input file cannot be read.");
        }

        // Check if the output file exists and is writable.
        if (std::filesystem::exists(outputPath)) {
            if (!std::filesystem::is_regular_file(outputPath)) {
                throw std::invalid_argument("Output path is not a regular file.");
            } else if (!std::filesystem::can_write(outputPath)) {
                throw std::invalid_argument("Output file cannot be written to.");
            }
        }

        // Convert the image using the third-party tool.
        ImageConverter converter;
        try {
            converter.convert(inputPath, outputPath, imageFormat_, pdfFormat_);
        } catch (const std::exception& e) {
            throw std::runtime_error("Error converting image to PDF: " + e.what());
        }
    }

private:
    // Load the necessary tools for the conversion at runtime.
    void loadTools() {
        if (imageFormat_ == "jpg" || imageFormat_ == "jpeg") {
            ImageConverter::loadJpeg();
        } else if (imageFormat_ == "png") {
            ImageConverter::loadPng();
        } else if (imageFormat_ == "gif") {
            ImageConverter::loadGif();
        } else {
            throw std::invalid_argument("Invalid image format.");
        }
    }

    // The input image format.
    const std::string imageFormat_;

    // The output PDF format.
    const std::string pdfFormat_;
};
```
This class takes an `imageFormat` and a `pdfFormat` as constructor arguments, and provides a `convert()` method that accepts file paths for input images and desired output PDF files. It also includes a `loadTools()` method to dynamically load the necessary tools for the conversion at runtime.

