// Define a hash table for storing the RNTI values
typedef struct {
    uint16_t rnti; // Unique identifier for the UE
    struct Node *node; // Pointer to the linked list node
} HashTable;

// Function to generate a unique sequence number based on the timestamp and device ID
uint32_t get_unique_seq_num(void) {
    uint32_t seq_num;
    time_t t = time(NULL); // Get current timestamp
    srand((unsigned int)t); // Seed the RNG with the timestamp
    seq_num = rand() % 65535; // Generate a random number between 0 and 65535
    return seq_num;
}

// Function to add a new RX information to the list
void add_rx_info(NFAPI_CRC_INDICATION_PDU_T *rx_info) {
    // Check for null pointers and errors
    if (rx_info == NULL || rx_info->rnti > 65535) {
        return;
    }

    // Generate a unique sequence number based on the timestamp and device ID
    uint32_t seq_num = get_unique_seq_num();

    // Create a new linked list node for the RX information
    Node *new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        // Handle memory exhaustion error
        return;
    }

    // Initialize the node with the RX information and sequence number
    new_node->rx_info = rx_info;
    new_node->seq_num = seq_num;

    // Add the node to the linked list
    if (head == NULL) {
        head = new_node;
    } else {
        Node *current_node = head;
        while (current_node->next != NULL) {
            current_node = current_node->next;
        }
        current_node->next = new_node;
    }

    // Add the RNTI value to the hash table
    HashTable *ht = malloc(sizeof(HashTable));
    if (ht == NULL) {
        // Handle memory exhaustion error
        return;
    }
    ht->rnti = rx_info->rnti;
    ht->node = new_node;
    if (head == NULL) {
        head = ht;
    } else {
        HashTable *current_ht = head;
        while (current_ht->next != NULL) {
            current_ht = current_ht->next;
        }
        current_ht->next = ht;
    }
}

// Function to remove an RX information from the list
void remove_rx_info(uint16_t rnti) {
    // Check for null pointers and errors
    if (head == NULL || rnti > 65535) {
        return;
    }

    // Find the node in the linked list corresponding to the RNTI value
    Node *current_node = head;
    while (current_node != NULL && current_node->rx_info->rnti != rnti) {
        current_node = current_node->next;
    }
    if (current_node == NULL) {
        return; // RNTI value not found in the list
    }

    // Remove the node from the linked list and free its memory
    Node *prev_node = current_node->prev;
    if (prev_node != NULL) {
        prev_node->next = current_node->next;
    } else {
        head = current_node->next;
    }
    free(current_node);

    // Remove the RNTI value from the hash table and free its memory
    HashTable *ht = head;
    while (ht != NULL && ht->rnti != rnti) {
        ht = ht->next;
    }
    if (ht == NULL) {
        return; // RNTI value not found in the hash table
    }
    HashTable *prev_ht = ht->prev;
    if (prev_ht != NULL) {
        prev_ht->next = ht->next;
    } else {
        head = ht->next;
    }
    free(ht);
}

// Function to retrieve the number of unique RNTI values in the list
int get_rnti_count() {
    int count = 0;
    HashTable *ht = head;
    while (ht != NULL) {
        count++;
        ht = ht->next;
    }
    return count;
}

// Function to periodically clear the list after processing 10,000 entries
void clear_list() {
    if (head == NULL) {
        return;
    }
    Node *current_node = head;
    int count = 0;
    while (current_node != NULL && count < 10000) {
        current_node = current_node->next;
        count++;
    }
    if (count >= 10000) {
        // Clear the list and reset the sequence number
        free(head);
        head = NULL;
        seq_num = 0;
    }
}

// Public interface to add a new RX information to the list
void add_rx_info_public(NFAPI_CRC_INDICATION_PDU_T *rx_info) {
    pthread_mutex_lock(&mutex);
    add_rx_info(rx_info);
    pthread_mutex_unlock(&mutex);
}

// Public interface to remove an RX information from the list
void remove_rx_info_public(uint16_t rnti) {
    pthread_mutex_lock(&mutex);
    remove_rx_info(rnti);
    pthread_mutex_unlock(&mutex);
}

// Public interface to retrieve the number of unique RNTI values in the list
int get_rnti_count_public() {
    int count = 0;
    pthread_mutex_lock(&mutex);
    count = get_rnti_count();
    pthread_mutex_unlock(&mutex);
    return count;
}
