    uint32_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void populate_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t *size, size_t capacity, FILE *input) {
    // Allocate memory for the list on the stack if possible, otherwise on the heap
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    if (capacity <= 1000) {
        pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
    } else {
        pdu = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    // Read the input file and populate the list
    size_t count = 0;
    while (fscanf(input, "%u %u %u", &pdu[count].RX_UE_INFORMATION_TAG, &pdu[count].RNTI, &pdu[count].CRC_INDICATION_REL8_TAG) == 3 && count < capacity) {
        ++count;
    }

    // Update the size of the list and return the populated list
    *size = count;
    *list = pdu;
}

void cleanup_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t size) {
    // Free the memory allocated for the list
    free(*list);
