    // Allocate memory for the transactions array
    transaction* transactions = (transaction*)malloc(num_transactions * sizeof(transaction));
    if (!transactions) {
        // Handle error: unable to allocate memory for transactions array
        free(timestamps);
        free(users);
        return;
    }

    // Generate random transaction amounts and user IDs
