        transactions[i].amount = rand() % 10000.0;
        int user_index = rand() % num_users;
        transactions[i].user_id = users[user_index];
    }

    // Allocate memory for the log entries array
    log_entry* log_entries = (log_entry*)malloc(num_logs * sizeof(log_entry));
    if (!log_entries) {
        // Handle error: unable to allocate memory for log entries array
        free(timestamps);
        free(users);
        free(transactions);
        return;
    }

    // Initialize each log entry with a valid transaction
    int count = 0;
    while (count < num_logs) {
        int transaction_index = rand() % num_transactions;
        if (transactions[transaction_index].user_id != NULL) {
            log_entries[count].timestamp = timestamps[rand() % num_timestamps];
            log_entries[count].transaction = transactions[transaction_index];
            count++;
        }
    }

    // Free memory allocated for each array
    free(timestamps);
    free(users);
    free(transactions);
