// Function to initialize and populate an array of FrameHeader structures
void initFrameHeaders(FrameHeader** headers, int maxFrames) {
    // Allocate memory for the array of frame headers
    *headers = (FrameHeader*)malloc(maxFrames * sizeof(FrameHeader));
    if (*headers == NULL) {
        // Handle out-of-memory error
        fprintf(stderr, "Error: failed to allocate memory for frame headers\n");
        return;
    }

    int sequenceNumber = 0;
    long timestamp = 0;
    for (int i = 0; i < maxFrames; i++) {
        // Populate the frame header with the next available sequence number and timestamp
        (*headers)[i].sequenceNumber = sequenceNumber++;
        (*headers)[i].timestamp = timestamp + FRAME_INTERVAL;
        if (sequenceNumber > INT_MAX) {
            // Handle overflow in the sequence number
            sequenceNumber = 0;
            timestamp += FRAME_INTERVAL * INT_MAX;
        }
    }
}

// Function to handle data from an external source that may experience latency or temporary unavailability
void populateFrameHeaders(FrameHeader** headers, int maxFrames, void* externalData) {
    // Ensure the external data is valid and can be used to populate the frame headers
    if (externalData == NULL) {
        return;
    }

    // Iterate over the external data and populate the frame headers accordingly
    for (int i = 0; i < maxFrames; i++) {
        // Check for any errors or delays in the external data source
        if (externalData[i].sequenceNumber < sequenceNumber) {
            // Handle out-of-order or missing data from the external source
            continue;
        } else if (externalData[i].timestamp > timestamp) {
            // Handle any timestamps that are not yet supported by the system
            continue;
        }

        (*headers)[i].sequenceNumber = externalData[i].sequenceNumber;
        (*headers)[i].timestamp = externalData[i].timestamp;
    }
}
