    // Check if there is enough space in the pool for the requested number of elements
    if (num > pool->capacity - pool->count) {
        printf("Error: Not enough space in the pool. Capacity: %zu, Count: %zu, Requested: %zu\n", pool->capacity, pool->count, num);
        pthread_mutex_unlock(&pool->lock);
        return NULL;
