    // Update the pool statistics and unlock the mutex
    pool->count += num;
    pthread_mutex_unlock(&pool->lock);

    return elements;
}

// Function to free a CRC indication structure from the pool
void nfapi_crc_indication_free(NFAPI_CRC_INDICATION_PDU_T *element) {
    // Check if the input parameter is NULL
