        printf("Error: Invalid input parameter. Must not be NULL.\n");
        return;
    }

    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&pool->lock);

    // Check if the element is in the pool and decrement the count accordingly
    size_t index = (size_t)(element - pool->elements);
    if (index >= pool->capacity || pool->count == 0) {
        printf("Error: Element not found in the pool. Capacity: %zu, Count: %zu\n", pool->capacity, pool->count);
        pthread_mutex_unlock(&pool->lock);
        return;
    }
    pool->count -= 1;

    // Free the element and update the statistics
    free(element);

    // Unlock the mutex
    pthread_mutex_unlock(&pool->lock);
}
