static void* shared_mem_pool = NULL; // Pointer to the start of the shared memory pool
static size_t shared_mem_size = 0; // Size of the shared memory pool
static size_t shared_mem_usage = 0; // Current usage of the shared memory pool

// Function to initialize the shared memory pool
int nfapi_rx_frame_pdu_init(void* mem_pool, size_t mem_size) {
    if (shared_mem_pool != NULL || mem_pool == NULL || mem_size == 0) {
        return -1; // Error: invalid input parameters or already initialized
    }
    shared_mem_pool = mem_pool;
    shared_mem_size = mem_size;
    shared_mem_usage = 0;
    return 0; // Success
}

// Function to dynamically allocate memory for an array of NFAPI RX frame PDUs
NFAPI_RX_FRAME_PDU_T* nfapi_rx_frame_pdu_alloc(size_t num_pdu) {
    if (shared_mem_pool == NULL || num_pdu == 0 || num_pdu > 10000) { // Limit the maximum number of PDUs to prevent resource exhaustion
        return NULL;
    }
    size_t mem_size = num_pdu * sizeof(NFAPI_RX_FRAME_PDU_T);
    if (shared_mem_usage + mem_size > shared_mem_size) { // Check for overflow and sufficient memory
        return NULL;
    }
    NFAPI_RX_FRAME_PDU_T* pdu = (NFAPI_RX_FRAME_PDU_T*)malloc(mem_size);
    if (pdu == NULL) { // Malloc failed
        return NULL;
    }
    memset(pdu, 0, mem_size); // Clear the memory
    shared_mem_usage += mem_size; // Update the usage of shared memory
    return pdu; // Return the allocated memory
}

// Function to free the memory allocated by nfapi_rx_frame_pdu_alloc()
void nfapi_rx_frame_pdu_free(NFAPI_RX_FRAME_PDU_T* pdu, size_t num_pdu) {
    if (pdu == NULL || num_pdu == 0 || shared_mem_pool == NULL) { // Invalid input parameters or not initialized
        return;
    }
    size_t mem_size = num_pdu * sizeof(NFAPI_RX_FRAME_PDU_T);
    if (shared_mem_usage < mem_size) { // Check for underflow and sufficient memory
        return;
    }
    shared_mem_usage -= mem_size; // Update the usage of shared memory
    free(pdu); // Free the memory
}
