#include "nfapi_types.h"

// Function to dynamically create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(unsigned int num_rx_ue, unsigned int num_rnti) {
  // Initialize a random seed for the generation of RNTIs
  srand(time(NULL));

  // Allocate memory for the list of structures
  NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_rx_ue);

  // Populate the list of structures with valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG values
  for (int i = 0; i < num_rx_ue; i++) {
    pdu_list[i].tag = RX_UE_INFORMATION_TAG;
    pdu_list[i].rx_ue_information.rnti = rand() % num_rnti + 1; // Generate a random RNTI between 1 and the maximum number of RNTIs (num_rnti)
    pdu_list[i].crc_indication_rel8_tag = rand() % 2; // Generate a random CRCFLAG value (0 or 1)
  }

  // Check for duplicates in the RNTI values and reallocate the structures in memory if necessary
  bool duplicate_found = false;
  unsigned int unique_rnti_count = num_rx_ue;
  do {
    duplicate_found = false;
    for (int i = 0; i < num_rx_ue - 1; i++) {
      if (pdu_list[i].rx_ue_information.rnti == pdu_list[i + 1].rx_ue_information.rnti) {
        duplicate_found = true;
        break;
      }
    }

    // If duplicates are found, reallocate the structures in memory to resolve conflicts without causing performance bottlenecks or increasing lock contention
    if (duplicate_found) {
      NFAPI_CRC_INDICATION_PDU_T* new_pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * unique_rnti_count);
      if (!new_pdu_list) {
        // If reallocation fails, free the existing memory and return NULL to indicate an error
        free(pdu_list);
        return NULL;
      }

      pdu_list = new_pdu_list;
      unique_rnti_count--;
    }
  } while (duplicate_found);

  // Return the populated list of structures
  return pdu_list;
}
