// C function to manage a dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    bool crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// List of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **list;
    size_t capacity; // number of elements in the list
    size_t count; // number of elements in the list
} CRC_INDICATION_LIST;

// Initialize the list with a given capacity
void init_crc_indication_list(CRC_INDICATION_LIST *list, size_t capacity) {
    list->capacity = capacity;
    list->count = 0;
    list->list = (NFAPI_CRC_INDICATION_PDU_T **)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T *) * capacity);
}

// Add a new element to the list
void add_crc_indication(CRC_INDICATION_LIST *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    if (list->count >= list->capacity) {
        // Resize the list if it's full
        list->capacity *= 2;
        list->list = (NFAPI_CRC_INDICATION_PDU_T **)realloc(list->list, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * list->capacity);
    }

    list->list[list->count++] = element;
}

// Remove an element from the list by its index
void remove_crc_indication_at(CRC_INDICATION_LIST *list, size_t index) {
    if (index >= list->count) {
        return;
    }

    for (size_t i = index; i < list->count - 1; i++) {
        list->list[i] = list->list[i + 1];
    }

    list->count--;
}

// Remove an element from the list by its RNTI value
void remove_crc_indication(CRC_INDICATION_LIST *list, uint32_t rnti) {
    for (size_t i = 0; i < list->count; i++) {
        if (list->list[i]->rnti == rnti) {
            remove_crc_indication_at(list, i);
            return;
        }
    }
}

// Check if a given RNTI exists in the list
bool crc_indication_exists(CRC_INDICATION_LIST *list, uint32_t rnti) {
    for (size_t i = 0; i < list->count; i++) {
        if (list->list[i]->rnti == rnti) {
            return true;
        }
    }

    return false;
}

// Serialize the list to a file
void serialize_crc_indication_list(CRC_INDICATION_LIST *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        printf("Error: Failed to open %s for writing\n", filename);
        return;
    }

    for (size_t i = 0; i < list->count; i++) {
        NFAPI_CRC_INDICATION_PDU_T *element = list->list[i];
        fwrite(&element, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    fclose(file);
}

// Deserialize the list from a file
void deserialize_crc_indication_list(CRC_INDICATION_LIST *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        printf("Error: Failed to open %s for reading\n", filename);
        return;
    }

    while (true) {
        NFAPI_CRC_INDICATION_PDU_T element;
        size_t bytes_read = fread(&element, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        if (bytes_read == 0) {
            break; // reached end of file
        } else if (bytes_read != 1) {
            printf("Error: Failed to read from %s\n", filename);
            fclose(file);
            return;
        }

        add_crc_indication(list, &element);
    }

    fclose(file);
}

// Test cases
void test_add_crc_indication() {
    CRC_INDICATION_LIST list;
    init_crc_indication_list(&list, 10);

    add_crc_indication(&list, 1);
    assert(list.count == 1);

    add_crc_indication(&list, 2);
    assert(list.count == 2);

    remove_crc_indication(&list, 1);
    assert(list.count == 1);
}

void test_remove_crc_indication() {
    CRC_INDICATION_LIST list;
    init_crc_indication_list(&list, 10);

    add_crc_indication(&list, 1);
    remove_crc_indication(&list, 1);
    assert(list.count == 0);
}

void test_remove_crc_indication_at() {
    CRC_INDICATION_LIST list;
    init_crc_indication_list(&list, 10);

    add_crc_indication(&list, 1);
    remove_crc_indication_at(&list, 0);
    assert(list.count == 0);
}

void test_serialize() {
    CRC_INDICATION_LIST list;
    init_crc_indication_list(&list, 10);

    add_crc_indication(&list, 1);
    add_crc_indication(&list, 2);
    serialize_crc_indication_list(&list, "test.bin");

    assert(file_exists("test.bin"));
}

void test_deserialize() {
    CRC_INDICATION_LIST list;
    init_crc_indication_list(&list, 10);

    deserialize_crc_indication_list(&list, "test.bin");
    assert(list.count == 2);
}
