This is a small example that demonstrates how to use the CRC32 algorithm to checksum data in a file. The `crc32` function takes a pointer to an input buffer and its size as arguments, and returns the calculated CRC32 value.

```c
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <assert.h>

uint32_t crc32(const uint8_t *buf, size_t len) {
    uint32_t crc = 0xffffffff;

    for (size_t i = 0; i < len; i++) {
        uint8_t data = buf[i];
        for (int j = 7; j >= 0; j--) {
            uint32_t mix = (crc & 0xaaaaaaaa) << 1 | (crc & 0x55555555) >> 1;
            crc = (crc >> 1) ^ (data & 0x80 ? 0x04c11db7 : 0);
            data <<= 1;
            if ((mix ^ crc) & 0xc0000000) {
                crc = (crc << 1) ^ 0x04c11db7;
            }
        }
    }

    return ~crc;
}
```

