// The size of the hash table
static int rnti_hash_size = 0;

// The number of elements in the list
static int num_elements = 0;

// A lock for protecting concurrent access to the list and the hash table
static pthread_mutex_t *list_lock = NULL;

// Initializes the list with a given size
void nfapi_crc_indication_pdu_init(int size) {
  rnti_hash = (NFAPI_CRC_INDICATION_PDU_T **)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
  for (int i = 0; i < size; ++i) {
    rnti_hash[i] = NULL;
  }
  num_elements = 0;
  rnti_hash_size = size;
}

// Adds a new element to the list, reallocating memory if necessary
void nfapi_crc_indication_pdu_add(NFAPI_CRC_INDICATION_PDU_T *new_element) {
  // Acquire the lock before modifying the list
  pthread_mutex_lock(&list_lock);
  // Check if there is enough space in the hash table to store the new RNTI
  if (num_elements >= rnti_hash_size) {
    // Reallocate the hash table with a larger size
