            // Duplicate source ID found, return false
            free(sourceIdTable);
            return 0;
        }
    }

    // No duplicates found, return true
    free(sourceIdTable);
    return 1;
}

// Resize the array when the initial capacity is exceeded
DataPacket* resizePackets(DataPacket *packets, int numPackets) {
    // Allocate memory for a larger array
    DataPacket *newPackets = (DataPacket *)realloc(packets, sizeof(DataPacket) * 2 * numPackets);
    if (!newPackets) {
        perror("Error resizing data packets");
        return NULL;
    }

    // Update the number of packets and allocate new memory for the new array
    int newNumPackets = 2 * numPackets;
    newPackets = (DataPacket *)malloc(sizeof(DataPacket) * newNumPackets);
    if (!newPackets) {
        perror("Error allocating memory for resized data packets");
        return NULL;
    }

    // Copy the old array to the new one and free the old memory
    memcpy(newPackets, packets, sizeof(DataPacket) * numPackets);
    free(packets);

    return newPackets;
}
```
