// Define the structure for storing CRC indication data
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    char CRCFLAG; // randomly set to '1' or '0'
} NFAPI_CRC_INDICATION_PDU_T;

// Define a hash map for storing the unique RNTIs per thread
typedef struct {
    int *RNTI_list;
    pthread_mutex_t mutex; // mutex for synchronizing access to the hash map
} RNTI_HASHMAP_T;

// Define a function for generating a unique RNTI for each thread
int generateUniqueRNTI(pthread_t thread) {
    int rnti = 0; // initialize with a random value

    // Use a spinlock to ensure mutual exclusion while accessing the hash map
    pthread_spinlock_t lock;
    pthread_spin_init(&lock, PTHREAD_PROCESS_SHARED);
    pthread_spin_lock(&lock);

    // Iterate through the hash map to check for existing RNTIs
    RNTI_HASHMAP_T *hashmap = (RNTI_HASHMAP_T *)malloc(sizeof(RNTI_HASHMAP_T));
    hashmap->mutex = PTHREAD_MUTEX_INITIALIZER; // initialize the mutex for synchronizing access to the hash map
    hashmap->RNTI_list = (int *)malloc(10000 * sizeof(int)); // allocate memory for 10,000 RNTIs

    for (int i = 0; i < 10000; i++) {
        if (hashmap->RNTI_list[i] == -1) {
            rnti = i; // assign a unique RNTI to the thread
            hashmap->RNTI_list[i] = thread; // store the thread ID in the hash map
            break;
        }
    }

    pthread_spin_unlock(&lock);
    pthread_spin_destroy(&lock);

    return rnti;
}

// Define a function for allocating memory for an array of `NFAPI_CRC_INDICATION_PDU_T` structures
void allocateMemory(int num_elements, NFAPI_CRC_INDICATION_PDU_T **array) {
    // Allocate memory for the array and initialize each element with a unique RNTI
    *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < num_elements; i++) {
        (*array)[i].RX_UE_INFORMATION_TAG = generateUniqueRNTI(pthread_self());
        (*array)[i].RNTI = generateUniqueRNTI(pthread_self());
        (*array)[i].CRC_INDICATION_REL8_TAG = rand() % 2; // randomly set the CRCFLAG to '1' or '0'
    }
}

// Define a function for freeing memory allocated by `allocateMemory()`
void freeMemory(NFAPI_CRC_INDICATION_PDU_T **array) {
    // Free the memory allocated by `allocateMemory()`
    if (*array != NULL) {
        free(*array);
        *array = NULL;
    }
}

// Define a function for inserting an element into the array
void insertElement(NFAPI_CRC_INDICATION_PDU_T **array, int index, NFAPI_CRC_INDICATION_PDU_T element) {
    // Insert the element at the specified index in the array
    (*array)[index] = element;
}

// Define a function for searching an element in the array
NFAPI_CRC_INDICATION_PDU_T *searchElement(NFAPI_CRC_INDICATION_PDU_T **array, int index) {
    // Search for the specified element in the array
    if (index >= 0 && index < num_elements) {
        return &(*array)[index];
    } else {
        return NULL;
    }
}

// Define a function for updating an element in the array
void updateElement(NFAPI_CRC_INDICATION_PDU_T **array, int index, NFAPI_CRC_INDICATION_PDU_T element) {
    // Update the specified element in the array
    (*array)[index] = element;
}

// Define a function for deleting an element from the array
void deleteElement(NFAPI_CRC_INDICATION_PDU_T **array, int index) {
    // Delete the specified element from the array
    if (index >= 0 && index < num_elements) {
        (*array)[index] = NULL;
    }
}

// Define a function for handling concurrent read and write operations in the array
void handleConcurrentAccess(NFAPI_CRC_INDICATION_PDU_T **array, int num_threads, pthread_t *thread_list) {
    // Handle concurrent read and write operations in the array by using a mutex for synchronizing access
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // initialize the mutex for synchronizing access to the array
    pthread_mutex_lock(&mutex); // lock the mutex before accessing the array
    for (int i = 0; i < num_threads; i++) {
        int thread_id = pthread_self();
        if (thread_list[i] == thread_id) {
            NFAPI_CRC_INDICATION_PDU_T *element = searchElement(array, i);
            if (element != NULL) {
                updateElement(array, i, element);
            } else {
                allocateMemory(1, &element); // allocate memory for the element
                insertElement(array, i, element); // insert the element into the array
            }
        }
    }
    pthread_mutex_unlock(&mutex); // unlock the mutex after accessing the array
}

