// Define a mutex for synchronizing access to the list
pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically manage the list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_LIST_T *nfapi_crc_indication_list_manage(NFAPI_CRC_INDICATION_LIST_T *list, uint16_t rnti, uint8_t crcIndicationTag) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&listMutex);

    // Validate the RNTI value and log a warning if it falls outside the typical 5G network range
    if (rnti < 1 || rnti > 65535) {
        printf("Warning: Out-of-range RNTI value detected (%d)\n", rnti);
    }

    // Allocate memory for a new NFAPI_CRC_INDICATION_PDU_T structure if necessary
    if (list == NULL) {
        list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
        if (list == NULL) {
            // Handle memory allocation failure gracefully
            printf("Error: Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T structure\n");
            pthread_mutex_unlock(&listMutex);
            return list;
        }
    }

    // Ensure proper alignment of the RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG fields
    list->data = realloc(list->data, (list->count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->data == NULL) {
        // Handle memory allocation failure gracefully
        printf("Error: Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T structure\n");
        free(list);
        list = NULL;
        pthread_mutex_unlock(&listMutex);
        return list;
    }

    // Set the RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG fields of the new structure
    list->data[list->count].rnti = rnti;
    list->data[list->count].crcIndicationTag = crcIndicationTag;

    // Increment the number of elements in the list
    list->count++;

    // Unlock the mutex and return the updated list
    pthread_mutex_unlock(&listMutex);
    return list;
}

// Function to query the current number of elements in the list
size_t nfapi_crc_indication_list_count(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&listMutex);

    // Return the current number of elements in the list
    size_t count = list->count;

    // Unlock the mutex and return the value
    pthread_mutex_unlock(&listMutex);
    return count;
}
