// Define a concrete implementation of the InterfaceTable interface using a thread-safe data structure
class ConcreteInterfaceTable : public InterfaceTable {
 private:
  std::unordered_set<RNTI> uniqueRntiSet;
  std::vector<NFAPI_CRC_INDICATION_PDU_T> pduList;
  boost::mutex mutex;

 public:
  ConcreteInterfaceTable() : mutex(boost::mutex()) {}
  ~ConcreteInterfaceTable() { clear(); }

  void add(const NFAPI_CRC_INDICATION_PDU_T& pdu) override {
    boost::unique_lock<boost::mutex> lock(mutex);
    // Check if the RNTI value is unique and add the PDU to the list
    if (uniqueRntiSet.find(pdu.rx_ue_information.rnti) == uniqueRntiSet.end()) {
      pduList.push_back(pdu);
      uniqueRntiSet.insert(pdu.rx_ue_information.rnti);
    }
  }

  const std::vector<NFAPI_CRC_INDICATION_PDU_T>& getAll() const override {
    return pduList;
  }

  void clear() {
    boost::unique_lock<boost::mutex> lock(mutex);
    uniqueRntiSet.clear();
    pduList.clear();
  }
};

// Define a class to manage the list of NFAPI_CRC_INDICATION_PDU_T structures and handle contention
class ListManager {
 private:
  std::shared_ptr<InterfaceTable> interfaceTable;
