            free(pool->rnti_pool);
            pool->rnti_pool = new_pool;
            pool->rnti_pool_size = new_size;
        }
    }
    if (ret >= 0) {
        ret = pool->rnti_pool[pool->next_available_index++];
    }
    pthread_mutex_unlock(&pool->mutex);
    return ret;
}

