    }

    // Release lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to garbage collect unused structures in the array
void garbageCollect() {
    // Acquire lock on the mutex
    pthread_mutex_lock(&mutex);

    // Find the first structure with a CRCFLAG set to false
    int firstUnused = 0;
    for (int i = 0; i < receivedSignals->RX_UE_INFORMATION_TAG; ++i) {
