    uint64_t rnti = generate_rnti(rnti_hash);
    p->RNTI = rnti;

    // Set the CRCFLAG to a random value
    p->CRC_INDICATION_REL8_TAG = rand() % 256;
  }

  // Free the hash table and return the allocated memory
  free(rnti_hash);
}

uint64_t generate_rnti(uint64_t *rnti_hash) {
  uint64_t rnti;
  do {
    // Generate a random RNTI
    rnti = rand();

    // Check if the RNTI is unique in the hash table
    if (rnti_hash[rnti % num_ues] == 0) {
      // If the RNTI is unique, set it in the hash table and return it
      rnti_hash[rnti % num_ues] = rnti;
      return rnti;
    }
  } while (true);
}

void free_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU **pdu) {
