#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <unistd.h>
#include <string.h>
#include <stdbool.h>
#include <assert.h>

#define MAX_LIST_SIZE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct list_node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct list_node *next;
};

static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
static struct list_node *list_head = NULL;

// Function to initialize the list
void init_list() {
    // Initialize the head of the list as NULL
    list_head = NULL;
}

// Function to add a new element to the list
bool add_element(NFAPI_CRC_INDICATION_PDU_T *new_data) {
    bool ret = false;
    pthread_mutex_lock(&list_lock);
    struct list_node *new_node = malloc(sizeof(struct list_node));
    if (new_node != NULL) {
        new_node->data = new_data;
        new_node->next = list_head;
        list_head = new_node;
        ret = true;
    } else {
        fprintf(stderr, "Failed to allocate memory for new element\n");
    }
    pthread_mutex_unlock(&list_lock);
    return ret;
}

// Function to check if a given RNTI value is already present in the list
bool is_duplicate(unsigned int rnti) {
    bool ret = false;
    pthread_mutex_lock(&list_lock);
    struct list_node *current = list_head;
    while (current != NULL) {
        if (current->data->RNTI == rnti) {
            ret = true;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list_lock);
    return ret;
}

// Function to remove an element from the list based on RNTI value
void remove_element(unsigned int rnti) {
    pthread_mutex_lock(&list_lock);
    struct list_node *current = list_head, *previous = NULL;
    while (current != NULL && current->data->RNTI != rnti) {
        previous = current;
        current = current->next;
    }
    if (current != NULL) {
        if (previous == NULL) {
            list_head = current->next;
        } else {
            previous->next = current->next;
        }
        free(current);
    }
    pthread_mutex_unlock(&list_lock);
}

// Function to purge old elements from the list
void purge_old_elements() {
    pthread_mutex_lock(&list_lock);
    struct list_node *current = list_head, *previous = NULL;
    while (current != NULL) {
        if (current->data->CRCFLAG == true) {
            previous = current;
            current = current->next;
        } else {
            remove_element(current->data->RNTI);
        }
    }
    pthread_mutex_unlock(&list_lock);
}

// Function to free the memory associated with the list
void free_list() {
    struct list_node *current = list_head, *previous = NULL;
    while (current != NULL) {
        previous = current;
        current = current->next;
        free(previous);
    }
}

// Function to populate the list with new data from a given UE information source
void populate_list(UE_INFO *ue_info) {
    NFAPI_CRC_INDICATION_PDU_T *new_data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_data != NULL) {
        new_data->RX_UE_INFORMATION_TAG = ue_info->RX_UE_INFORMATION_TAG;
        new_data->RNTI = ue_info->RNTI;
        new_data->CRCFLAG = false;
        add_element(new_data);
    } else {
        fprintf(stderr, "Failed to allocate memory for new element\n");
    }
}

// Function to verify and enforce the uniqueness of RNTI values within the list
void check_uniqueness() {
    pthread_mutex_lock(&list_lock);
    struct list_node *current = list_head;
    while (current != NULL) {
        if (is_duplicate(current->data->RNTI)) {
            fprintf(stderr, "Duplicate RNTI value detected\n");
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list_lock);
}

// Function to manage dynamic memory allocation and deallocation for the list
void manage_memory() {
    struct list_node *current = list_head, *previous = NULL;
    while (current != NULL) {
        if (current->data == NULL) {
            previous = current;
            current = current->next;
            free(previous);
        } else {
            previous = current;
            current = current->next;
        }
    }
}

// Function to maintain the list in a sorted order based on RNTI value
void sort_list() {
    struct list_node *current = list_head, *previous = NULL;
    while (current != NULL) {
        if (current->next != NULL && current->next->data->RNTI < current->data->RNTI) {
            previous = current;
            current = current->next;
        } else {
            break;
        }
    }
}

// Function to handle the periodic purging of old elements from the list
void manage_old_elements() {
    purge_old_elements();
}

// Function to handle any errors that may occur during population process
void error_handler(int err) {
    if (err == -1) {
        fprintf(stderr, "Error: Failed to allocate memory for new element\n");
    } else {
        fprintf(stderr, "Error: Unknown error occurred\n");
    }
}

// Function to check the size of the list and purge old elements if necessary
void manage_list_size() {
    pthread_mutex_lock(&list_lock);
    struct list_node *current = list_head;
    while (current != NULL) {
        if (current->data == NULL) {
            previous = current;
            current = current->next;
            free(previous);
        } else {
            previous = current;
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list_lock);
