// Define the mutex variable and initialize it
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct NFAPI_CRC_INDICATION_PDU {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRC_FLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void process_nfaapi_crc_indication(char* input_file, char* output_file) {
    // Check if the input file is provided
    if (input_file == NULL) {
        printf("Usage: %s -i <input_file> [-o <output_file>] [-s] [-m]\n", argv[0]);
        return;
    }

    // Open the input file and read line by line
    FILE* fp = fopen(input_file, "r");
    if (fp == NULL) {
        printf("Error: unable to open input file %s\n", input_file);
        return;
    }

    // Define the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = NULL;

    // Allocate memory for the list
    pdu_list = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 100);
    if (pdu_list == NULL) {
        printf("Error: unable to allocate memory for the list\n");
        return;
    }

    // Initialize the mutex variable
    pthread_mutex_init(&mutex, NULL);

    // Process each line in the file
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Parse the JSON object from the line
        json_object* json = json_tokener_parse(line);
        if (json == NULL) {
            printf("Error: unable to parse JSON object\n");
            continue;
        }

        // Get the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG values from the JSON object
        uint16_t RX_UE_INFORMATION_TAG = json_object_get_int(json);
        uint32_t RNTI = json_object_get_int(json);
        uint8_t CRC_INDICATION_REL8_TAG = json_object_get_int(json);

        // Create a new NFAPI_CRC_INDICATION_PDU_T structure and populate it with the values
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            printf("Error: unable to allocate memory for the PDU\n");
            return;
        }
        pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        pdu->RNTI = RNTI;
        pdu->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

        // Determine the CRC flag based on the input data
        uint8_t CRC_FLAG = 0;
        if (RX_UE_INFORMATION_TAG == 1) {
            CRC_FLAG = 1;
        } else if (CRC_INDICATION_REL8_TAG == 1) {
            CRC_FLAG = 2;
        }
        pdu->CRC_FLAG = CRC_FLAG;

        // Acquire the mutex lock to ensure thread-safe access to the list
        pthread_mutex_lock(&mutex);

        // Add the new structure to the list
        if (pdu_list == NULL) {
            pdu_list = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        } else {
            NFAPI_CRC_INDICATION_PDU_T* new_pdu_list = realloc(pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (num_pdus + 1));
            if (new_pdu_list == NULL) {
                printf("Error: unable to reallocate memory for the list\n");
                return;
            } else {
                pdu_list = new_pdu_list;
            }
        }
        pdu_list[num_pdus] = *pdu;
        num_pdus++;

        // Release the mutex lock
        pthread_mutex_unlock(&mutex);
    }

    // Free the JSON object and the line buffer
    json_object_put(json);
    free(line);

    // Close the input file
    fclose(fp);
}
