// Structure to represent an NFAPI_RRC_CCO_REQUEST
typedef struct {
    uint64_t UE_ID;
    uint32_t frequency_bands[10]; // Maximum number of frequency bands supported is 10
    int priority_level;
    uint64_t timestamp;
} NFAPI_RRC_CCO_REQUEST;

// Dynamic resizable list to store the NFAPI_RRC_CCO_REQUEST structures
typedef struct {
    NFAPI_RRC_CCO_REQUEST ** requests; // Pointer to an array of pointers to NFAPI_RRC_CCO_REQUEST structures
    size_t capacity; // Number of elements that the list can hold
    size_t count; // Current number of elements in the list
    pthread_mutex_t lock; // Mutex for synchronizing access to the list by multiple threads
} NFAPI_RRC_CCO_REQUEST_LIST;

// Initialize a new list with the specified capacity
void nfapi_rrc_cco_request_list_init(NFAPI_RRC_CCO_REQUEST_LIST *list, size_t capacity) {
    list->requests = (NFAPI_RRC_CCO_REQUEST **) malloc(sizeof(NFAPI_RRC_CCO_REQUEST *) * capacity);
    list->capacity = capacity;
    list->count = 0;
}

// Add a new NFAPI_RRC_CCO_REQUEST structure to the list
void nfapi_rrc_cco_request_list_add(NFAPI_RRC_CCO_REQUEST_LIST *list, NFAPI_RRC_CCO_REQUEST *request) {
    pthread_mutex_lock(&list->lock);
    if (list->count == list->capacity) {
        // Resize the list to make room for a new request
        size_t new_capacity = list->capacity * 2;
        NFAPI_RRC_CCO_REQUEST **new_requests = (NFAPI_RRC_CCO_REQUEST **) realloc(list->requests, sizeof(NFAPI_RRC_CCO_REQUEST *) * new_capacity);
        if (new_requests == NULL) {
            // Memory allocation failed, fall back to using the current capacity
            new_requests = list->requests;
            new_capacity = list->capacity;
        }
        list->requests = new_requests;
        list->capacity = new_capacity;
    }
    list->requests[list->count++] = request;
    pthread_mutex_unlock(&list->lock);
}

// Remove an NFAPI_RRC_CCO_REQUEST structure from the list
void nfapi_rrc_cco_request_list_remove(NFAPI_RRC_CCO_REQUEST_LIST *list, uint64_t UE_ID) {
    pthread_mutex_lock(&list->lock);
    size_t i = 0;
    while (i < list->count && list->requests[i]->UE_ID != UE_ID) {
        i++;
    }
    if (i < list->count) {
        // Remove the request from the list
        size_t j = i + 1;
        while (j < list->count) {
            list->requests[i] = list->requests[j];
            i++;
            j++;
        }
        list->count--;
    }
    pthread_mutex_unlock(&list->lock);
}

// Filter the list based on a specific criteria (e.g., UE_ID or priority level)
void nfapi_rrc_cco_request_list_filter(NFAPI_RRC_CCO_REQUEST_LIST *list, uint64_t UE_ID) {
    pthread_mutex_lock(&list->lock);
    size_t i = 0;
    while (i < list->count) {
        if (list->requests[i]->UE_ID == UE_ID) {
            // Remove the request from the list
            size_t j = i + 1;
            while (j < list->count) {
                list->requests[i] = list->requests[j];
                i++;
                j++;
            }
            list->count--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

// Get the NFAPI_RRC_CCO_REQUEST structure with the specified UE_ID from the list
NFAPI_RRC_CCO_REQUEST *nfapi_rrc_cco_request_list_get(NFAPI_RRC_CCO_REQUEST_LIST *list, uint64_t UE_ID) {
    pthread_mutex_lock(&list->lock);
    size_t i = 0;
    while (i < list->count && list->requests[i]->UE_ID != UE_ID) {
        i++;
    }
    NFAPI_RRC_CCO_REQUEST *request = NULL;
    if (i < list->count) {
        request = list->requests[i];
    }
    pthread_mutex_unlock(&list->lock);
    return request;
}

// Free the memory allocated for the list and its elements
void nfapi_rrc_cco_request_list_free(NFAPI_RRC_CCO_REQUEST_LIST *list) {
    pthread_mutex_destroy(&list->lock);
    free(list->requests);
}
