    // Use the rand() function to generate a random integer between 0 and 10^9
    int flow_id = rand() % (int)pow(10, 9);

    // Check if the generated flow ID is already in use
    while (flow_in_use(flow_id)) {
        flow_id = rand() % (int)pow(10, 9);
    }

    return flow_id;
}

// Check if a given flow identifier is in use
