#define MAX_REQUESTS 10000
#define INITIAL_ALLOCATION 500
#define THRESHOLD 0.25

typedef struct {
    int user_id;
    char *session_token;
    time_t timestamp;
} session_request_t;

// Thread-safe queue for storing session requests
struct thread_safe_queue {
    pthread_mutex_t mutex;
    pthread_cond_t cv;
    int size;
    int capacity;
    session_request_t *requests[];
};

struct thread_safe_queue *create_queue(int capacity) {
    struct thread_safe_queue *queue = malloc(sizeof(struct thread_safe_queue));
    queue->mutex = PTHREAD_MUTEX_INITIALIZER;
    queue->cv = PTHREAD_COND_INITIALIZER;
    queue->size = 0;
    queue->capacity = capacity;
    queue->requests = malloc(sizeof(session_request_t) * capacity);
    return queue;
}

void destroy_queue(struct thread_safe_queue *queue) {
    free(queue->requests);
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->cv);
    free(queue);
}

// Thread-safe function to add a session request to the queue
void enqueue(struct thread_safe_queue *queue, int user_id, char *session_token) {
    // Lock the mutex before accessing the queue
    pthread_mutex_lock(&queue->mutex);

    // Wait for space in the queue if necessary
    while (queue->size == queue->capacity) {
        pthread_cond_wait(&queue->cv, &queue->mutex);
    }

    session_request_t *new_request = malloc(sizeof(session_request_t));
    new_request->user_id = user_id;
    new_request->session_token = session_token;
    new_request->timestamp = time(NULL);

    // Add the request to the end of the queue
    queue->requests[queue->size++] = new_request;

    // Unlock the mutex and signal other threads that space is available
    pthread_mutex_unlock(&queue->mutex);
    pthread_cond_signal(&queue->cv);
}

// Thread-safe function to remove a session request from the queue
session_request_t *dequeue(struct thread_safe_queue *queue) {
    // Lock the mutex before accessing the queue
    pthread_mutex_lock(&queue->mutex);

    // Wait for requests in the queue if necessary
    while (queue->size == 0) {
        pthread_cond_wait(&queue->cv, &queue->mutex);
    }

    session_request_t *request = queue->requests[--queue->size];

    // Unlock the mutex and signal other threads that space is available
    pthread_mutex_unlock(&queue->mutex);
    pthread_cond_signal(&queue->cv);

    return request;
}

// Function to serialize a session request to JSON format for storage
char *serialize(session_request_t *request) {
    json_object *json = json_object_new();
    json_object_object_add(json, "user_id", json_object_new_int(request->user_id));
    json_object_object_add(json, "session_token", json_object_new_string(request->session_token));
    json_object_object_add(json, "timestamp", json_object_new_double(request->timestamp));
    return strdup(json_object_to_json_string(json));
}

// Function to deserialize a session request from JSON format for processing
session_request_t *deserialize(char *json) {
    json_object *obj = json_tokener_parse(json);
    int user_id = json_object_get_int(json_object_object_get(obj, "user_id"));
    char *session_token = strdup(json_object_get_string(json_object_object_get(obj, "session_token")));
    time_t timestamp = json_object_get_double(json_object_object_get(obj, "timestamp"));
    session_request_t *request = malloc(sizeof(session_request_t));
    request->user_id = user_id;
    request->session_token = session_token;
    request->timestamp = timestamp;
    return request;
}

// Function to handle errors and log them to an error log file
void handle_error(char *message) {
    FILE *error_log = fopen("error.log", "a+");
    if (error_log == NULL) {
        perror("Error opening error log file");
    } else {
        char *time = strdup(ctime(&(time_t){ time(NULL) }));
        fprintf(error_log, "%s: %s\n", time, message);
        free(time);
        fclose(error_log);
    }
}

// Function to manage a dynamic list of session initiation requests for a web-based application
void manage_requests(struct thread_safe_queue *queue) {
    int num_requests = 0;
    // Check the threshold and resize the queue if necessary
    if (queue->size > MAX_REQUESTS * THRESHOLD) {
        queue->capacity = queue->capacity * 2 + INITIAL_ALLOCATION;
        queue->requests = realloc(queue->requests, sizeof(session_request_t) * queue->capacity);
    }

    // Loop until the queue is empty
    while (queue->size > 0) {
        session_request_t *request = dequeue(queue);

        // Handle potential failures gracefully by logging errors
        if (request == NULL) {
            handle_error("Failed to retrieve session request from queue");
            continue;
        }

        char *json = serialize(request);

        // Log the serialized session request to an external logging service for performance monitoring and error tracking
        // You can integrate with an external logging service using the appropriate API
        log_session_request(json);

        free(json);
        free(request->session_token);
        free(request);
    }
}
```
This code implements a function to manage a dynamic list of session initiation requests for a web-based application. The function enforces a maximum threshold on the total number of requests to optimize server resources, while allowing the list to dynamically resize to accommodate up to 25% more elements than its initial allocation. The function also serializes the requests into JSON format for efficient storage and retrieval, and ensures that the serialization process is efficient under high load conditions.

