void manage_frames(FrameHeader **frames, size_t *num_frames, size_t max_size) {
    // Initialize the frames array and number of frames
    if (*frames == NULL) {
        *frames = (FrameHeader**)malloc(sizeof(FrameHeader*) * max_size);
        *num_frames = 0;
    }

    // Add a new frame to the end of the array
