    if (new_frame == NULL) {
        log_error("Failed to allocate memory for new frame");
        return;
    }
    (*frames)[*num_frames] = new_frame;
    (*num_frames)++;

    // Ensure that the payload size does not exceed the maximum limit
    if (new_frame->payload != NULL && strlen(new_frame->payload) > max_size) {
        log_error("Payload size exceeds maximum limit");
        free(new_frame);
        return;
    }
}

