typedef struct netif_settings {
    int status;
    uint16_t port;
    char* ip_addr;
    void (*callback)(void*, void*);
} netif_settings_t;

// Structure to store the network interface settings and its associated resources
typedef struct netif {
    int sockfd;
    netif_settings_t* settings;
    pthread_mutex_t mutex; // Mutex for synchronizing access to shared resources
} netif_t;

// Function to initialize and configure a network interface for a high-traffic web service
int init_netif(netif_t* netif, const char* ip_addr, uint16_t port) {
    // Allocate memory for the network interface settings
    netif->settings = (netif_settings_t*)malloc(sizeof(netif_settings_t));
    if (netif->settings == NULL) {
        perror("Failed to allocate memory for network interface settings");
        return -1;
    }

    // Initialize the network interface settings
    netif->settings->status = 0;
    netif->settings->port = port;
    netif->settings->ip_addr = strdup(ip_addr);

    // Create a socket and bind it to the specified IP address and port number
    netif->sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (netif->sockfd == -1) {
        perror("Failed to create socket");
        return -1;
    }

    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(port);

    if (inet_pton(AF_INET, ip_addr, &serv_addr.sin_addr) <= 0) {
        perror("Failed to convert IP address");
        return -1;
    }

    if (bind(netif->sockfd, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("Failed to bind socket");
        return -1;
    }

    // Initialize the mutex for synchronizing access to shared resources
    if (pthread_mutex_init(&netif->mutex, NULL) != 0) {
        perror("Failed to initialize mutex");
        return -1;
    }

    return 0;
}

// Function to handle incoming requests asynchronously without blocking the main thread's operation
void* request_handler(void* arg) {
    netif_t* netif = (netif_t*)arg;

    // Acquire the mutex for synchronizing access to shared resources
    pthread_mutex_lock(&netif->mutex);

    // Check if the network interface is still running
    if (netif->settings == NULL || netif->sockfd < 0) {
        printf("Network interface is not initialized or shut down\n");
        pthread_exit(NULL);
    }

    // Handle incoming requests using the callback function
    char* buffer = (char*)malloc(sizeof(char)*1024);
    ssize_t len = read(netif->sockfd, buffer, 1024);
    if (len < 0) {
        perror("Failed to read from socket");
        pthread_exit(NULL);
    }

    // Call the callback function with the received data
    netif->settings->callback(buffer, len);

    free(buffer);

    // Release the mutex for synchronizing access to shared resources
    pthread_mutex_unlock(&netif->mutex);

    return NULL;
}

// Function to handle incoming requests asynchronously without blocking the main thread's operation
void* shutdown_handler(void* arg) {
    netif_t* netif = (netif_t*)arg;

    // Acquire the mutex for synchronizing access to shared resources
    pthread_mutex_lock(&netif->mutex);

    // Check if the network interface is still running
    if (netif->settings == NULL || netif->sockfd < 0) {
        printf("Network interface is not initialized or shut down\n");
        pthread_exit(NULL);
    }

    // Shut down the socket and release the mutex for synchronizing access to shared resources
    close(netif->sockfd);
    netif->sockfd = -1;
    free(netif->settings);
    netif->settings = NULL;

    pthread_mutex_unlock(&netif->mutex);

    return NULL;
}

// Function to process incoming requests asynchronously without blocking the main thread's operation
int process_requests(netif_t* netif) {
    // Acquire the mutex for synchronizing access to shared resources
    pthread_mutex_lock(&netif->mutex);

    // Check if the network interface is still running
    if (netif->settings == NULL || netif->sockfd < 0) {
        printf("Network interface is not initialized or shut down\n");
        return -1;
    }

    // Create a new thread for handling incoming requests
    pthread_t request_handler_thread;
    if (pthread_create(&request_handler_thread, NULL, request_handler, netif) != 0) {
        perror("Failed to create thread");
        return -1;
    }

    // Create a new thread for shutting down the network interface
    pthread_t shutdown_handler_thread;
    if (pthread_create(&shutdown_handler_thread, NULL, shutdown_handler, netif) != 0) {
        perror("Failed to create thread");
        return -1;
    }

    // Release the mutex for synchronizing access to shared resources
    pthread_mutex_unlock(&netif->mutex);

    // Wait for the request handler and shutdown handler threads to finish
    void* status;
    if (pthread_join(request_handler_thread, &status) != 0) {
        perror("Failed to join thread");
        return -1;
    }
    if (pthread_join(shutdown_handler_thread, &status) != 0) {
        perror("Failed to join thread");
        return -1;
    }

    return 0;
}

// Main function for testing the network interface initialization and request processing functionality
int main() {
    // Initialize the network interface with a callback function
    netif_t netif;
    init_callback(&netif, handle_request);

    // Process incoming requests asynchronously without blocking the main thread's operation
    process_requests(&netif);

    return 0;
}
```
This is a simple implementation of a network interface that can be used to send and receive data. The `init` function initializes the network interface with a callback function, which will be called whenever an incoming request is received. The `process_requests` function creates two new threads for handling incoming requests and shutting down the network interface. The main thread only needs to call `process_requests` and can then continue with its own work.

