    size_t pool_size; // Current pool size
    pthread_mutex_t mutex; // Mutex for thread-safe operations
};

// Initialize the pool with a given initial size
void init_pool(struct pool *pool, int init_size) {
    pool->pool_array = (pool_element_t *) malloc(init_size * sizeof(pool_element_t));
    if (pool->pool_array == NULL) {
        printf("Error: Failed to allocate memory for pool\n");
        exit(1);
    }
    pool->pool_size = init_size;
}

// Add a new element to the pool
