// Function to add a new connection to the list of active connections
void add_connection(int socket_fd, char* peer_addr) {
    // Create a new TCP connection record and initialize it
    TCP_CONNECTION_RECORD* conn = (TCP_CONNECTION_RECORD*) malloc(sizeof(TCP_CONNECTION_RECORD));
    conn->socket_fd = socket_fd;
    conn->peer_addr = strdup(peer_addr);
    conn->flags = 0;

    // Add the new connection to the vector of active connections
    pthread_mutex_lock(&tcp_connections.mutex);
    tcp_connections.push_back(conn);
    pthread_mutex_unlock(&tcp_connections.mutex);
}

// Function to remove a connection from the list of active connections
void remove_connection(int socket_fd) {
    // Find the index of the connection in the vector
    int i;
    for (i = 0; i < tcp_connections.size(); i++) {
        if (tcp_connections[i]->socket_fd == socket_fd) {
            break;
        }
    }

    // If the connection is found, remove it from the vector
    if (i < tcp_connections.size()) {
        TCP_CONNECTION_RECORD* conn = tcp_connections[i];

        pthread_mutex_lock(&tcp_connections.mutex);
        tcp_connections.erase(tcp_connections.begin() + i);
        free(conn->peer_addr);
        free(conn);
        pthread_mutex_unlock(&tcp_connections.mutex);
    }
}

