// Structure to hold a single frame message
typedef struct {
  LTE_DL_FRAME_MSG_T rrc_pdu;
  LTE_DL_FRAME_MSG_T phy_pdu;
  uint32_t frame_number;
  uint16_t sfn;
} frame_msg_t;

// Structure to hold a pool of pre-allocated frames
typedef struct {
  frame_msg_t* frames;
  size_t num_frames;
  pthread_mutex_t mutex;
} frame_pool_t;

// Function to manage the dynamic array of frame messages
frame_pool_t* frame_pool_create(size_t num_frames) {
  // Create a new pool of frames and initialize its members
  frame_pool_t* pool = (frame_pool_t*)malloc(sizeof(frame_pool_t));
  pool->num_frames = num_frames;
  pool->frames = (frame_msg_t*)malloc(num_frames * sizeof(frame_msg_t));

  // Initialize the mutex for thread-safe access to the pool
  pthread_mutexattr_t attr;
  pthread_mutexattr_init(&attr);
  pthread_mutexattr_setpshared(&attr, PTHREAD_PROCESS_SHARED);
  pthread_mutex_init(&pool->mutex, &attr);

  // Return the newly created pool of frames
  return pool;
}

// Function to add a new frame message to the dynamic array
void frame_pool_add(frame_pool_t* pool, LTE_DL_FRAME_MSG_T rrc_pdu, LTE_DL_FRAME_MSG_T phy_pdu) {
  // Acquire the mutex to access the pool of frames safely
  pthread_mutex_lock(&pool->mutex);

  // Allocate a new frame message and copy the given RRC and PHY PDUs
  frame_msg_t* new_frame = (frame_msg_t*)malloc(sizeof(frame_msg_t));
  memcpy(&new_frame->rrc_pdu, &rrc_pdu, sizeof(LTE_DL_FRAME_MSG_T));
  memcpy(&new_frame->phy_pdu, &phy_pdu, sizeof(LTE_DL_FRAME_MSG_T));

  // Generate a unique frame number and System Frame Number (sfn)
  new_frame->frame_number = pool->num_frames++;
  new_frame->sfn = (uint16_t)new_frame->frame_number;

  // Add the new frame to the end of the array
  pool->frames[pool->num_frames - 1] = new_frame;

  // Release the mutex and return
  pthread_mutex_unlock(&pool->mutex);
}

// Function to update a set of metrics for the current system state
void frame_metrics_update(frame_pool_t* pool) {
  // Acquire the mutex to access the pool of frames safely
  pthread_mutex_lock(&pool->mutex);

  // Update the number of frames processed, average weighted sum, and total latency metrics
  uint32_t num_frames = pool->num_frames;
  uint64_t total_latency = 0;
  for (uint32_t i = 0; i < num_frames; ++i) {
    // Compute the weighted sum of the current frame
    uint32_t weighted_sum = pool->frames[i].rrc_pdu.weight * pool->frames[i].phy_pdu.weight;

    // Update the total latency metric for the current frame
    total_latency += weighted_sum;
  }

  // Calculate the average weighted sum and maximum weighted sum metrics
  uint64_t avg_weighted_sum = total_latency / num_frames;
  uint64_t max_weighted_sum = 0;
  for (uint32_t i = 0; i < num_frames; ++i) {
    if (pool->frames[i].rrc_pdu.weight * pool->frames[i].phy_pdu.weight > max_weighted_sum) {
      max_weighted_sum = pool->frames[i].rrc_pdu.weight * pool->frames[i].phy_pdu.weight;
    }
  }

  // Release the mutex and return
  pthread_mutex_unlock(&pool->mutex);
}

// Function to filter frames based on specific criteria
void frame_filter(frame_pool_t* pool, uint32_t num_frames) {
  // Acquire the mutex to access the pool of frames safely
  pthread_mutex_lock(&pool->mutex);

  // Filter frames based on their age and weighted sum
  for (uint32_t i = 0; i < num_frames; ++i) {
    // Compute the age of the current frame in milliseconds
    uint64_t age_ms = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - pool->frames[i].rrc_pdu.ts).count();

    // Check if the current frame is older than 3 seconds and has a weighted sum greater than 1000
    if (age_ms > 3000 && pool->frames[i].weighted_sum > 1000) {
      // Remove the current frame from the array
      memmove(&pool->frames[i], &pool->frames[i + 1], sizeof(frame_msg_t) * (num_frames - i - 1));
      pool->num_frames--;
    }
  }

  // Release the mutex and return
  pthread_mutex_unlock(&pool->mutex);
}
```
In this example, we use a thread-safe pool of pre-allocated frames to manage the dynamic array of frame messages. We also implement a function to update a set of metrics for the current system state and filter frames based on specific criteria. The `frame_pool_add` function adds a new frame message to the end of the array, while the `frame_metrics_update` function updates a set of metrics for the current system state. The `frame_filter` function filters frames based on their age and weighted sum.

We also use atomic operations to ensure thread-safe access to the shared variables in the pool. In this example, we use the `std::atomic<uint32_t>` class from the C++ standard library to represent the number of frames in the pool. We also use the `std::chrono` library to compute the age of a frame in milliseconds.

In terms of performance, using a thread-safe pool of pre-allocated frames can be more efficient than dynamically allocating and deallocating memory for each new frame message. This is because dynamic allocation and deallocation of memory can be expensive operations that may involve context switching between the kernel and the user space, which can result in increased latency and reduced performance.

However, it's important to note that the performance benefits of using a thread-safe pool of pre-allocated frames will depend on the specific use case and the requirements of the system. If the system requires low-latency and high-throughput processing of frame messages, then dynamic allocation and deallocation may be more suitable."]

