    int max_count;
    TAP_MME_UPLINK_NAS_TRANSPORT_T *entries;
} UPLINK_NAS_TRANSPORT_LIST;

// Define the function to manage the dynamic list of entries
void uplink_nas_transport(UPLINK_NAS_TRANSPORT_LIST *list, int tmsi, char *nas_msg) {
    // Acquire a lock on the list to prevent concurrent access from multiple threads
    pthread_mutex_lock(&list->lock);

    // Check if the list is full and needs to be resized
    if (list->count == list->max_count) {
        // Reallocate memory for the list with a new size that is twice the current size
        list->entries = realloc(list->entries, list->max_count * 2 * sizeof(TAP_MME_UPLINK_NAS_TRANSPORT_T));
        if (list->entries == NULL) {
            // Handle memory allocation failure by raising an error and returning
            printf("Error: Failed to allocate memory for uplink NAS transport list\n");
            return;
        }
        list->max_count *= 2;
    }

    // Add the new entry to the end of the list
    list->entries[list->count].tmsi = tmsi;
    list->entries[list->count].nas_msg = nas_msg;
    list->count++;

    // Release the lock on the list and return
    pthread_mutex_unlock(&list->lock);
}

// Define a mechanism to handle memory leaks by ensuring all allocated memory is properly freed after use
void free_uplink_nas_transport(UPLINK_NAS_TRANSPORT_LIST *list) {
    // Acquire a lock on the list to prevent concurrent access from multiple threads
    pthread_mutex_lock(&list->lock);

    // Free all memory allocated for the list entries
