    int crc_indication_rel8_tag;
    int crcflag;
} crc_indication_rel8_tag_t;

void process_log_records(int n) {
    // Allocate memory for the offset and key arrays
    long* offsets = malloc(n * sizeof(long));
    int* keys = malloc(n * sizeof(int));

    // Initialize the offset and key arrays
    for (int i = 0; i < n; i++) {
        offsets[i] = -1;
        keys[i] = -1;
    }

    // Allocate memory for the record array
    log_record_t* records = malloc(n * sizeof(log_record_t));

    // Initialize the record array
    for (int i = 0; i < n; i++) {
        records[i].timestamp = -1;
        records[i].log_id = -1;
        records[i].message = NULL;
    }

    // Allocate memory for the RX_UE_INFORMATION_TAG array
    rx_ue_information_tag_t* rx_ue_information_tags = malloc(NUM_RX_UE_INFORMATION_TAGS * sizeof(rx_ue_information_tag_t));

    // Initialize the RX_UE_INFORMATION_TAG array
    for (int i = 0; i < NUM_RX_UE_INFORMATION_TAGS; i++) {
        rx_ue_information_tags[i].rx_ue_information_tag = -1;
        rx_ue_information_tags[i].rnti = -1;
        rx_ue_information_tags[i].crc_indication_rel8_tag = -1;
    }

    // Allocate memory for the CRC_INDICATION_REL8_TAG array
    crc_indication_rel8_tag_t* crc_indication_rel8_tags = malloc(NUM_CRC_INDICATION_REL8_TAGS * sizeof(crc_indication_rel8_tag_t));

    // Initialize the CRC_INDICATION_REL8_TAG array
    for (int i = 0; i < NUM_CRC_INDICATION_REL8_TAGS; i++) {
        crc_indication_rel8_tags[i].crc_indication_rel8_tag = -1;
        crc_indication_rel8_tags[i].crcflag = 0;
    }

    // Allocate memory for the random integer array
    int* random_ints = malloc(n * sizeof(int));

    // Initialize the random integer array with random values within the range [MIN_RANDOM_INT, MAX_RANDOM_INT]
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        random_ints[i] = rand() % (MAX_RANDOM_INT - MIN_RANDOM_INT + 1) + MIN_RANDOM_INT;
    }

    // Process the log records in parallel using multiple threads
    #pragma omp parallel for schedule(dynamic, 10)
    for (int i = 0; i < n; i++) {
        // Initialize a local copy of the record to be processed
        log_record_t record = records[i];

        // Validate and uniquify the log message
        char* unique_message = NULL;
        if (record.message == NULL) {
            unique_message = malloc(LOG_MESSAGE_MAX_LENGTH * sizeof(char));
            snprintf(unique_message, LOG_MESSAGE_MAX_LENGTH, "%d", random_ints[i]);
        } else {
            int message_length = strlen(record.message);
            unique_message = malloc((message_length + 1) * sizeof(char));
            snprintf(unique_message, message_length + 1, "%s_%d", record.message, random_ints[i]);
        }

        // Set the timestamp field to the current system time
        time_t current_time = time(NULL);
        record.timestamp = (int)current_time;

        // Handle potential synchronization issues in a multi-threaded environment
        #pragma omp critical
        {
            // Update the offset and key arrays with the processed record
            offsets[i] = i;
            keys[i] = record.timestamp;

            // Update the RX_UE_INFORMATION_TAG array with the processed record
            for (int j = 0; j < NUM_RX_UE_INFORMATION_TAGS; j++) {
                if (record.rx_ue_information_tag == rx_ue_information_tags[j].rx_ue_information_tag) {
                    rx_ue_information_tags[j].rnti = record.log_id;
                    rx_ue_information_tags[j].crc_indication_rel8_tag = record.timestamp;
                }
            }

            // Update the CRC_INDICATION_REL8_TAG array with the processed record
            for (int j = 0; j < NUM_CRC_INDICATION_REL8_TAGS; j++) {
                if (record.crc_indication_rel8_tag == crc_indication_rel8_tags[j].crc_indication_rel8_tag) {
                    crc_indication_rel8_tags[j].crcflag = record.timestamp;
                }
            }
        }

        // Free the local copy of the unique message
        free(unique_message);
    }

    // Free the memory allocated for the offset and key arrays, record array, RX_UE_INFORMATION_TAG array, CRC_INDICATION_REL8_TAG array, and random integer array
    free(offsets);
    free(keys);
    free(records);
    free(rx_ue_information_tags);
    free(crc_indication_rel8_tags);
    free(random_ints);
}
