int allocate_tag_array(struct TagArray** arr, size_t initial_capacity) {
    assert(arr != NULL);
    *arr = malloc(sizeof(struct TagArray));
    if (*arr == NULL) {
        return -1; // failure to allocate memory
    }

    (*arr)->elements = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if ((*arr)->elements == NULL) {
        free(*arr);
        return -1; // failure to allocate memory
    }

    (*arr)->capacity = initial_capacity;
    (*arr)->num_elements = 0;
    return 0; // success
}

int resize_tag_array(struct TagArray* arr, size_t new_size) {
    assert(arr != NULL);

    if (new_size > arr->capacity) {
        NFAPI_CRC_INDICATION_PDU_T* temp = realloc(arr->elements, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (temp == NULL) {
