#include <string.h>
#include <assert.h>
#include <pthread.h>

// Define the maximum capacity of the list
#define MAX_CAPACITY 1500

// Define the structure for storing NFAPI_CRC_INDICATION_PDU_T elements
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for storing the list of elements
typedef struct {
    int size;
    int capacity;
    NFAPI_CRC_INDICATION_PDU_T* elements;
    pthread_mutex_t mutex;
} CRC_INDICATION_LIST;

// Define the function to initialize the list
void init_list(CRC_INDICATION_LIST* list) {
    list->size = 0;
    list->capacity = MAX_CAPACITY;
    list->elements = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);
    assert(list->elements != NULL);
    pthread_mutex_init(&list->mutex, NULL);
}

// Define the function to add a new element to the list
void add_element(CRC_INDICATION_LIST* list, RX_UE_INFORMATION_TAG rx_ue_info, RNTI rnti) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        // Dynamically allocate more memory for the list
        list->capacity *= 2;
        NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*) realloc(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);
        assert(new_elements != NULL);
        list->elements = new_elements;
    }
    list->elements[list->size].rx_ue_info = rx_ue_info;
    list->elements[list->size].rnti = rnti;
    // Generate a random CRCFLAG value for the new element
    list->elements[list->size].crc_indication.CRCFLAG = rand() % 1000;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

// Define the function to remove an element from the list by index
void remove_element(CRC_INDICATION_LIST* list, int index) {
    pthread_mutex_lock(&list->mutex);
    assert(index >= 0 && index < list->size);
    // Shift all elements after the removed element to fill the gap
    memmove(&list->elements[index], &list->elements[index + 1], (list->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size--;
    pthread_mutex_unlock(&list->mutex);
}

// Define the function to iterate over the list and print out all tags and RNTI values
void print_list(CRC_INDICATION_LIST* list) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->size; i++) {
        printf("Tag: %d, RNTI: %d, CRCFLAG: %d\n", list->elements[i].rx_ue_info.tag, list->elements[i].rnti, list->elements[i].crc_indication.CRCFLAG);
    }
    pthread_mutex_unlock(&list->mutex);
}

// Define the function to maintain an internal checksum that is updated whenever a new element is added or removed from the list
void update_checksum(CRC_INDICATION_LIST* list) {
    int checksum = 0;
    for (int i = 0; i < list->size; i++) {
        checksum += list->elements[i].rx_ue_info.tag + list->elements[i].rnti + list->elements[i].crc_indication.CRCFLAG;
    }
    list->checksum = checksum;
}

// Define the function to verify the internal checksum and restore the list to a consistent state if necessary
void verify_checksum(CRC_INDICATION_LIST* list) {
    int new_checksum = 0;
    for (int i = 0; i < list->size; i++) {
        new_checksum += list->elements[i].rx_ue_info.tag + list->elements[i].rnti + list->elements[i].crc_indication.CRCFLAG;
    }
    if (new_checksum != list->checksum) {
        printf("Error: Checksum does not match. Attempting to restore list to a consistent state.\n");
        // Restore the list by re-adding all elements
        for (int i = 0; i < list->size; i++) {
            add_element(list, list->elements[i].rx_ue_info, list->elements[i].rnti);
        }
    }
}
