// Define the pool of CRC_INDICATION_PDU structures
static NFAPI_CRC_INDICATION_PDU* pool = NULL;

// Initialize the pool with a given number of structures
void initialize_pool(int num) {
  // Allocate memory for the pool
  pool = (NFAPI_CRC_INDICATION_PDU*)malloc(num * sizeof(NFAPI_CRC_INDICATION_PDU));

  // Initialize each structure in the pool
  for (int i = 0; i < num; i++) {
    pool[i].rx_ue_information_tag = rand() % 1024;
    pool[i].rnti = rand() % 65536;
    pool[i].crc_indication_rel8_tag = rand() % 1024;
    pool[i].crc_flag = rand() % 2;
  }

  // Log the initialization of the pool
  printf("Initialized CRC indication pool with %d structures\n", num);
}

// Release memory allocated to the pool
void release_pool() {
  free(pool);
  pool = NULL;
}

// Add a new structure to the pool
int add_structure() {
  // Allocate memory for the new structure
  NFAPI_CRC_INDICATION_PDU* new_struct = (NFAPI_CRC_INDICATION_PDU*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU));

  // Initialize the new structure with random values
  new_struct->rx_ue_information_tag = rand() % 1024;
  new_struct->rnti = rand() % 65536;
  new_struct->crc_indication_rel8_tag = rand() % 1024;
  new_struct->crc_flag = rand() % 2;

  // Add the new structure to the pool
  int index = (int)(pool - new_struct) / sizeof(NFAPI_CRC_INDICATION_PDU);
  pool[index] = *new_struct;

  return index;
}

// Remove a structure from the pool
void remove_structure(int index) {
  // Free the memory allocated to the structure
  free(&pool[index]);

  // Shift all structures after the removed one to fill the gap
  for (int i = index; i < num - 1; i++) {
    pool[i] = pool[i + 1];
  }

  // Decrement the number of structures in the pool
  num--;
}

// Handle a CRC indication message
void handle_crc_indication(NFAPI_CRC_INDICATION_PDU* msg) {
  // Log the reception of the CRC indication message
  printf("Received CRC indication for RNTI %d\n", msg->rnti);

  // Check if the message is valid
