  // Check if the message has a valid CRC flag
  if (msg->crc_flag != 1) {
    printf("CRC flag not set in CRC indication message\n");
    return;
  }

  // Add the structure to the pool
  int index = add_structure();
  pool[index] = *msg;

  // Log the addition of the structure to the pool
  printf("Added CRC indication structure with RNTI %d to pool\n", msg->rnti);
}

// Main function for testing and demonstrating the functionality of the CRC indication pool
int main(int argc, char** argv) {
