    array->array = malloc(sizeof(DataPacket) * INITIAL_ARRAY_SIZE);
    if (array->array == NULL) {
        fprintf(stderr, "Failed to allocate memory for dynamic array\n");
        return;
    }
    // Set the initial capacity of the dynamic array
    array->capacity = INITIAL_ARRAY_SIZE;
    // Initialize the length of the dynamic array to 0
    array->length = 0;
}

