typedef struct LTE_DL_FRAME_MSG {
    DL_FRAME_STRUCT frame;
} LTE_DL_FRAME_MSG_T;

void init_dl_frame_msg(LTE_DL_FRAME_MSG_T **frames, size_t num_frames) {
    // Allocate memory for the frames
    *frames = (LTE_DL_FRAME_MSG_T*)malloc(num_frames*sizeof(LTE_DL_FRAME_MSG_T));
    if (*frames == NULL) {
        printf("Error: Memory allocation failed.\n");
        return;
    }

    // Initialize the frames with default values
    for (size_t i = 0; i < num_frames; i++) {
        (*frames)[i].frame.ul_tpc = 15;
        (*frames)[i].frame.dl_tpc = 15;
    }
}

void update_tpc(LTE_DL_FRAME_MSG_T **frames, size_t num_frames, int *cqi) {
    // Update the TPC based on CQI and cell configuration
    for (size_t i = 0; i < num_frames; i++) {
        if (cqi[i] <= 15) {
            (*frames)[i].frame.dl_tpc = cqi[i];
        } else {
            (*frames)[i].frame.dl_tpc = 15;
        }
    }
}

void apply_tpc(LTE_DL_FRAME_MSG_T **frames, size_t num_frames) {
    // Apply the TPC commands to the frames
    for (size_t i = 0; i < num_frames; i++) {
        (*frames)[i].frame.ul_power = (*frames)[i].frame.dl_tpc*10000;
        (*frames)[i].frame.dl_power = (*frames)[i].frame.dl_tpc*10000;
    }
}

void free_dl_frame_msg(LTE_DL_FRAME_MSG_T **frames) {
    // Free the memory allocated for the frames
    if (*frames != NULL) {
        free(*frames);
        *frames = NULL;
    }
}
