} NFAPI_CRC_INDICATION_PDU_T;

// Function to dynamically create and populate a linked list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* nfapi_create_crc_indication_list(int num_elements) {
    // Allocate memory for the linked list structure
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_elements);
    if (!list) {
        perror("Failed to allocate memory for CRC indication list");
        return NULL;
    }

    // Initialize each element in the linked list with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (int i = 0; i < num_elements; i++) {
        NFAPI_CRC_INDICATION_PDU_T *element = &list[i];
        element->rxUeInformationTag = RX_UE_INFORMATION_TAG_INITIALIZER;
        element->rnti = rand();
        element->crcIndicationRel8Tag = CRC_INDICATION_REL8_TAG_INITIALIZER;
        element->crcIndicationRel8Tag.crcFlag = (rand() % 2) ? true : false;
    }

    // Return the pointer to the first element in the linked list
    return list;
}

// Function to add a new node to the linked list of NFAPI_CRC_INDICATION_PDU_T structures
void nfapi_add_crc_indication(NFAPI_CRC_INDICATION_PDU_T *list, int rnti) {
    // Allocate memory for the new node
    NFAPI_CRC_INDICATION_PDU_T *node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) {
        perror("Failed to allocate memory for CRC indication node");
        return;
    }

    // Initialize the new node with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    node->rxUeInformationTag = RX_UE_INFORMATION_TAG_INITIALIZER;
    node->rnti = rnti;
    node->crcIndicationRel8Tag = CRC_INDICATION_REL8_TAG_INITIALIZER;
    node->crcIndicationRel8Tag.crcFlag = (rand() % 2) ? true : false;

    // Add the new node to the linked list
    list->next = node;
}

// Function to free the memory used by a linked list of NFAPI_CRC_INDICATION_PDU_T structures
void nfapi_free_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T *list) {
    // Iterate through the linked list and free each node's memory
    while (list) {
        NFAPI_CRC_INDICATION_PDU_T *next = list->next;
        free(list);
        list = next;
    }
}
