// Define the structure for PDCP SN range
typedef struct {
    uint32_t pdcp_sn;
    uint32_t pdcp_sn_range;
} MAC_PDCP_SN_RANGE_T;

// Define the array type for dynamic PDCP SN ranges
MAC_PDCP_SN_RANGE_T *pdcp_sn_ranges = NULL;

// Define the mutex lock to ensure thread safety
pthread_mutex_t pdcp_sn_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize and populate the array of PDCP SN ranges
int init_pdcp_sn_ranges(uint32_t num_elements, uint32_t increment) {
    // Check if the array is already initialized
    if (pdcp_sn_ranges != NULL) {
        return 0;
    }

    // Allocate memory for the array of PDCP SN ranges
    pdcp_sn_ranges = malloc(num_elements * sizeof(MAC_PDCP_SN_RANGE_T));
    if (pdcp_sn_ranges == NULL) {
        return -1;
    }

    // Initialize the array of PDCP SN ranges with sequential values
    for (uint32_t i = 0; i < num_elements; i++) {
        pdcp_sn_ranges[i].pdcp_sn = i + 1;
        pdcp_sn_ranges[i].pdcp_sn_range = increment;
    }

    // Calculate the PDCP SN ranges based on the configured increment value
    for (uint32_t i = 0; i < num_elements; i++) {
        pdcp_sn_ranges[i].pdcp_sn_range = increment * i;
    }

    // Verify correct population of the array by checking for duplicate SNs
    bool has_duplicates = false;
    for (uint32_t i = 0; i < num_elements - 1; i++) {
        if (pdcp_sn_ranges[i].pdcp_sn == pdcp_sn_ranges[i + 1].pdcp_sn) {
            has_duplicates = true;
            break;
        }
    }

    // Return error if there are duplicates in the array
    if (has_duplicates) {
        return -2;
    }

    // Initialize the mutex lock for thread safety
    pthread_mutex_init(&pdcp_sn_lock, NULL);

    return 0;
}

// Function to update the array of PDCP SN ranges with a new value
int update_pdcp_sn_ranges(uint32_t pdcp_sn) {
    // Acquire the mutex lock for thread safety
    pthread_mutex_lock(&pdcp_sn_lock);

    // Find the index of the PDCP SN in the array
    uint32_t index = 0;
    while (index < num_elements && pdcp_sn > pdcp_sn_ranges[index].pdcp_sn) {
        index++;
    }

    // Update the PDCP SN range for the found index
    if (index < num_elements) {
        pdcp_sn_ranges[index].pdcp_sn = pdcp_sn;
        pdcp_sn_ranges[index].pdcp_sn_range = increment * index;
    } else {
        // Return error if the PDCP SN is not found in the array
        pthread_mutex_unlock(&pdcp_sn_lock);
        return -1;
    }

    // Release the mutex lock for thread safety
    pthread_mutex_unlock(&pdcp_sn_lock);

    return 0;
}

// Function to retrieve the array of PDCP SN ranges
MAC_PDCP_SN_RANGE_T *get_pdcp_sn_ranges() {
    // Acquire the mutex lock for thread safety
    pthread_mutex_lock(&pdcp_sn_lock);

    // Return a copy of the array of PDCP SN ranges
    MAC_PDCP_SN_RANGE_T *copy = malloc(num_elements * sizeof(MAC_PDCP_SN_RANGE_T));
    if (copy == NULL) {
        pthread_mutex_unlock(&pdcp_sn_lock);
        return NULL;
    }

    for (uint32_t i = 0; i < num_elements; i++) {
        copy[i].pdcp_sn = pdcp_sn_ranges[i].pdcp_sn;
        copy[i].pdcp_sn_range = pdcp_sn_ranges[i].pdcp_sn_range;
    }

    // Release the mutex lock for thread safety
    pthread_mutex_unlock(&pdcp_sn_lock);

    return copy;
}

// Function to release the array of PDCP SN ranges
void release_pdcp_sn_ranges() {
    // Acquire the mutex lock for thread safety
    pthread_mutex_lock(&pdcp_sn_lock);

    // Release memory allocated for the array of PDCP SN ranges
