// Define the function to initialize and populate the dynamic array of DataPackets
int initDataPackets(struct DataPacket** dataPackets, int maxSize) {
    // Check if the input parameters are valid
    if (dataPackets == NULL || maxSize <= 0) {
        return -1;
    }

    // Allocate memory for the dynamic array of DataPackets
    *dataPackets = (struct DataPacket*)malloc(sizeof(struct DataPacket) * maxSize);
    if (*dataPackets == NULL) {
        return -2;
    }

    // Initialize the elements in the dynamic array to zero
    for (int i = 0; i < maxSize; ++i) {
        (*dataPackets)[i].sourceIP = 0;
        (*dataPackets)[i].destinationIP = 0;
        (*dataPackets)[i].payloadLength = 0;
        (*dataPackets)[i].payload = NULL;
    }

    return 0;
}

// Define the function to add a new data packet to the dynamic array of DataPackets
int addDataPacket(struct DataPacket** dataPackets, int maxSize, struct DataPacket* newPacket) {
    // Check if the input parameters are valid
    if (dataPackets == NULL || maxSize <= 0 || newPacket == NULL) {
        return -1;
    }

    // Check if the dynamic array is full
    if (*dataPackets == NULL || *maxSize == 0) {
        // Initialize the dynamic array of DataPackets if it is not initialized yet
        initDataPackets(dataPackets, maxSize);
        if (*dataPackets == NULL) {
