    // Check if there is no available slot
    if (i == *maxSize) {
        return -3;
    }

    // Copy the new data packet to the next available slot in the dynamic array
    memcpy(&(*dataPackets)[i], newPacket, sizeof(struct DataPacket));

    return 0;
}

// Define the function to reconstruct a fragmented packet from multiple fragments
int reconstructPacket(struct DataPacket** dataPackets, int maxSize, struct DataPacket* fragPacket) {
    // Check if the input parameters are valid
    if (dataPackets == NULL || maxSize <= 0 || fragPacket == NULL) {
        return -1;
    }

    // Find the fragmented packet in the dynamic array of DataPackets
    int i = 0;
    while (i < *maxSize && (*dataPackets)[i].sourceIP != fragPacket->sourceIP ||
                           (*dataPackets)[i].destinationIP != fragPacket->destinationIP) {
        ++i;
    }

    // Check if the fragmented packet is not found in the dynamic array of DataPackets
    if (i == *maxSize) {
        return -2;
    }

    // Reconstruct the fragmented packet from multiple fragments
    size_t fragLen = fragPacket->payloadLength;
    char* fragData = fragPacket->payload;
    while (fragLen > 0 && i < *maxSize) {
        // Check if the current fragment is not the last one
        if ((*dataPackets)[i].payloadLength > 0) {
            size_t curFragLen = (*dataPackets)[i].payloadLength;
            char* curFragData = (*dataPackets)[i].payload;
            // Copy the current fragment data to the fragmented packet payload
            memcpy(fragData, curFragData, curFragLen);
            fragData += curFragLen;
            fragLen -= curFragLen;
        } else {
            // Check if the current fragment is the last one
            size_t curFragLen = fragLen;
            char* curFragData = fragData;
            // Copy the current fragment data to the fragmented packet payload
            memcpy(curFragData, (*dataPackets)[i].payload, curFragLen);
            fragData += curFragLen;
            fragLen -= curFragLen;
        }
        ++i;
    }

    return 0;
