// Define a linked list node for the DOM tree
typedef struct {
    char* tag;
    void* data;
    struct Node* next;
} Node;

// Define a recursive traversal function to traverse the DOM tree and generate an array of NFAPI_CRC_INDICATION_PDU_T structures
int generateNfaArray(Node* root, char** selectors, int numSelectors, NFAPI_CRC_INDICATION_PDU_T** arr, int* size) {
    // Check if the current node is NULL or if it doesn't match any of the selectors
    if (root == NULL || !nodeMatchesSelector(root, selectors, numSelectors)) {
        return 0;
    }

    // Recursively traverse the DOM tree and generate an array of NFAPI_CRC_INDICATION_PDU_T structures for the current node
    int numChildren = countNumChildren(root);
    NFAPI_CRC_INDICATION_PDU_T** childrenArr = (NFAPI_CRC_INDICATION_PDU_T**)malloc(numChildren * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    int numChildrenGenerated = 0;
    for (int i = 0; i < numChildren; i++) {
        Node* childNode = root->next;
        numChildrenGenerated += generateNfaArray(childNode, selectors, numSelectors, childrenArr + numChildrenGenerated, size);
    }

    // If the current node matches any of the selectors, add it to the array
    if (nodeMatchesSelector(root, selectors, numSelectors)) {
        *arr = (NFAPI_CRC_INDICATION_PDU_T*)realloc(*arr, (*size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        NFAPI_CRC_INDICATION_PDU_T* nfaStruct = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        nfaStruct->rxUETag = (RX_UE_INFORMATION_TAG*)root->data;
        nfaStruct->rnti = root->tag;
        nfaStruct->crcIndRel8Tag = (CRC_INDICATION_REL8_TAG*)malloc(sizeof(CRC_INDICATION_REL8_TAG));
        nfaStruct->crcIndRel8Tag->crFlag = rand() % 2; // randomly set CRCFLAG
        (*arr)[*size] = *nfaStruct;
        *size += 1;
    }

    // Free the memory allocated for the child nodes
    for (int i = 0; i < numChildrenGenerated; i++) {
        free(childrenArr[i]);
    }
    free(childrenArr);

    return 1;
}

// Count the number of children in a linked list node
int countNumChildren(Node* root) {
    int count = 0;
    while (root->next != NULL) {
        root = root->next;
        count++;
    }
    return count;
}

// Check if a linked list node matches any of the selectors
bool nodeMatchesSelector(Node* node, char** selectors, int numSelectors) {
    for (int i = 0; i < numSelectors; i++) {
        if (strcmp(node->tag, selectors[i]) == 0) {
            return true;
        }
    }
    return false;
}
