// Structure to hold the cache of RX buffer nodes
typedef struct {
    NFAPI_L2_RX_BUFFER *head;
    NFAPI_L2_RX_BUFFER *tail;
} RX_CACHE;

// Function to initialize a new RX buffer node
NFAPI_L2_RX_BUFFER* init_rx_buffer(void) {
    // Allocate memory for the new node
    NFAPI_L2_RX_BUFFER *node = (NFAPI_L2_RX_BUFFER *)malloc(sizeof(NFAPI_L2_RX_BUFFER));
    if (!node) {
        // Handle allocation failure
        return NULL;
    }

    // Initialize the node fields
    node->rx_buffer_id = 0;
    node->phy_layer_tag = 0;
    node->data_payload = (uint8_t *)malloc(MAX_DATA_PAYLOAD_SIZE);
    if (!node->data_payload) {
        // Handle allocation failure
        free(node);
        return NULL;
    }

    return node;
}

// Function to add a new RX buffer node to the cache
int add_rx_buffer(RX_CACHE *cache, NFAPI_L2_RX_BUFFER *node) {
    // Acquire lock on the cache
    pthread_mutex_lock(&cache->lock);

    // Check if there is space in the cache for the new node
    if (cache->size >= MAX_CACHE_SIZE) {
        // Remove the oldest node from the cache
        NFAPI_L2_RX_BUFFER *oldest = cache->head;
        cache->head = cache->head->next;
        free(oldest);
    }

    // Add the new node to the end of the cache
    cache->tail->next = node;
    cache->tail = node;
    cache->size++;

    // Release lock on the cache
    pthread_mutex_unlock(&cache->lock);

    return 0;
}

// Function to remove a RX buffer node from the cache
int remove_rx_buffer(RX_CACHE *cache, NFAPI_L2_RX_BUFFER *node) {
    // Acquire lock on the cache
    pthread_mutex_lock(&cache->lock);

    // Check if the node is in the cache
    if (node == NULL || node != cache->head) {
        // Release lock on the cache and return error
        pthread_mutex_unlock(&cache->lock);
        return -1;
    }

    // Remove the node from the cache
    cache->head = node->next;
    if (cache->head == NULL) {
        cache->tail = NULL;
    }
    free(node);
    cache->size--;

    // Release lock on the cache
    pthread_mutex_unlock(&cache->lock);

    return 0;
}

// Function to get a RX buffer node from the cache
NFAPI_L2_RX_BUFFER* get_rx_buffer(RX_CACHE *cache) {
    // Acquire lock on the cache
    pthread_mutex_lock(&cache->lock);

    // Check if there are any available nodes in the cache
    if (cache->size == 0) {
        // Release lock on the cache and return NULL
        pthread_mutex_unlock(&cache->lock);
        return NULL;
    }

    // Get the oldest node from the cache
    NFAPI_L2_RX_BUFFER *node = cache->head;
    cache->head = cache->head->next;
    if (cache->head == NULL) {
        cache->tail = NULL;
    }
    free(node);
    cache->size--;

    // Release lock on the cache
    pthread_mutex_unlock(&cache->lock);

    return node;
}
