// Define the structure to hold the LTE_DL_FRAME_MESSAGE data
typedef struct {
    DL_FRAME_TAG dlFrameTag;
    CELL_ID cellId;
    PHY_LAYER_STATUS phyLayerStatus;
} LTE_DL_FRAME_MESSAGE;

// Define a linked list node to store the LTE_DL_FRAME_MESSAGE structures
typedef struct {
    LTE_DL_FRAME_MESSAGE *data;
    struct node *next;
} node;

// Define the linked list head pointer
node *head = NULL;

// Define the semaphore to synchronize access from multiple threads
semaphore_t semaphore;

// Define the function to initialize the linked list and acquire the semaphore
void initLinkedList() {
    // Allocate memory for the head node
    head = (node *)malloc(sizeof(node));
    if (!head) {
        perror("Failed to allocate memory for head node");
        exit(1);
    }
    head->data = NULL;
    head->next = NULL;

    // Initialize the semaphore
    semaphore_init(&semaphore, 1);
}

// Define the function to add a new LTE_DL_FRAME_MESSAGE structure to the linked list
void addNewEntry(LTE_DL_FRAME_MESSAGE *entry) {
    // Acquire the semaphore
    semaphore_wait(&semaphore);

    // Allocate memory for the new node
    node *newNode = (node *)malloc(sizeof(node));
    if (!newNode) {
        perror("Failed to allocate memory for new node");
        exit(1);
    }
    newNode->data = entry;

    // Insert the new node at the end of the linked list
    node *currNode = head;
    while (currNode->next != NULL) {
        currNode = currNode->next;
    }
    currNode->next = newNode;

    // Release the semaphore
    semaphore_post(&semaphore);
}

// Define the function to remove an LTE_DL_FRAME_MESSAGE structure from the linked list
void removeEntry(LTE_DL_FRAME_MESSAGE *entry) {
    // Acquire the semaphore
    semaphore_wait(&semaphore);

    // Find the node containing the entry to be removed
    node *currNode = head;
    while (currNode->next != NULL && currNode->data != entry) {
        currNode = currNode->next;
    }
    if (currNode->data == entry) {
        // Remove the node from the linked list
        node *prevNode = currNode->prev;
        prevNode->next = currNode->next;

        // Free the memory of the removed node
        free(currNode);
    }

    // Release the semaphore
    semaphore_post(&semaphore);
}

// Define the function to retrieve the most recent LTE_DL_FRAME_MESSAGE structure from the linked list
LTE_DL_FRAME_MESSAGE *getLatestEntry() {
    // Acquire the semaphore
    semaphore_wait(&semaphore);

    // Find the most recent node containing a valid entry
    node *currNode = head;
    while (currNode->next != NULL && currNode->data == NULL) {
        currNode = currNode->next;
    }
    LTE_DL_FRAME_MESSAGE *latestEntry = currNode->data;

    // Release the semaphore
    semaphore_post(&semaphore);

    return latestEntry;
}
```
