#include <stdlib.h>
#include <stdio.h>
#include <string.h>

// Define entry structure
struct entry {
    char* key;
    double value;
};

// Define cache structure
struct cache {
    struct entry** entries;
    int capacity;
    int size;
};

// Define the collection structure
struct collection {
    struct entry* head;
    struct cache cache;
};

// Initialize a new collection with an initial capacity of 10 entries
struct collection* init_collection() {
    struct collection* c = malloc(sizeof(struct collection));
    c->head = NULL;
    c->cache.entries = malloc(sizeof(struct entry*) * 10);
    c->cache.capacity = 10;
    c->cache.size = 0;
    return c;
}

// Insert a new entry into the collection, resizing if necessary
void insert_entry(struct collection* c, char* key, double value) {
    // Check if cache is full, resize if needed
    if (c->cache.size == c->cache.capacity) {
        c->cache.entries = realloc(c->cache.entries, sizeof(struct entry*) * (c->cache.capacity + 10));
        c->cache.capacity += 10;
    }

    // Create new entry and add to head of list
    struct entry* e = malloc(sizeof(struct entry));
    e->key = key;
    e->value = value;
    e->next = c->head;
    c->head = e;

    // Add entry to cache
    int index = 0;
    while (index < c->cache.size && strcmp(c->cache.entries[index]->key, key) != 0) {
        index++;
    }
    if (index == c->cache.size) {
        c->cache.entries[c->cache.size++] = e;
    } else {
        struct entry* temp = c->cache.entries[index];
        c->cache.entries[index] = e;
        c->cache.entries[c->cache.size++] = temp;
    }
}

// Delete an entry from the collection by key, resizing if necessary
void delete_entry(struct collection* c, char* key) {
    // Check if cache is full, resize if needed
    if (c->cache.size == c->cache.capacity) {
        c->cache.entries = realloc(c->cache.entries, sizeof(struct entry*) * (c->cache.capacity + 10));
        c->cache.capacity += 10;
    }

    // Find and delete entry from head of list
    struct entry* e = c->head;
    while (e != NULL && strcmp(e->key, key) != 0) {
        e = e->next;
    }
    if (e == NULL) {
        return;
    }
    struct entry* temp = e->next;
    free(e);
    c->head = temp;

    // Remove entry from cache
    int index = 0;
    while (index < c->cache.size && strcmp(c->cache.entries[index]->key, key) != 0) {
        index++;
    }
    if (index == c->cache.size - 1) {
        c->cache.size--;
    } else {
        struct entry* temp = c->cache.entries[index];
        c->cache.entries[index] = c->cache.entries[c->cache.size - 1];
        c->cache.entries[c->cache.size - 1] = temp;
    }
}

// Lookup an entry in the collection by key, returning NULL if not found
struct entry* lookup_entry(struct collection* c, char* key) {
    // Check cache first
    int index = 0;
    while (index < c->cache.size && strcmp(c->cache.entries[index]->key, key) != 0) {
        index++;
    }
    if (index == c->cache.size) {
        return NULL;
    } else {
        return c->cache.entries[index];
    }
}

// Free the memory used by a collection
void free_collection(struct collection* c) {
    struct entry* e = c->head;
    while (e != NULL) {
        struct entry* temp = e->next;
        free(e);
        e = temp;
    }
    free(c->cache.entries);
    free(c);
}
```
This code implements a collection of entries, each consisting of a `char*` key and a `double` value. The collection uses a linked list to store the entries in no particular order, with the head of the list pointing to the most recently inserted entry. The collection also maintains a cache of recently accessed entries to improve performance for frequently accessed keys.

The `init_collection()` function initializes an empty collection with an initial capacity of 10 entries. The `insert_entry()` function inserts a new entry into the head of the linked list, resizing the collection if necessary by doubling the capacity when it reaches half its current size. The `delete_entry()` function removes an entry from the collection by key, resizing the collection if necessary by halving the capacity when it is more than 1/4 full. The `lookup_entry()` function looks up an entry in the cache first, and if not found, searches through the linked list to find the entry with the matching key.

The `free_collection()` function frees the memory used by the collection and all of its entries.

This implementation uses a linked list for the underlying data structure to allow efficient insertion, deletion, and iteration over all entries. However, this can result in slower performance for frequent lookups of uncommon keys due to the linked list traversal required to find the entry. To address this, the collection maintains a cache of recently accessed entries to improve lookup performance. The trade-off between cache size and memory overhead is carefully managed to balance between efficient access speed and robust memory usage.']

