// Structure to store a data packet
typedef struct DataPacket {
    time_t timestamp;
    uint32_t sourceIP;
    uint32_t destinationIP;
} DataPacket;

// Thread-safe queue for data processing
struct DataQueue {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    DataPacket* buffer;
    int size;
};

void initDataQueue(struct DataQueue* q) {
    pthread_mutex_init(&q->lock, NULL);
    pthread_cond_init(&q->cond, NULL);
    q->buffer = malloc(sizeof(DataPacket) * INITIAL_BUFFER_SIZE);
    q->size = 0;
}

void deinitDataQueue(struct DataQueue* q) {
    free(q->buffer);
    pthread_mutex_destroy(&q->lock);
    pthread_cond_destroy(&q->cond);
}

int enqueueDataPacket(struct DataQueue* q, DataPacket packet) {
    int result = 0;
    pthread_mutex_lock(&q->lock);
    if (q->size == MAX_BUFFER_SIZE) {
        // Buffer is full, wait for some space to become available
        pthread_cond_wait(&q->cond, &q->lock);
    }
    q->buffer[q->size++] = packet;
    pthread_mutex_unlock(&q->lock);
    return result;
}

int dequeueDataPacket(struct DataQueue* q, DataPacket* packet) {
    int result = 0;
    pthread_mutex_lock(&q->lock);
    if (q->size == 0) {
        // Buffer is empty, wait for some data to arrive
        pthread_cond_wait(&q->cond, &q->lock);
    }
    *packet = q->buffer[--q->size];
    pthread_mutex_unlock(&q->lock);
    return result;
}

// Function to manage a dynamic array of DataPacket structures
void manageDataPackets(struct DataQueue* q) {
    // Initialize the data queue
    initDataQueue(q);

    // Create a thread-safe queue for data processing
    struct DataQueue* processingQ = malloc(sizeof(struct DataQueue));
    initDataQueue(processingQ);

    // Initialize the network socket and buffer
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    char* buf = malloc(SOCKET_BUFFER_SIZE);

    while (1) {
        // Receive data packets from the network socket
        ssize_t len = recvfrom(sock, buf, SOCKET_BUFFER_SIZE, 0, NULL, NULL);
        if (len < 0) {
            perror("recvfrom");
            break;
        }

        // Parse the received data packets and enqueue them in the data queue
        DataPacket* packet = (DataPacket*)buf;
        while (packet < buf + len) {
            // Check for duplicate packets within a sliding time window of 10 seconds
            if (!checkForDuplicate(q, packet)) {
                enqueueDataPacket(q, *packet);
            }
            // Process the data packet using the thread-safe queue
            enqueueDataPacket(processingQ, *packet);
        }
    }

    // Close the network socket and free the buffer
    close(sock);
    free(buf);

    // Deinitialize the thread-safe queue for data processing
    deinitDataQueue(processingQ);

    // Deinitialize the data queue
    deinitDataQueue(q);
}

// Thread-safe duplicate detection function within a sliding time window of 10 seconds
int checkForDuplicate(struct DataQueue* q, DataPacket packet) {
    int result = 0;
    pthread_mutex_lock(&q->lock);
    // Check for duplicate packets within the last 10 seconds
    time_t now = time(NULL);
    for (int i = q->size - 1; i >= 0; i--) {
        if ((now - q->buffer[i].timestamp) <= DUPLICATE_WINDOW &&
            q->buffer[i].sourceIP == packet.sourceIP &&
            q->buffer[i].destinationIP == packet.destinationIP) {
                result = 1;
                break;
        }
    }
    pthread_mutex_unlock(&q->lock);
    return result;
}
