// Define a function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_LIST_T* nfapi_crc_indication_list_create(size_t num_elements) {
    // Allocate memory for the list structure and initialize its size and capacity
    NFAPI_CRC_INDICATION_LIST_T* list = (NFAPI_CRC_INDICATION_LIST_T*)malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) {
        return NULL;
    }
    list->size = 0;
    list->capacity = num_elements;
    // Allocate memory for the list elements and initialize them to zero
    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(num_elements, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    // Generate random RNTIs and CRCFLAGs for each list element
    srand(time(NULL));
    for (size_t i = 0; i < num_elements; ++i) {
        list->elements[i].rx_ue_information_tag = rand() % UINT32_MAX;
        list->elements[i].rnti = rand() % UINT16_MAX;
        list->elements[i].crc_indication_rel8_tag = rand() % UINT8_MAX;
        list->elements[i].crcflag = (rand() % 2) ? true : false;
    }

    return list;
}

// Define a function to add an element to the end of the list and resize the list if necessary
void nfapi_crc_indication_list_add(NFAPI_CRC_INDICATION_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T element) {
    // If the list is full, resize it by a factor of 2 to prevent frequent resizing
    if (list->size == list->capacity) {
        list->capacity *= 2;
        NFAPI_CRC_INDICATION_PDU_T* new_elements = realloc(list->elements, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            // If memory allocation fails, free the old elements and return NULL
            for (size_t i = 0; i < list->size; ++i) {
                free(list->elements[i].rnti);
                free(list->elements[i].crcflag);
            }
            free(list->elements);
            return NULL;
        }
        list->elements = new_elements;
    }
    // Add the element to the end of the list and increment its size
    list->elements[list->size] = element;
    list->size += 1;
}

// Define a function to remove an element from the list by its index and resize the list if necessary
void nfapi_crc_indication_list_remove(NFAPI_CRC_INDICATION_LIST_T* list, size_t index) {
    // If the list is empty or the given index is out of bounds, return NULL
    if (index >= list->size || list->size == 0) {
        return;
    }
    // Decrement the size of the list and free the removed element
    list->size -= 1;
    free(list->elements[index].rnti);
    free(list->elements[index].crcflag);
    // Shift all elements after the given index to fill the gap
    for (size_t i = index; i < list->size; ++i) {
        list->elements[i] = list->elements[i + 1];
    }
    // If the new size is less than half the capacity, resize the list by a factor of 2 to prevent frequent resizing
    if (list->size < list->capacity / 2) {
        list->capacity /= 2;
        NFAPI_CRC_INDICATION_PDU_T* new_elements = realloc(list->elements, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            // If memory allocation fails, free the old elements and return NULL
            for (size_t i = 0; i < list->size; ++i) {
                free(list->elements[i].rnti);
                free(list->elements[i].crcflag);
            }
            free(list->elements);
            return NULL;
        }
        list->elements = new_elements;
    }
}

// Define a function to find an element in the list by its RNTI and return its index
size_t nfapi_crc_indication_list_find(NFAPI_CRC_INDICATION_LIST_T* list, uint16_t rnti) {
    for (size_t i = 0; i < list->size; ++i) {
        if (list->elements[i].rnti == rnti) {
            return i;
        }
    }
    // If the RNTI is not found, return NULL
    return -1;
}

// Define a function to clear all elements from the list and free its memory
void nfapi_crc_indication_list_clear(NFAPI_CRC_INDICATION_LIST_T* list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->elements[i].rnti);
        free(list->elements[i].crcflag);
    }
    free(list->elements);
}

// Define a function to export the list as a JSON string
void nfapi_crc_indication_list_to_json(NFAPI_CRC_INDICATION_LIST_T* list, char* json) {
    // Initialize the JSON array and add each element to it
    *json = '[';
    for (size_t i = 0; i < list->size; ++i) {
        if (i > 0) {
            strcat(json, ",");
        }
        sprintf(json + strlen(json), "{\"rx-ue-information\":{\"rnti\":\"%u\",\"crc-flag\":\"%s\"}}", list->elements[i].rnti, (list->elements[i].crcflag) ? "true" : "false");
    }
    strcat(json, ']');
}

// Define a function to import the list from a JSON string
void nfapi_crc_indication_list_from_json(NFAPI_CRC_INDICATION_LIST_T* list, char* json) {
    // Initialize the JSON array and add each element to it
    *json = '[';
    for (size_t i = 0; i < list->size; ++i) {
        if (i > 0) {
            strcat(json, ",");
        }
        sprintf(json + strlen(json), "{\"rx-ue-information\":{\"rnti\":\"%u\",\"crc-flag\":\"%s\"}}", list->elements[i].rnti, (list->elements[i].crcflag) ? "true" : "false");
    }
    strcat(json, ']');
}

int main() {
    // Create a new instance of the NFAPI_CRC_INDICATION_LIST_T struct
    NFAPI_CRC_INDICATION_LIST_T* list = nfapi_crc_indication_list_create();

    // Add some elements to the list
    nfapi_crc_indication_list_add(list, {"rx-ue-information":{"rnti":123,"crc-flag":"false"}});
    nfapi_crc_indication_list_add(list, {"rx-ue-information":{"rnti":456,"crc-flag":"true"}});
    nfapi_crc_indication_list_add(list, {"rx-ue-information":{"rnti":789,"crc-flag":"false"}});

