#define MAX_NFAPI_RACH_REQUESTS 1024

typedef struct {
    int sequence_number;
} NFAPI_RACH_REQUEST_TAG;

typedef struct {
    NFAPI_RACH_REQUEST_TAG *tag;
    char *buffer;
    size_t buffer_size;
} NFAPI_RACH_REQUEST_PDU;

// Thread-safe queue for storing rach requests
static pthread_mutex_t rach_request_queue_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t rach_request_queue_not_empty = PTHREAD_COND_INITIALIZER;
static NFAPI_RACH_REQUEST_PDU *rach_request_queue[MAX_NFAPI_RACH_REQUESTS];
static size_t rach_request_queue_head = 0;
static size_t rach_request_queue_tail = 0;

// Initialize and populate an array of NFAPI_RACH_REQUEST_PDU structures
int init_rach_requests(NFAPI_RACH_REQUEST_PDU **requests, int num_requests) {
    if (num_requests > MAX_NFAPI_RACH_REQUESTS) {
        return -1; // Error: too many requests
    }

    // Allocate memory for the NFAPI_RACH_REQUEST_PDU structures
    *requests = malloc(sizeof(NFAPI_RACH_REQUEST_PDU) * num_requests);
    if (*requests == NULL) {
        return -2; // Error: could not allocate memory
    }

    // Initialize the NFAPI_RACH_REQUEST_TAG structures and populate the buffer with random data
    for (int i = 0; i < num_requests; i++) {
        (*requests)[i].tag = malloc(sizeof(NFAPI_RACH_REQUEST_TAG));
        if ((*requests)[i].tag == NULL) {
            return -3; // Error: could not allocate memory for NFAPI_RACH_REQUEST_TAG structure
        }

        (*requests)[i].buffer = malloc(1024); // Use a fixed buffer size of 1024 bytes
        if ((*requests)[i].buffer == NULL) {
            return -4; // Error: could not allocate memory for buffer
        }

        (*requests)[i].buffer_size = 1024;

        (*requests)[i].tag->sequence_number = i + 1; // Use a sequence number starting from 1

        // Populate the buffer with random data
        memset((*requests)[i].buffer, 'A', 1024);
    }

    return num_requests;
}

// Add a new rach request to the queue
int add_rach_request(NFAPI_RACH_REQUEST_PDU *request) {
    pthread_mutex_lock(&rach_request_queue_mutex);

    if (rach_request_queue_tail == MAX_NFAPI_RACH_REQUESTS) {
        // Queue is full, return error
        pthread_mutex_unlock(&rach_request_queue_mutex);
        return -1;
    }

    // Add the new request to the queue
    rach_request_queue[rach_request_queue_tail] = request;
    rach_request_queue_tail++;

    pthread_cond_signal(&rach_request_queue_not_empty);
    pthread_mutex_unlock(&rach_request_queue_mutex);

    return 0; // Success: the new request was added to the queue
}

// Remove a rach request from the queue
NFAPI_RACH_REQUEST_PDU *remove_rach_request() {
    pthread_mutex_lock(&rach_request_queue_mutex);

    while (rach_request_queue_head == rach_request_queue_tail) {
        // Queue is empty, wait for new requests to arrive
        pthread_cond_wait(&rach_request_queue_not_empty, &rach_request_queue_mutex);
    }

    NFAPI_RACH_REQUEST_PDU *request = rach_request_queue[rach_request_queue_head];
    rach_request_queue_head++;

    pthread_mutex_unlock(&rach_request_queue_mutex);

    return request;
}

// Free the memory allocated for a given NFAPI_RACH_REQUEST_PDU structure
void free_rach_request(NFAPI_RACH_REQUEST_PDU *request) {
    if (request != NULL) {
        // Free the tag and buffer
        free(request->tag);
        free(request->buffer);
    }
}
