#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <assert.h>

// Structure to store CRC indication data for a single UE
typedef struct {
    uint32_t rx_ue_information_tag; // RX_UE_INFORMATION_TAG
    uint16_t rnti;                  // RNTI
    bool crcflag;                   // CRCFLAG
} NFAPI_CRC_INDICATION_PDU_T;

// Linked list node for storing CRC indication data
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct nfaci_crc_ind_node *next;
} NFAPI_CRC_INDICATION_NODE_T;

// Linked list to store CRC indication data for multiple UEs
static NFAPI_CRC_INDICATION_NODE_T *crc_list = NULL;

// Maximum threshold for the size of the linked list
#define MAX_LIST_SIZE 1000

/**
 * Adds a new node to the end of the linked list, and sets the CRCFLAG
 * based on the provided RX_UE_INFORMATION_TAG and RNTI. The function
 * returns true if the addition was successful, false otherwise.
 */
bool add_crc_indication(uint32_t rx_ue_information_tag, uint16_t rnti) {
    // Create a new node for the CRC indication data
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        return false;
    }

    // Set the CRCFLAG based on the provided RX_UE_INFORMATION_TAG and RNTI
    uint64_t hash = (uint64_t) rx_ue_information_tag ^ (uint64_t) rnti;
    new_data->crcflag = (hash % 2 == 0);

    // Add the new node to the end of the linked list
    NFAPI_CRC_INDICATION_NODE_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_NODE_T));
    if (!new_node) {
        free(new_data);
        return false;
    }
    new_node->data = new_data;
    new_node->next = NULL;

    // Check if the linked list is empty, and set the head node if necessary
    if (!crc_list) {
        crc_list = new_node;
    } else {
        NFAPI_CRC_INDICATION_NODE_T *current = crc_list;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }

    return true;
}

/**
 * Removes the first node from the linked list and returns its data.
 * If the list is empty, returns NULL.
 */
NFAPI_CRC_INDICATION_PDU_T *remove_crc_indication() {
    if (!crc_list) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_NODE_T *head = crc_list;
    NFAPI_CRC_INDICATION_PDU_T *data = head->data;
    crc_list = crc_list->next;
    free(head);

    return data;
}

/**
 * Periodically clears and resets the entire linked list, ensuring memory usage
 * optimization while maintaining valid CRC indication data.
 */
void reset_crc_indications() {
    NFAPI_CRC_INDICATION_NODE_T *current = crc_list;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *data = current->data;
        free(data);
        current = current->next;
    }
    crc_list = NULL;
}

/**
 * Logs a warning when the size of the linked list exceeds a predefined maximum
 * threshold, and caps the list size accordingly.
 */
void check_list_size() {
    if (get_list_size() > MAX_LIST_SIZE) {
        printf("WARNING: Linked list size exceeded %d\n", MAX_LIST_SIZE);
        crc_list = NULL; // Reset the linked list to free up memory
    }
}

/**
 * Returns the current size of the linked list.
 */
int get_list_size() {
    int count = 0;
    NFAPI_CRC_INDICATION_NODE_T *current = crc_list;
    while (current) {
        ++count;
        current = current->next;
    }
    return count;
}
