                median = (recordArray[N / 2 - 1]->value + recordArray[N / 2]->value) / 2.0;
            } else {
                median = recordArray[N / 2]->value;
            }
            printf("Module: processIntegerData\nTest: Printing statistics\n");
            printf("Largest integer in array: %d\n", recordArray[i]->value);
            printf("Average of all integers: %.2f\n", average);
            printf("Median of all integers: %.2f\n", median);
        }
    }

    // Clean up all allocations and return the result
    free(recordArray[i]);
    free(keyArray[i]);
    free(offsetArray[i]);
    free(recordArray);
    free(keyArray);
    free(offsetArray);
    return;
}
```
