// Define the structure for the linked list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list type
typedef struct LinkedList {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct LinkedList *next;
} LinkedList;

// Define the semaphore for synchronizing access to the linked list
sem_t listSemaphore;

// Define the logging mechanism with different verbosity levels
#define DEBUG 1
#define INFO 2
#define WARNING 3
#define ERROR 4

// Define the initial value of the semaphore from the configuration file
int semValue = 0;

// Define the threshold for initiating garbage collection
int listThreshold = 5000;

void initList(void) {
    // Initialize the linked list and set the head to NULL
    LinkedList *head = NULL;

    // Create a semaphore with the initial value from the configuration file
    if (sem_init(&listSemaphore, 1, semValue) == -1) {
        perror("Failed to create semaphore");
        exit(1);
    }
}

void addElement(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    // Acquire the lock on the list
    if (sem_wait(&listSemaphore) == -1) {
        perror("Failed to acquire semaphore");
        exit(1);
    }

    // Allocate memory for the new element and initialize it
    NFAPI_CRC_INDICATION_PDU_T *newElement = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newElement == NULL) {
        perror("Failed to allocate memory for new element");
        exit(1);
    }
    newElement->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newElement->RNTI = RNTI;
    newElement->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

    // Add the new element to the head of the linked list
    LinkedList *current = head;
    while (current != NULL) {
        if (current->next == NULL) {
            current->next = newElement;
            break;
        }
        current = current->next;
    }

    // If the list exceeds the threshold, initiate garbage collection
    int size = getListSize();
    if (size > listThreshold) {
        printf("Initiating garbage collection...\n");
        freeLeastRecentlyUsedElements(size - listThreshold);
    }

    // Release the lock on the list
    if (sem_post(&listSemaphore) == -1) {
        perror("Failed to release semaphore");
        exit(1);
    }
}

int getListSize(void) {
    // Acquire the lock on the list
    if (sem_wait(&listSemaphore) == -1) {
        perror("Failed to acquire semaphore");
        exit(1);
    }

    // Count the number of elements in the linked list
    LinkedList *current = head;
    int size = 0;
    while (current != NULL) {
        size++;
        current = current->next;
    }

    // Release the lock on the list
    if (sem_post(&listSemaphore) == -1) {
        perror("Failed to release semaphore");
        exit(1);
    }

    return size;
}

void freeLeastRecentlyUsedElements(int count) {
    // Acquire the lock on the list
    if (sem_wait(&listSemaphore) == -1) {
        perror("Failed to acquire semaphore");
        exit(1);
    }

    // Traverse the linked list and free the least recently used elements
    LinkedList *current = head;
    while (count > 0 && current != NULL) {
        if (current->next == NULL) {
            break;
        }
        count--;
        NFAPI_CRC_INDICATION_PDU_T *elementToFree = current->next;
        current->next = elementToFree->next;
        free(elementToFree);
    }

    // Release the lock on the list
    if (sem_post(&listSemaphore) == -1) {
        perror("Failed to release semaphore");
        exit(1);
    }
}
