// Define the dynamic array of NFAPI_RX_FRAME_PDU_T structures
typedef struct {
    NFAPI_RX_FRAME_PDU_T **frames;
    size_t capacity;
    size_t count;
} NFAPI_RX_FRAMES_T;

// Define the filtering mechanism to select frames based on a specified RNTI value
typedef struct {
    uint16_t rnti;
    bool enabled;
} FILTERING_CONTEXT_T;

// Initialize the dynamic array of NFAPI_RX_FRAME_PDU_T structures
void nfapi_rx_frames_init(NFAPI_RX_FRAMES_T *frames) {
    frames->frames = NULL;
    frames->capacity = 0;
    frames->count = 0;
}

// Deinitialize the dynamic array of NFAPI_RX_FRAME_PDU_T structures
void nfapi_rx_frames_deinit(NFAPI_RX_FRAMES_T *frames) {
    for (size_t i = 0; i < frames->count; ++i) {
        free(frames->frames[i]->payload);
        free(frames->frames[i]);
    }
    free(frames->frames);
}

// Add a new frame to the dynamic array of NFAPI_RX_FRAME_PDU_T structures
void nfapi_rx_frame_add(NFAPI_RX_FRAMES_T *frames, uint16_t rnti, uint32_t frame_number, uint8_t *payload) {
    // Check if the dynamic array needs to be resized
    if (frames->count == frames->capacity) {
        size_t new_capacity = frames->capacity > 0 ? frames->capacity * 2 : 1;
        NFAPI_RX_FRAME_PDU_T **new_frames = realloc(frames->frames, sizeof(NFAPI_RX_FRAME_PDU_T *) * new_capacity);
        if (new_frames == NULL) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
        frames->frames = new_frames;
        frames->capacity = new_capacity;
    }

    // Allocate memory for the new frame
    NFAPI_RX_FRAME_PDU_T *new_frame = malloc(sizeof(NFAPI_RX_FRAME_PDU_T));
    if (new_frame == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    // Fill in the fields of the new frame
    new_frame->rnti = rnti;
    new_frame->frame_number = frame_number;
    new_frame->payload = payload;

    // Add the new frame to the dynamic array
    frames->frames[frames->count++] = new_frame;
}

// Remove a frame from the dynamic array of NFAPI_RX_FRAME_PDU_T structures
void nfapi_rx_frame_remove(NFAPI_RX_FRAMES_T *frames, size_t index) {
    // Check if the specified index is out of bounds
    if (index >= frames->count) {
        fprintf(stderr, "Index %zu is out of bounds for array of length %zu\n", index, frames->count);
        exit(EXIT_FAILURE);
    }

    // Free the memory allocated to the frame
    free(frames->frames[index]->payload);
    free(frames->frames[index]);

    // Shift all subsequent frames to fill the gap
    for (size_t i = index + 1; i < frames->count; ++i) {
        frames->frames[i - 1] = frames->frames[i];
    }

    // Decrement the count of frames
    --frames->count;
}

// Iterate over all frames in the dynamic array of NFAPI_RX_FRAME_PDU_T structures
void nfapi_rx_frames_iter(NFAPI_RX_FRAMES_T *frames, void (*callback)(NFAPI_RX_FRAME_PDU_T *)) {
    for (size_t i = 0; i < frames->count; ++i) {
        callback(frames->frames[i]);
    }
}

// Filter frames based on a specified RNTI value
void nfapi_rx_filter_rnti(NFAPI_RX_FRAMES_T *frames, uint16_t rnti) {
    // Check if the filtering mechanism is enabled
    FILTERING_CONTEXT_T ctx = { .enabled = true, .rnti = rnti };

    // Iterate over all frames in the dynamic array of NFAPI_RX_FRAME_PDU_T structures
    nfapi_rx_frames_iter(frames, (NFAPI_RX_FRAME_PDU_T *frame) {
        if (ctx.enabled && frame->rnti == ctx.rnti) {
            callback(frame);
        }
    });
}

// Enable the filtering mechanism for a specified RNTI value
void nfapi_rx_filter_enable(NFAPI_RX_FRAMES_T *frames, uint16_t rnti) {
    FILTERING_CONTEXT_T ctx = { .enabled = true, .rnti = rnti };
}

// Disable the filtering mechanism for a specified RNTI value
void nfapi_rx_filter_disable(NFAPI_RX_FRAMES_T *frames, uint16_t rnti) {
    FILTERING_CONTEXT_T ctx = { .enabled = false, .rnti = rnti };
}']

