    size_t available_slots = queue->capacity - (queue->back - queue->front + 1) % queue->capacity;

    if (available_slots > 0) {
        // Process the incoming data.
        process_data(queue, m, n);
    } else {
        // Handle a full buffer gracefully.
        pthread_mutex_unlock(&queue->mutex);
        return;
