// Define the list management function
void manage_list(LTE_PHY_RX_STRUCT *list, int num_elements) {
    // Initialize the list with the given number of elements
    for (int i = 0; i < num_elements; i++) {
        list[i].UE_ID = i;
        list[i].signal_strength = 0.0f;
        memset(list[i].configured_antennas, '\0', sizeof(list[i].configured_antennas));
    }

    // Define a custom memory pool to reduce overhead of frequent allocations and deallocations
    struct {
        int *memory;
        int size;
    } memory_pool = {NULL, 0};

    // Function to allocate memory from the pool
    void *allocate_memory(int size) {
        if (size > memory_pool.size) {
            return NULL;
        }

        for (int i = 0; i < num_elements; i++) {
            if (list[i].UE_ID == -1) {
                list[i].UE_ID = size;
                memory_pool.memory[size] = 1;
                return &list[i];
            }
        }

        return NULL;
    }

    // Function to deallocate memory from the pool
    void deallocate_memory(void *ptr) {
        int size = ((LTE_PHY_RX_STRUCT *) ptr)->UE_ID;
        list[size].UE_ID = -1;
        memory_pool.memory[size] = 0;
    }

    // Function to resize the list dynamically based on user input
    void resize_list(int new_size) {
        if (new_size < num_elements) {
            return;
        }

        int *old_memory = memory_pool.memory;
        memory_pool.memory = calloc(new_size, sizeof(int));
        memory_pool.size = new_size;

        for (int i = 0; i < num_elements; i++) {
            if (list[i].UE_ID != -1) {
                int size = list[i].UE_ID;
                list[i].UE_ID = i;
                memory_pool.memory[size] = 1;
