    }

    // Function to handle concurrent access from multiple threads without data corruption
    void *lock(void) {
        pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
        pthread_mutex_lock(&mutex);
        return &mutex;
    }

    // Function to handle concurrent access from multiple threads without data corruption
    void unlock(void *mutex) {
        pthread_mutex_unlock((pthread_mutex_t *) mutex);
    }

    // Filtering and sorting operations on the list based on signal strength and UE_ID
