                // Swap elements with lower signal strength to the beginning of the list
                for (int j = i - 1; j >= 0; j--) {
                    if (list[j].signal_strength < min_signal_strength) {
                        LTE_PHY_RX_STRUCT temp = list[j];
                        list[j] = list[i];
                        list[i] = temp;
                    } else {
                        break;
                    }
                }
            }
        }
    }
}
