    return (uint16_t)((t & 0xFFFF) << 8);
}

//define a function to serialize an array of NFAPI_RRC_CU_TRANSPORT_PDU_T structures to disk
int serialize_array(struct PDU_list *pdu_list, int num_pdus, size_t pdu_size) {
