    size_t max_size;
} NFAPI_CRC_INDICATION_LIST_MANAGER_T;

// Function to create a new list manager with the given maximum size
NFAPI_CRC_INDICATION_LIST_MANAGER_T *nfapi_crc_indication_list_manager_create(size_t max_size) {
    // Allocate memory for the list manager structure
    NFAPI_CRC_INDICATION_LIST_MANAGER_T *list_manager = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_MANAGER_T));

    // Initialize the list manager structure
    list_manager->elements = NULL;
    list_manager->count = 0;
    list_manager->max_size = max_size;

    return list_manager;
}

// Function to destroy a list manager and free its memory
void nfapi_crc_indication_list_manager_destroy(NFAPI_CRC_INDICATION_LIST_MANAGER_T *list_manager) {
    // Free the elements in the list
    for (size_t i = 0; i < list_manager->count; i++) {
        free(list_manager->elements[i].RX_UE_INFORMATION_TAG);
        free(list_manager->elements[i].RNTI);
    }

    // Free the memory for the list manager structure
    free(list_manager);
}

// Function to add a new element to the list, ensuring that insertion fails if the list is at capacity
bool nfapi_crc_indication_list_add(NFAPI_CRC_INDICATION_LIST_MANAGER_T *list_manager, NFAPI_CRC_INDICATION_PDU_T element) {
    // Check if the list is at capacity
    if (list_manager->count >= list_manager->max_size) {
        return false;
    }

    // Allocate memory for the new element
    NFAPI_CRC_INDICATION_PDU_T *new_element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize the new element with the given values
    new_element->RX_UE_INFORMATION_TAG = element.RX_UE_INFORMATION_TAG;
    new_element->RNTI = element.RNTI;
    new_element->CRCFLAG = element.CRCFLAG;

    // Add the new element to the list
    list_manager->elements[list_manager->count++] = new_element;

    return true;
}

// Function to remove an element from the list by its RNTI, returning a boolean indicating whether the operation was successful
bool nfapi_crc_indication_list_remove(NFAPI_CRC_INDICATION_LIST_MANAGER_T *list_manager, uint16_t RNTI) {
    // Find the index of the element to be removed
    size_t index = 0;

    for (size_t i = 0; i < list_manager->count; i++) {
        if (list_manager->elements[i].RNTI == RNTI) {
            index = i;
            break;
        }
    }

    // Check if the element was found in the list
    if (index >= list_manager->count) {
        return false;
    }

    // Remove the element from the list by swapping it with the last element and then freeing the memory
    NFAPI_CRC_INDICATION_PDU_T *last_element = &list_manager->elements[--list_manager->count];

    if (index < list_manager->count) {
        memcpy(list_manager->elements + index, last_element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    free(last_element);

    return true;
}

// Function to update the CRCFLAG of an element in the list by its RNTI, returning a boolean indicating whether the operation was successful
bool nfapi_crc_indication_list_update(NFAPI_CRC_INDICATION_LIST_MANAGER_T *list_manager, uint16_t RNTI, uint8_t CRCFLAG) {
    // Find the index of the element to be updated
    size_t index = 0;

    for (size_t i = 0; i < list_manager->count; i++) {
        if (list_manager->elements[i].RNTI == RNTI) {
            index = i;
            break;
        }
    }

    // Check if the element was found in the list
    if (index >= list_manager->count) {
        return false;
    }

    // Update the CRCFLAG of the element
    list_manager->elements[index].CRCFLAG = CRCFLAG;

    return true;
}
