// Probabilistic function to set CRCFLAG with 50% chance of being true
bool prob_set_crcflag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
  srand((unsigned int)time(NULL)); // Initialize the random seed
  int random_num = rand() % 2; // Generate a random number between 0 and 1
  if (random_num == 0) {
    return false; // Set CRCFLAG to false with probability 50%
  } else {
    return true; // Set CRCFLAG to true with probability 50%
  }
}

// Function to set the CRCFLAG for a given PDU
void set_crcflag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
  // Lock the array for thread-safe access
  pthread_mutex_lock(&crc_indication_lock);

  // Set the CRCFLAG based on the probabilistic function
  pdu->CRCFLAG = prob_set_crcflag(pdu);

  // Unlock the array
  pthread_mutex_unlock(&crc_indication_lock);
}

// Function to add a new PDU to the array
void add_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
  // Lock the array for thread-safe access
  pthread_mutex_lock(&crc_indication_lock);

  // Increase the size of the array by one
  crc_indication_pdu_array = realloc(crc_indication_pdu_array, (sizeof(NFAPI_CRC_INDICATION_PDU_T) * (num_crc_indication_pdus + 1)));

  // Set the new PDU to the array
  crc_indication_pdu_array[num_crc_indication_pdus] = *pdu;

  // Increment the number of PDUS in the array
  num_crc_indication_pdus++;

  // Unlock the array
  pthread_mutex_unlock(&crc_indication_lock);
}

// Function to iterate over the array and set the CRCFLAG for each PDU
void set_crcflags() {
  int i;

  // Lock the array for thread-safe access
  pthread_mutex_lock(&crc_indication_lock);

  // Iterate over the array and set the CRCFLAG for each PDU
  for (i = 0; i < num_crc_indication_pdus; i++) {
    set_crcflag(crc_indication_pdu_array[i]);
  }

  // Unlock the array
  pthread_mutex_unlock(&crc_indication_lock);
}
