void add_tcp_connection(char* ip_address, int port_number) {
    // Create a new structure to hold the connection information
    tcp_connection_info* new_connection = malloc(sizeof(tcp_connection_info));
    if (!new_connection) {
        perror("malloc");
        return;
    }

    new_connection->ip_address = strdup(ip_address);
    new_connection->port_number = port_number;
    new_connection->timestamp = time(NULL);

    // Lock the list to prevent concurrent access while modifying it
    pthread_mutex_lock(&list_lock);

    // Add the new connection to the end of the list
    if (list_head == NULL) {
        list_head = new_connection;
    } else {
        tcp_connection_info* current = list_head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_connection;
