    // Unlock the list to allow other threads to access it
    pthread_mutex_unlock(&list_lock);
}

// Function to remove a TCP connection from the list by IP address
void remove_tcp_connection(char* ip_address) {
    // Lock the list to prevent concurrent access while modifying it
    pthread_mutex_lock(&list_lock);

    // Find the connection with the specified IP address and remove it from the list
    tcp_connection_info* current = list_head;
