    tcp_connection_info* current = list_head;
    while (current != NULL) {
        if (difftime(time(NULL), current->timestamp) > GARBAGE_COLLECTION_DURATION) {
            // Remove the connection from the list
            remove_tcp_connection(current->ip_address);
        } else {
            current = current->next;
        }
    }

    // Unlock the list to allow other threads to access it
    pthread_mutex_unlock(&list_lock);
}

// Global variables for the linked list and garbage collection timer
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
tcp_connection_info* list_head = NULL;
time_t GARBAGE_COLLECTION_DURATION = 300; // 5 minutes
timer_t gc_timer;

int main() {
    // Create a new thread to perform garbage collection
    pthread_create(&gc_timer, NULL, (void*(*)(void*))gc, NULL);

    return 0;
}
