record* allocate_records(size_t count) {
    record* records = malloc(count * sizeof(record));
    if (!records) {
        perror("Memory allocation failed");
        return NULL;
    }
    for (int i = 0; i < count; i++) {
        records[i].key = generate_random(MIN_KEYS, MAX_KEYS);
        records[i].offset = generate_random(MIN_OFFSETS, MAX_OFFSETS);
    }
    return records;
}

// Define a function to validate the offsets and keys in the array
int validate_records(record* records, size_t count) {
    for (int i = 0; i < count - 1; i++) {
        if (records[i].key == records[i + 1].key) {
            printf("Key conflict detected: %d\n", records[i].key);
            return 1;
        }
    }
    for (int i = 0; i < count - 1; i++) {
        if (records[i].offset == records[i + 1].offset) {
            printf("Offset conflict detected: %ld\n", records[i].offset);
            return 1;
        }
    }
    return 0;
}

// Define a function to add new records to the array and update the memory usage
int add_records(record* records, size_t count) {
    pthread_mutex_lock(&lock);
    current_memory_usage += (count * sizeof(record));
    if (current_memory_usage > MAX_MEMORY_USAGE) {
        perror("Memory usage limit exceeded");
        return -1;
    }
    for (int i = 0; i < count; i++) {
        records[i].key = generate_random(MIN_KEYS, MAX_KEYS);
        records[i].offset = generate_random(MIN_OFFSETS, MAX_OFFSETS);
    }
    validate_records(records, count);
    pthread_mutex_unlock(&lock);
}

// Define a function to remove records from the array and update the memory usage
int remove_records(record* records, size_t count) {
    pthread_mutex_lock(&lock);
    current_memory_usage -= (count * sizeof(record));
    for (int i = 0; i < count; i++) {
        for (int j = 0; j < MAX_RECORDS - i; j++) {
            records[j].key = records[j + 1].key;
            records[j].offset = records[j + 1].offset;
        }
    }
    validate_records(records, count);
    pthread_mutex_unlock(&lock);
}

// Define a function to retrieve the number of records in the array
size_t get_record_count() {
    return MAX_RECORDS;
}

// Define a function to retrieve an individual record from the array by index
record* get_record(int index) {
    if (index < 0 || index >= MAX_RECORDS) {
        perror("Invalid record index");
        return NULL;
    }
    return &records[index];
}

// Define a function to retrieve all records in the array
record* get_all_records() {
    return records;
}
