std::vector<int> readIntegersFromFile(const std::string& filePath, size_t maxInts) {
  std::ifstream inFile(filePath);
  if (!inFile.is_open()) {
    throw std::runtime_error("Failed to open input file");
  }

  std::vector<int> integers;
  while (true) {
    int integer;
    inFile >> integer;
    if (inFile.eof()) break;
    integers.push_back(integer);
  }

  // Truncate the vector to maxInts elements if necessary
  if (integers.size() > maxInts) {
    integers.resize(maxInts);
  }

  return integers;
}

// Function to initialize CRC flags randomly
std::vector<NfapiCrcIndicationPduT> initCrcFlagsRandomly(const std::vector<int>& integers) {
  std::random_device rd;
  std::mt19937 gen(rd());
  std::uniform_int_distribution<> dis(0, 1);

  std::vector<NfapiCrcIndicationPduT> crcFlags(integers.size());
  for (size_t i = 0; i < integers.size(); ++i) {
    crcFlags[i].rnti = integers[i];
    crcFlags[i].crc_flag = dis(gen);
  }

  return crcFlags;
}

