typedef struct {
    PduBatch batches[MAX_PDU];
    size_t curr_batch;
    sem_t mutex;
} PduManager;

void init_pdu_manager(PduManager *mgr) {
    for (size_t i = 0; i < MAX_PDU; i++) {
        mgr->batches[i].pdus = NULL;
        mgr->batches[i].count = 0;
    }
    mgr->curr_batch = 0;
    sem_init(&mgr->mutex, 1, 1);
}

void add_pdu(PduManager *mgr, NFAPI_CRC_INDICATION_PDU_T pdu) {
    int rv = sem_wait(&mgr->mutex);
    if (rv < 0) {
        perror("sem_wait");
        return;
    }
    PduBatch *batch = &mgr->batches[mgr->curr_batch];
    size_t count = batch->count++;
    NFAPI_CRC_INDICATION_PDU_T *pdus = realloc(batch->pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (count + 1));
    if (!pdus) {
        perror("realloc");
        return;
    }
    batch->pdus = pdus;
    memcpy(&batch->pdus[count], &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    sem_post(&mgr->mutex);
}

