void allocate_crc_indication_pdu(unsigned int N, NFAPI_CRC_INDICATION_PDU_T **pdu) {
  // Check if the input is valid
  if (N == 0) {
    printf("Error: Invalid input. N must be greater than 0.\n");
    return;
  }

  // Allocate memory for the array of PDUs
  *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
  if (*pdu == NULL) {
    printf("Error: Failed to allocate memory for PDUs.\n");
    return;
  }

  // Initialize the array of PDUs
  for (unsigned int i = 0; i < N; i++) {
    (*pdu)[i].RX_UE_INFORMATION_TAG = rand() % 1000;
    (*pdu)[i].RNTI = rand() % 1000;
    (*pdu)[i].CRC_INDICATION_REL8_TAG = rand() % 2;
  }

  // Validate the integrity of each PDU
  for (unsigned int i = 0; i < N; i++) {
    if ((*pdu)[i].RX_UE_INFORMATION_TAG == (*pdu)[i + 1].RX_UE_INFORMATION_TAG) {
      printf("Error: Duplicate RX_UE_INFORMATION_TAG values found.\n");
      free(*pdu);
      return;
    }
    if ((*pdu)[i].RNTI == (*pdu)[i + 1].RNTI) {
      printf("Error: Duplicate RNTI values found.\n");
      free(*pdu);
      return;
    }
    if ((*pdu)[i].CRC_INDICATION_REL8_TAG == (*pdu)[i + 1].CRC_INDICATION_REL8_TAG) {
      printf("Error: Duplicate CRC_INDICATION_REL8_TAG values found.\n");
      free(*pdu);
      return;
    }
  }
}

