  int largest = pdu[0].RX_UE_INFORMATION_TAG;
  for (unsigned int i = 1; i < N; i++) {
    if (pdu[i].RX_UE_INFORMATION_TAG > largest) {
      largest = pdu[i].RX_UE_INFORMATION_TAG;
    }
  }

