/* Structure for holding NFAPI_CRC_INDICATION_PDU_T data */
struct nfas_crc_indication {
    long offset;
    int key;
    char buffer[NAS_METADATA_LEN];
};

/* List of NFAPI_CRC_INDICATION_PDU_T structures for managing resources */
struct nfas_crc_indication_list {
    struct nfas_crc_indication *data;
    size_t len;
};

static struct nfas_crc_indication_list crc_indications = {
    .data = NULL,
    .len = 0
};

/* Function for allocating and initializing a new NFAPI_CRC_INDICATION_PDU_T structure */
static struct nfas_crc_indication *nfas_crc_indication_new(void) {
    struct nfas_crc_indication *indication = malloc(sizeof(*indication));
    if (!indication) {
        printf("ERROR: Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T structure\n");
        return NULL;
    }
    indication->offset = 0;
    indication->key = 0;
    memset(indication->buffer, '\0', NAS_METADATA_LEN);
    return indication;
}

/* Function for updating a NFAPI_CRC_INDICATION_PDU_T structure */
static void nfas_crc_indication_update(struct nfas_crc_indication *indication, long offset, int key, char *buffer) {
    if (!indication || !offset || !key || !buffer) {
        printf("ERROR: Invalid arguments for updating NFAPI_CRC_INDICATION_PDU_T structure\n");
        return;
    }
    indication->offset = offset;
    indication->key = key;
    strncpy(indication->buffer, buffer, NAS_METADATA_LEN);
}

/* Function for freeing a NFAPI_CRC_INDICATION_PDU_T structure */
static void nfas_crc_indication_free(struct nfas_crc_indication *indication) {
    if (!indication) return;
    free(indication);
}

/* Function for adding a NFAPI_CRC_INDICATION_PDU_T structure to the list */
static void nfas_crc_indications_add(struct nfas_crc_indication *indication) {
    if (!indication) return;
    struct nfas_crc_indication_list *new_list = malloc(sizeof(*new_list));
    if (!new_list) {
        printf("ERROR: Failed to allocate memory for new NFAPI_CRC_INDICATION_PDU_T list\n");
        return;
    }
    new_list->data = malloc(sizeof(*indication) * (crc_indications.len + 1));
    if (!new_list->data) {
        printf("ERROR: Failed to allocate memory for new NFAPI_CRC_INDICATION_PDU_T list\n");
        free(new_list);
        return;
    }
    new_list->len = crc_indications.len + 1;
    memcpy(new_list->data, crc_indications.data, sizeof(*indication) * crc_indications.len);
    new_list->data[crc_indications.len] = *indication;
    free(crc_indications.data);
    crc_indications = *new_list;
}

/* Function for updating a NFAPI_CRC_INDICATION_PDU_T structure in the list */
static void nfas_crc_indications_update(struct nfas_crc_indication *indication) {
    if (!indication) return;
    for (size_t i = 0; i < crc_indications.len; ++i) {
        if (crc_indications.data[i].key == indication->key) {
            memcpy(&crc_indications.data[i], indication, sizeof(*indication));
            return;
        }
    }
}

/* Function for deleting a NFAPI_CRC_INDICATION_PDU_T structure from the list */
static void nfas_crc_indications_delete(int key) {
    if (!key) return;
    for (size_t i = 0; i < crc_indications.len; ++i) {
        if (crc_indications.data[i].key == key) {
            nfas_crc_indication_free(&crc_indications.data[i]);
            crc_indications.data[i] = crc_indications.data[crc_indications.len - 1];
            --crc_indications.len;
        }
    }
}

/* Function for handling incoming PUT requests */
static void handle_put(const char *path, const char *payload) {
    if (!path || !payload) return;
    struct nfas_crc_indication *indication = NULL;
    indication = nfas_crc_indication_new();
    if (!indication) {
        printf("ERROR: Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T structure\n");
        return;
    }
    char *ptr1 = NULL, *ptr2 = NULL;
    ptr1 = strchr(payload, '|');
    if (ptr1) {
        ++ptr1;
        ptr2 = strchr(ptr1, '|');
        if (ptr2) {
            long offset = 0;
            sscanf(ptr1, "%ld", &offset);
            int key = 0;
            sscanf(ptr2, "%d", &key);
            nfas_crc_indication_update(indication, offset, key, payload);
        } else {
            printf("ERROR: Invalid payload format for PUT request\n");
            nfas_crc_indication_free(indication);
            return;
        }
    } else {
        printf("ERROR: Invalid payload format for PUT request\n");
        nfas_crc_indication_free(indication);
        return;
    }
    nfas_crc_indications_add(indication);
}

/* Function for handling incoming DELETE requests */
static void handle_delete(const char *path) {
    if (!path) return;
    int key = 0;
    sscanf(path, "%d", &key);
    nfas_crc_indications_delete(key);
}

/* Function for handling incoming GET requests */
static void handle_get(const char *path) {
    if (!path) return;
    int key = 0;
    sscanf(path, "%d", &key);
    struct nfas_crc_indication *indication = NULL;
    for (size_t i = 0; i < crc_indications.len; ++i) {
        if (crc_indications.data[i].key == key) {
            indication = &crc_indications.data[i];
            break;
        }
    }
    if (!indication) return;
    printf("{\"offset\":%ld,\"key\":%d,\"buffer\":\"%s\"}\n",
           indication->offset, indication->key, indication->buffer);
}

int main(void) {
    struct http_server server = {0};
    server.port = 8080;
    while (1) {
        sleep(1);
        if (http_request(&server)) break;
        const char *method = NULL, *path = NULL, *payload = NULL;
        http_get_method(&method);
        http_get_path(&path);
        http_get_payload(&payload);
