    uint16_t rnti;
    uint16_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CRC_INDICATION_LIST {
    pthread_mutex_t lock;
    int size;
    int capacity;
    NFAPI_CRC_INDICATION_PDU_T* data;
} CRC_INDICATION_LIST_T;

void init_crc_indication_list(CRC_INDICATION_LIST_T* list) {
    list->lock = PTHREAD_MUTEX_INITIALIZER;
    list->size = 0;
    list->capacity = MAX_CRC_INDICATIONS;
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_CRC_INDICATIONS);
}

void add_crc_indication(CRC_INDICATION_LIST_T* list, uint32_t rx_ue_information_tag, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);
    while (list->size >= list->capacity) {
        // Resize the list if it's full
        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity * 2);
        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            // Handle memory allocation failure
            return;
        }
        list->data = new_data;
        list->capacity *= 2;
    }
    NFAPI_CRC_INDICATION_PDU_T* crc_indication = &list->data[list->size++];
    crc_indication->rx_ue_information_tag = rx_ue_information_tag;
    crc_indication->rnti = rnti;
    crc_indication->crc_indication_rel8_tag = (uint16_t)rand() % 2; // Randomly set CRCFLAG
    pthread_mutex_unlock(&list->lock);
}

void process_crc_indications(CRC_INDICATION_LIST_T* list, int num_threads) {
    pthread_t threads[MAX_CONCURRENT_THREADS];
    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, process_crc_indication, list)) {
            // Handle thread creation failure
            return;
        }
    }
    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void* process_crc_indication(void* arg) {
