// Structure to represent a node in the array
typedef struct Node {
    char* string;
    int priority;
} Node;

// Function to initialize an array of nodes with default values
void initNodes(Node** nodes, int numNodes) {
    // Allocate memory for the nodes and their strings
    *nodes = (Node*)malloc(sizeof(Node) * numNodes);
    char* tempStrings = (char*)malloc(sizeof(char) * 10);
    sprintf(tempStrings, "default");

    // Initialize each node with a random priority within the range [1, 10]
    for (int i = 0; i < numNodes; i++) {
        (*nodes)[i].priority = rand() % 10 + 1;
        (*nodes)[i].string = strdup(tempStrings);
    }

    // Free the temporary memory allocated for the strings
    free(tempStrings);
}

// Function to insert a new string and priority at a specified index
void insertNode(Node** nodes, int numNodes, int index, char* string, int priority) {
    // Check if the index is valid
    if (index < 0 || index >= numNodes) {
        return;
    }

    // Allocate memory for the new node
    Node* newNode = malloc(sizeof(Node));

    // Initialize the new node with the given string and priority
    newNode->string = strdup(string);
    newNode->priority = priority;

    // Insert the new node at the specified index in the array of nodes
    for (int i = numNodes - 1; i >= index; i--) {
        (*nodes)[i + 1] = (*nodes)[i];
    }
    (*nodes)[index] = newNode;
}

// Function to delete a node at a specified index
void deleteNode(Node** nodes, int numNodes, int index) {
    // Check if the index is valid
    if (index < 0 || index >= numNodes) {
        return;
    }

    // Free the memory allocated for the node being deleted
    free((*nodes)[index]->string);
    free((*nodes)[index]);

    // Shift all nodes after the specified index to fill the gap
    for (int i = index; i < numNodes - 1; i++) {
        (*nodes)[i] = (*nodes)[i + 1];
    }
}

// Function to resize the array of nodes when it is full
void resizeNodes(Node** nodes, int* numNodes) {
    // Allocate memory for a new array with twice the current size
    Node** newNodes = (Node**)malloc(sizeof(Node*) * (*numNodes) * 2);

    // Copy all nodes from the old array to the new one
    for (int i = 0; i < *numNodes; i++) {
        newNodes[i] = malloc(sizeof(Node));
        memcpy(newNodes[i], (*nodes)[i], sizeof(Node));
    }

    // Free the memory allocated for the old array and replace it with the new one
    free(*nodes);
    *nodes = newNodes;
    *numNodes = *numNodes * 2;
}

// Function to clean up the array of nodes when it is no longer needed
void cleanupNodes(Node** nodes, int numNodes) {
    // Free the memory allocated for each node and its string
    for (int i = 0; i < numNodes; i++) {
        free((*nodes)[i]->string);
        free((*nodes)[i]);
    }

    // Free the memory allocated for the array of nodes itself
    free(*nodes);
}
