// Define a cache eviction policy to manage memory usage when the number of packets exceeds a predefined threshold
void evictCache(TX_PACKET_INFO* packetList, int numPackets) {
    // Calculate the maximum number of packets that can be stored in the cache
    int maxNumPackets = 100;

    // Check if the current number of packets exceeds the maximum threshold
    if (numPackets > maxNumPackets) {
        // Evict the least recently used packet from the cache
        TX_PACKET_INFO* evictedPacket = &packetList[0];
        for (int i = 1; i < numPackets; i++) {
            if (evictedPacket->transmissionTime > packetList[i].transmissionTime) {
                evictedPacket = &packetList[i];
            }
        }
        // Free the memory used by the evicted packet
        free(evictedPacket);
    }
}

