            } else { // reallocation successful, update array and capacity
                array = newArray;
                capacity++;
            }
        }
    } else { // element already exists in the array, log error and continue processing
        pthread_mutex_unlock(&mutex);
        return -3;
    }
    array[index] = *element;
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to remove an element from the array
int removeElement(int RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&mutex);
    int index = 0;
    while (index < capacity && array[index].RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG) {
        index++;
    }
    if (index == capacity) { // element not found in the array, return failure
        pthread_mutex_unlock(&mutex);
        return -1;
    } else { // remove element from the array and update capacity
        NFAPI_CRC_INDICATION_PDU_T *newArray = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array, (capacity - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newArray) { // reallocation failed
            pthread_mutex_unlock(&mutex);
            return -2;
        } else { // reallocation successful, update array and capacity
            array = newArray;
            capacity--;
        }
    }
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to retrieve an element from the array by RX_UE_INFORMATION_TAG
NFAPI_CRC_INDICATION_PDU_T *getElement(int RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&mutex);
    int index = 0;
    while (index < capacity && array[index].RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG) {
        index++;
    }
    if (index == capacity) { // element not found in the array, return NULL
        pthread_mutex_unlock(&mutex);
        return NULL;
    } else { // return pointer to the found element
        NFAPI_CRC_INDICATION_PDU_T *element = &array[index];
        pthread_mutex_unlock(&mutex);
        return element;
    }
}

// Function to update an existing element in the array by RX_UE_INFORMATION_TAG
int updateElement(NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&mutex);
    int index = 0;
    while (index < capacity && array[index].RX_UE_INFORMATION_TAG != element->RX_UE_INFORMATION_TAG) {
        index++;
    }
    if (index == capacity) { // element not found in the array, return failure
        pthread_mutex_unlock(&mutex);
        return -1;
    } else { // update existing element with new values and return success
        array[index] = *element;
        pthread_mutex_unlock(&mutex);
        return 0;
    }
}

// Function to clear the entire array
void clearArray() {
    pthread_mutex_lock(&mutex);
    free(array);
    array = NULL;
    capacity = 0;
    pthread_mutex_unlock(&mutex);
}

// Function to log an operation and its outcome
void logOperation(int op, int result) {
    // Implement logging functionality here
}
