#define MAX_ELEMENTS 10000
#define RX_UE_INFORMATION_TAG 0x123456789abcdef
#define RNTI_REQUEST_DELAY 100 // in milliseconds
#define RNTI_RETRY_LIMIT 5
#define CRCFLAG_MIN 0x100000000
#define CRCFLAG_MAX 0xfffffffff
#define MEMORY_OVERFLOW_THRESHOLD 80 // in percentage

typedef struct NFAPI_CRC_INDICATION_PDU {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned long CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct DynamicArray {
    size_t capacity;
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T *elements;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray array;
pthread_mutex_t rnti_request_lock = PTHREAD_MUTEX_INITIALIZER;
unsigned int rnti_request_count = 0;
bool rnti_request_in_progress = false;

void init_array(size_t capacity) {
    array.capacity = capacity;
    array.size = 0;
    array.elements = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
    pthread_mutex_init(&array.mutex, NULL);
}

void destroy_array() {
    free(array.elements);
    pthread_mutex_destroy(&array.mutex);
}

bool is_full() {
    return array.size == array.capacity;
}

void add_element(unsigned long RX_UE_INFORMATION_TAG, unsigned int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T *new_element = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_element->RNTI = RNTI;
    unsigned long CRCFLAG = generate_CRCFLAG();
    new_element->CRCFLAG = CRCFLAG;

    pthread_mutex_lock(&array.mutex);
    if (!is_full()) {
        array.elements[array.size++] = *new_element;
    } else {
        printf("DynamicArray is full, cannot add more elements\n");
    }
    pthread_mutex_unlock(&array.mutex);
}

unsigned long generate_CRCFLAG() {
    return (rand() % CRCFLAG_MAX) + CRCFLAG_MIN;
}

void request_RNTI(size_t element_index) {
    NFAPI_CRC_INDICATION_PDU_T *element = &array.elements[element_index];
    unsigned int RNTI = element->RNTI;
    bool duplicate = false;

    pthread_mutex_lock(&rnti_request_lock);
    if (rnti_request_in_progress) {
        rnti_request_count++;
        printf("RNTI request already in progress, waiting...\n");
        while (rnti_request_in_progress && rnti_request_count < RNTI_RETRY_LIMIT) {
            usleep(RNTI_REQUEST_DELAY * 1000);
            printf(".");
        }
    } else {
        rnti_request_in_progress = true;
        rnti_request_count = 0;
    }
    pthread_mutex_unlock(&rnti_request_lock);

    if (rnti_request_count >= RNTI_RETRY_LIMIT) {
        printf("RNTI request failed after %d retries\n", RNTI_RETRY_LIMIT);
    } else {
        printf("Requesting RNTI for element %lu\n", element->RX_UE_INFORMATION_TAG);
    }
}

void validate_unique_RX_UE_INFORMATION_TAG() {
    size_t i;
    for (i = 0; i < array.size - 1; i++) {
        if (array.elements[i].RX_UE_INFORMATION_TAG == array.elements[i + 1].RX_UE_INFORMATION_TAG) {
            printf("Duplicate RX_UE_INFORMATION_TAG found at element %lu\n", array.elements[i].RX_UE_INFORMATION_TAG);
        }
    }
}

void adjust_capacity() {
    size_t new_capacity = array.size * 2;
    if (new_capacity > MAX_ELEMENTS) {
        printf("New capacity exceeds maximum allowed, cannot adjust\n");
        return;
    }
    NFAPI_CRC_INDICATION_PDU_T *new_elements = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    for (size_t i = 0; i < array.size; i++) {
        new_elements[i] = array.elements[i];
    }
    free(array.elements);
    array.elements = new_elements;
}

void monitor_memory() {
    size_t memory_used = (sizeof(NFAPI_CRC_INDICATION_PDU_T) * array.size) + sizeof(NFAPI_CRC_INDICATION_PDU_T*) + sizeof(size_t) * 2;
    printf("Memory used by DynamicArray: %lu bytes\n", memory_used);
}

void print_array() {
    for (size_t i = 0; i < array.size; i++) {
        NFAPI_CRC_INDICATION_PDU_T *element = &array.elements[i];
        printf("Element %lu: RX_UE_INFORMATION_TAG=%lu, RNTI=%u, CRCFLAG=%lu\n", element->RX_UE_INFORMATION_TAG, element->RX_UE_INFORMATION_TAG, element->RNTI, element->CRCFLAG);
    }
}

int main() {
    init_array(100);
    add_element(0, 0);
    add_element(1, 1);
    add_element(2, 2);
    print_array();
    request_RNTI(0);
    print_array();
    monitor_memory();
}
