struct MEASUREMENT_REPORT_T {
    uint32_t timestamp;
    uint16_t cellId;
    float signalStrength;
};

// Function to initialize the UE context list with M initial MeasurementReports
void initUeContextList(int numUes, int numMeasReports) {
    // Allocate memory for the UE context list and measurement reports
    struct UE_CONTEXT_T *ueContextList = malloc(numUes * sizeof(struct UE_CONTEXT_T));
    struct MEASUREMENT_REPORT_T *measReports = malloc(numMeasReports * sizeof(struct MEASUREMENT_REPORT_T));

    // Initialize the UE context list and measurement reports
    for (int i = 0; i < numUes; i++) {
        ueContextList[i].ueRnti = i + 1;
        ueContextList[i].validRxUeInfoTag = 1;
        ueContextList[i].signalStrength = -100.0;
        for (int j = 0; j < numMeasReports; j++) {
            measReports[j].timestamp = i + j;
            measReports[j].cellId = i * 10 + j;
            measReports[j].signalStrength = -120.0 + (float)i / 10.0;
        }
        ueContextList[i].measReports = measReports;
    }
}

// Function to update the signal strength for a specific RNTI without altering other data associated with that context
void updateSignalStrength(int rnti, float newSignalStrength) {
    // Find the UE context with the specified RNTI
    struct UE_CONTEXT_T *ueContext = findUeContextByRnti(rnti);
    if (ueContext != NULL) {
        ueContext->signalStrength = newSignalStrength;
    }
}

// Function to efficiently update the signal strength for a specific RNTI without altering other data associated with that context
void efficientUpdateSignalStrength(int rnti, float newSignalStrength) {
    // Find the UE context with the specified RNTI
    struct UE_CONTEXT_T *ueContext = findUeContextByRnti(rnti);
    if (ueContext != NULL) {
        ueContext->signalStrength = newSignalStrength;
    }
}

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void generateCrcIndicationList(int numUes, int numMeasReports) {
    // Allocate memory for the CRC indication list
    struct NFAPI_CRC_INDICATION_PDU_T *crcIndicationList = malloc(numUes * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));

    // Initialize the CRC indication list
    for (int i = 0; i < numUes; i++) {
        crcIndicationList[i].rnti = i + 1;
        crcIndicationList[i].crcFlag = 1;
    }
}

// Function to find the UE context with a specified RNTI
struct UE_CONTEXT_T *findUeContextByRnti(int rnti) {
    for (int i = 0; i < numUes; i++) {
        if (ueContextList[i].ueRnti == rnti) {
            return &ueContextList[i];
        }
    }
    return NULL;
}

