    for (int i = 0; i < numUes; i++) {
        ueContextList[i].signalStrength = -100.0;
    }
}

// Function to calculate and update the signal strength values in the measurement reports
void updateSignalStrengthValues() {
    for (int i = 0; i < numUes; i++) {
        float sum = 0.0;
        int numReports = 0;
        for (int j = 0; j < numMeasReports; j++) {
            if (ueContextList[i].measReports[j].signalStrength > -120.0) {
                sum += ueContextList[i].measReports[j].signalStrength;
                numReports++;
            }
        }
        ueContextList[i].signalStrength = sum / (float)numReports;
    }
}

// Function to generate a random RNTI for each UE context
void generateRnti() {
    for (int i = 0; i < numUes; i++) {
        ueContextList[i].ueRnti = rand() % 100 + 1;
    }
}

// Function to clear the CRC flag values in the CRC indication list
void clearCrcFlagValues() {
    for (int i = 0; i < numUes; i++) {
        crcIndicationList[i].crcFlag = 0;
    }
}

// Function to calculate and update the CRC flag values in the CRC indication list
void updateCrcFlagValues() {
    for (int i = 0; i < numUes; i++) {
        crcIndicationList[i].crcFlag = rand() % 2;
    }
}
