// Define the structure for storing custom network events
typedef struct {
  long timestamp;
  int event_type;
  void* data;
} CustomEvent;

// Define a dynamic array for storing the custom events
typedef struct {
  CustomEvent** events;
  size_t capacity;
  size_t count;
  pthread_mutex_t mutex;
} EventArray;

// Initialize the dynamic array with a default capacity
void init_event_array(EventArray* arr) {
  arr->events = NULL;
  arr->capacity = 1024; // default capacity for the dynamic array
  arr->count = 0;
  pthread_mutex_init(&arr->mutex, NULL);
}

// Free the memory allocated for the dynamic array
void free_event_array(EventArray* arr) {
  if (arr->events != NULL) {
    free(arr->events);
  }
  pthread_mutex_destroy(&arr->mutex);
}

// Insert a new event into the dynamic array, growing the capacity if necessary
void insert_event(EventArray* arr, CustomEvent event) {
  // Acquire lock to prevent concurrent access from multiple threads
  pthread_mutex_lock(&arr->mutex);

  // Check if the dynamic array needs to be resized
  if (arr->count >= arr->capacity) {
    // Grow the capacity by a factor of 2
    arr->capacity *= 2;
    CustomEvent** new_events = realloc(arr->events, sizeof(CustomEvent*) * arr->capacity);
    if (new_events == NULL) {
      perror("realloc");
      exit(1);
    }
    arr->events = new_events;
  }

  // Insert the new event into the dynamic array
  arr->events[arr->count++] = malloc(sizeof(CustomEvent));
  memcpy(arr->events[arr->count - 1], &event, sizeof(CustomEvent));

  // Release lock to allow other threads to access the dynamic array
  pthread_mutex_unlock(&arr->mutex);
}

// Delete an event from the dynamic array by its index
void delete_event(EventArray* arr, size_t index) {
  // Acquire lock to prevent concurrent access from multiple threads
  pthread_mutex_lock(&arr->mutex);

  // Check if the specified index is valid
  if (index >= arr->count) {
    perror("Index out of bounds");
    exit(1);
  }

  // Free the memory allocated for the event
  free(arr->events[index]);

  // Shift all events after the specified index to fill the gap
  for (size_t i = index; i < arr->count - 1; ++i) {
    memcpy(arr->events[i], arr->events[i + 1], sizeof(CustomEvent));
  }

  // Decrement the count of events by 1
  --arr->count;

  // Release lock to allow other threads to access the dynamic array
  pthread_mutex_unlock(&arr->mutex);
}

// Iterate over all events in the dynamic array, applying a user-defined function
void iterate_events(EventArray* arr, void (*fn)(CustomEvent)) {
  // Acquire lock to prevent concurrent access from multiple threads
  pthread_mutex_lock(&arr->mutex);

  for (size_t i = 0; i < arr->count; ++i) {
    fn(arr->events[i]);
  }

  // Release lock to allow other threads to access the dynamic array
  pthread_mutex_unlock(&arr->mutex);
}
