// Function to add a new element to the list, with a randomly set CRCFLAG and uniquely identified by an ID generated from a combination of the current timestamp and a hash of the RNTI
void nfapi_crc_indication_list_add(nfapi_crc_indication_list_t* list, uint16_t rx_ue_information_tag, uint32_t rnti) {
    // Acquire the lock to prevent concurrent access from multiple threads
    pthread_mutex_lock(&list_lock);

    // Generate a unique ID for the new element using a combination of the current timestamp and a hash of the RNTI
    uint64_t id = ((uint64_t)time(NULL)) << 32 | (uint32_t)hash(rnti);

