            return;
        }
    } else {
        // If there is not enough memory, log a warning and return
        printf("Not enough memory available to add the new element\n");
        pthread_mutex_unlock(&list_lock);
        return;
    }

    // Release the lock to allow concurrent access from multiple threads
    pthread_mutex_unlock(&list_lock);
}

// Function to remove an element from the list by ID
void nfapi_crc_indication_list_remove(nfapi_crc_indication_list_t* list, uint64_t id) {
    // Acquire the lock to prevent concurrent access from multiple threads
    pthread_mutex_lock(&list_lock);

    // Iterate through the list to find the element with the matching ID
    for (size_t i = 0; i < list->size; i++) {
        if (list->data[i]->id == id) {
            // If the element is found, free its memory and remove it from the list
            free(list->data[i]);
            list->data[i] = NULL;
            list->size--;
            break;
        }
    }

    // Release the lock to allow concurrent access from multiple threads
    pthread_mutex_unlock(&list_lock);
}

// Function to release all allocated resources when the list is no longer needed
void nfapi_crc_indication_list_cleanup(nfapi_crc_indication_list_t* list) {
    // Acquire the lock to prevent concurrent access from multiple threads
    pthread_mutex_lock(&list_lock);

    // Iterate through the list and free each element's memory
    for (size_t i = 0; i < list->size; i++) {
        free(list->data[i]);
    }

    // Reset the list size to 0 and release the lock
    list->size = 0;
    pthread_mutex_unlock(&list_lock);
}
