void free_data(struct DataStruct *data) {
    // Free the offsets array
    if (data->offsets != NULL) {
        free(data->offsets);
        data->offsets = NULL;
    }

    // Free the keys array
    if (data->keys != NULL) {
        free(data->keys);
        data->keys = NULL;
    }

    // Free the records array
    if (data->records != NULL) {
        free(data->records);
        data->records = NULL;
    }

    // Free the data structure
    if (data != NULL) {
        free(data);
        data = NULL;
    }
}
