int construct_nfa(FILE *file, int max_size) {
    // Read integers from the file into a dynamically allocated array
    int *integers = malloc(max_size * sizeof(int));
    if (!integers) {
        return NULL;
    }
    for (int i = 0; i < max_size; i++) {
        integers[i] = fgetc(file);
        if (feof(file)) {
            break;
        }
    }

    // Create a list of NFAPI_CRC_INDICATION_PDU_T structures
    struct nfapi_crc_indication_pdu *nfa_list = malloc(max_size * sizeof(struct nfapi_crc_indication_pdu));
    if (!nfa_list) {
        free(integers);
        return NULL;
    }

    // Populate the list with valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG values
    for (int i = 0; i < max_size; i++) {
        nfa_list[i].rx_ue_information.tl.tag = NFAPI_RX_UE_INFORMATION_TAG;
        nfa_list[i].rx_ue_information.rnti = integers[i];
        nfa_list[i].crc_indication_rel8.tl.tag = NFAPI_CRC_INDICATION_REL8_TAG;
        nfa_list[i].crc_indication_rel8.crc_flag = (uint8_t)rand();
    }

    // Construct and return the list of states that the FSA reaches after processing all integers
    struct fsa_state *states = malloc(max_size * sizeof(struct fsa_state));
    if (!states) {
        free(nfa_list);
        free(integers);
        return NULL;
    }
    int num_states = 0;
    for (int i = 0; i < max_size; i++) {
        struct fsa_state *state = malloc(sizeof(struct fsa_state));
        if (!state) {
            free(states);
            break;
        }
        state->value = integers[i];
        state->visited = false;
        states[num_states++] = state;
    }

    // Traverse the FSA using a combination of depth-first and breadth-first search strategies
    for (int i = 0; i < max_size; i++) {
        struct fsa_state *curr_state = states[i];
        if (!curr_state) {
            continue;
        }
        curr_state->visited = true;
        int next_states[2];
        for (int j = 0; j < 2; j++) {
            next_states[j] = fsa_transition(curr_state, nfa_list[i]);
            if (next_states[j] != -1) {
                break;
            }
        }
        if (next_states[0] == -1 && next_states[1] == -1) {
            continue;
        } else if (next_states[0] != -1) {
            curr_state->next = states[next_states[0]];
        } else if (next_states[1] != -1) {
