// Function to initialize and populate the rach_requests array
NFAPI_RACH_REQUEST_PDU_T *nfapi_rach_request_init(uint16_t num_elements) {
    // Check if the number of elements is valid
    if (num_elements > 1024) {
        return NULL;
    }

    // Lock the rach_lock to prevent concurrent access
    pthread_mutex_lock(&rach_lock);

    // Allocate memory for the array of RACH requests
    if (rach_requests == NULL) {
        rach_requests = malloc(sizeof(NFAPI_RACH_REQUEST_PDU_T) * num_elements);
    } else {
        NFAPI_RACH_REQUEST_PDU_T *new_requests = realloc(rach_requests, sizeof(NFAPI_RACH_REQUEST_PDU_T) * num_elements);
        if (new_requests == NULL) {
            // Reallocation failed, return NULL
            pthread_mutex_unlock(&rach_lock);
            return NULL;
        } else {
            rach_requests = new_requests;
        }
    }

    // Initialize and populate the RACH requests
    for (uint16_t i = 0; i < num_elements; i++) {
        NFAPI_RACH_REQUEST_PDU_T *request = &rach_requests[i];
        request->sequence_number = i + 1;
        request->rnti = rand(); // Randomly generate RNTI for each request
        request->crc_flag = (rand() % 2) == 0; // Randomly set CRCFLAG for each request
