    pthread_mutex_unlock(&rach_lock);

    return rach_requests;
}

// Function to release the memory allocated by nfapi_rach_request_init()
void nfapi_rach_request_release(NFAPI_RACH_REQUEST_PDU_T *rach_requests) {
