// Define the linked list node structure
typedef struct LIST_NODE {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct LIST_NODE *next;
} LIST_NODE;

// Function to manage a dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
int32_t manage_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T *data, int32_t max_elements) {
    // Check if the list is full
    if (max_elements <= 0) {
        return -1; // Return an error code indicating that the list is full
    }

    // Allocate memory for the new structure
    NFAPI_CRC_INDICATION_PDU_T *new_data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_data == NULL) {
        return -2; // Return an error code indicating that memory allocation failed
    }

    // Copy the data into the new structure
    memcpy(new_data, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Add the new structure to the list
    LIST_NODE *list = malloc(sizeof(LIST_NODE));
    if (list == NULL) {
        free(new_data);
        return -3; // Return an error code indicating that memory allocation failed
    }
    list->data = new_data;
    list->next = NULL;

    // Iterate over the list and append the new structure to the end of it
    LIST_NODE *node = list;
    while (node->next != NULL) {
        node = node->next;
    }
    node->next = list;

    return 0; // Return a success code indicating that the element was added to the list
}

// Function to iterate over the linked list and print out details of each element for debugging purposes
void print_crc_indication_list() {
    LIST_NODE *node = head;
    while (node != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %u\n", node->data->rx_ue_information_tag, node->data->rnti);
        node = node->next;
    }
}

// Function to clean up the linked list and deallocate memory for each structure
void cleanup_crc_indication_list() {
    LIST_NODE *node = head;
    while (node != NULL) {
        free(node->data);
        LIST_NODE *next = node->next;
        free(node);
        node = next;
    }
}
