// Define the structure for the LTE_RRC_CUCCH_SCH_CONFIG_SRB0_T
typedef struct {
    uint16_t SRB0_ID; // Unique ID for each configuration
    uint8_t PUCCH资源配置; // PUCCH resource configuration
    CUCCH_SCH_CONFIG config; // Configuration parameters for the CUCCH scheduler
} LTE_RRC_CUCCH_SCH_CONFIG_SRB0_T;

// Define a dynamic array to store the list of configurations
LTE_RRC_CUCCH_SCH_CONFIG_SRB0_T *configs = NULL;
size_t configs_len = 0; // Current length of the list
size_t configs_cap = 0; // Maximum capacity of the list

// Function to add a new configuration to the list
void add_configuration(uint16_t SRB0_ID, uint8_t PUCCH资源配置, CUCCH_SCH_CONFIG config) {
    if (SRB0_ID == 0) { // Check for duplicate ID
        return;
    }

    // If the list is full, double its capacity
    if (configs_len >= configs_cap) {
        configs_cap *= 2;
        configs = realloc(configs, sizeof(*configs) * configs_cap);
    }

    // Add the new configuration to the list
    configs[configs_len].SRB0_ID = SRB0_ID;
    configs[configs_len].PUCCH资源配置 = PUCCH资源配置;
    memcpy(&(configs[configs_len].config), &config, sizeof(CUCCH_SCH_CONFIG));
    ++configs_len;
}

// Function to check if an ID is already in use in the list
bool is_id_in_use(uint16_t SRB0_ID) {
    for (size_t i = 0; i < configs_len; ++i) {
        if (configs[i].SRB0_ID == SRB0_ID) {
            return true;
        }
    }
    return false;
}

// Function to retrieve the configuration for a given ID
CUCCH_SCH_CONFIG *get_configuration(uint16_t SRB0_ID) {
    for (size_t i = 0; i < configs_len; ++i) {
        if (configs[i].SRB0_ID == SRB0_ID) {
            return &(configs[i].config);
        }
    }
    // If no configuration is found, return NULL
    return NULL;
}

// Function to delete a configuration from the list
void delete_configuration(uint16_t SRB0_ID) {
    for (size_t i = 0; i < configs_len; ++i) {
        if (configs[i].SRB0_ID == SRB0_ID) {
            // Shift all subsequent configurations to the left
            memmove(&(configs[i]), &(configs[i + 1]), sizeof(*configs) * (configs_len - i - 1));
            --configs_len;
            break;
        }
    }
}
