#define NFAPI_CRC_INDICATION_PDU_T struct { \
    uint16_t RNTI; \
    int32_t RX_UE_INFORMATION_TAG; \
    int32_t CRC_INDICATION_REL8_TAG; \
    bool CRCFLAG; \
}

void allocate_and_populate_array(int N, struct NFAPI_CRC_INDICATION_PDU_T* arr) {
    // Initialize the array with unique RNTIs and valid RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG values
    for (int i = 0; i < N; i++) {
        struct NFAPI_CRC_INDICATION_PDU_T* pdu = &arr[i];
        pdu->RNTI = i + 1; // Unique RNTIs start from 1
        pdu->RX_UE_INFORMATION_TAG = rand() % 100; // Generate random valid values for RX_UE_INFORMATION_TAG
        pdu->CRC_INDICATION_REL8_TAG = rand() % 100; // Generate random valid values for CRC_INDICATION_REL8_TAG
        pdu->CRCFLAG = (rand() % 2) == 0; // Set CRCFLAG to true or false randomly
    }
}

int main(void) {
    int N = 1000000; // Large dataset size
    struct NFAPI_CRC_INDICATION_PDU_T* arr = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T) * N);
    if (arr == NULL) {
        perror("malloc");
        return 1;
    }
    allocate_and_populate_array(N, arr);

    // Handle duplicate RNTIs and ensure robust cleanup of resources allocated during execution
    int num_duplicates = 0;
    for (int i = 0; i < N - 1; i++) {
        for (int j = i + 1; j < N; j++) {
            if (arr[i].RNTI == arr[j].RNTI) {
                num_duplicates++;
            }
        }
    }
    if (num_duplicates > 0) {
        printf("Duplicate RNTIs found: %d\n", num_duplicates);
        // Clean up duplicate RNTIs and free memory
        for (int i = 0; i < N - 1; i++) {
            if (arr[i].RNTI == arr[j].RNTI) {
                struct NFAPI_CRC_INDICATION_PDU_T tmp = arr[i];
                arr[i] = arr[N - 1];
                arr[N - 1] = tmp;
            }
        }
    }

    // Handle large datasets efficiently, managing memory allocation and deallocation to prevent excessive resource consumption or performance degradation
    int thread_count = 8; // Adjust as per system resources
    struct NFAPI_CRC_INDICATION_PDU_T* arr_threaded[thread_count];
    for (int i = 0; i < thread_count; i++) {
        arr_threaded[i] = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T) * ceil((N - num_duplicates) / thread_count));
    }
    for (int i = 0; i < thread_count; i++) {
        int start = i * ceil((N - num_duplicates) / thread_count);
        int end = min(start + ceil((N - num_duplicates) / thread_count), N);
        for (int j = start; j < end; j++) {
            arr_threaded[i][j - start] = arr[j]; // Shift duplicate RNTIs to the end of the array
        }
    }
    for (int i = 0; i < thread_count; i++) {
        free(arr);
    }
}
```
