// Define the MAC_PDCP_SN_RANGE_T structure
typedef struct {
    uint32_t pdcp_sn;
    uint32_t pdcp_sn_range;
} MAC_PDCP_SN_RANGE_T;

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    uint8_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to manage the dynamic array of MAC_PDCP_SN_RANGE_T structures
void manage_mac_pdcp_sn_range_array(MAC_PDCP_SN_RANGE_T **array, size_t initial_capacity) {
    // Allocate memory for the array
    *array = (MAC_PDCP_SN_RANGE_T *)malloc(initial_capacity * sizeof(MAC_PDCP_SN_RANGE_T));

    if (*array == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for the MAC PDCP SN range array\n");
        return;
    }

    // Initialize the array with sequential PDCP SNs starting from 1
    size_t i;
    for (i = 0; i < initial_capacity; i++) {
        (*array)[i].pdcp_sn = i + 1;
        (*array)[i].pdcp_sn_range = 0;
    }
}

// Define the function to calculate SN ranges based on a configured increment value
void calculate_sn_ranges(MAC_PDCP_SN_RANGE_T *array, size_t array_size, uint32_t increment) {
    // Calculate the SN ranges for each element in the array
    size_t i;
    for (i = 0; i < array_size; i++) {
        if (i > 0 && array[i - 1].pdcp_sn + increment == array[i].pdcp_sn) {
            // If the current PDCP SN is equal to the previous PDCP SN plus the configured increment, update the SN range
            array[i - 1].pdcp_sn_range++;
        } else if (i > 0 && array[i - 1].pdcp_sn + increment != array[i].pdcp_sn) {
            // If the current PDCP SN is not equal to the previous PDCP SN plus the configured increment, update the SN range and reset the previous element's SN range to 0
            array[i - 1].pdcp_sn_range = 0;
            array[i].pdcp_sn_range++;
        } else {
            // If this is the first element in the array, update its SN range to 1
            array[i].pdcp_sn_range = 1;
        }
    }
}

// Define the function to resize the dynamic array of MAC_PDCP_SN_RANGE_T structures if the initial capacity is exceeded
void resize_mac_pdcp_sn_range_array(MAC_PDCP_SN_RANGE_T **array, size_t *capacity) {
    // Double the current capacity and reallocate memory for the array
    *capacity *= 2;
    MAC_PDCP_SN_RANGE_T *new_array = (MAC_PDCP_SN_RANGE_T *)realloc(*array, *capacity * sizeof(MAC_PDCP_SN_RANGE_T));

    if (new_array == NULL) {
        fprintf(stderr, "Error: Failed to resize the MAC PDCP SN range array\n");
        return;
    }

    // Update the pointer to point to the new memory block and free the old memory block
    *array = new_array;
    free(*array);
}

