// Define the data structure for the list of TX_DATA_FRAME structures
typedef struct {
    TX_DATA_FRAME *frames;
    size_t size;
} TX_DATA_FRAME_LIST;

// Define the function to manage the dynamic list of TX_DATA_FRAME structures
void manage_tx_data_frame_list(TX_DATA_FRAME_LIST *list) {
    // Get the current time in seconds
    double timestamp = get_timestamp();

    // Check if there are any frames to be transmitted
    if (list->size > 0) {
        // Loop through each frame and transmit it
        for (size_t i = 0; i < list->size; i++) {
            TX_DATA_FRAME *frame = &(list->frames[i]);

            // Transmit the frame using the MAC and PHY protocols
            transmit_frame(frame);
        }

        // Clear the list of transmitted frames
        clear_tx_data_frame_list(list);
    }

    // Sleep for a short period of time to prevent overloading the CPU
    usleep(100);
}

// Define the function to transmit a single TX_DATA_FRAME structure using the MAC and PHY protocols
void transmit_frame(TX_DATA_FRAME *frame) {
    // Get the current time in seconds
    double timestamp = get_timestamp();

    // Transmit the frame using the MAC and PHY protocols
    mac_transmit_frame(frame);
    phy_transmit_frame(frame);
}

// Define the function to clear the list of transmitted frames
void clear_tx_data_frame_list(TX_DATA_FRAME_LIST *list) {
    // Free the memory allocated for the list of frames
    free(list->frames);

    // Reset the size of the list to 0
    list->size = 0;
}

// Define the function to get the current time in seconds
double get_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000;
}
