#include <arpa/inet.h>

// Structure to hold network interface configuration settings
struct NetworkInterfaceConfig {
    char *interfaceName; // Name of the network interface (e.g., "eth0")
    struct in_addr ipAddress; // IP address of the interface
    struct in_addr subnetMask; // Subnet mask of the interface
    struct in_addr gateway; // Gateway IP address for the interface
    struct in_addr dnsServers[4]; // DNS server IP addresses (up to 4)
    int mtu; // MTU value for the interface
    int linkSpeed; // Link speed in megabits per second (Mbps)
};

// Function to initialize and manage network interface configuration settings
void initNetworkInterfaceConfig(struct NetworkInterfaceConfig *config, char *interfaceName) {
    // Validate input parameters
    if (!config || !interfaceName) {
        printf("Invalid input parameters\n");
        return;
    }

    // Initialize struct members with default values
    config->interfaceName = interfaceName;
    config->ipAddress.s_addr = inet_addr("127.0.0.1");
    config->subnetMask.s_addr = inet_addr("255.255.255.0");
    config->gateway.s_addr = inet_addr("127.0.0.1");
    config->dnsServers[0].s_addr = inet_addr("8.8.8.8");
    config->dnsServers[1].s_addr = inet_addr("8.8.4.4");
    config->mtu = 1500;
    config->linkSpeed = 100;
}

// Function to load network interface configuration settings from a file
void loadNetworkInterfaceConfig(struct NetworkInterfaceConfig *config, char *fileName) {
    // Validate input parameters
    if (!config || !fileName) {
        printf("Invalid input parameters\n");
        return;
    }

    // Open the configuration file and parse it line by line
    FILE *file = fopen(fileName, "r");
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Parse the line and update the struct members accordingly
        if (strncmp(line, "IP_ADDRESS", 10) == 0) {
            config->ipAddress.s_addr = inet_addr(line + 11);
        } else if (strncmp(line, "SUBNET_MASK", 12) == 0) {
            config->subnetMask.s_addr = inet_addr(line + 13);
        } else if (strncmp(line, "GATEWAY", 7) == 0) {
            config->gateway.s_addr = inet_addr(line + 8);
        } else if (strncmp(line, "DNS_SERVERS", 12) == 0) {
            int i;
            for (i = 0; i < 4; i++) {
                char *token = strtok(line + 13, ",");
                if (token != NULL) {
                    config->dnsServers[i].s_addr = inet_addr(token);
                } else {
                    break;
                }
            }
        } else if (strncmp(line, "MTU", 3) == 0) {
            config->mtu = atoi(line + 4);
        } else if (strncmp(line, "LINK_SPEED", 10) == 0) {
            config->linkSpeed = atoi(line + 11);
        }
    }
    fclose(file);
}

// Function to save network interface configuration settings to a file
void saveNetworkInterfaceConfig(struct NetworkInterfaceConfig *config, char *fileName) {
    // Validate input parameters
    if (!config || !fileName) {
        printf("Invalid input parameters\n");
        return;
    }

    // Open the configuration file and write the struct members to it
    FILE *file = fopen(fileName, "w");
    fprintf(file, "IP_ADDRESS %s\n", inet_ntoa(config->ipAddress));
    fprintf(file, "SUBNET_MASK %s\n", inet_ntoa(config->subnetMask));
    fprintf(file, "GATEWAY %s\n", inet_ntoa(config->gateway));
    int i;
    for (i = 0; i < 4; i++) {
        if (config->dnsServers[i].s_addr != 0) {
            fprintf(file, "DNS_SERVERS %s\n", inet_ntoa(config->dnsServers[i]));
        }
    }
    fprintf(file, "MTU %d\n", config->mtu);
    fprintf(file, "LINK_SPEED %d\n", config->linkSpeed);
    fclose(file);
}

// Function to handle parsing errors gracefully
void parseErrorHandler(struct NetworkInterfaceConfig *config) {
    // Print an error message and reset the struct members to default values
    printf("Parsing error in network interface configuration\n");
    config->interfaceName = NULL;
    config->ipAddress.s_addr = inet_addr("127.0.0.1");
    config->subnetMask.s_addr = inet_addr("255.255.255.0");
    config->gateway.s_addr = inet_addr("127.0.0.1");
    config->dnsServers[0].s_addr = inet_addr("8.8.8.8");
    config->dnsServers[1].s_addr = inet_addr("8.8.4.4");
    config->mtu = 1500;
    config->linkSpeed = 100;
}
