    // Update the list structure with the new array and size
    requests->requests = new_requests;
    requests->num_requests = new_size;
}

// Function to serialize a list of NFAPI_RRC_CCO_REQUEST structures to a file
void serialize_nfapi_rrc_cco_requests(nfapi_rrc_cco_request_list_t* requests, FILE* file) {
    // Write the number of requests to the file
    int num_requests = requests->num_requests;
    fwrite(&num_requests, sizeof(int), 1, file);

    // Write each request to the file
    for (int i = 0; i < num_requests; i++) {
        nfapi_rrc_cco_request_t* request = requests->requests[i];
        uint32_t ue_id = request->ue_id;
        fwrite(&ue_id, sizeof(uint32_t), 1, file);
        int freq_bands[MAX_FREQ_BANDS] = {0};
        memcpy(freq_bands, request->freq_bands, sizeof(int)*MAX_FREQ_BANDS);
        fwrite(freq_bands, sizeof(int), MAX_FREQ_BANDS, file);
        uint64_t timestamp = request->timestamp;
        fwrite(&timestamp, sizeof(uint64_t), 1, file);
        int status_flags = request->status_flags;
        fwrite(&status_flags, sizeof(int), 1, file);
    }
}

// Function to deserialize a list of NFAPI_RRC_CCO_REQUEST structures from a file
void deserialize_nfapi_rrc_cco_requests(FILE* file, nfapi_rrc_cco_request_list_t* requests) {
    // Read the number of requests from the file
    int num_requests;
    fread(&num_requests, sizeof(int), 1, file);

    // Allocate memory for a new array of requests
    nfapi_rrc_cco_request_t** new_requests = malloc(sizeof(nfapi_rrc_cco_request_t*)*num_requests);
    if (new_requests == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Read each request from the file and allocate memory for it
    for (int i = 0; i < num_requests; i++) {
        uint32_t ue_id;
        fread(&ue_id, sizeof(uint32_t), 1, file);
        nfapi_rrc_cco_request_t* request = malloc(sizeof(nfapi_rrc_cco_request_t));
        if (request == NULL) {
            printf("Memory allocation failed\n");
            return;
        }
        request->ue_id = ue_id;
        int freq_bands[MAX_FREQ_BANDS] = {0};
        fread(freq_bands, sizeof(int), MAX_FREQ_BANDS, file);
        memcpy(request->freq_bands, freq_bands, sizeof(int)*MAX_FREQ_BANDS);
        uint64_t timestamp;
        fread(&timestamp, sizeof(uint64_t), 1, file);
        request->timestamp = timestamp;
        int status_flags;
        fread(&status_flags, sizeof(int), 1, file);
        request->status_flags = status_flags;
        new_requests[i] = request;
    }

    // Update the list structure with the new array and size
    requests->requests = new_requests;
    requests->num_requests = num_requests;
}

// Function to print a list of NFAPI_RRC_CCO_REQUEST structures
void print_nfapi_rrc_cco_requests(nfapi_rrc_cco_request_list_t* requests) {
    // Print each request in the list
    for (int i = 0; i < requests->num_requests; i++) {
        nfapi_rrc_cco_request_t* request = requests->requests[i];
        printf("UE ID: %u\n", request->ue_id);
