    if (!list) {
        printf("Error: failed to allocate memory for the list\n");
        return NULL;
    }
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)calloc(MAX_LIST_SIZE, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        printf("Error: failed to allocate memory for the list data\n");
        free(list);
        return NULL;
    }
    list->count = 0;
    return list;
}

bool insertIntoList(List *list, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI, uint8_t CRC_INDICATION_REL8_TAG) {
    if (list->count >= MAX_LIST_SIZE) {
        // list overflow
        printf("Error: list overflow\n");
        return false;
    }
    NFAPI_CRC_INDICATION_PDU_T *pdu = &(list->data[list->count]);
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    pdu->CRCFLAG = CRCFLAG;
    list->count++;
    return true;
}

bool removeFromList(List *list, uint16_t RNTI) {
    if (list->count == 0) {
        // list is empty
        printf("Error: list is empty\n");
        return false;
    }
    for (int i = 0; i < list->count; i++) {
        if (list->data[i].RNTI == RNTI) {
            // found RNTI in the list, remove it
            NFAPI_CRC_INDICATION_PDU_T *pdu = &(list->data[i]);
            memmove(&(list->data[i]), &(list->data[i + 1]), (list->count - i) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->count--;
            return true;
        }
    }
    // RNTI not found in the list
    printf("Error: RNTI %u not found in the list\n", RNTI);
    return false;
}

bool clearList(List *list) {
    if (list->count == 0) {
        // list is empty
        printf("Error: list is empty\n");
        return false;
    }
    free(list->data);
    list->data = NULL;
    list->count = 0;
    return true;
}

void destroyList(List *list) {
    if (list) {
        clearList(list);
        free(list);
    }
}

bool handleOverflow(List *list, uint16_t RNTI) {
