    bool success = false;
    if (clearList(list)) {
        success = true;
    } else {
        printf("Error: failed to clear the list\n");
    }
    if (success) {
        // attempt to insert the RNTI again
        success = insertIntoList(list, RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG);
        if (!success) {
            printf("Error: failed to insert RNTI %u into the list\n", RNTI);
        }
    }
    return success;
}

bool handleCollision(List *list, uint16_t RNTI) {
    // attempt to remove and reinsert the RNTI when necessary
    bool success = false;
    if (removeFromList(list, RNTI)) {
        success = true;
    } else {
        printf("Error: failed to remove RNTI %u from the list\n", RNTI);
    }
    if (success) {
        // attempt to insert the RNTI again
        success = insertIntoList(list, RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG);
        if (!success) {
            printf("Error: failed to insert RNTI %u into the list\n", RNTI);
        }
    }
    return success;
}

bool manageList(List *list, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI, uint8_t CRC_INDICATION_REL8_TAG) {
    bool success = false;
    if (insertIntoList(list, RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG)) {
        success = true;
    } else {
        printf("Error: failed to insert RNTI %u into the list\n", RNTI);
    }
    if (!success) {
        // handle list overflow or RNTI collision
        if (list->count >= MAX_LIST_SIZE || removeFromList(list, RNTI)) {
            // list overflow
            success = handleOverflow(list, RNTI);
        } else {
            // RNTI collision
            success = handleCollision(list, RNTI);
        }
    }
    return success;
}
