    } else if (num_digits > MAX_NUM_DIGITS) {
        // Limit the number of digits to avoid potential performance bottlenecks
        num_digits = MAX_NUM_DIGITS;
    }

    pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_vowels);
