char* removeSpecialCharactersAndSpaces(char* filename) {
    char* new_filename = malloc(strlen(filename));
    int j = 0;
    for (int i = 0; i < strlen(filename); i++) {
        if (isalnum(filename[i]) || filename[i] == '_') {
            new_filename[j++] = filename[i];
        }
    }
    new_filename[j] = '\0';
    return new_filename;
}

int countVowels(char* filename) {
    int num_vowels = 0;
    for (int i = 0; i < strlen(filename); i++) {
        if (isalpha(filename[i]) && isvowel(filename[i])) {
            num_vowels++;
        }
    }
    return num_vowels;
}

int determineNumDigits(int num_vowels) {
    int num_digits = 3;
    if (num_vowels > 0) {
        num_digits = log10(num_vowels) + 1;
    } else {
        num_digits = DEFAULT_NUM_DIGITS;
    }
    return num_digits;
}

char* validateExtension(char* filename, int num_digits) {
    char* new_extension = malloc(strlen(filename) + num_digits);
    sprintf(new_extension, "%s%03d", filename, num_digits);
    return new_extension;
}

int getRNTI(char* filename) {
    // Implement a function to generate a valid RNTI value based on the given filename
    int rnti = 0xBEEF;
    for (int i = 0; i < strlen(filename); i++) {
        if (isalpha(filename[i])) {
            rnti += filename[i];
        }
    }
    return rnti;
}

int getCRCFlag() {
    // Implement a function to generate a valid CRCFLAG value based on the given filename and RNTI
    int crcflag = 0xCAFE;
    for (int i = 0; i < strlen(filename); i++) {
        if (isalpha(filename[i])) {
            crcflag += filename[i];
        }
    }
    return crcflag;
}
