            printf("Populated transaction record %lu: timestamp=%lu, sourceMacAddress=%.6s, destinationMacAddress=%.6s, acknowledgementFlag=%d\n", i + 1, records[i].transactionTimestamp, records[i].sourceMacAddress, records[i].destinationMacAddress, records[i].acknowledgementFlag);
        }
    }

    // Design the function to be modular and extensible, allowing for future enhancements such as adding new fields to MAC_TRANSACTION_RECORD or supporting additional transaction types
    return numRecords;
}

bool validateTransactionRecord(MAC_TRANSACTION_RECORD record) {
    // Check for valid input parameters
    if (record.transactionTimestamp <= 0 || record.sourceMacAddress[0] == '\0' || record.destinationMacAddress[0] == '\0') {
        return false;
    }

    // Implement checks for out-of-range transaction timestamps
    if (record.transactionTimestamp > INT64_MAX) {
        return false;
    }

    // Check for duplicate acknowledgement flags in consecutive structures
    size_t i = 0;
    while (i < numRecords - 1) {
        if (records[i].acknowledgementFlag == records[i + 1].acknowledgementFlag) {
            return false;
        }
        ++i;
    }

    return true;
}
