#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

static const int MAX_NFAPI_CRC_INDICATIONS = 1000;

// Thread-safe queue for storing NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int front, rear, size;
    NFAPI_CRC_INDICATION_PDU_T* array[MAX_NFAPI_CRC_INDICATIONS];
} CrcIndicationQueue;

// Initialize the queue
void initQueue(CrcIndicationQueue* queue) {
    pthread_mutexattr_t attr;
    pthread_condattr_t condAttr;

    // Set mutex and condition attributes
    pthread_mutexattr_init(&attr);
    pthread_condattr_init(&condAttr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);

    // Initialize mutex and condition variables
    pthread_mutex_init(&queue->mutex, &attr);
    pthread_cond_init(&queue->cond, &condAttr);

    queue->front = 0;
    queue->rear = MAX_NFAPI_CRC_INDICATIONS - 1;
    queue->size = 0;
}

// Add an element to the queue
void addQueue(CrcIndicationQueue* queue, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&queue->mutex);

    // Increment size and rear index
    queue->size++;
    queue->rear = (queue->rear + 1) % MAX_NFAPI_CRC_INDICATIONS;

    // Copy element into array at rear index
    memcpy(&(queue->array[queue->rear]), element, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->mutex);
}

// Remove an element from the queue
NFAPI_CRC_INDICATION_PDU_T* removeQueue(CrcIndicationQueue* queue) {
    NFAPI_CRC_INDICATION_PDU_T* element = NULL;

    pthread_mutex_lock(&queue->mutex);

    // Check if queue is empty
    if (queue->size > 0) {
        // Decrement size and front index
        queue->size--;
        queue->front = (queue->front + 1) % MAX_NFAPI_CRC_INDICATIONS;

        // Get element from array at front index
        element = &(queue->array[queue->front]);
    }

    pthread_mutex_unlock(&queue->mutex);

    return element;
}

// Destroy the queue
void destroyQueue(CrcIndicationQueue* queue) {
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->cond);
}

// CRC indication listener thread function
void* crcListenerThread(void* arg) {
    // Get the socket and port number as arguments
    int sock = *((int*)arg);
    int port = *((int*)(arg + sizeof(int)));

    // Create a new UDP socket
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(struct sockaddr_in));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    addr.sin_addr.s_addr = INADDR_ANY;

    // Bind the socket to the specified port
    if (bind(sock, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        perror("Binding failed");
        exit(EXIT_FAILURE);
    }

    printf("Listening on UDP port %d\n", port);

    // Initialize the CRC indication queue
    CrcIndicationQueue crcIndications;
    initQueue(&crcIndications);

    // Loop indefinitely to receive and process CRC indications
    while (1) {
        // Receive a single CRC indication packet
        struct sockaddr_in clientAddr;
        memset(&clientAddr, 0, sizeof(struct sockaddr_in));
        int clientLen = sizeof(clientAddr);
        char buffer[1024];

        if (recvfrom(sock, buffer, 1024, 0, (struct sockaddr*)&clientAddr, &clientLen) < 0) {
            perror("Error receiving CRC indication");
        } else {
            // Parse the received packet and extract the RX_UE_INFORMATION_TAG and RNTI
            uint8_t* p = (uint8_t*)buffer;
            uint16_t rxueiTag = *(uint16_t*)p;
            p += 2;
            uint16_t rnti = *(uint16_t*)p;
