    // Remove the element from the list by shifting all elements after it back one position
    for (size_t j = i + 1; j < list->size; ++j) {
      list->elements[j - 1] = list->elements[j];
    }

    // Decrement the size of the list
    --list->size;
  }

  pthread_mutex_unlock(&list_lock);
}

// Function to update an element in the list, ensuring thread-safe access
void nfapi_rx_frame_list_update(nfapi_rx_frame_list_t *list, const uint16_t qos_priority, const uint16_t rnti, const uint8_t message_tag) {
  pthread_mutex_lock(&list_lock);

  // Find the element to update
  size_t i = 0;
  while (i < list->size && (list->elements[i].qos_priority != qos_priority || list->elements[i].rnti != rnti || list->elements[i].message_tag != message_tag)) {
    ++i;
  }

  // Check if the element was found
  if (i < list->size) {
    // Update the element in the list
    list->elements[i].qos_priority = qos_priority;
    list->elements[i].rnti = rnti;
    list->elements[i].message_tag = message_tag;
  }

  pthread_mutex_unlock(&list_lock);
}

// Function to retrieve an element from the list, ensuring thread-safe access
nfapi_rx_frame_pdu_t nfapi_rx_frame_list_get(const nfapi_rx_frame_list_t *list, const uint16_t qos_priority, const uint16_t rnti, const uint8_t message_tag) {
  pthread_mutex_lock(&list_lock);

  // Find the element to retrieve
  size_t i = 0;
  while (i < list->size && (list->elements[i].qos_priority != qos_priority || list->elements[i].rnti != rnti || list->elements[i].message_tag != message_tag)) {
    ++i;
  }

  // Check if the element was found
  if (i < list->size) {
    return list->elements[i];
  } else {
    return NULL;
  }
}

// Function to clear the list, ensuring thread-safe access
void nfapi_rx_frame_list_clear(nfapi_rx_frame_list_t *list) {
  pthread_mutex_lock(&list_lock);

  // Reset the size of the list to zero
  list->size = 0;

  pthread_mutex_unlock(&list_lock);
}

// Function to free the allocated resources for the list, ensuring thread-safe access
void nfapi_rx_frame_list_free(nfapi_rx_frame_list_t *list) {
  pthread_mutex_lock(&list_lock);

  // Free the allocated memory for the elements
  free(list->elements);

  // Reset the capacity and size of the list to zero
  list->capacity = 0;
  list->size = 0;

  pthread_mutex_unlock(&list_lock);
}
