#define MAX_NICP_MESSAGES 1024
#define MAC_ADDR_LEN 6
#define IPV4_ADDR_LEN 4
#define PROTOCOL_VER 8

typedef struct NICPMessageHeader {
    uint8_t macAddr[MAC_ADDR_LEN];
    uint32_t ipv4Addr;
    uint16_t protocolVer;
} NICPMessageHeader;

typedef struct RX_UE_INFORMATION_TAG {
    uint16_t rnti;
    uint8_t payload[0];
