typedef struct NetworkInterface {
    int32_t macAddr[MAC_ADDR_LEN];
    uint16_t ipv4Addr;
    uint16_t protocolVer;
} NetworkInterface;

int32_t initializeNetworkInterfaces(uint16_t numIfaces, NetworkInterface *ifaceArray) {
    int32_t i;
    for (i = 0; i < numIfaces; ++i) {
        ifaceArray[i].macAddr[0] = rand() % 256;
        ifaceArray[i].macAddr[1] = rand() % 256;
        ifaceArray[i].macAddr[2] = rand() % 256;
        ifaceArray[i].macAddr[3] = rand() % 256;
        ifaceArray[i].macAddr[4] = rand() % 256;
        ifaceArray[i].macAddr[5] = rand() % 256;
        ifaceArray[i].ipv4Addr = rand() % 0xffffff;
        ifaceArray[i].protocolVer = PROTOCOL_VER;
    }
    return numIfaces;
}

int32_t verifyMacAddress(uint8_t *macAddr) {
    int32_t i;
    for (i = 0; i < MAX_NICP_MESSAGES - 1; ++i) {
        if (memcmp(macAddr, ifaceArray[i].macAddr, MAC_ADDR_LEN) == 0) {
            return 0;
        }
    }
    return 1;
}

int32_t createMessageHeaders(uint16_t numIfaces, NetworkInterface *ifaceArray) {
    int32_t i, j;
    NICPMessageHeader *msgHdr = (NICPMessageHeader *)malloc(sizeof(NICPMessageHeader));
    if (!msgHdr) {
        return 0;
    }
    for (i = 0; i < numIfaces; ++i) {
        msgHdr->macAddr[0] = ifaceArray[i].macAddr[0];
        msgHdr->macAddr[1] = ifaceArray[i].macAddr[1];
        msgHdr->macAddr[2] = ifaceArray[i].macAddr[2];
        msgHdr->macAddr[3] = ifaceArray[i].macAddr[3];
        msgHdr->macAddr[4] = ifaceArray[i].macAddr[4];
        msgHdr->macAddr[5] = ifaceArray[i].macAddr[5];
        msgHdr->ipv4Addr = ifaceArray[i].ipv4Addr;
        msgHdr->protocolVer = ifaceArray[i].protocolVer;
        for (j = 0; j < MAX_NICP_MESSAGES - 1; ++j) {
            if (memcmp(msgHdr->macAddr, ifaceArray[j].macAddr, MAC_ADDR_LEN) == 0) {
                free(msgHdr);
                return 0;
            }
        }
    }
    free(msgHdr);
    return 1;
}

int32_t populateMessageHeaders(uint16_t numIfaces, NetworkInterface *ifaceArray) {
    int32_t i, j;
    RX_UE_INFORMATION_TAG *rxUeInfo = (RX_UE_INFORMATION_TAG *)malloc(sizeof(RX_UE_INFORMATION_TAG));
    if (!rxUeInfo) {
        return 0;
    }
    CRC_INDICATION_REL8_TAG *crcIndicationRel8 = (CRC_INDICATION_REL8_TAG *)malloc(sizeof(CRC_INDICATION_REL8_TAG));
    if (!crcIndicationRel8) {
        free(rxUeInfo);
        return 0;
    }
    for (i = 0; i < numIfaces; ++i) {
        rxUeInfo->rnti = rand() % 0xffff;
        crcIndicationRel8->crcFlag = rand() % 0xff;
        for (j = 0; j < MAX_NICP_MESSAGES - 1; ++j) {
            if (memcmp(rxUeInfo->rnti, ifaceArray[j].rxUeInfo->rnti, sizeof(rxUeInfo->rnti)) == 0) {
                free(crcIndicationRel8);
                free(rxUeInfo);
                return 0;
            }
        }
    }
    free(crcIndicationRel8);
    free(rxUeInfo);
    return 1;
}

int32_t getMessageHeader(uint16_t numIfaces, NetworkInterface *ifaceArray) {
    int32_t i, j;
    for (i = 0; i < MAX_NICP_MESSAGES - 1; ++i) {
