```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Define a maximum number of structures to allocate
#define MAX_STRUCTS 100

typedef struct {
    uint8_t crcFlag;
    uint64_t rnti;
    NFAPI_CRC_INDICATION_PDU_T *indicationPdu;
} RX_UE_INFORMATION_TAG;

void allocateRxUeInformation(int numUes) {
    // Check for valid number of UEs
    if (numUes <= 0 || numUes > MAX_STRUCTS) {
        fprintf(stderr, "Error: Invalid number of UEs specified\n");
        return;
    }

    // Allocate memory for the array of RX UE information structures
    RX_UE_INFORMATION_TAG *rxUeInformation = malloc(numUes * sizeof(RX_UE_INFORMATION_TAG));
    if (!rxUeInformation) {
        fprintf(stderr, "Error: Failed to allocate memory for RX UE information\n");
        return;
    }

    // Initialize the array of RX UE information structures
    memset(rxUeInformation, 0, numUes * sizeof(RX_UE_INFORMATION_TAG));

    // Set the random value for the CRCFLAG
    srand((unsigned)time(NULL));
    int crcFlag = rand() % 2;

    // Allocate memory for the NFAPI CRC indication PDUs
    for (int i = 0; i < numUes; i++) {
        rxUeInformation[i].indicationPdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!rxUeInformation[i].indicationPdu) {
            fprintf(stderr, "Error: Failed to allocate memory for NFAPI CRC indication PDU\n");
            return;
        }
    }

    // Set the RNTIs and CRCFLAGs
    for (int i = 0; i < numUes; i++) {
        rxUeInformation[i].rnti = rand() % MAX_STRUCTS + 1;
        rxUeInformation[i].crcFlag = crcFlag;
    }

    // Check for duplicate RNTIs and re-attempt allocation if necessary
    int duplicatesFound = 0;
    do {
        duplicatesFound = 0;
        for (int i = 0; i < numUes - 1; i++) {
            for (int j = i + 1; j < numUes; j++) {
                if (rxUeInformation[i].rnti == rxUeInformation[j].rnti) {
                    duplicatesFound++;
                    break;
                }
            }
        }
        if (duplicatesFound > 0) {
            // Reallocate memory for the array of RX UE information structures
            free(rxUeInformation);
            rxUeInformation = realloc(rxUeInformation, (numUes - duplicatesFound) * sizeof(RX_UE_INFORMATION_TAG));
            if (!rxUeInformation) {
                fprintf(stderr, "Error: Failed to re-allocate memory for RX UE information\n");
                return;
            }
            // Reallocate memory for the NFAPI CRC indication PDUs
            for (int i = 0; i < numUes - duplicatesFound; i++) {
                rxUeInformation[i].indicationPdu = realloc(rxUeInformation[i].indicationPdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
