#define MAX_NICBS 100
#define MAX_MAC_ADDRESSES 500
#define MAX_POOL_SIZE (MAX_MAC_ADDRESSES * sizeof(char))

typedef struct nicb {
    char ipv4[4];
    char subnet_mask[4];
    int num_mac_addresses;
    char mac_addresses[500][6];
    short network_speed;
    short power_saving_mode;
} nicb;

typedef struct {
    pthread_mutex_t mutex;
    int num_nicbs;
    nicb nicbs[MAX_NICBS];
} nicb_pool;

nicb_pool* create_nicb_pool(int num_nicbs) {
    if (num_nicbs > MAX_NICBS) {
        fprintf(stderr, "Error: maximum number of NICBs exceeded\n");
        return NULL;
    }

    nicb_pool* pool = malloc(sizeof(nicb_pool));
    if (!pool) {
        fprintf(stderr, "Error: failed to allocate memory for NICB pool\n");
        return NULL;
    }

    pool->num_nicbs = num_nicbs;

    pthread_mutex_init(&(pool->mutex), NULL);

    // initialize NICBs
    for (int i = 0; i < num_nicbs; i++) {
        nicb* nicb = &(pool->nicbs[i]);
        memset(nicb, 0, sizeof(nicb));
    }

    return pool;
}

void destroy_nicb_pool(nicb_pool* pool) {
    pthread_mutex_destroy(&(pool->mutex));
    free(pool);
}

