    int count; // Number of entries in the hash table
    NFAPI_CRC_INDICATION_PDU_T** entries; // Array of pointers to the linked list entries
} HashTable;

// Function to create a new instance of the hash table
HashTable* createHashTable(int size) {
    HashTable* hashTable = malloc(sizeof(HashTable));
    if (hashTable == NULL) {
        logError("Failed to allocate memory for hash table");
        return NULL;
    }

    hashTable->size = size;
    hashTable->count = 0;
    hashTable->entries = calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (hashTable->entries == NULL) {
        logError("Failed to allocate memory for hash table entries");
        free(hashTable);
        return NULL;
    }

    return hashTable;
}

// Function to destroy an instance of the hash table
void destroyHashTable(HashTable* hashTable) {
    if (hashTable == NULL) {
        logError("Invalid argument: hashTable is null");
        return;
    }

    // Free the memory for the linked list entries
    for (int i = 0; i < hashTable->size; i++) {
        free(hashTable->entries[i]);
    }

    // Free the memory for the hash table structure
    free(hashTable->entries);
    free(hashTable);
}

// Function to insert a new entry into the linked list and hash table
bool insertEntry(HashTable* hashTable, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, bool CRCFLAG) {
    // Check if the RNTI already exists in the hash table
    for (int i = 0; i < hashTable->count; i++) {
