    newEntry->RNTI = RNTI;
    newEntry->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    newEntry->CRCFLAG = CRCFLAG;

    // Check if the hash table needs to be resized
    if (hashTable->count == hashTable->size) {
        int newSize = 2 * hashTable->size;
        NFAPI_CRC_INDICATION_PDU_T** newEntries = realloc(hashTable->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * newSize);
        if (newEntries == NULL) {
            logError("Failed to resize hash table");
            return false;
        }

        hashTable->size = newSize;
        hashTable->entries = newEntries;
    }

    // Add the new entry to the hash table
    hashTable->entries[hashTable->count++] = newEntry;

    return true;
