const string LOG_FILENAME = "request_log.txt";

class SandeshClient {
public:
    // Constructor to initialize the client with a given IP address and port number
    SandeshClient(const string& ip, const int port) : io_context_(1), resolver_(io_context_), socket_(io_context_) {
        endpoint_ = tcp::endpoint(boost::asio::ip::address::from_string(ip), port);
    }

    // Function to send a GET request to the server and verify the response value within a given tolerance
    void sendRequest(const string& request, const double& expectedValue) {
        boost::system::error_code ec;
        socket_.async_connect(endpoint_, [this, &request, &expectedValue](const boost::system::error_code& error) {
            if (!error) {
                // Create a GET request with the specified IP address and port number
                stringstream ss;
                ss << "GET " << request << " HTTP/1.1\r\n";
                ss << "Host: " << endpoint_.address().to_string() << "\r\n";
                ss << "Connection: close\r\n";
                ss << "\r\n";

                // Send the GET request to the server and store the response in a stringstream object
                boost::asio::write(socket_, boost::asio::buffer(ss.str()), ec);

                if (!ec) {
                    // Read the response from the server and extract the value
                    string response;
                    boost::asio::read(socket_, boost::asio::dynamic_buffer(response), ec);

                    if (!ec) {
                        // Parse the response and verify that the value is within the given tolerance
                        double actualValue = stod(response);
                        if (abs(actualValue - expectedValue) <= TOLERANCE) {
                            cout << "Request successful: " << request << endl;
                            logRequest(request, response);
                        } else {
                            cout << "Request failed: " << request << endl;
                        }
                    }
                }
            }
        });
    }

private:
    // Log the start and end time of each request and record any errors encountered
    void logRequest(const string& request, const string& response) {
        time_t now = time(0);
        ofstream logFile(LOG_FILENAME, ios::app);
        if (logFile.is_open()) {
            logFile << "[" << put_time(localtime(&now), "%F %T") << "] Request: " << request;
            logFile << "\nResponse: " << response;
            logFile.close();
        }
    }

    // Define the maximum number of concurrent requests and the rate limit for requests per second
    boost::asio::io_context io_context_;
    tcp::resolver resolver_;
    tcp::socket socket_;
    tcp::endpoint endpoint_;
};

int main() {
    vector<string> requestList = {"GET /resource/1", "GET /resource/2", "GET /resource/3"};
    unordered_map<string, double> expectedValues = {{requestList[0], 1.5}, {requestList[1], 3.7}, {requestList[2], 4.2}};

    // Initialize the Sandesh client with a given IP address and port number
    SandeshClient client("192.168.0.1", 80);

    // Create a custom test double for the InterfaceTable class to handle edge cases where the IP might not belong to any recognized subnet
    class TestDoubleInterfaceTable : public InterfaceTable {
        bool FindVmUuidFromMetadataIp(const string& metadataIp) override {
            if (metadataIp.find("192.168.0.0") != string::npos) return true;
            else return false;
        }
    };

    // Use a rate-limiting mechanism to control the frequency of requests, limiting no more than R requests per second
    std::chrono::milliseconds ms(1000 / RATE_LIMIT);

    // Define the number of concurrent requests and the maximum number of proxy sessions
    int currentRequestCount = 0;
    int maxConcurrentRequests = MAX_CONCURRENT_REQUESTS;
    int maxProxySessions = 10;

    // Loop over the request list and send GET requests to the server for each resource
    for (auto& request : requestList) {
        // Check if the current number of concurrent requests exceeds the maximum, if so, wait for a proxy session to become available
        while (currentRequestCount >= maxConcurrentRequests) {
            boost::this_thread::sleep(ms);
        }

        // Increment the number of concurrent requests and send the GET request
        currentRequestCount++;
        client.sendRequest(request, expectedValues[request]);
    }

    // Wait for all outstanding requests to complete and print out the number of successful requests, proxy sessions, and internal errors
    io_context_.run();
    cout << "Number of successful requests: " << requestList.size() - client.getInternalErrors() << endl;
    cout << "Number of proxy sessions: " << currentRequestCount << endl;
    cout << "Number of internal errors: " << client.getInternalErrors() << endl;

    return 0;
}
