    for (size_t i = 0; i < numFlows; ++i) {
        TrafficFlow *flow = &(*trafficFlows)[i];
        flow->flowID = flowID++;
        strcpy(flow->sourceAddress, "192.168.0.1");
        strcpy(flow->destinationAddress, "192.168.0.2");
    }

    // Set the buffer size to the actual number of bytes used
    bufSize = (buf - *trafficFlows) + numFlows * sizeof(TrafficFlow);
    free(buf);

    // Log the total number of packets processed successfully and failed due to buffer overflow
