#define NFAPI_MESSAGE_PDU_T struct { \
    uint32_t ue_id; \
    RX_DATA_PDU_T *rx_data_pdu; \
}

#define RX_DATA_PDU_T struct { \
    int modulation_scheme; \
    size_t symbol_count; \
    uint8_t payload[]; \
}

NFAPI_MESSAGE_PDU_T *nfapi_message_pdu_init(uint32_t ue_id, int modulation_scheme, size_t symbol_count) {
    NFAPI_MESSAGE_PDU_T *nfapi_message_pdu = malloc(sizeof(NFAPI_MESSAGE_PDU_T));
    if (!nfapi_message_pdu) {
        perror("malloc");
        return NULL;
    }

    nfapi_message_pdu->ue_id = ue_id;
    nfapi_message_pdu->rx_data_pdu = malloc(sizeof(RX_DATA_PDU_T) + symbol_count * sizeof(uint8_t));
    if (!nfapi_message_pdu->rx_data_pdu) {
        perror("malloc");
        free(nfapi_message_pdu);
        return NULL;
    }

    nfapi_message_pdu->rx_data_pdu->modulation_scheme = modulation_scheme;
    nfapi_message_pdu->rx_data_pdu->symbol_count = symbol_count;

    return nfapi_message_pdu;
}

void nfapi_message_pdu_free(NFAPI_MESSAGE_PDU_T *nfapi_message_pdu) {
    if (nfapi_message_pdu->rx_data_pdu) {
        free(nfapi_message_pdu->rx_data_pdu);
    }
    free(nfapi_message_pdu);
}

void nfapi_message_pdu_resize(NFAPI_MESSAGE_PDU_T *nfapi_message_pdu, size_t new_size) {
    if (new_size == 0) {
        return;
    }

    RX_DATA_PDU_T *rx_data_pdu = realloc(nfapi_message_pdu->rx_data_pdu, sizeof(RX_DATA_PDU_T) + new_size);
    if (!rx_data_pdu) {
        perror("realloc");
        return;
    }

    nfapi_message_pdu->rx_data_pdu = rx_data_pdu;
}

int nfapi_message_pdu_fetch(NFAPI_MESSAGE_PDU_T *nfapi_message_pdu, uint8_t *buffer, size_t buffer_size) {
    if (buffer_size < sizeof(RX_DATA_PDU_T)) {
        return -1;
    }

    ssize_t bytes_read = recvfrom(socket_fd, buffer, buffer_size, 0, NULL, NULL);
    if (bytes_read == -1) {
        perror("recvfrom");
        return -1;
    }

    RX_DATA_PDU_T *rx_data_pdu = nfapi_message_pdu->rx_data_pdu;
    size_t payload_size = bytes_read - sizeof(RX_DATA_PDU_T);

    memcpy(&rx_data_pdu->modulation_scheme, buffer, sizeof(int));
    memcpy(&rx_data_pdu->symbol_count, buffer + sizeof(int), sizeof(size_t));
    memcpy(rx_data_pdu->payload, buffer + sizeof(int) + sizeof(size_t), payload_size);

    return bytes_read;
}

int nfapi_message_pdu_send(NFAPI_MESSAGE_PDU_T *nfapi_message_pdu) {
    if (socket_fd == -1) {
        perror("socket");
        return -1;
    }

    size_t payload_size = nfapi_message_pdu->rx_data_pdu->symbol_count * sizeof(uint8_t);
    uint8_t buffer[payload_size + sizeof(RX_DATA_PDU_T)];

    memcpy(buffer, &nfapi_message_pdu->rx_data_pdu->modulation_scheme, sizeof(int));
    memcpy(buffer + sizeof(int), &nfapi_message_pdu->rx_data_pdu->symbol_count, sizeof(size_t));
    memcpy(buffer + sizeof(int) + sizeof(size_t), nfapi_message_pdu->rx_data_pdu->payload, payload_size);

    ssize_t bytes_sent = sendto(socket_fd, buffer, payload_size + sizeof(RX_DATA_PDU_T), 0, NULL, NULL);
    if (bytes_sent == -1) {
        perror("sendto");
        return -1;
    }

    return bytes_sent;
}
