// Structure to hold the list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t length;
} CrcIndicationList;

// Custom hash table to efficiently lookup RNTIs in the list
typedef struct {
    int key;
    NFAPI_CRC_INDICATION_PDU_T value;
} RntiLookupTable;

// Internal statistics counter to track total number of CRC indications processed
static size_t crcIndicationCount = 0;

// Mutex for thread-safe access to the list
static pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;

// Function to append a new CRC indication to the list
void addCrcIndication(NFAPI_CRC_INDICATION_PDU_T *crcIndication) {
    // Acquire mutex for thread-safe access to the list
    pthread_mutex_lock(&listMutex);

    // Dynamically allocate memory for a new NFAPI_CRC_INDICATION_PDU_T structure
    CrcIndicationList *newList = malloc(sizeof(CrcIndicationList));
    if (!newList) {
        printf("ERROR: Failed to allocate memory for new CRC indication list\n");
        pthread_mutex_unlock(&listMutex);
        return;
    }

    // Append the new CRC indication to the end of the list
    newList->length = 1;
    newList->list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newList->list) {
        printf("ERROR: Failed to allocate memory for new CRC indication\n");
        free(newList);
        pthread_mutex_unlock(&listMutex);
        return;
    }
    memcpy(newList->list, crcIndication, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Update the list length and add the new entry to the lookup table
    CrcIndicationList *currentList = &lookupTable[RNTI];
    currentList->length++;
    RntiLookupTable *newEntry = malloc(sizeof(RntiLookupTable));
    if (!newEntry) {
        printf("ERROR: Failed to allocate memory for new lookup table entry\n");
        free(currentList);
        pthread_mutex_unlock(&listMutex);
        return;
    }
    newEntry->key = RNTI;
    newEntry->value = *crcIndication;
    currentList->list = realloc(currentList->list, currentList->length * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!currentList->list) {
        printf("ERROR: Failed to allocate memory for new CRC indication list\n");
        free(newEntry);
        pthread_mutex_unlock(&listMutex);
        return;
    }
    currentList->list[currentList->length - 1] = *crcIndication;

    // Release mutex for thread-safe access to the list
    pthread_mutex_unlock(&listMutex);
}

// Function to retrieve a CRC indication from the list by RNTI
NFAPI_CRC_INDICATION_PDU_T *getCrcIndication(int RNTI) {
    // Acquire mutex for thread-safe access to the list
    pthread_mutex_lock(&listMutex);

    // Lookup the CRC indication in the lookup table
    RntiLookupTable *lookupEntry = &lookupTable[RNTI];
    if (lookupEntry) {
        NFAPI_CRC_INDICATION_PDU_T *crcIndication = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memcpy(crcIndication, &lookupEntry->value, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pthread_mutex_unlock(&listMutex);
        return crcIndication;
    } else {
        pthread_mutex_unlock(&listMutex);
        return NULL;
    }
}

// Function to serialize the list to a file in binary format
void serializeCrcIndications(FILE *file) {
    // Acquire mutex for thread-safe access to the list
    pthread_mutex_lock(&listMutex);

    // Write the length of the list to the file
    fwrite(&lookupTable.length, sizeof(size_t), 1, file);

    // Write each CRC indication in the list to the file
    for (int i = 0; i < lookupTable.length; i++) {
        RntiLookupTable *lookupEntry = &lookupTable[i];
        fwrite(&lookupEntry->value, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    // Release mutex for thread-safe access to the list
    pthread_mutex_unlock(&listMutex);
}

// Function to deserialize the list from a file in binary format
void deserializeCrcIndications(FILE *file) {
    // Acquire mutex for thread-safe access to the list
    pthread_mutex_lock(&listMutex);

    // Read the length of the list from the file
    size_t length;
    fread(&length, sizeof(size_t), 1, file);

    // Dynamically allocate memory for the new list
    CrcIndicationList *newList = malloc(sizeof(CrcIndicationList));
    if (!newList) {
        printf("ERROR: Failed to allocate memory for new CRC indication list\n");
        pthread_mutex_unlock(&listMutex);
        return;
    }
    newList->length = length;
    newList->list = malloc(length * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newList->list) {
        printf("ERROR: Failed to allocate memory for new CRC indication list\n");
        free(newList);
        pthread_mutex_unlock(&listMutex);
        return;
    }

    // Read each CRC indication from the file and add it to the list
    for (int i = 0; i < length; i++) {
        NFAPI_CRC_INDICATION_PDU_T crcIndication;
        fread(&crcIndication, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        newList->list[i] = crcIndication;
    }

    // Replace the current list with the new one
    pthread_mutex_unlock(&listMutex);
}
