// Define the struct for the CRC indication PDUs
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *crcIndPdu;
    RX_UE_INFORMATION_TAG rxUeInfoTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcFlag;
} CrcIndPduElement;

// Define the linked list structure
typedef struct {
    int capacity; // Maximum number of elements in the list
    int count; // Current number of elements in the list
    CrcIndPduElement *elements; // Pointer to an array of elements
} LinkedList;

// Define a callback function type for handling new CRC indications
typedef void (*CrcCallback)(NFAPI_CRC_INDICATION_PDU_T *crcIndPdu);

// Function to add a new element to the linked list
void addElement(LinkedList *list, NFAPI_CRC_INDICATION_PDU_T *crcIndPdu, RX_UE_INFORMATION_TAG rxUeInfoTag, RNTI rnti, CRC_INDICATION_REL8_TAG crcFlag) {
    // Check if the linked list is full
    if (list->count >= list->capacity) {
        printf("Linked list is full. Returning.\n");
        return;
    }

    // Create a new element and fill in its fields
    CrcIndPduElement *newElement = malloc(sizeof(CrcIndPduElement));
    newElement->crcIndPdu = crcIndPdu;
    newElement->rxUeInfoTag = rxUeInfoTag;
    newElement->rnti = rnti;
    newElement->crcFlag = crcFlag;

    // Add the new element to the linked list
    list->elements[list->count] = newElement;
    list->count++;
}

// Function to handle a CRC indication from the UE
void handleCrcInd(NFAPI_CRC_INDICATION_PDU_T *crcIndPdu, RX_UE_INFORMATION_TAG rxUeInfoTag, RNTI rnti, CRC_INDICATION_REL8_TAG crcFlag) {
    // Create a new linked list element and add it to the list
    addElement(list, crcIndPdu, rxUeInfoTag, rnti, crcFlag);
}

// Function to process all CRC indications in the linked list
void processCrcs() {
    // Loop through each element in the linked list and handle it
    for (int i = 0; i < list->count; i++) {
        CrcIndPduElement *element = list->elements[i];
        NFAPI_CRC_INDICATION_PDU_T *crcIndPdu = element->crcIndPdu;
        RX_UE_INFORMATION_TAG rxUeInfoTag = element->rxUeInfoTag;
        RNTI rnti = element->rnti;
        CRC_INDICATION_REL8_TAG crcFlag = element->crcFlag;

        // Call the callback function for each new CRC indication
        if (crcCallback != NULL) {
            crcCallback(crcIndPdu);
        }
    }
}

// Function to remove an element from the linked list
void removeElement(LinkedList *list, int index) {
    // Check if the index is valid
    if (index < 0 || index >= list->count) {
        printf("Invalid index. Returning.\n");
        return;
    }

    // Free the memory of the element and update the count
    CrcIndPduElement *element = list->elements[index];
    free(element);
    list->count--;
}

// Function to handle a buffer overflow by removing excess elements
void handleOverflow() {
    // Check if the linked list is full
    if (list->count >= list->capacity) {
        printf("Linked list is full. Removing excess elements.\n");

        // Remove the excess elements from the linked list
        for (int i = list->count - 1; i >= list->capacity; i--) {
            removeElement(list, i);
        }
    }
}

// Function to handle a new CRC indication from the UE
void handleNewCrcInd(NFAPI_CRC_INDICATION_PDU_T *crcIndPdu, RX_UE_INFORMATION_TAG rxUeInfoTag, RNTI rnti, CRC_INDICATION_REL8_TAG crcFlag) {
    // Handle the new CRC indication by adding it to the linked list and processing it
    handleCrcInd(crcIndPdu, rxUeInfoTag, rnti, crcFlag);
    processCrcs();
}

// Function to handle a buffer overflow by removing excess elements and logging the condition
void handleBufferOverflow() {
    // Log the buffer overflow condition
