typedef struct {
    int UE_INDEX;
    NFAPI_RX_PDU_T* pdu_list; // list of NFAPI_RX_PDU_T structures for this UE
} UE_ENTRY_T;

// Define the global variables for the hash map and the semaphore
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static sem_t sem = SEM_FAILED;
static struct hashmap* map = NULL;

// Function to initialize the hash map and the semaphore
void init() {
    // Initialize the hash map
    map = (struct hashmap*)malloc(sizeof(struct hashmap));
    hashmap_init(map);

    // Initialize the semaphore
    if ((sem = sem_open("my_sem", O_CREAT, 0644, 1)) == SEM_FAILED) {
        perror("Failed to create semaphore");
        exit(EXIT_FAILURE);
    }
}

// Function to add a new NFAPI_RX_PDU_T structure to the hash map
void add_pdu(int UE_INDEX, int RRC_STATE, void* RRC_MESSAGE_T) {
    // Acquire the lock for the hash map and the semaphore
    pthread_mutex_lock(&lock);

    // Get the current value of the semaphore
    int semval = 0;
    if (sem_getvalue(sem, &semval) == -1) {
        perror("Failed to get semaphore value");
    }

    // If the semaphore is non-zero, wait for it to be signaled
    while (semval > 0) {
        pthread_mutex_unlock(&lock);
        if (sem_wait(sem) == -1) {
            perror("Failed to wait on semaphore");
        }
        pthread_mutex_lock(&lock);
    }

    // If the hash map does not contain the UE_INDEX, create a new entry for it
    if (hashmap_get(map, UE_INDEX) == NULL) {
        UE_ENTRY_T* entry = (UE_ENTRY_T*)malloc(sizeof(UE_ENTRY_T));
        entry->UE_INDEX = UE_INDEX;
        entry->pdu_list = NULL;
        hashmap_put(map, entry);
    }

    // Add the new NFAPI_RX_PDU_T structure to the list of PDUs for this UE
    UE_ENTRY_T* entry = (UE_ENTRY_T*)hashmap_get(map, UE_INDEX);
    NFAPI_RX_PDU_T* pdu = (NFAPI_RX_PDU_T*)malloc(sizeof(NFAPI_RX_PDU_T));
    pdu->UE_INDEX = UE_INDEX;
    pdu->RRC_STATE = RRC_STATE;
    pdu->RRC_MESSAGE_T = RRC_MESSAGE_T;
    entry->pdu_list = (NFAPI_RX_PDU_T*)realloc(entry->pdu_list, sizeof(NFAPI_RX_PDU_T) * (entry->pdu_list->length + 1));
    entry->pdu_list[entry->pdu_list->length++] = pdu;

    // Release the lock for the hash map and the semaphore
    pthread_mutex_unlock(&lock);
}

// Function to remove a NFAPI_RX_PDU_T structure from the hash map
void remove_pdu(int UE_INDEX, int sequence_number) {
    // Acquire the lock for the hash map and the semaphore
    pthread_mutex_lock(&lock);

    // If the hash map contains the UE_INDEX, find the PDU with the given sequence number and remove it from the list
    if (hashmap_get(map, UE_INDEX) != NULL) {
        UE_ENTRY_T* entry = (UE_ENTRY_T*)hashmap_get(map, UE_INDEX);
        for (int i = 0; i < entry->pdu_list->length; ++i) {
            if (entry->pdu_list[i]->sequence_number == sequence_number) {
                NFAPI_RX_PDU_T* pdu = entry->pdu_list[i];
                for (int j = i + 1; j < entry->pdu_list->length; ++j) {
                    entry->pdu_list[j - 1] = entry->pdu_list[j];
                }
                --entry->pdu_list->length;
                free(pdu);
            }
        }
    }

    // Release the lock for the hash map and the semaphore
    pthread_mutex_unlock(&lock);
}

// Function to update the RRC state of a UE in the hash map
void set_rrc_state(int UE_INDEX, int RRC_STATE) {
    // Acquire the lock for the hash map and the semaphore
    pthread_mutex_lock(&lock);

    // If the hash map contains the UE_INDEX, update its RRC state
    if (hashmap_get(map, UE_INDEX) != NULL) {
        UE_ENTRY_T* entry = (UE_ENTRY_T*)hashmap_get(map, UE_INDEX);
        entry->RRC_STATE = RRC_STATE;
    }

    // Release the lock for the hash map and the semaphore
    pthread_mutex_unlock(&lock);
}

// Function to retrieve a NFAPI_RX_PDU structure from the hash map for a given UE index and sequence number
NFAPI_RX_PDU* get_pdu(int UE_INDEX, int sequence_number) {
    // Acquire the lock for the hash map and the semaphore
    pthread_mutex_lock(&lock);

    // If the hash map contains the UE_INDEX, find the PDU with the given sequence number and return it
    if (hashmap_get(map, UE_INDEX) != NULL) {
        UE_ENTRY_T* entry = (UE_ENTRY_T*)hashmap_get(map, UE_INDEX);
        for (int i = 0; i < entry->pdu_list->length; ++i) {
            if (entry->pdu_list[i]->sequence_number == sequence_number) {
                NFAPI_RX_PDU* pdu = entry->pdu_list[i];
                return pdu;
            }
        }
    }

    // Release the lock for the hash map and the semaphore
    pthread_mutex_unlock(&lock);

    // If no PDU was found, return NULL
    return NULL;
}

// Function to retrieve all NFAPI_RX_PDU structures from the hash map for a given UE index
NFAPI_RX_PDU** get_all_pdus(int UE_INDEX) {
    // Acquire the lock for the hash map and the semaphore
    pthread_mutex_lock(&lock);

    // If the hash map contains the UE_INDEX, return all PDUs for this UE
    if (hashmap_get(map, UE_INDEX) != NULL) {
        UE_ENTRY_T* entry = (UE_ENTRY_T*)hashmap_get(map, UE_INDEX);
        NFAPI_RX_PDU** pdus = (NFAPI_RX_PDU**)malloc(sizeof(NFAPI_RX_PDU*) * entry->pdu_list->length);
        for (int i = 0; i < entry->pdu_list->length; ++i) {
            pdus[i] = entry->pdu_list[i];
        }
        return pdus;
    }

    // Release the lock for the hash map and the semaphore
    pthread_mutex_unlock(&lock);

    // If no PDUs were found, return NULL
    return NULL;
}

// Function to retrieve all UE indices from the hash map
int* get_all_uids() {
    // Acquire the lock for the hash map and the semaphore
    pthread_mutex_lock(&lock);

    // Get the number of keys in the hash map
    int key_count = hashmap_key_count(map);
    int* uids = (int*)malloc(sizeof(int) * key_count);

    // Iterate over the keys and fill the list of UE indices
    struct hashmap_iter iter;
    hashmap_iter_init(&iter, map);
    while (hashmap_iter_next(&iter)) {
        uids[iter.idx] = *(int*)iter.key;
    }

    // Release the lock for the hash map and the semaphore
    pthread_mutex_unlock(&lock);

    return uids;
}
