// Define the dynamic list data structure
typedef struct {
    size_t capacity; // maximum number of elements in the list
    size_t count; // current number of elements in the list
    nfapi_crc_indication_pdu_t *elements; // pointer to an array of NFAPI_CRC_INDICATION_PDU_T elements
} nfapi_crc_indication_list_t;

// Define the mutex and condition variable for synchronization
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t list_condition = PTHREAD_COND_INITIALIZER;

// Function to create a new element in the dynamic list
void nfapi_crc_indication_list_add(nfapi_crc_indication_list_t *list, uint16_t rx_ue_information_tag, uint32_t rnti, bool crcflag) {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&list_mutex);

    // Check if there is space in the list to add a new element
    if (list->count < list->capacity) {
        // Allocate memory for the new element
        nfapi_crc_indication_pdu_t *new_element = malloc(sizeof(nfapi_crc_indication_pdu_t));
        if (new_element == NULL) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&list_mutex);
            return;
        }

        // Initialize the new element with the given values
        new_element->rx_ue_information_tag = rx_ue_information_tag;
        new_element->rnti = rnti;
        new_element->crc_indication_rel8_tag = crcflag;

        // Add the new element to the list and increment the count
        list->elements[list->count++] = *new_element;
    } else {
        // Handle overflow by increasing the capacity of the list
        list->capacity += 1024;
        list->elements = realloc(list->elements, list->capacity * sizeof(nfapi_crc_indication_pdu_t));
    }

    // Unlock the mutex and signal the condition variable
    pthread_mutex_unlock(&list_mutex);
    pthread_cond_signal(&list_condition);
}

// Function to remove an element from the dynamic list by RNTI
void nfapi_crc_indication_list_remove(nfapi_crc_indication_list_t *list, uint32_t rnti) {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&list_mutex);

    // Find the index of the element to be removed
    size_t i;
    for (i = 0; i < list->count; i++) {
        if (list->elements[i].rnti == rnti) {
            break;
        }
    }

    // Check if the element was found and remove it from the list
    if (i < list->count) {
        // Shift all elements after the removed element to the left
        for (size_t j = i; j < list->count - 1; j++) {
            list->elements[j] = list->elements[j + 1];
        }

        // Decrement the count and free the memory of the removed element
        list->count--;
        free(list->elements[i].crc_indication_rel8_tag);
    }

    // Unlock the mutex and signal the condition variable
    pthread_mutex_unlock(&list_mutex);
    pthread_cond_signal(&list_condition);
}

// Function to retrieve an element from the dynamic list by index
void nfapi_crc_indication_list_get(nfapi_crc_indication_list_t *list, size_t index) {
    // Check if the index is valid and return the corresponding element
    if (index < list->count) {
        return &list->elements[index];
    } else {
        return NULL;
    }
}

// Function to clean up unused elements in the dynamic list
void nfapi_crc_indication_list_cleanup(nfapi_crc_indication_list_t *list) {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&list_mutex);

    // Iterate through the list and remove elements with a CRCFLAG set to false
    for (size_t i = 0; i < list->count; i++) {
        if (!list->elements[i].crcflag) {
            nfapi_crc_indication_pdu_t *element = &list->elements[i];
            // Shift all elements after the removed element to the left
            for (size_t j = i; j < list->count - 1; j++) {
                list->elements[j] = list->elements[j + 1];
            }
            // Decrement the count and free the memory of the removed element
            list->count--;
            free(element);
        }
    }

    // Unlock the mutex and signal the condition variable
    pthread_mutex_unlock(&list_mutex);
    pthread_cond_signal(&list_condition);
}

// Function to handle overflow in the dynamic list
void nfapi_crc_indication_list_handle_overflow(nfapi_crc_indication_list_t *list) {
    // Increase the capacity of the list by a factor of 2
    list->capacity = list->capacity + (list->capacity / 2);
    list->elements = realloc(list->elements, list->capacity * sizeof(nfapi_crc_indication_pdu_t));
}
