} nfapi_crc_indication_list_t;

static const size_t DEFAULT_CAPACITY = 1024; // default capacity for the list

nfapi_crc_indication_list_t* nfapi_crc_indication_list_create(size_t capacity) {
    if (capacity == 0) {
        capacity = DEFAULT_CAPACITY; // default capacity for the list
    }

    nfapi_crc_indication_list_t *list = malloc(sizeof(nfapi_crc_indication_list_t));
    if (list == NULL) {
        return NULL; // memory allocation failed
    }

    list->data = malloc(capacity * sizeof(nfapi_crc_indication_pdu_t));
    if (list->data == NULL) {
        free(list);
        return NULL; // memory allocation failed
    }

    list->capacity = capacity;
    list->count = 0;

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_setpshared(&attr, PTHREAD_PROCESS_SHARED);
    pthread_mutex_init(&list->lock, &attr);

    return list;
}

void nfapi_crc_indication_list_destroy(nfapi_crc_indication_list_t *list) {
    if (list == NULL || list->data == NULL) {
        return; // invalid arguments
    }

    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->data[i].rx_ue_information_tag);
        free(list->data[i].rnti);
        free(list->data[i].crc_indication_rel8_tag);
    }
    pthread_mutex_unlock(&list->lock);

    free(list->data);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

nfapi_crc_indication_pdu_t* nfapi_crc_indication_list_add(nfapi_crc_indication_list_t *list, uint32_t rx_ue_information_tag, uint16_t rnti, uint8_t crc_indication_rel8_tag) {
    if (list == NULL || list->data == NULL) {
        return NULL; // invalid arguments
    }

    pthread_mutex_lock(&list->lock);

    size_t index = list->count++;
    nfapi_crc_indication_pdu_t *element = &(list->data[index]);
    element->rx_ue_information_tag = rx_ue_information_tag;
    element->rnti = rnti;
    element->crc_indication_rel8_tag = crc_indication_rel8_tag;
    element->crcflag = false;

    pthread_mutex_unlock(&list->lock);

    return element;
