        return NULL; // invalid arguments
    }

    pthread_mutex_lock(&list->lock);

    size_t index = 0;
    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i].rnti == rnti) {
            index = i;
            break;
        }
