  for (int i=0; i<cache_size; i++) {
    key_array[i] = value_range * rand() / RAND_MAX + 1;
  }

  // Initialize the doubly linked list to manage the recently used records.
  struct record {
    unsigned long offset;
    unsigned int key;
    struct record* next;
    struct record* prev;
  };
  struct record* head = NULL;
  struct record* tail = NULL;

  // Initialize the cache size and eviction policy.
  unsigned long cache_capacity = cache_size * sizeof(unsigned long);
  unsigned long total_records = offset_array + key_array;

  // Loop through each record in the array and insert it into the cache.
  for (int i=0; i<total_records; i++) {
    struct record* new_record = malloc(sizeof(struct record));
    new_record->offset = offset_array[i];
    new_record->key = key_array[i];

    // If the cache is full, remove the least recently used record from the cache.
    if (head == NULL || tail == NULL) {
      head = new_record;
      tail = new_record;
    } else {
      struct record* old_head = head;
      head = new_record;
      head->next = old_head;
      head->prev = NULL;
      old_head->prev = head;
    }
  }

  // Return a pointer to the offset and key arrays.
  return offset_array + key_array;
}

// Function to free memory allocated by init_record().
void free_record(int* offset_array, int* key_array) {
  // Free the memory allocated for the offset array and key array.
  free(offset_array);
  free(key_array);
}
