// Thread-safe data structure for managing the list of UE contexts
typedef struct {
    pthread_mutex_t mutex; // Mutex to protect concurrent access to the list
    int size; // Size of the list (number of UE contexts)
    int capacity; // Capacity of the list (maximum number of UE contexts)
    struct UeContext *head; // Head node of the list
} UeContextList;

// Structure to represent an individual UE context
typedef struct {
    int ueId; // Unique ID for this UE context
    struct {
        char *apn; // Access Point Name (APN) for this UE
        char *imei; // International Mobile Equipment Identity (IMEI) for this UE
        char *iccid; // Integrated Circuit Card Identifier (ICCID) for this UE
    } configuration; // Configured parameters for this UE
} UeContext;

// Initialize the list of UE contexts with a given capacity
void initUeContextList(UeContextList *list, int capacity) {
    list->size = 0;
    list->capacity = capacity;
    list->head = NULL;
}

// Add a new UE context to the list
int addUeContext(UeContextList *list, UeContext *context) {
    // Acquire mutex lock
    pthread_mutex_lock(&list->mutex);

    // Check if there is enough capacity in the list
    if (list->size == list->capacity) {
        // Release mutex lock and return error
        pthread_mutex_unlock(&list->mutex);
        return -ENOMEM;
    }

    // Add new UE context to the end of the list
    struct UeContext *newNode = malloc(sizeof(struct UeContext));
    newNode->ueId = context->ueId;
    strcpy(newNode->configuration.apn, context->configuration.apn);
    strcpy(newNode->configuration.imei, context->configuration.imei);
    strcpy(newNode->configuration.iccid, context->configuration.iccid);
    newNode->next = NULL;

    if (list->head == NULL) {
        list->head = newNode;
    } else {
        struct UeContext *tail = list->head;
        while (tail->next != NULL) {
            tail = tail->next;
        }
        tail->next = newNode;
    }

    // Increment size of the list
    list->size++;

    // Release mutex lock and return success
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Remove a UE context from the list by index
int removeUeContext(UeContextList *list, int index) {
    // Acquire mutex lock
    pthread_mutex_lock(&list->mutex);

    // Check if the index is valid
    if (index >= list->size || index < 0) {
        // Release mutex lock and return error
        pthread_mutex_unlock(&list->mutex);
        return -EINVAL;
    }

    struct UeContext *node = list->head;
    int currentIndex = 0;
    while (currentIndex < index) {
        node = node->next;
        currentIndex++;
    }

    // Remove the UE context from the list
    if (node == list->head) {
        list->head = node->next;
    } else {
        struct UeContext *prevNode = node->prev;
        prevNode->next = node->next;
    }

    // Decrement size of the list
    list->size--;

    // Release mutex lock and return success
    pthread_mutex_unlock(&list->mutex);
    free(node);
    return 0;
}

// Update a UE context in the list by index
int updateUeContext(UeContextList *list, int index, UeContext *context) {
    // Acquire mutex lock
    pthread_mutex_lock(&list->mutex);

    // Check if the index is valid
    if (index >= list->size || index < 0) {
        // Release mutex lock and return error
        pthread_mutex_unlock(&list->mutex);
        return -EINVAL;
    }

    struct UeContext *node = list->head;
    int currentIndex = 0;
    while (currentIndex < index) {
        node = node->next;
        currentIndex++;
    }

    // Update the UE context in the list
    strcpy(node->configuration.apn, context->configuration.apn);
    strcpy(node->configuration.imei, context->configuration.imei);
    strcpy(node->configuration.iccid, context->configuration.iccid);

    // Release mutex lock and return success
    pthread_mutex_unlock(&list->mutex);
    return 0;
}
```
