// Initialize TX buffer array with given capacity
void init_tx_buffers(int capacity) {
    // Check if buffer already initialized
    if (tx_buffers != NULL) return;

    // Allocate memory for the buffer
    tx_buffers = malloc(capacity * sizeof(tx_buffer_t));
    if (tx_buffers == NULL) {
        printf("Error: Failed to allocate TX buffer\n");
        exit(1);
    }

    // Initialize each element of the buffer with default values
    for (int i = 0; i < capacity; ++i) {
        tx_buffers[i].tx_buffer.valid = false;
        tx_buffers[i].crc_indication.RX_UE_INFORMATION_TAG = NULL;
        tx_buffers[i].crc_indication.RNTI = 0;
        tx_buffers[i].crc_indication.CRC_INDICATION_REL8_TAG = NULL;
    }

    // Set size and capacity of the buffer
    buffer_size = 0;
    buffer_capacity = capacity;
}

// Add new TX buffer to the array
void add_tx_buffer(LTE_PHY_TX_BUFFER_T tx_buffer, NFAPI_CRC_INDICATION_PDU_T crc_indication) {
    // Lock mutex for thread-safe access
    pthread_mutex_lock(&tx_buffer_mutex);

    // Check if buffer is full and needs to be reallocated
    if (buffer_size == buffer_capacity) {
        int new_capacity = buffer_capacity * 2;
        tx_buffers = realloc(tx_buffers, new_capacity * sizeof(tx_buffer_t));
        if (tx_buffers == NULL) {
            printf("Error: Failed to reallocate TX buffer\n");
            exit(1);
        }
        buffer_capacity = new_capacity;
    }

    // Add new element to the array
    tx_buffers[buffer_size].tx_buffer = tx_buffer;
    tx_buffers[buffer_size].crc_indication = crc_indication;
    buffer_size++;

    // Unlock mutex for thread-safe access
    pthread_mutex_unlock(&tx_buffer_mutex);
}

// Remove TX buffer from the array
void remove_tx_buffer(int index) {
    // Lock mutex for thread-safe access
    pthread_mutex_lock(&tx_buffer_mutex);

    // Check if index is out of bounds
    if (index < 0 || index >= buffer_size) return;

    // Shift elements to the left to remove element at index
    for (int i = index; i < buffer_size - 1; ++i) {
        tx_buffers[i].tx_buffer = tx_buffers[i + 1].tx_buffer;
        tx_buffers[i].crc_indication = tx_buffers[i + 1].crc_indication;
    }

    // Decrement buffer size and update last element with default values
    buffer_size--;
    tx_buffers[buffer_size].tx_buffer.valid = false;
    tx_buffers[buffer_size].crc_indication.RX_UE_INFORMATION_TAG = NULL;
    tx_buffers[buffer_size].crc_indication.RNTI = 0;
    tx_buffers[buffer_size].crc_indication.CRC_INDICATION_REL8_TAG = NULL;

    // Unlock mutex for thread-safe access
    pthread_mutex_unlock(&tx_buffer_mutex);
}

// Get TX buffer at given index
LTE_PHY_TX_BUFFER_T get_tx_buffer(int index) {
    // Check if index is out of bounds
    if (index < 0 || index >= buffer_size) return NULL;

    // Return TX buffer at given index
    return tx_buffers[index].tx_buffer;
}

// Get CRC indication for given frame and UE
NFAPI_CRC_INDICATION_PDU_T get_crc_indication(int frame, int ue) {
    // Check if buffer is initialized
    if (tx_buffers == NULL) return NULL;

    // Loop through buffers to find matching frame and UE
