    // Check that all CRCFlags are either true or false.
    for (int i = 0; i < list->size; i++) {
        if (list->entries[i].crcflag != true && list->entries[i].crcflag != false) {
            printf("Error: Invalid CRC flag value detected in CRC indication list\n");
            return false;
        }
    }

    // Check that the list is thread-safe.
    if (pthread_mutex_lock(&list->mutex) != 0) {
        printf("Error: Mutex lock failed in CRC indication list\n");
        return false;
    }

    pthread_mutex_unlock(&list->mutex);

    return true;
}
