// Function to create and populate an array of custom network packets
bool createPackets(int numPackets, struct Packet** packets) {
    // Check if the environment variable is already set
    const char* envVar = getenv("PACKETS_DIR");
    if (envVar == NULL) {
        // If not, create a new directory with the specified name and set the environment variable
        mkdir("/path/to/packets", 0755);
        envVar = "/path/to/packets";
        putenv(strdup("PACKETS_DIR=" + envVar));
    }

    // Allocate memory for the array of packets
    *packets = malloc(numPackets * sizeof(struct Packet));
    if (*packets == NULL) {
        return false;
    }

    // Populate the array with unique packet IDs, timestamps, and payload checksums
    for (int i = 0; i < numPackets; i++) {
        struct Packet* packet = *packets + i;
        packet->id = i + 1;
        packet->timestamp = time(NULL);
        char* payload = malloc(PACKET_PAYLOAD_SIZE);
        if (payload == NULL) {
            free(*packets);
            return false;
        }
        memset(payload, 'a', PACKET_PAYLOAD_SIZE);
        packet->payload = payload;
    }

    // Calculate checksum for each packet's payload and compare with stored value if available
    for (int i = 0; i < numPackets; i++) {
        struct Packet* packet = *packets + i;
        char* payload = packet->payload;
        unsigned int checksum = calculateChecksum(payload, PACKET_PAYLOAD_SIZE);
        if (checksum != packet->checksum) {
            free(packet->payload);
            packet->payload = NULL;
            return false;
        }
    }

    return true;
}

// Function to calculate the checksum of a given payload
unsigned int calculateChecksum(char* payload, size_t length) {
    unsigned int checksum = 0;
    for (size_t i = 0; i < length; i++) {
        checksum += payload[i];
    }
    return checksum;
}
