};

void initializeNetworkConfigurations(int N, const char* ip_range_start, const char* ip_range_end, bool comprehensive_validation) {
    // Initialize the dynamic array of network interface configurations
    struct NetworkConfig** configs = malloc(N * sizeof(struct NetworkConfig*));
    for (int i = 0; i < N; ++i) {
        configs[i] = malloc(sizeof(struct NetworkConfig));
        configs[i]->ip_address = NULL;
        configs[i]->subnet_mask = NULL;
        configs[i]->gateway = NULL;
        configs[i]->dns_servers = NULL;
    }

    // Load the network interface configurations from a persistent storage mechanism
    FILE* fp = fopen("network_configurations.txt", "r");
    if (fp == NULL) {
        printf("Error: Could not open file for reading\n");
        return;
    }
    char line[1024];
    while (fgets(line, sizeof(line), fp)) {
        // Parse the line and extract the IP address, subnet mask, gateway, and DNS server list
        struct NetworkConfig* config = configs[i];
        int start_index = 0;
        for (int j = 0; j < N; ++j) {
            int end_index = strcspn(line + start_index, ",");
            if (end_index == 0) {
                break;
            }
            char* field = malloc((end_index - start_index + 1) * sizeof(char));
            memcpy(field, line + start_index, end_index - start_index);
            field[end_index - start_index] = '\0';
            if (j == 0) {
                config->ip_address = field;
            } else if (j == 1) {
                config->subnet_mask = field;
            } else if (j == 2) {
                config->gateway = field;
            } else if (j == 3) {
                char** dns_servers = malloc((end_index - start_index + 1) * sizeof(char*));
                memcpy(dns_servers, line + start_index, end_index - start_index);
                dns_servers[end_index - start_index] = '\0';
                config->dns_servers = dns_servers;
            }
            start_index += end_index + 1;
        }
    }
    fclose(fp);

    // Perform comprehensive validation of each configuration, if requested
    if (comprehensive_validation) {
        for (int i = 0; i < N; ++i) {
            struct NetworkConfig* config = configs[i];
            if (!validateIPAddress(config->ip_address)) {
                printf("Error: Invalid IP address: %s\n", config->ip_address);
                return;
            }
            if (!validateIPAddress(config->subnet_mask)) {
                printf("Error: Invalid subnet mask: %s\n", config->subnet_mask);
                return;
            }
            if (!validateIPAddress(config->gateway)) {
                printf("Error: Invalid gateway: %s\n", config->gateway);
                return;
            }
            for (int j = 0; j < strlen(config->dns_servers); ++j) {
                if (!validateIPAddress(config->dns_servers[j])) {
                    printf("Error: Invalid DNS server: %s\n", config->dns_servers[j]);
                    return;
                }
            }
        }
    }

    // Log the name of the module being tested and the name of each test to a specified log file
    FILE* log_file = fopen("log.txt", "a");
    if (log_file == NULL) {
        printf("Error: Could not open log file for writing\n");
        return;
    }
    fprintf(log_file, "Module Name: Network Configuration Testing\n");
    fprintf(log_file, "Test Name: InitializeNetworkConfigurations\n");
    fclose(log_file);
}

bool validateIPAddress(const char* ip_address) {
    // Regular expression for validating an IP address
    const char* REGEX = "^(([0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])$";
    if (strlen(ip_address) > 16) {
        return false;
    }
    return (regex_match(REGEX, ip_address));
}
