int allocate_crc_indication_pdu(CRC_INDICATION_PDU_ARRAY* array, size_t size) {
    if (array->entries != NULL) {
        free(array->entries);
    }
    array->entries = (NFAPI_CRC_INDICATION_PDU_T*) malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array->entries == NULL) {
        return -1;
    }
    array->current_size = size;
    array->max_size = size;
    return 0;
}

int add_crc_indication_pdu(CRC_INDICATION_PDU_ARRAY* array, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (array->current_size >= array->max_size) {
        return -1;
    }
    pthread_mutex_lock(&mutex);
    array->entries[array->current_size] = *pdu;
    array->current_size++;
    pthread_mutex_unlock(&mutex);
    return 0;
}

int free_crc_indication_pdu(CRC_INDICATION_PDU_ARRAY* array) {
    if (array->entries != NULL) {
        free(array->entries);
