    pthread_mutex_lock(&session_lock);

    // Remove the session corresponding to the given username
    list_node_t* node = list_find(session_manager, (void*)username, compare_session_usernames);
    if (node != NULL) {
        list_remove(session_manager, node);
    }

    // Release lock
    pthread_mutex_unlock(&session_lock);
}

void add_device(user_session_t* session, char* device_id) {
    // Acquire lock to ensure thread-safe access
    pthread_mutex_lock(&session_lock);

    // Add the new device to the list of active devices
    list_push_back(session->active_devices, (void*)device_id);

    // Release lock
    pthread_mutex_unlock(&session_lock);
}

void remove_device(user_session_t* session, char* device_id) {
