    pthread_mutex_lock(&session_lock);

    // Remove the given device from the list of active devices
    list_node_t* node = list_find(session->active_devices, (void*)device_id, compare_active_devices);
    if (node != NULL) {
        list_remove(session->active_devices, node);
    }

