    return session->config.session_expiration_time;
}

void set_session_expired(user_session_t* session, bool is_expired) {
    // Acquire lock to ensure thread-safe access
    pthread_mutex_lock(&session_lock);

    // Update the session's expiration status
    session->config.is_session_expired = is_expired;

    // Release lock
    pthread_mutex_unlock(&session_lock);
}

void set_session_expiration_time(user_session_t* session, time_t expiration_time) {
    // Acquire lock to ensure thread-safe access
    pthread_mutex_lock(&session_lock);

    // Update the session's expiration time
    session->config.session_expiration_time = expiration_time;

    // Release lock
    pthread_mutex_unlock(&session_lock);
}

void cleanup_inactive_sessions() {
    // Acquire lock to ensure thread-safe access
    pthread_mutex_lock(&session_lock);

    // Iterate over all sessions and remove those that have expired
    list_node_t* node = session_manager->head;
    while (node != NULL) {
        user_session_t* session = (user_session_t*)node->data;
        if (is_session_expired(session)) {
            // Remove the inactive session from the list
            list_remove(session_manager, node);
            free(session->auth_data);
            free(session->active_devices);
            free(session);
        } else {
            node = node->next;
        }
    }

    // Release lock
    pthread_mutex_unlock(&session_lock);
}
