int largestInteger(int* arr, int size) {
    if (size == 0) {
        return INT_MIN;
    }

    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }

    return max;
}

// Function to process and hash the integers read from standard input
void processAndHash(int* array, int size) {
    // Allocate memory for the NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* pduArray = (NFAPI_CRC_INDICATION_PDU_T*) malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
