    }

    // Find the largest integer in the array and print it
    int largestInt = largestInteger(array, size);
    printf("Largest integer: %d\n", largestInt);

    // Generate and print the MD5 hash of the string representation of the largest integer
    char* hashStr = (char*) malloc(sizeof(int) * 8);
    if (hashStr == NULL) {
        printf("Error: Failed to allocate memory for MD5 hash\n");
        return;
    }
    sprintf(hashStr, "%d", largestInt);
    unsigned char* hash = md5_buffer((unsigned char*) hashStr, strlen(hashStr));
    if (hash == NULL) {
        printf("Error: Failed to generate MD5 hash\n");
        return;
    }
    for (int i = 0; i < 16; i++) {
        printf("%02x", hash[i]);
    }
    free(hash);
    free(hashStr);

    // Free the allocated memory for the NFAPI_CRC_INDICATION_PDU_T structures and the MD5 hash
    free(pduArray);
}

int main() {
    // Read integers from standard input and store them in an array
    int* array = (int*) malloc(sizeof(int) * 100);
    if (array == NULL) {
        printf("Error: Failed to allocate memory for integer array\n");
        return -1;
    }
