// Structure to hold network interface configuration data
typedef struct {
    char name[256]; // Name of the network interface
    int num_ips; // Number of IP addresses associated with the interface
    char ips[10][46]; // Array of IP addresses associated with the interface
    int num_ports; // Number of ports associated with the interface
    char ports[10][11]; // Array of ports associated with the interface
} network_interface_t;

// Structure to hold data for all configured network interfaces
typedef struct {
    size_t num_interfaces; // Number of configured network interfaces
    network_interface_t *interfaces; // Array of pointers to network interface structures
} network_config_t;

// Global variable to store the configuration data
network_config_t config = {0};

// Mutex for synchronizing access to the configuration data
pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;

// Semaphore for signaling when new interface configurations are available
semaphore_t new_interface_config = SEMAPHORE_INITIALIZER(0);

// Function to add a new network interface configuration
void add_network_interface(const char *name, int num_ips, char ips[10][46], int num_ports, char ports[10][11]) {
    // Acquire the mutex for accessing the configuration data
    pthread_mutex_lock(&config_lock);

    // Allocate memory for the new network interface structure
    config.num_interfaces++;
    config.interfaces = realloc(config.interfaces, config.num_interfaces * sizeof(network_interface_t));
    network_interface_t *new_interface = &config.interfaces[config.num_interfaces - 1];

    // Copy the interface name and IP addresses into the new structure
    strcpy(new_interface->name, name);
    new_interface->num_ips = num_ips;
    for (int i = 0; i < num_ips; i++) {
        strcpy(new_interface->ips[i], ips[i]);
    }

    // Copy the port information into the new structure
    new_interface->num_ports = num_ports;
    for (int j = 0; j < num_ports; j++) {
        strcpy(new_interface->ports[j], ports[j]);
    }

    // Release the mutex and signal that new interface configurations are available
    pthread_mutex_unlock(&config_lock);
    semaphore_post(&new_interface_config);
}

// Function to update an existing network interface configuration
void update_network_interface(int index, const char *name, int num_ips, char ips[10][46], int num_ports, char ports[10][11]) {
    // Acquire the mutex for accessing the configuration data
    pthread_mutex_lock(&config_lock);

    // Check if the index is within bounds
    if (index < 0 || index >= config.num_interfaces) {
        printf("Error: Invalid interface index\n");
        pthread_mutex_unlock(&config_lock);
        return;
    }

    // Update the interface name and IP addresses
    strcpy(config.interfaces[index].name, name);
    config.interfaces[index].num_ips = num_ips;
    for (int i = 0; i < num_ips; i++) {
        strcpy(config.interfaces[index].ips[i], ips[i]);
    }

    // Update the port information
    config.interfaces[index].num_ports = num_ports;
    for (int j = 0; j < num_ports; j++) {
        strcpy(config.interfaces[index].ports[j], ports[j]);
    }

    // Release the mutex and signal that new interface configurations are available
    pthread_mutex_unlock(&config_lock);
    semaphore_post(&new_interface_config);
}

// Function to retrieve a network interface configuration by index
const char *get_network_interface(int index) {
    // Acquire the mutex for accessing the configuration data
    pthread_mutex_lock(&config_lock);

    // Check if the index is within bounds
    if (index < 0 || index >= config.num_interfaces) {
        printf("Error: Invalid interface index\n");
        pthread_mutex_unlock(&config_lock);
        return NULL;
    }

    // Return a pointer to the network interface structure
    const char *interface = &config.interfaces[index];

    // Release the mutex and signal that new interface configurations are available
    pthread_mutex_unlock(&config_lock);
    semaphore_post(&new_interface_config);

    return interface;
}

// Function to retrieve all network interfaces as a list of pointers
const char **get_all_network_interfaces() {
    // Acquire the mutex for accessing the configuration data
    pthread_mutex_lock(&config_lock);

    // Allocate memory for the list of pointers
    const char **interfaces = malloc(config.num_interfaces * sizeof(const char *));

    // Copy the network interface structures into the list of pointers
    for (int i = 0; i < config.num_interfaces; i++) {
        interfaces[i] = &config.interfaces[i];
    }

    // Release the mutex and signal that new interface configurations are available
    pthread_mutex_unlock(&config_lock);
    semaphore_post(&new_interface_config);

    return interfaces;
}

// Function to release all network interfaces as a list of pointers
void release_all_network_interfaces(const char **interfaces) {
    // Acquire the mutex for accessing the configuration data
    pthread_mutex_lock(&config_lock);

    // Release the memory allocated for the list of pointers
    free(interfaces);

    // Release the mutex and signal that new interface configurations are available
    pthread_mutex_unlock(&config_lock);
    semaphore_post(&new_interface_config);
}
