typedef struct {
  int cell_id;
  int phy_channel_bandwidth;
  int crs_power_level;
} LTEPHYRACHConfig_t;

LTEPHYRACHConfig_t* initAndPopulateDynamicArray(int num_cells) {
  // Allocate memory for the dynamic array of LTEPHYRACHConfig_t structures
  LTEPHYRACHConfig_t *rach_config = (LTEPHYRACHConfig_t*) malloc(num_cells * sizeof(LTEPHYRACHConfig_t));

  // Initialize the dynamic array with valid cell identities, physical layer channel configuration parameters, and CRS power levels
  for (int i = 0; i < num_cells; i++) {
    rach_config[i].cell_id = i + 1;
    rach_config[i].phy_channel_bandwidth = pow(2, floor(log2(num_cells / 2)) + 1);
    rach_config[i].crs_power_level = 30 - (rach_config[i].cell_id % 5) * 5;
  }

  // Ensure that cell identities do not conflict within the same bandwidth part
  for (int i = 0; i < num_cells - 1; i++) {
    for (int j = i + 1; j < num_cells; j++) {
      if ((rach_config[i].cell_id % rach_config[j].phy_channel_bandwidth) ==
          (rach_config[j].cell_id % rach_config[i].phy_channel_bandwidth)) {
        rach_config[i].cell_id += 1;
      }
    }
  }

  // Manage memory allocation efficiently to minimize fragmentation and optimize performance under varying network loads
  for (int i = 0; i < num_cells; i++) {
    rach_config[i].crs_power_level = rach_config[i].crs_power_level * (1 - pow(10, -3) / pow(rach_config[i].phy_channel_bandwidth, 2));
  }

  // Return the initialized and populated dynamic array of LTEPHYRACHConfig_t structures
  return rach_config;
}
