        initChunks(&packet->chunks, 1);
        if (packet->chunks == NULL) {
            return;
        }
    } else {
        DataChunk* new_chunk = malloc(sizeof(DataChunk));
        if (new_chunk == NULL) {
            return;
        }
        memset(new_chunk, 0, sizeof(DataChunk));
        packet->chunks = realloc(packet->chunks, (packet->count + 1) * sizeof(DataChunk*));
        if (packet->chunks == NULL) {
            free(new_chunk);
            return;
        }
        packet->chunks[packet->count++] = new_chunk;
    }
    packet->chunks[packet->count - 1]->data = malloc(length);
    if (packet->chunks[packet->count - 1]->data == NULL) {
        freeChunks(&packet->chunks);
        return;
    }
    memcpy(packet->chunks[packet->count - 1]->data, data, length);
    packet->chunks[packet->count - 1]->length = length;
    packet->chunks[packet->count - 1]->checksum = calculateChecksum(data, length);
}

void removeDataChunk(DataPacket* packet, size_t index) {
    assert(packet != NULL);
    if (index >= packet->count) {
        return;
    }
    free(packet->chunks[index]->data);
    packet->chunks[index] = NULL;
    for (size_t i = index + 1; i < packet->count; ++i) {
        memcpy(&packet->chunks[i - 1], &packet->chunks[i], sizeof(DataChunk*));
    }
    --packet->count;
}
