// Function to initialize and populate a doubly linked list of DataPackets
void init_list(int max_packets) {
    // Allocate memory for the linked list head node
    head = malloc(sizeof(ListNode));
    assert(head != NULL);

    // Initialize the head node
    head->prev = NULL;
    head->next = NULL;
    head->packet = NULL;

    // Set the maximum number of packets to be stored in the list
    if (max_packets > 0) {
        head->max_packets = max_packets;
    } else {
        head->max_packets = INT_MAX;
    }
}

// Function to insert a new DataPacket into the linked list
void insert_packet(DataPacket* packet) {
    // Check if the list is full
    if (head->packet_count == head->max_packets) {
        // Remove the oldest packet from the list
        ListNode* oldest = head;
        while (oldest->next != NULL && oldest->next->packet_count < head->min_packet_count) {
            oldest = oldest->next;
        }
        free(oldest->packet);
        oldest->prev->next = oldest->next;
        if (head->next == oldest) {
            head->next = NULL;
        }
    }

    // Allocate memory for the new packet node
    ListNode* new_node = malloc(sizeof(ListNode));
    assert(new_node != NULL);

    // Initialize the new packet node
    new_node->prev = head->prev;
    new_node->next = head;
    new_node->packet = packet;

    // Update the linked list pointers
    head->prev->next = new_node;
    head->prev = new_node;
}

// Function to remove a DataPacket from the linked list
void remove_packet(int id) {
    ListNode* node = head;
    while (node != NULL && node->packet->id != id) {
        node = node->next;
    }
    if (node == NULL) {
        return;
    }
    // Update the linked list pointers
    node->prev->next = node->next;
    if (head->next == node) {
        head->next = NULL;
    }
    free(node->packet);
    free(node);
}

// Function to get a DataPacket from the linked list by ID
DataPacket* get_packet(int id) {
    ListNode* node = head;
    while (node != NULL && node->packet->id != id) {
        node = node->next;
    }
    if (node == NULL) {
        return NULL;
    }
    return node->packet;
}

// Function to query the number of DataPackets currently stored in the linked list
int get_packet_count() {
    return head->packet_count;
}

// Function to validate a DataChunk by recalculating its checksum and comparing it with the stored value
