// Define a structure to store records
typedef struct {
    int key;
    long offset;
} record_t;

// Function to validate the data integrity of the arrays
void validate_data(record_t** offsets, record_t** keys, size_t num_records) {
    // Iterate over each record and check for invalid values
    for (size_t i = 0; i < num_records; i++) {
        if (!offsets[i] || !keys[i]) {
            printf("Invalid data found at index %zu\n", i);
            return;
        }
    }
}

// Function to initialize an array of 'record' structures
void init_records(size_t num_records, record_t** records) {
    // Allocate memory for the records array
    *records = (record_t*)malloc(num_records * sizeof(record_t));
    if (!*records) {
        printf("Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize each record with a random integer value within the range specified by the user
    for (size_t i = 0; i < num_records; i++) {
        (*records)[i].key = rand() % MAX_RANDOM_VALUE;
        (*records)[i].offset = 0;
    }
}

// Function to read the data from the CSV file and populate the arrays
void read_data(const char* filename, size_t num_records, record_t** offsets, record_t** keys) {
    // Open the input file in binary mode
    FILE* file = fopen(filename, "rb");
    if (!file) {
        printf("Error opening input file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Read the data from the file and populate the arrays
    for (size_t i = 0; i < num_records; i++) {
        // Read the offset value from the file
        fread(&(*offsets)[i], sizeof(long), 1, file);

        // Read the key value from the file
        fread(&(*keys)[i], sizeof(int), 1, file);
    }

    // Close the input file
    fclose(file);
}

// Function to write the data back to a new output file in the specified format
void write_data(const char* filename, size_t num_records, record_t** offsets, record_t** keys) {
    // Open the output file in binary mode
    FILE* file = fopen(filename, "wb");
    if (!file) {
        printf("Error opening output file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Write the data to the output file in the specified format
    for (size_t i = 0; i < num_records; i++) {
        // Write the offset value to the file
        fwrite(&(*offsets)[i], sizeof(long), 1, file);

        // Write the key value to the file
        fwrite(&(*keys)[i], sizeof(int), 1, file);
    }

    // Close the output file
    fclose(file);
}

// Main function
int main(int argc, char* argv[]) {
    // Check for the correct number of arguments
    if (argc != 4) {
        printf("Usage: %s <input_filename> <output_filename> <max_random_value>\n", argv[0]);
        return EXIT_FAILURE;
    }

    // Get the input and output filenames and the maximum random value from the command line arguments
    const char* input_filename = argv[1];
    const char* output_filename = argv[2];
    int max_random_value = atoi(argv[3]);

    // Get the number of records from the input file
    size_t num_records = 0;
    FILE* file = fopen(input_filename, "rb");
    if (!file) {
        printf("Error opening input file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    while (fread(&num_records, sizeof(size_t), 1, file)) {}
    fclose(file);

    // Allocate memory for the offset and key arrays
    record_t* offsets = NULL;
    record_t* keys = NULL;
    init_records(num_records, &offsets, &keys);

    // Read the data from the input file and populate the arrays
    read_data(input_filename, num_records, &offsets, &keys);

    // Validate the data integrity of the arrays
    validate_data(&offsets, &keys, num_records);

    // Initialize an array of 'record' structures to store intermediate results
    record_t* records = NULL;
    init_records(num_records, &records);

    // Populate the 'records' array with random integer values within the range specified by the user
    for (size_t i = 0; i < num_records; i++) {
        records[i].key = rand() % max_random_value;
        records[i].offset = 0;
    }

    // Write the data back to a new output file in the specified format
    write_data(output_filename, num_records, &offsets, &keys);

    // Free memory allocated for the arrays
    free(offsets);
    free(keys);
    free(records);

    return EXIT_SUCCESS;
}
