    // Initialize the head node with default values
    (*head)->packet_id = 0;
    (*head)->timestamp = 0;
    (*head)->chunks = NULL;

    // Set the next and previous pointers to NULL
    (*head)->next = NULL;
    (*head)->prev = NULL;
