// Function to add a new packet to the linked list
void add_packet(DataPacket **head, int packet_id, long timestamp) {
    // Create a new node for the packet
    DataPacket *new_node = (DataPacket *)malloc(sizeof(DataPacket));

    // Initialize the node with the given values
    new_node->packet_id = packet_id;
    new_node->timestamp = timestamp;
    new_node->chunks = NULL;

    // Set the next and previous pointers to NULL
    new_node->next = NULL;
    new_node->prev = NULL;

