    new_chunk->checksum = checksum;

    // Add the new chunk to the linked list of chunks
    if ((*head)->chunks == NULL) {
        (*head)->chunks = new_chunk;
    } else {
        new_chunk->next = (*head)->chunks;
        (*head)->chunks->prev = new_chunk;
        (*head)->chunks = new_chunk;
