    } else {
        // Update existing entry in the array
        arr->data[arr->size - 1].PCI = PCI;
        arr->data[arr->size - 1].ChannelQualityIndication = ChannelQualityIndication;
        arr->data[arr->size - 1].RSRP = RSRP;
    }
}

