}

// Function to calculate RSRP based on cell identity and PCI
double calculateRSRP(int NRCellIdentity, int PCI) {
    // Calculate RSRP using a lookup table or a model
    return 10 * log10((float)NRCellIdentity / (PCI + 1));
}
