pthread_mutex_t longOffsetValuesLock; // Lock for long offset values array
pthread_mutex_t intKeysLock; // Lock for int keys array

// Function to manage dynamic arrays of NRCellMeasurementResults structures
void manageNRCellMeasurements(const char* cellIdentity, int32_t pci, float channelQualityIndication, float rsrp) {
    bool cellExists = false; // Flag to indicate if the cell exists in the array
    size_t index = 0; // Index of the cell in the array

    // Check if the cell identity is already present in the array
    for (size_t i = 0; i < numMeasurements; i++) {
        if (measurementResults[i].nrCellIdentity == atoi(cellIdentity)) {
            index = i;
            cellExists = true;
            break;
        }
    }

    // If the cell does not exist, create a new entry in the array
    if (!cellExists) {
        measurementResults[numMeasurements].nrCellIdentity = atoi(cellIdentity);
        measurementResults[numMeasurements].pci = pci;
        measurementResults[numMeasurements].channelQualityIndication = channelQualityIndication;
        measurementResults[numMeasurements].rsrp = rsrp;
        numMeasurements++;
    } else { // If the cell already exists, update the existing entry
        measurementResults[index].pci = pci;
        measurementResults[index].channelQualityIndication = channelQualityIndication;
        measurementResults[index].rsrp = rsrp;
    }

    // Check if the long offset values need to be updated
    for (size_t i = 0; i < numLongOffsets; i++) {
        if (longOffsetValues[i].nrCellIdentity == atoi(cellIdentity)) {
            longOffsetValues[i].pci = pci;
            longOffsetValues[i].rsrp = rsrp;
        }
    }

    // Check if the int keys need to be updated
    for (size_t i = 0; i < numIntKeys; i++) {
        if (intKeys[i].nrCellIdentity == atoi(cellIdentity)) {
            intKeys[i].pci = pci;
        }
    }
}

// Function to synchronize the arrays with an external data source
void synchronizeArrays(const char* cellIdentities, int32_t pcis, float channelQualityIndications, float rsrps) {
    // Lock the measurementResults array
    pthread_mutex_lock(&measurementResultsLock);

    // Iterate over the cells and update or create new entries in the arrays
    for (size_t i = 0; i < numMeasurements; i++) {
        bool cellExists = false; // Flag to indicate if the cell exists in the array
        size_t index = 0; // Index of the cell in the array

        for (size_t j = 0; j < numLongOffsets; j++) {
            if (longOffsetValues[j].nrCellIdentity == atoi(cellIdentities[i])) {
                longOffsetValues[j].pci = pcis[i];
                longOffsetValues[j].rsrp = rsrps[i];
            }
        }

        for (size_t j = 0; j < numIntKeys; j++) {
            if (intKeys[j].nrCellIdentity == atoi(cellIdentities[i])) {
                intKeys[j].pci = pcis[i];
            }
        }
    }

    // Unlock the measurementResults array
    pthread_mutex_unlock(&measurementResultsLock);
}
