#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// Define data structures for storing offsets, keys, and transactions
typedef struct offset {
    long val;
} Offset;

typedef struct key {
    int val;
} Key;

typedef struct transaction {
    double amount;
    char* user_id;
} Transaction;

typedef struct log_entry {
    char* timestamp;
    Transaction* transaction;
} LogEntry;

// Define function to manage memory for variable number of data structures
void* manage_memory(int num_offsets, int num_keys, int num_transactions, int num_logs) {
    // Allocate memory for offsets and keys arrays
    Offset* offsets = (Offset*)malloc(num_offsets * sizeof(Offset));
    Key* keys = (Key*)malloc(num_keys * sizeof(Key));

    // Initialize offset values to zero
    for (int i = 0; i < num_offsets; i++) {
        offsets[i].val = 0;
    }

    // Initialize key values randomly within specified range
    srand(time(NULL));
    for (int i = 0; i < num_keys; i++) {
        keys[i].val = rand() % 100 + 1;
    }

    // Allocate memory for transactions array
    Transaction* transactions = (Transaction*)malloc(num_transactions * sizeof(Transaction));

    // Initialize transaction amounts randomly within specified range
    for (int i = 0; i < num_transactions; i++) {
        transactions[i].amount = rand() % 10000.0 + 1;
    }

    // Allocate memory for log entries array
    LogEntry* log_entries = (LogEntry*)malloc(num_logs * sizeof(LogEntry));

    // Initialize log entries with transactions and timestamps
    for (int i = 0; i < num_logs; i++) {
        Transaction* transaction = &transactions[i];
        char* timestamp = (char*)malloc(16);
        sprintf(timestamp, "%.4f", transaction->amount);
        log_entries[i].transaction = transaction;
        log_entries[i].timestamp = timestamp;
    }

    // Return memory pointer for log entries array
    return (void*)log_entries;
}
```
