#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include "NFAPI_CRC_INDICATION_PDU_T.h"

typedef struct {
  NFAPI_CRC_INDICATION_PDU_T *data;
  int size;
  sem_t lock;
} NFAPI_CRC_INDICATION_PDU_LIST;

NFAPI_CRC_INDICATION_PDU_LIST* create_list() {
  NFAPI_CRC_INDICATION_PDU_LIST *list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_LIST));
  list->data = NULL;
  list->size = 0;
  if (sem_init(&list->lock, 1, 1) < 0) {
    perror("Error creating semaphore");
    return NULL;
  }
  return list;
}

void destroy_list(NFAPI_CRC_INDICATION_PDU_LIST *list) {
  if (sem_destroy(&list->lock) < 0) {
    perror("Error destroying semaphore");
  }
  free(list);
}

void add_element(NFAPI_CRC_INDICATION_PDU_LIST *list, NFAPI_CRC_INDICATION_PDU_T element) {
  if (sem_wait(&list->lock) < 0) {
    perror("Error waiting for semaphore");
  }
  list->data = realloc(list->data, (list->size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
  if (!list->data) {
    perror("Error allocating memory for data");
    exit(1);
  }
  list->data[list->size] = element;
  list->size++;
  if (sem_post(&list->lock) < 0) {
    perror("Error posting semaphore");
  }
}

void remove_element(NFAPI_CRC_INDICATION_PDU_LIST *list, int index) {
  if (index >= list->size || index < 0) {
    return;
  }
  if (sem_wait(&list->lock) < 0) {
    perror("Error waiting for semaphore");
  }
  NFAPI_CRC_INDICATION_PDU_T *data = list->data + index;
  memmove(data, data + 1, (list->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
  list->size--;
  if (sem_post(&list->lock) < 0) {
    perror("Error posting semaphore");
  }
}

void remove_all(NFAPI_CRC_INDICATION_PDU_LIST *list) {
  if (sem_wait(&list->lock) < 0) {
    perror("Error waiting for semaphore");
  }
  list->size = 0;
  free(list->data);
  list->data = NULL;
  if (sem_post(&list->lock) < 0) {
    perror("Error posting semaphore");
  }
}
