// Function to create a new session state structure
UeSessionState* create_session_state() {
    UeSessionState* state = (UeSessionState*)malloc(sizeof(UeSessionState));
    if (state == NULL) {
        return NULL;
    }
    state->rrc_connection_state.connected = false;
    state->rrc_connection_info.is_registered = false;
    state->rrc_connection_config.max_megabits = 0;
    return state;
}

// Function to add a new session state to the dynamic array
void add_session_state(struct UeSessionStateArray* array, UeSessionState* state) {
    if (array->size == array->capacity) {
        // Increase capacity by 50% when it reaches its maximum size
        int new_capacity = array->capacity * 1.5;
        UeSessionState* new_elements = (UeSessionState*)realloc(array->elements, sizeof(UeSessionState) * new_capacity);
        if (new_elements == NULL) {
            free(state);
            return;
        }
        array->elements = new_elements;
        array->capacity = new_capacity;
    }
    array->elements[array->size++] = *state;
}

// Function to remove a session state from the dynamic array
void remove_session_state(struct UeSessionStateArray* array, int index) {
    if (index < 0 || index >= array->size) {
        return;
    }
    UeSessionState* last = &array->elements[array->size - 1];
    memcpy(&array->elements[index], last, sizeof(UeSessionState));
    free(last);
    array->size--;
}

