  memset(statusFlags, OK, num_devices * num_sensors * sizeof(enum status_flag));

  // Allocate memory for the device ID array
  int *deviceIds = (int *)malloc(num_devices * sizeof(int));
  memset(deviceIds, 0, num_devices * sizeof(int));

  // Initialize the sensor data array
  sensorData *sensorDataArray = (sensorData *)malloc(num_devices * num_sensors * sizeof(sensorData));
  for (int i = 0; i < num_devices; ++i) {
    for (int j = 0; j < num_sensors; ++j) {
      sensorDataArray[i * num_sensors + j] = {timestamps[i], sensorReadings[i * num_sensors + j], deviceIds[i], statusFlags[i * num_sensors + j]};
    }
  }

  // Integrate with external API to fetch real-time device metadata
  // ...
}

// Function to set the status flag based on average sensor reading over a specified time window
void setStatusFlag(sensorData *sensorDataArray, int num_devices, int num_sensors) {
  for (int i = 0; i < num_devices; ++i) {
    float avgReading = 0.0f;
    for (int j = 0; j < num_sensors; ++j) {
      avgReading += sensorDataArray[i * num_sensors + j].reading;
    }
    avgReading /= num_sensors;

    // Set the status flag based on the average reading and a specified time window
    if (avgReading < 10.0f) {
      sensorDataArray[i * num_sensors].status = OK;
    } else if (avgReading < 20.0f) {
      sensorDataArray[i * num_sensors].status = WARNING;
    } else {
      sensorDataArray[i * num_sensors].status = ERROR;
    }
  }
}

// Main function to demonstrate usage of the initArrays and setStatusFlag functions
