        if (ret == -1) {
            LOG_ERROR("Failed to wait on semaphore: %s", strerror(errno));
            continue;
        }

        pthread_mutex_lock(&mutex);
        if (!pdu) {
            CHECK_NULL(pdu = calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T)));
        } else {
