        if (!pdu[i].CRC_INDICATION_REL8_TAG) {
            CHECK_ZERO(pdu[i].CRC_INDICATION_REL8_TAG = json_integer_value(json_CRC_INDICATION_REL8_TAG));
        }
        if (!pdu[i].CRCFLAG) {
            CHECK_NULL(pdu[i].CRCFLAG = json_is_true(json_CRCFLAG) ? 1 : 0);
        }
    }

    pthread_mutex_lock(&mutex);
    if (pdu && i > 0) {
        CHECK_NULL(pdu = realloc(pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (i + 1)));
    }
    pthread_mutex_unlock(&mutex);

    if (semaphore && i > 0) {
        sem_post(semaphore);
    }
}

int main() {
    // Initialize the mutex and semaphore
    pthread_mutex_init(&mutex, NULL);
    semaphore = sem_open("/nfaapi_crc_indication", O_CREAT, 0644, MAX_NFAPI_CRC_INDICATION_PDU);

    // Load the JSON data from a file
    json_loadf("example.json");

    // Clean up
    pthread_mutex_destroy(&mutex);
    sem_close(semaphore);
}
