        new_context->cell_id = new_ue_context_info.cell_id;
        new_context->downlink_mac_pdu = malloc(new_ue_context_info.downlink_mac_pdu_size);
        if (!new_context->downlink_mac_pdu) {
            fprintf(stderr, "Error: failed to allocate memory for downlink MAC PDU\n");
            exit(1);
        }

        // Add the new context to the array of UE contexts
        if (num_ue_contexts == max_num_ue_contexts) {
            fprintf(stderr, "Error: maximum number of UE contexts exceeded\n");
            exit(1);
        }
        ue_contexts[num_ue_contexts] = new_context;
        num_ue_contexts++;
    }

    // Remove expired UE contexts from the array
    for (size_t i = 0; i < num_ue_contexts; i++) {
        if (ue_contexts[i]->expiry_time <= time(NULL)) {
