// Define the doubly linked list structure for storing NFAPI_CRC_INDICATION_PDU_T structures
typedef struct Node {
  CRC_INDICATION_REL8_TAG data;
  struct Node* next;
  struct Node* prev;
} Node;

// Define the function to generate random seeds for RX_UE_INFORMATION_TAG and RNTI
uint32_t generateSeed() {
  // Use a default seed value if external seed generation fails
  uint32_t seed = time(NULL);
  return seed;
}

// Define the function to construct a list of NFAPI_CRC_INDICATION_PDU_T structures
void generateNFAPCRawData(uint16_t numPDUs, Node** head) {
  // Initialize the doubly linked list with an initial value
  *head = NULL;

  // Loop through each integer parameter and validate it
  for (int i = 0; i < numPDUs; i++) {
    // Generate a random RX_UE_INFORMATION_TAG and RNTI using the external API or default seed value
    uint16_t RX_UE_INFORMATION_TAG = generateSeed();
    uint32_t RNTI = generateSeed();

    // Set a random CRCFLAG value
    uint8_t CRCFLAG = (uint8_t)((rand() % 100) > 50 ? 1 : 0);

