    Node* node = malloc(sizeof(Node));
    node->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    node->data.RNTI = RNTI;
    node->data.CRCFLAG = CRCFLAG;
    node->next = *head;
    node->prev = NULL;
    if (*head != NULL) {
      (*head)->prev = node;
    }
    *head = node;
  }

  // Log the module name and each test to the console
  printf("generateNFAPCRawData: %d PDUs generated\n", numPDUs);

  // Use a semaphore to manage concurrent access to the list
  sem_t* sem = sem_open("/sem", O_CREAT, 0644, 1);
  if (sem == SEM_FAILED) {
    perror("sem_open");
    return;
  }

  // Cleanup the environment for subsequent tests
  sem_wait(sem);
  Node* current = *head;
  while (current != NULL) {
    Node* next = current->next;
    free(current);
    current = next;
  }
  *head = NULL;

  // Print statistics for the largest integer in the list
  printf("generateNFAPCRawData: Largest integer is %d\n", numPDUs);
  printf("generateNFAPCRawData: Average is %f, median is %f\n", average(numPDUs), median(numPDUs));

  // Close the semaphore and return
  sem_close(sem);
  return;
}

// Define the function to calculate the average of a list of integers
float average(uint16_t numPDUs) {
  float sum = 0.0f;
  for (int i = 0; i < numPDUs; i++) {
    sum += i;
  }
  return sum / numPDUs;
}

// Define the function to calculate the median of a list of integers
float median(uint16_t numPDUs) {
  // Sort the list of integers in ascending order
  Node* current = *head;
  Node* previous = NULL;
  while (current != NULL) {
    if (previous == NULL || previous->data.RX_UE_INFORMATION_TAG > current->data.RX_UE_INFORMATION_TAG) {
      previous = current;
    } else {
      Node* temp = previous->next;
      previous->next = current;
      current->prev = previous;
      current->next = temp;
    }
    current = current->next;
  }

  // Find the median integer
  if (numPDUs % 2 == 0) {
    return (previous->data.RX_UE_INFORMATION_TAG + previous->prev->data.RX_UE_INFORMATION_TAG) / 2;
  } else {
    return previous->data.RX_UE_INFORMATION_TAG;
  }
}
