// Define the maximum number of structures to store in memory
#define MAX_STRUCTURES 10000

// Structure to represent an NFAPI CRC indication PDU
typedef struct {
    int crc;
    int len;
    unsigned char *data;
} NFAPI_CRC_INDICATION_PDU_T;

// Global variable to store the list of structures
NFAPI_CRC_INDICATION_PDU_T *structures = NULL;

// Semaphore to synchronize access to the list of structures
sem_t sem;

// Function to add a new structure to the list
void add_structure(int crc, int len, unsigned char *data) {
    // Lock the semaphore to ensure thread-safe operation
    sem_wait(&sem);

    // Check if we have reached the maximum number of structures in memory
    if (structures == NULL || num_structures >= MAX_STRUCTURES) {
        // If so, log an error and return
        fprintf(stderr, "Error: Maximum number of structures exceeded\n");
        sem_post(&sem);
        return;
    }

    // Allocate memory for the new structure
    NFAPI_CRC_INDICATION_PDU_T *new_structure = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_structure == NULL) {
        // If allocation fails, log an error and return
        fprintf(stderr, "Error: Allocation failed\n");
        sem_post(&sem);
        return;
    }

    // Set the fields of the new structure
    new_structure->crc = crc;
    new_structure->len = len;
    new_structure->data = data;

    // Add the new structure to the list
    if (structures == NULL) {
        structures = new_structure;
    } else {
        struct NFAPI_CRC_INDICATION_PDU_T *current = structures;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_structure;
    }

    // Increment the number of structures in memory
    num_structures++;

    // Unlock the semaphore
    sem_post(&sem);
}

// Function to remove a structure from the list
void remove_structure(NFAPI_CRC_INDICATION_PDU_T *structure) {
    // Lock the semaphore to ensure thread-safe operation
    sem_wait(&sem);

    // Find the structure in the list and remove it
    struct NFAPI_CRC_INDICATION_PDU_T *current = structures;
    while (current != NULL && current->next != structure) {
        current = current->next;
    }
    if (current == NULL) {
        fprintf(stderr, "Error: Structure not found\n");
        sem_post(&sem);
        return;
    }
    current->next = current->next->next;

    // Decrement the number of structures in memory
    num_structures--;

    // Free the memory allocated for the structure
    free(structure);

    // Unlock the semaphore
    sem_post(&sem);
}

// Function to get the head of the list
NFAPI_CRC_INDICATION_PDU_T *get_head() {
    return structures;
}

// Function to get the next structure in the list
NFAPI_CRC_INDICATION_PDU_T *get_next(NFAPI_CRC_INDICATION_PDU_T *structure) {
    return structure->next;
}

// Function to get the number of structures in memory
int get_num_structures() {
    return num_structures;
}

// Function to log an error message and increment the error counter
void log_error(char *message) {
    fprintf(stderr, "Error: %s\n", message);
    error_counter++;
}

// Function to monitor operation details and facilitate debugging and performance analysis
void monitor() {
    time_t current_time = time(NULL);
    struct tm *time_info = localtime(&current_time);
    fprintf(stderr, "Monitor: Time: %d-%02d-%02d %02d:%02d:%02d, Num Structures: %d\n",
            time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday,
            time_info->tm_hour, time_info->tm_min, time_info->tm_sec, num_structures);
}
