typedef struct {
    char *str;
    unsigned int id;
} item_t;

void manageDynamicCollection(int numItems, int strLen) {
    // Allocate memory for the collection of items
    item_t *items = malloc(numItems * sizeof(item_t));

    // Populate each string with random alphanumeric characters of varying lengths
    for (int i = 0; i < numItems; i++) {
        items[i].str = generateRandomString(strLen);
        items[i].id = i + 1;
    }

    // Free the memory when the collection is no longer needed
    free(items);
}

char *generateRandomString(int len) {
    char *str = malloc((len + 1) * sizeof(char));
    for (int i = 0; i < len; i++) {
        str[i] = 'a' + rand() % ('z' - 'a' + 1);
    }
    str[len] = '\0';
    return str;
}
