typedef struct NFAPI_MESSAGE_PDU_T_Node {
    struct NFAPI_MESSAGE_PDU_T *data;
    struct NFAPI_MESSAGE_PDU_T_Node *next;
} NFAPI_MESSAGE_PDU_T_Node;

typedef struct DL_FRAME_PDU_T_Node {
    struct DL_FRAME_PDU_T *data;
    struct DL_FRAME_PDU_T_Node *next;
} DL_FRAME_PDU_T_Node;

typedef struct NFAPI_MESSAGE_PDU_T_Table {
    pthread_mutex_t lock;
    int size;
    NFAPI_MESSAGE_PDU_T_Node *head;
} NFAPI_MESSAGE_PDU_T_Table;

typedef struct DL_FRAME_PDU_T_Table {
    pthread_mutex_t lock;
    int size;
    DL_FRAME_PDU_T_Node *head;
} DL_FRAME_PDU_T_Table;

void NFAPI_MESSAGE_PDU_T_init(NFAPI_MESSAGE_PDU_T_Table *table) {
    table->size = 0;
    table->head = NULL;
}

int NFAPI_MESSAGE_PDU_T_add(NFAPI_MESSAGE_PDU_T_Table *table, struct NFAPI_MESSAGE_PDU_T *data) {
    pthread_mutex_lock(&table->lock);
    if (table->size >= 10000000) { // Remove the oldest entry if the table is full
        NFAPI_MESSAGE_PDU_T_Node *oldest = table->head;
        while (oldest->next != NULL) {
            oldest = oldest->next;
        }
        table->head = oldest->prev;
        table->size--;
    }
    NFAPI_MESSAGE_PDU_T_Node *new_node = malloc(sizeof(NFAPI_MESSAGE_PDU_T_Node));
    new_node->data = data;
    if (table->head == NULL) {
        table->head = new_node;
    } else {
        NFAPI_MESSAGE_PDU_T_Node *current = table->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
        new_node->prev = current;
    }
    table->size++;
    pthread_mutex_unlock(&table->lock);
}

struct NFAPI_MESSAGE_PDU_T *NFAPI_MESSAGE_PDU_T_get(NFAPI_MESSAGE_PDU_T_Table *table, int id) {
    pthread_mutex_lock(&table->lock);
    NFAPI_MESSAGE_PDU_T_Node *current = table->head;
    while (current != NULL) {
        if (current->data->ue_context == id) {
            pthread_mutex_unlock(&table->lock);
            return current->data;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&table->lock);
    return NULL;
}

int NFAPI_MESSAGE_PDU_T_remove(NFAPI_MESSAGE_PDU_T_Table *table, int id) {
    pthread_mutex_lock(&table->lock);
    NFAPI_MESSAGE_PDU_T_Node *current = table->head;
    while (current != NULL) {
        if (current->data->ue_context == id) {
            NFAPI_MESSAGE_PDU_T_Node *prev = current->prev;
            prev->next = current->next;
            free(current);
            table->size--;
            pthread_mutex_unlock(&table->lock);
            return 0;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&table->lock);
    return -1;
}

