pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
void lock() { pthread_mutex_lock(&mutex); }
void unlock() { pthread_mutex_unlock(&mutex); }
void signal() { pthread_cond_signal(&cond); }

// Implement the C function to dynamically allocate memory for and initialize three separate data structures: an array of long offsets, an array of int keys, and a linked list of record structures.
void initialize_data(array_t *array) {
    // Initialize arrays for storing offsets, keys, and records
    array->offsets = malloc(sizeof(long) * 10000);
    array->keys = malloc(sizeof(int) * 10000);
    array->records = malloc(sizeof(record_t) * 10000);

    // Initialize the size of each data structure to zero
    array->size = 0;

    // Initialize mutex and condition variables for concurrency management
    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond, NULL);
}

// Add a new record to the data structure. If the size of the array reaches its capacity, the function will reallocate the memory and update the offsets array accordingly.
void add_record(array_t *array, int key, int value) {
    lock();

    // Check if the size of the array has reached its capacity and reallocate the memory if necessary
    if (array->size >= array->capacity) {
        array->capacity = array->capacity * 2;
        array->offsets = realloc(array->offsets, sizeof(long) * array->capacity);
        array->keys = realloc(array->keys, sizeof(int) * array->capacity);
        array->records = realloc(array->records, sizeof(record_t) * array->capacity);
    }

    // Store the offset of the new record in the offsets array
    long offset = (long)(&(array->records[array->size])) - (long)(&(array->records[0]));
    array->offsets[array->size] = offset;

    // Store the key and value of the new record in the keys and records arrays
    array->keys[array->size] = key;
    array->records[array->size].value = value;

    // Increment the size of the array
    array->size++;

    unlock();
}

// Retrieve a record from the data structure. If the specified key is not found, the function will return NULL.
int get_record(array_t *array, int key) {
    lock();

    // Iterate over the keys array until the specified key is found
    for (int i = 0; i < array->size; i++) {
        if (array->keys[i] == key) {
            int offset = array->offsets[i];
            record_t *record = &(array->records[offset]);
            unlock();
            return record->value;
        }
    }

    // If the specified key is not found, return NULL
    unlock();
    return NULL;
}

// Remove a record from the data structure. If the specified key is not found, the function will do nothing.
void remove_record(array_t *array, int key) {
    lock();

    // Iterate over the keys array until the specified key is found
    for (int i = 0; i < array->size; i++) {
        if (array->keys[i] == key) {
            long offset = array->offsets[i];
            record_t *record = &(array->records[offset]);

            // Update the offsets and keys arrays by shifting subsequent elements backwards
            for (int j = i + 1; j < array->size; j++) {
                array->offsets[j - 1] = array->offsets[j];
                array->keys[j - 1] = array->keys[j];
            }

            // Decrement the size of the array and reallocate memory if necessary
            array->size--;
            if (array->size < array->capacity / 2) {
                array->capacity = array->capacity / 2;
                array->offsets = realloc(array->offsets, sizeof(long) * array->capacity);
                array->keys = realloc(array->keys, sizeof(int) * array->capacity);
                array->records = realloc(array->records, sizeof(record_t) * array->capacity);
            }

            unlock();
            return;
        }
    }

    // If the specified key is not found, do nothing
    unlock();
}

// Traverse the linked list of records in forward order and apply a callback function to each record.
void traverse_forward(array_t *array, void (*callback)(record_t)) {
    lock();

    // Iterate over the offsets array and retrieve the next record for the specified key
    for (int i = 0; i < array->size; i++) {
        long offset = array->offsets[i];
        record_t *record = &(array->records[offset]);

        // Apply the callback function to the current record
        (*callback)(*record);
    }

    unlock();
}

// Traverse the linked list of records in reverse order and apply a callback function to each record.
void traverse_reverse(array_t *array, void (*callback)(record_t)) {
    lock();

    // Iterate over the offsets array and retrieve the previous record for the specified key
    for (int i = array->size - 1; i >= 0; i--) {
        long offset = array->offsets[i];
        record_t *record = &(array->records[offset]);

        // Apply the callback function to the current record
        (*callback)(*record);
    }

    unlock();
}

// Free all memory allocated by the data structure.
void free_data_structure(array_t *array) {
    lock();

    // Free all memory allocated by the offsets, keys, and records arrays
    free(array->offsets);
    free(array->keys);
    free(array->records);

    unlock();
}

