    record->value = value;
    return record;
}

NFAPI_CRC_INDICATION_PDU_T* initialize_crc_indication_pdu(long RNTI, unsigned char CRC_INDICATION_REL8_TAG, bool CRCFLAG) {
    NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
