    if (!ptr) {
        printf("Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

record_t** initialize_records(int num_records, int value_range) {
    record_t **records = (record_t**) allocate_memory(sizeof(record_t*) * num_records);
    for (int i = 0; i < num_records; i++) {
        records[i] = initialize_record(value_range * ((float)rand() / RAND_MAX));
    }
    return records;
}

