// Function to traverse a finite state automaton and dynamically construct a state list
void traverseFSA(NFAPI_CRC_INDICATION_PDU_T *list, int size, int maxSize) {
    // Create an empty state list with the specified maximum size
    int *stateList = malloc(maxSize * sizeof(int));

    // Initialize the state list with the initial state
    stateList[0] = 1;
    int count = 1;

    // Traverse the FSA and dynamically construct the state list
    while (count < size) {
        // Determine the next state based on the current state and input conditions
        int nextState = getNextState(stateList[count - 1], list[count].RX_UE_INFORMATION_TAG, list[count].RNTI);

        // Add the next state to the state list if it is not already present
        if (!isInStateList(stateList, count, nextState)) {
            stateList[count] = nextState;
            count++;
        }
    }

    // Resize the state list if necessary
    if (count >= maxSize) {
        int *newStateList = realloc(stateList, count * sizeof(int));
        stateList = newStateList;
    }

    // Free the memory allocated for the state list
    free(stateList);
}

// Function to detect and handle invalid transitions within an FSA
void handleInvalidTransitions(NFAPI_CRC_INDICATION_PDU_T *list, int size) {
