    size_t count;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_LIST_T;

// Initialize the list data structure
NFAPI_CRC_INDICATION_LIST_T* nfapi_crc_indication_list_create() {
    NFAPI_CRC_INDICATION_LIST_T* list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) {
        // Handle memory allocation failure gracefully
        return NULL;
    }
    list->elements = NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Add an element to the list
void nfapi_crc_indication_list_add(NFAPI_CRC_INDICATION_LIST_T* list, RX_UE_INFORMATION_TAG tag, uint32_t rnti, CRC_INDICATION_REL8_TAG crcFlag) {
    pthread_mutex_lock(&list->mutex);
    // Allocate memory for the new element
    NFAPI_CRC_INDICATION_PDU_T* element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!element) {
        // Handle memory allocation failure gracefully
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    element->tag = tag;
    element->rnti = rnti;
    element->crcFlag = crcFlag;
    element->timestamp = time(NULL);
    // Add the new element to the list
    if (list->elements == NULL) {
        list->elements = element;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* current = list->elements;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = element;
    }
    list->count++;
    pthread_mutex_unlock(&list->mutex);
}

// Get the next element from the list, or NULL if there are no more elements
NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_list_get(NFAPI_CRC_INDICATION_LIST_T* list) {
    pthread_mutex_lock(&list->mutex);
    if (list->elements == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* element = list->elements;
    list->elements = element->next;
    element->next = NULL;
    list->count--;
    pthread_mutex_unlock(&list->mutex);
    return element;
}

// Destroy the list and free all allocated memory
void nfapi_crc_indication_list_destroy(NFAPI_CRC_INDICATION_LIST_T* list) {
    pthread_mutex_lock(&list->mutex);
    while (list->elements != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* element = list->elements;
        list->elements = element->next;
        free(element);
    }
    pthread_mutex_unlock(&list->mutex);
    free(list);
}
