// Define a structure to hold the NFAPI_L2_MEASUREMENTS data
typedef struct {
    unsigned long timestamp; // Time at which the measurement was taken, in seconds
    unsigned char measurementType; // Type of measurement (e.g., RSSI or CINR)
    void* payload; // Pointer to the variable-length data payload for this measurement
} NFAPI_L2_MEASUREMENTS;

// Define a linked list node structure to hold the measurements
typedef struct {
    NFAPI_L2_MEASUREMENTS measurement; // The actual measurement data
    struct Node* next; // Pointer to the next node in the list
} Node;

// Global variable to store the head of the linked list
Node* head = NULL;

// Function to add a new measurement to the list
void addMeasurement(unsigned long timestamp, unsigned char measurementType, void* payload) {
    // Create a new node for this measurement and allocate memory for its data
    Node* newNode = (Node*) malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Error: unable to allocate memory for the new node\n");
        return;
    }

    // Initialize the node with the given measurement data
    newNode->measurement.timestamp = timestamp;
    newNode->measurement.measurementType = measurementType;
    newNode->measurement.payload = payload;
    newNode->next = NULL;

    // Lock the list to prevent concurrent access from other threads
    pthread_mutex_lock(&head->mutex);

    // Add the new node to the end of the list
    Node* current = head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = newNode;

    // Unlock the list and return
    pthread_mutex_unlock(&head->mutex);
}

// Function to retrieve a measurement from the list by its timestamp
NFAPI_L2_MEASUREMENTS* getMeasurement(unsigned long timestamp) {
    // Lock the list to prevent concurrent access from other threads
    pthread_mutex_lock(&head->mutex);

    // Iterate through the list until we find a matching timestamp or reach the end of the list
    Node* current = head;
    while (current != NULL && current->measurement.timestamp < timestamp) {
        current = current->next;
    }

    // If we found a matching timestamp, return its measurement data
    if (current != NULL && current->measurement.timestamp == timestamp) {
        pthread_mutex_unlock(&head->mutex);
        return &(current->measurement);
    } else {
        // Otherwise, return NULL to indicate that no matching measurement was found
        pthread_mutex_unlock(&head->mutex);
        return NULL;
    }
}

// Function to delete a measurement from the list by its timestamp
void deleteMeasurement(unsigned long timestamp) {
    // Lock the list to prevent concurrent access from other threads
    pthread_mutex_lock(&head->mutex);

    // Iterate through the list until we find a matching timestamp or reach the end of the list
    Node* current = head;
    while (current != NULL && current->measurement.timestamp < timestamp) {
        current = current->next;
    }

    // If we found a matching timestamp, delete the corresponding node and update the list
    if (current != NULL && current->measurement.timestamp == timestamp) {
        Node* toDelete = current;
        current = current->next;
        pthread_mutex_unlock(&head->mutex);
        free(toDelete);
    } else {
        // Otherwise, unlock the list and indicate that no matching measurement was found
        pthread_mutex_unlock(&head->mutex);
        return;
    }
}
