        printf("Failed to receive data from remote server: %s\n", strerror(errno));
        return false;
    }
    return true;
}

void processReceivedData(char** buffer) {
    // Process received data here
    printf("Received data: %s\n", *buffer);
}

void closeSocket(int* socket) {
    if (*socket != -1) {
        close(*socket);
        *socket = -1;
    }
}
