// Define the UEContext structure
typedef struct {
    uint32_t ueId;
    uint16_t currentTAC;
    bool cellMeasurement;
} UEContext;

// Define a hash table to store the UEContext structures
static UEContext *contextTable = NULL;

// Function to add a new UEContext structure to the hash table
void addUEContext(uint32_t ueId, uint16_t currentTAC, bool cellMeasurement) {
    // Check if the hash table is initialized
    if (contextTable == NULL) {
        // Initialize the hash table with a default size of 100
        contextTable = malloc(sizeof(UEContext *) * 100);
    }

    // Calculate the hash value for the UE ID
    uint32_t hashValue = ueId % 100;

    // Check if there is an existing entry in the table for this UE ID
    if (contextTable[hashValue] == NULL) {
        // Create a new UEContext structure and assign the values
        UEContext *newEntry = malloc(sizeof(UEContext));
        newEntry->ueId = ueId;
        newEntry->currentTAC = currentTAC;
        newEntry->cellMeasurement = cellMeasurement;

        // Add the new entry to the hash table
        contextTable[hashValue] = newEntry;
    } else {
        // Update the existing UEContext structure with the new values
        UEContext *existingEntry = contextTable[hashValue];
        existingEntry->currentTAC = currentTAC;
        existingEntry->cellMeasurement = cellMeasurement;
    }
}

// Function to update an existing UEContext structure in the hash table
void updateUEContext(uint32_t ueId, uint16_t newCurrentTAC, bool newCellMeasurement) {
    // Calculate the hash value for the UE ID
    uint32_t hashValue = ueId % 100;

    // Check if there is an existing entry in the table for this UE ID
    if (contextTable[hashValue] != NULL) {
        // Update the current TAC and cell measurement status of the UEContext structure
        contextTable[hashValue]->currentTAC = newCurrentTAC;
        contextTable[hashValue]->cellMeasurement = newCellMeasurement;
    }
}

// Function to retrieve an existing UEContext structure from the hash table by its UE ID
UEContext *getUEContext(uint32_t ueId) {
    // Calculate the hash value for the UE ID
    uint32_t hashValue = ueId % 100;

    // Check if there is an existing entry in the table for this UE ID
    if (contextTable[hashValue] != NULL) {
        return contextTable[hashValue];
    } else {
        return NULL;
    }
}

// Function to delete an existing UEContext structure from the hash table by its UE ID
void deleteUEContext(uint32_t ueId) {
    // Calculate the hash value for the UE ID
    uint32_t hashValue = ueId % 100;

    // Check if there is an existing entry in the table for this UE ID
    if (contextTable[hashValue] != NULL) {
        free(contextTable[hashValue]);
        contextTable[hashValue] = NULL;
    }
}
```

