    nfapi_rx_frame_array.add(&rx_frame1);

    NFAPI_RX_FRAME_PDU rx_frame2 = { .status = FRAME_STATUS_FAILURE };
    nfapi_rx_frame_array.add(&rx_frame2);

    // Update the status of one of the frames in the array
    nfapi_rx_frame_array.update(0, FRAME_STATUS_SUCCESS);

