#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "nfapi_rx_frame_info.h"

typedef struct Frame {
    NFAPI_RX_FRAME_PDU_T *pdu;
    void *rx_frame; // dynamically allocated RX_FRAME buffer
} Frame;

// frame management structure
struct FrameManager {
    uint32_t capacity; // maximum number of frames that can be stored
    uint32_t size; // current number of frames in the buffer
    Frame *frames; // array of frames
    pthread_mutex_t mutex; // mutex to protect concurrent access
};

// initialize frame manager structure
void init_frame_manager(struct FrameManager *fm, uint32_t capacity) {
    fm->capacity = capacity;
    fm->size = 0;
    fm->frames = malloc(sizeof(Frame) * capacity);
    memset(fm->frames, 0, sizeof(Frame) * capacity);
    pthread_mutex_init(&fm->mutex, NULL);
}

// add a new frame to the buffer
bool add_frame(struct FrameManager *fm, NFAPI_RX_FRAME_PDU_T *pdu, void *rx_frame) {
    pthread_mutex_lock(&fm->mutex);
    if (fm->size >= fm->capacity) { // buffer is full, cannot add new frames
        pthread_mutex_unlock(&fm->mutex);
        return false;
    }

    Frame *frame = malloc(sizeof(Frame));
    frame->pdu = pdu;
    frame->rx_frame = rx_frame;

    // insert the new frame at the beginning of the list
    fm->frames[fm->size] = frame;
    fm->size++;

    pthread_mutex_unlock(&fm->mutex);
    return true;
}

// update the status of a frame based on feedback signals from an external data source
void update_frame(struct FrameManager *fm, uint32_t index, NFAPI_FRAME_FEEDBACK_T *feedback) {
    pthread_mutex_lock(&fm->mutex);

    // check if the frame is valid and has not been processed yet
    if (fm->frames[index] == NULL || fm->frames[index]->pdu->processed) {
        pthread_mutex_unlock(&fm->mutex);
        return;
    }

    // update the frame status based on feedback signals
    fm->frames[index]->pdu->status = feedback->status;
    fm->frames[index]->pdu->processed = true;

    pthread_mutex_unlock(&fm->mutex);
}

// iterate over all frames in the buffer and update their status based on feedback signals from an external data source
void update_all_frames(struct FrameManager *fm, NFAPI_FRAME_FEEDBACK_T *feedback) {
    pthread_mutex_lock(&fm->mutex);

    for (uint32_t i = 0; i < fm->size; i++) {
        update_frame(fm, i, feedback);
    }

    pthread_mutex_unlock(&fm->mutex);
}

// remove a frame from the buffer and free its resources
void remove_frame(struct FrameManager *fm, uint32_t index) {
    pthread_mutex_lock(&fm->mutex);

    // check if the frame is valid and has not been processed yet
    if (fm->frames[index] == NULL || fm->frames[index]->pdu->processed) {
        pthread_mutex_unlock(&fm->mutex);
        return;
    }

    // free the frame's RX_FRAME buffer and PDU structure
    free(fm->frames[index]->rx_frame);
    free(fm->frames[index]->pdu);
    fm->frames[index] = NULL;

    pthread_mutex_unlock(&fm->mutex);
}

// iterate over all frames in the buffer and remove them if they have been processed
void cleanup_frames(struct FrameManager *fm) {
    pthread_mutex_lock(&fm->mutex);

    for (uint32_t i = 0; i < fm->size; i++) {
        // check if the frame has been processed and remove it if necessary
        if (fm->frames[i] != NULL && fm->frames[i]->pdu->processed) {
            remove_frame(fm, i);
        }
    }

    pthread_mutex_unlock(&fm->mutex);
}

// dump the current state of the frame management structure for debugging purposes
void dump_frames(struct FrameManager *fm) {
    pthread_mutex_lock(&fm->mutex);

    printf("Frame manager: capacity = %u, size = %u\n", fm->capacity, fm->size);
    for (uint32_t i = 0; i < fm->size; i++) {
        if (fm->frames[i] == NULL) continue;
        printf("  Frame %u:\n", i);
        printf("    PDU: status = %d, processed = %s\n", fm->frames[i]->pdu->status, fm->frames[i]->pdu->processed ? "true" : "false");
        if (fm->frames[i]->rx_frame != NULL) {
            printf("    RX frame: size = %u\n", ((struct nfapi_rx_frame *)(fm->frames[i]->rx_frame))->size);
        }
    }

    pthread_mutex_unlock(&fm->mutex);
}
```
This code implements a frame management structure that can store a dynamic array of `NFAPI_RX_FRAME_PDU_T` structures, each containing a PDU structure and a RX frame buffer. The structure provides methods for adding, updating, and removing frames from the buffer, as well as iterating over all frames in the buffer and updating their status based on feedback signals from an external data source.

The `dump_frames` method is intended for debugging purposes and dumps the current state of the frame management structure to standard output. It locks the mutex before dumping the state, ensuring that only one thread can access the buffer at a time.

In the `update_frame` method, we first check if the frame is valid and has not been processed yet. If it is not valid or has already been processed, we return immediately without updating the status of the frame. Otherwise, we update the status of the frame based on the feedback signals from an external data source and set its `processed` flag to true.

In the `cleanup_frames` method, we iterate over all frames in the buffer and remove them if they have been processed. We lock the mutex before iterating over the frames to ensure that only one thread can access the buffer at a time.

In the `update_all_frames` method, we iterate over all frames in the buffer and update their status based on feedback signals from an external data source. We first check if the frame is valid and has not been processed yet before updating its status. If it is not valid or has already been processed, we skip to the next frame.

The `add_frame` method adds a new frame to the buffer and locks the mutex before doing so. It creates a new PDU structure and RX frame buffer for the frame, sets their sizes to zero, and adds them to the buffer. If the buffer is full, it removes the oldest frame from the buffer before adding the new one.

The `remove_frame` method removes a frame from the buffer and frees its resources. It first checks if the frame is valid and has not been processed yet, and if so, it locks the mutex before removing it from the buffer and freeing its resources.']

