// User session structure
typedef struct {
    char* sessionKey; // Unique identifier for the session
    time_t lastAccessTime; // Timestamp of the last access to the session
    int sessionState; // Current state of the session (e.g., active, inactive)
} UserSession;

// Session management data structure
typedef struct {
    UserSession* sessions; // Array of user sessions
    size_t numSessions; // Number of active user sessions
    time_t idleTimeout; // Timeout for inactive sessions (in seconds)
    pthread_mutex_t mutex; // Mutex to synchronize access to the session array
} SessionManager;

// Initialize a new session manager with the given number of concurrent users and idle timeout
SessionManager* initSessionManager(size_t numUsers, time_t idleTimeout) {
    SessionManager* sm = (SessionManager*)malloc(sizeof(SessionManager));
    if (!sm) {
        printf("Error: Failed to allocate memory for session manager\n");
        return NULL;
    }

    // Initialize the session array and mutex
    sm->sessions = (UserSession*)calloc(numUsers, sizeof(UserSession));
    if (!sm->sessions) {
        printf("Error: Failed to allocate memory for user sessions\n");
        free(sm);
        return NULL;
    }
    sm->mutex = PTHREAD_MUTEX_INITIALIZER;

    // Set the number of active sessions and idle timeout
    sm->numSessions = 0;
    sm->idleTimeout = idleTimeout;

    return sm;
}

// Add a new user session with the given key and initial state
int addSession(SessionManager* sm, char* sessionKey, int sessionState) {
    pthread_mutex_lock(&sm->mutex);

    // Check if there is room for another session
    if (sm->numSessions == MAX_NUM_SESSIONS) {
        printf("Error: No more room for new sessions\n");
        pthread_mutex_unlock(&sm->mutex);
        return -1;
    }

    // Create a new session and add it to the array
    UserSession* newSession = &sm->sessions[sm->numSessions++];
    strcpy(newSession->sessionKey, sessionKey);
    newSession->lastAccessTime = time(NULL);
    newSession->sessionState = sessionState;

    pthread_mutex_unlock(&sm->mutex);
    return 0;
}

// Update an existing user session with the given key and state
int updateSession(SessionManager* sm, char* sessionKey, int sessionState) {
    pthread_mutex_lock(&sm->mutex);

    // Find the session corresponding to the given key
    for (size_t i = 0; i < sm->numSessions; i++) {
        UserSession* session = &sm->sessions[i];
        if (!strcmp(session->sessionKey, sessionKey)) {
            // Update the session state and last access time
            session->sessionState = sessionState;
            session->lastAccessTime = time(NULL);
            pthread_mutex_unlock(&sm->mutex);
            return 0;
        }
    }

    // If no matching session is found, create a new one
    addSession(sm, sessionKey, sessionState);

    pthread_mutex_unlock(&sm->mutex);
    return 0;
}

// Retrieve the state and last access time for a given session key
int getSessionState(SessionManager* sm, char* sessionKey) {
    pthread_mutex_lock(&sm->mutex);

    // Find the session corresponding to the given key
    for (size_t i = 0; i < sm->numSessions; i++) {
        UserSession* session = &sm->sessions[i];
        if (!strcmp(session->sessionKey, sessionKey)) {
            // Return the state and last access time of the matching session
            int state = session->sessionState;
            time_t lastAccessTime = session->lastAccessTime;
            pthread_mutex_unlock(&sm->mutex);
            return state;
        }
    }

    // If no matching session is found, return an error code
    printf("Error: No matching session found for key %s\n", sessionKey);
    pthread_mutex_unlock(&sm->mutex);
    return -1;
}

// Automatically expire inactive sessions based on the specified idle timeout
void autoExpireSessions(SessionManager* sm) {
    time_t currentTime = time(NULL);

    // Iterate through all active sessions and check for expiration
    pthread_mutex_lock(&sm->mutex);
    for (size_t i = 0; i < sm->numSessions; i++) {
        UserSession* session = &sm->sessions[i];
        time_t lastAccessTime = session->lastAccessTime;
        if (difftime(currentTime, lastAccessTime) > sm->idleTimeout) {
            // Expire the inactive session and update the number of active sessions
            printf("Session %s expired due to inactivity\n", session->sessionKey);
            sm->numSessions--;
        }
    }
    pthread_mutex_unlock(&sm->mutex);
}

// Main function for testing the session manager
int main() {
    // Initialize a new session manager with 10 concurrent users and an idle timeout of 30 seconds
    SessionManager* sm = initSessionManager(10, 30);

    // Add a new user session with key "session1" and state "active"
    addSession(sm, "session1", ACTIVE_SESSION);

    // Update the state of the existing session with key "session1" to "inactive"
    updateSession(sm, "session1", INACTIVE_SESSION);

    // Retrieve the state and last access time for the session with key "session1"
    int state = getSessionState(sm, "session1");

    // Automatically expire inactive sessions based on the specified idle timeout
    autoExpireSessions(sm);

    return 0;
}
