// Structure to represent a UE context
typedef struct {
  int ueId; // Unique identifier for the UE
  int currentTAC; // Current TAC for the UE
  char cellMeasurement; // Status of the cell measurement for the UE
} UEContext;

// Dynamically allocated array to store UE contexts
UEContext* ueContexts = NULL;

// Number of UE contexts in the array
int numUeContexts = 0;

// Maximum number of UE contexts that can be stored in the array
#define MAX_NUM_UE_CONTEXTS (100000)

// Lock for thread-safe access to the UE contexts array
pthread_mutex_t ueContextsLock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new UE context to the array
void addUeContext(int ueId, int currentTAC) {
  // Lock the mutex for thread-safe access
  pthread_mutex_lock(&ueContextsLock);

  // Check if the array needs to be resized
  if (numUeContexts == MAX_NUM_UE_CONTEXTS) {
    // Resize the array by a factor of 2
    UEContext* newUeContexts = realloc(ueContexts, sizeof(UEContext) * MAX_NUM_UE_CONTEXTS * 2);

    // Check for memory allocation errors
    if (newUeContexts == NULL) {
      perror("Error resizing UE contexts array");
      exit(1);
    }

    ueContexts = newUeContexts;
    MAX_NUM_UE_CONTEXTS *= 2;
  }

  // Add the new UE context to the end of the array
  ueContexts[numUeContexts].ueId = ueId;
  ueContexts[numUeContexts].currentTAC = currentTAC;
  numUeContexts++;

  // Unlock the mutex
  pthread_mutex_unlock(&ueContextsLock);
}

// Function to update an existing UE context in the array
void updateUeContext(int ueId, int currentTAC) {
  // Lock the mutex for thread-safe access
  pthread_mutex_lock(&ueContextsLock);

  // Find the index of the UE context with the given ueId
  int i = 0;
  while (i < numUeContexts && ueContexts[i].ueId != ueId) {
    i++;
  }

  if (i == numUeContexts) {
    // UE context not found, return
    pthread_mutex_unlock(&ueContextsLock);
    return;
  }

  // Update the currentTAC of the UE context
  ueContexts[i].currentTAC = currentTAC;

  // Unlock the mutex
  pthread_mutex_unlock(&ueContextsLock);
}

// Function to retrieve an existing UE context from the array
void* getUeContext(int ueId) {
  // Lock the mutex for thread-safe access
  pthread_mutex_lock(&ueContextsLock);

  // Find the index of the UE context with the given ueId
  int i = 0;
  while (i < numUeContexts && ueContexts[i].ueId != ueId) {
    i++;
  }

  if (i == numUeContexts) {
    // UE context not found, return NULL
    pthread_mutex_unlock(&ueContextsLock);
    return NULL;
  }

  // Return a pointer to the UE context
  void* ueContext = &ueContexts[i];

  // Unlock the mutex
  pthread_mutex_unlock(&ueContextsLock);

  return ueContext;
}

// Function to serialize and deserialize the list of UE contexts
void* serializeUeContexts() {
  // Lock the mutex for thread-safe access
  pthread_mutex_lock(&ueContextsLock);

  // Serialize the list of UE contexts into a string
  char* serializedUeContexts = malloc(sizeof(char) * (numUeContexts + 1));

  if (serializedUeContexts == NULL) {
    perror("Error allocating memory for serialized UE contexts");
    exit(1);
  }

  // Write the UE contexts into the string, separated by spaces
  int i = 0;
  while (i < numUeContexts) {
    sprintf(&serializedUeContexts[i * 3], "%d %d ", ueContexts[i].ueId, ueContexts[i].currentTAC);
    i++;
  }

  // Add a null terminator to the end of the string
  serializedUeContexts[numUeContexts * 3] = '\0';

  // Unlock the mutex
  pthread_mutex_unlock(&ueContextsLock);

  return serializedUeContexts;
}

void deserializeUeContexts(char* serializedUeContexts) {
  // Lock the mutex for thread-safe access
  pthread_mutex_lock(&ueContextsLock);

  // Deserialize the list of UE contexts from the string
  int i = 0;
  while (i < numUeContexts) {
    sscanf(&serializedUeContexts[i * 3], "%d %d", &ueContexts[i].ueId, &ueContexts[i].currentTAC);
    i++;
  }

  // Unlock the mutex
  pthread_mutex_unlock(&ueContextsLock);
}

// Function to handle periodic updates on currentTAC values from an external data source
void updateUeContextCurrentTAC(int ueId, int currentTAC) {
  // Lock the mutex for thread-safe access
  pthread_mutex_lock(&ueContextsLock);

  // Find the index of the UE context with the given ueId
  int i = 0;
  while (i < numUeContexts && ueContexts[i].ueId != ueId) {
    i++;
  }

  if (i == numUeContexts) {
    // UE context not found, return
    pthread_mutex_unlock(&ueContextsLock);
    return;
  }

  // Update the currentTAC of the UE context
  ueContexts[i].currentTAC = currentTAC;

  // Unlock the mutex
  pthread_mutex_unlock(&ueContextsLock);
}

// Function to handle errors related to UE contexts
void errorUeContext(int errorCode) {
  switch (errorCode) {
    case ERROR_UE_CONTEXT_NOT_FOUND:
      printf("UE context not found\n");
      break;
    default:
      printf("Unknown error\n");
      break;
  }
}
