array_manager_t *init_arrays(int num_offsets, int num_keys, int num_records, int num_metadata) {
    // Allocate memory for the arrays
    long *offset_array = (long *)malloc(sizeof(long) * num_offsets);
    int *key_array = (int *)malloc(sizeof(int) * num_keys);
    record_t *records = (record_t *)malloc(sizeof(record_t) * num_records);
