    manager->offset_array = offset_array;
    manager->key_array = key_array;
    manager->records = records;
    manager->metadata = metadata;

    return manager;
}

void free_arrays(array_manager_t *manager) {
    // Free the memory allocated for the arrays
    free(manager->offset_array);
    free(manager->key_array);
    free(manager->records);
    free(manager->metadata);
}

