    // Return the index of the record with the specified key
    for (int i = 0; i < manager->num_keys; i++) {
        if (manager->key_array[i] == key) {
            return i;
        }
    }
    return -1;
}

void insert_record(array_manager_t *manager, int index, record_t *record) {
    // Insert the record at the specified index
    manager->records[index] = *record;
}

record_t *get_record(array_manager_t *manager, int index) {
    // Return a pointer to the record at the specified index
    return &manager->records[index];
}

int compare_records(const void *a, const void *b) {
    // Comparison function for sorting records by their values
    return (*((record_t *)a)).value - (*((record_t *)b)).value;
}

void sort_records(array_manager_t *manager, int(*compare)(const void *, const void *)) {
    // Sort the records using the specified comparison function
    qsort(manager->records, manager->num_records, sizeof(record_t), compare);
}

int main() {
