// Define a struct to represent a TAI (Tracking Area Identity) structure
struct tai {
    int cell_id;  // Unique cell ID
    char *plmn_ids;  // Set of associated PLMN IDs
};

// Define a struct to represent the list of TAI structures
struct tai_list {
    struct tai *tai_array;  // Array of TAI structures
    int size;  // Current size of the array
    int capacity;  // Maximum capacity of the array
};

// Function to initialize and manage a list of TAI structures
struct tai_list* init_tai_list() {
    struct tai_list *list = malloc(sizeof(struct tai_list));
    if (list == NULL) {
        perror("Error allocating memory for TAI list");
        return NULL;
    }
    list->size = 0;
    list->capacity = 16;  // Initial capacity of the array
    list->tai_array = malloc(list->capacity * sizeof(struct tai));
    if (list->tai_array == NULL) {
        perror("Error allocating memory for TAI array");
        free(list);
        return NULL;
    }
    return list;
}

// Function to add a new TAI structure to the list
int add_tai(struct tai_list *list, int cell_id, char *plmn_ids) {
    if (list == NULL || plmn_ids == NULL) {
        return -1;
    }
    // Check if the capacity of the array needs to be increased
    if (list->size >= list->capacity) {
        int new_capacity = list->capacity * 2;
        struct tai *new_array = realloc(list->tai_array, new_capacity * sizeof(struct tai));
        if (new_array == NULL) {
            perror("Error resizing TAI array");
            return -1;
        }
        list->capacity = new_capacity;
        list->tai_array = new_array;
    }
    // Add the new TAI structure to the end of the array
    list->tai_array[list->size].cell_id = cell_id;
    list->tai_array[list->size].plmn_ids = plmn_ids;
    list->size++;
    return 0;
}

// Function to remove a TAI structure from the list by its cell ID
int remove_tai(struct tai_list *list, int cell_id) {
    if (list == NULL) {
        return -1;
    }
    // Find the index of the TAI structure with the given cell ID
    int i = 0;
    for (; i < list->size && list->tai_array[i].cell_id != cell_id; i++) {}
    if (i == list->size) {
        return -1;
    }
    // Shift all subsequent elements one position to the left
    for (int j = i; j < list->size - 1; j++) {
        list->tai_array[j] = list->tai_array[j + 1];
    }
    list->size--;
    return 0;
}

// Function to check if a given PLMN ID is already present within the list for a specific cell ID
int contains_plmn(struct tai_list *list, int cell_id, char *plmn_id) {
    if (list == NULL || plmn_id == NULL) {
        return -1;
    }
    // Find the index of the TAI structure with the given cell ID
    int i = 0;
    for (; i < list->size && list->tai_array[i].cell_id != cell_id; i++) {}
    if (i == list->size) {
        return -1;
    }
    // Check if the PLMN ID is already present in the array
    for (int j = 0; j < list->tai_array[i].plmn_ids.length; j++) {
        if (strcmp(list->tai_array[i].plmn_ids[j], plmn_id) == 0) {
            return 1;
        }
    }
    return -1;
}

// Function to iterate over the list of TAI structures and perform operations on each one
void iterate_tais(struct tai_list *list, void (*callback)(struct tai*)) {
    if (list == NULL || callback == NULL) {
        return;
    }
    for (int i = 0; i < list->size; i++) {
        struct tai *tai = &list->tai_array[i];
        callback(tai);
    }
}

// Function to clean up the memory used by the TAI list
void destroy_tai_list(struct tai_list **list) {
    if (*list == NULL) {
        return;
    }
    free((*list)->tai_array);
    free(*list);
    *list = NULL;
}
