/**
 * Initializes and populates a dynamic array of UEStatsRecord structures.
 *
 * @param records Pointer to an array of UEStatsRecord pointers to be initialized.
 * @param count The number of records to initialize.
 * @return int Returns 0 on success, -1 on failure.
 */
int init_and_populate_records(UEStatsRecord** records, size_t count) {
    // Allocate memory for the array of UEStatsRecord structures
    *records = (UEStatsRecord*) malloc(count * sizeof(UEStatsRecord));
    if (*records == NULL) {
        // Handle allocation failure gracefully
        return -1;
    }

    // Initialize each UEStatsRecord structure in the array
    for (size_t i = 0; i < count; i++) {
        (*records)[i].count = 0;
        (*records)[i].reports = NULL;
    }

    // Populate the array with measurement reports from an external data source
    for (size_t i = 0; i < count; i++) {
        MeasurementReport* report = get_measurement_report();
        if (report == NULL) {
            continue;  // Skip this record if the data source is unavailable or delayed
        }
        (*records)[i].count++;
        (*records)[i].reports = realloc((*records)[i].reports, sizeof(MeasurementReport));
        if ((*records)[i].reports == NULL) {
            // Handle allocation failure gracefully
            return -1;
        }
        memcpy(&(*records)[i].reports[(*records)[i].count-1], report, sizeof(MeasurementReport));
    }

    return 0;
}
