/* Function to manage a dynamic array of TCP connection metadata structures */
struct conn_meta {
    uint64_t id; /* Unique connection ID */
    struct sockaddr_in remote_addr; /* Remote IP address and port number */
    struct sockaddr_in local_addr; /* Local IP address and port number */
};

struct conn_array {
    struct conn_meta **metadata; /* Array of connection metadata structures */
    size_t num_conns; /* Number of connections in the array */
    size_t max_conns; /* Maximum capacity of the array */
};

/* Add a new connection to the array, or update an existing one if already present */
int add_connection(struct conn_array *arr, struct sockaddr_in remote_addr, struct sockaddr_in local_addr) {
    int i;

    /* Check if the connection already exists in the array */
    for (i = 0; i < arr->num_conns; i++) {
        if (conn_metadata_equal(arr->metadata[i], remote_addr, local_addr)) {
            /* Update existing connection metadata */
            arr->metadata[i]->remote_addr = remote_addr;
            arr->metadata[i]->local_addr = local_addr;
            return 0;
        }
    }

    /* Add new connection to the end of the array if it does not exist already */
    if (arr->num_conns == arr->max_conns) {
        /* Reallocate memory for the array if necessary */
        arr->metadata = realloc(arr->metadata, sizeof(struct conn_meta *) * arr->max_conns * 2);
        arr->max_conns *= 2;
    }

    arr->metadata[arr->num_conns] = malloc(sizeof(struct conn_meta));
    arr->metadata[arr->num_conns]->id = generate_conn_id();
    arr->metadata[arr->num_conns]->remote_addr = remote_addr;
    arr->metadata[arr->num_conns]->local_addr = local_addr;
    arr->num_conns++;

    return 0;
}

/* Remove a connection from the array based on its ID */
int remove_connection(struct conn_array *arr, uint64_t id) {
    int i;

    /* Find the index of the connection with the given ID in the array */
    for (i = 0; i < arr->num_conns; i++) {
        if (arr->metadata[i]->id == id) {
            break;
        }
    }

    /* If the connection is not found, return an error code */
    if (i == arr->num_conns) {
        return -1;
    }

    /* Shift all connections after the removed one to the left */
    for (int j = i + 1; j < arr->num_conns; j++) {
        arr->metadata[j - 1] = arr->metadata[j];
    }

    arr->num_conns--;

    return 0;
}

/* Get a connection's metadata based on its ID */
struct conn_meta *get_connection(struct conn_array *arr, uint64_t id) {
    int i;

    /* Find the index of the connection with the given ID in the array */
    for (i = 0; i < arr->num_conns; i++) {
        if (arr->metadata[i]->id == id) {
            break;
        }
    }

    /* If the connection is not found, return NULL */
    if (i == arr->num_conns) {
        return NULL;
    }

    return arr->metadata[i];
}

/* Get a connection's metadata based on its IP address and port number */
struct conn_meta *get_connection_by_addr(struct conn_array *arr, struct sockaddr_in addr) {
    int i;

    /* Find the index of the connection with the given IP address and port number in the array */
    for (i = 0; i < arr->num_conns; i++) {
        if (conn_metadata_equal(arr->metadata[i], addr)) {
            break;
        }
    }

    /* If the connection is not found, return NULL */
    if (i == arr->num_conns) {
        return NULL;
    }

    return arr->metadata[i];
}

/* Check if two connection metadata structures are equal in terms of IP address and port number */
int conn_metadata_equal(struct conn_meta *conn1, struct conn_meta *conn2) {
    return (conn1->remote_addr.sin_addr.s_addr == conn2->remote_addr.sin_addr.s_addr &&
            conn1->remote_addr.sin_port == conn2->remote_addr.sin_port);
}

/* Generate a unique connection ID */
uint64_t generate_conn_id(void) {
    return (uint64_t)(rand() % 1000000000 + 1);
}

/* Clean up inactive connections based on the configured timeout threshold */
int cleanup_connections(struct conn_array *arr, uint32_t timeout) {
    int i;

    /* Iterate over all connections and check if they have not been updated within the specified timeout period */
    for (i = 0; i < arr->num_conns; i++) {
        if (conn_metadata_inactive(arr->metadata[i], timeout)) {
            /* Remove the inactive connection from the array */
            remove_connection(arr, arr->metadata[i]->id);
        }
    }

    return 0;
}

/* Check if a connection metadata structure is considered inactive based on the configured timeout threshold */
int conn_metadata_inactive(struct conn_meta *conn, uint32_t timeout) {
    /* Calculate the time difference between the current time and the last update time of the connection */
    uint64_t time_diff = get_timestamp() - conn->last_update;

    return (time_diff >= timeout);
}

/* Get the timestamp in milliseconds since epoch */
uint64_t get_timestamp(void) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (uint64_t)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
}"]

