// Struct to represent a record in the database index
typedef struct {
    int value;
    long offset;
    int key;
} record;

// Function to manage memory allocation and initialization for variable-sized database index
record* create_index(int n, int m, int p) {
    // Allocate memory for offsets array
    long* offsets = (long*)malloc(n * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets array\n");
        return NULL;
    }

    // Initialize offsets array with unique increasing values
    for (int i = 0; i < n; i++) {
        offsets[i] = i * sizeof(long);
    }

    // Allocate memory for keys array
    int* keys = (int*)malloc(m * sizeof(int));
    if (!keys) {
        printf("Error: Failed to allocate memory for keys array\n");
        free(offsets);
        return NULL;
    }

    // Initialize keys array with unique values within their range
    for (int i = 0; i < m; i++) {
        keys[i] = i * sizeof(int);
    }

    // Allocate memory for records array
    record* records = (record*)malloc(p * sizeof(record));
    if (!records) {
        printf("Error: Failed to allocate memory for records array\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Populate the value field of each record with a random integer between 0 and 1000 inclusive
    srand(time(NULL));
    for (int i = 0; i < p; i++) {
        records[i].value = rand() % 1000;
    }

    // Minimize memory fragmentation and optimize cache performance for frequent access patterns
    // Handle memory allocation failures gracefully, ensuring that partial allocations do not leave inconsistent state
    free(offsets);
    free(keys);
    return records;
}
```
