void manage_user_account(user_account_action_t action, user_account_t *account) {
    bool success = false;
    int fd;
    struct stat sb;
    void *ptr;
    off_t offset;

    switch (action) {
        case USER_ACCOUNT_ACTION_CREATE:
            if (!user_account_cache) {
                user_account_cache = calloc(USER_ACCOUNT_CACHE_SIZE, sizeof(struct user_account_cache_entry));
                assert(user_account_cache);
            }

