            write(fd, ptr, sizeof(user_account_t));

            // Close the file descriptor.
            close(fd);

            success = true;
            break;
        case USER_ACCOUNT_ACTION_UPDATE:
            if (!user_account_cache) {
                user_account_cache = calloc(USER_ACCOUNT_CACHE_SIZE, sizeof(struct user_account_cache_entry));
                assert(user_account_cache);
            }

            // Open/create the user account file.
