            if (fd == -1) {
                perror("open");
                return;
            }

            // Mmap the file to memory.
            ptr = mmap(NULL, sizeof(user_account_t), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
            if (ptr == MAP_FAILED) {
                perror("mmap");
                return;
            }

            // Update the user account in memory.
            offset = lseek(fd, sizeof(user_account_t) * account->id, SEEK_SET);
            write(fd, ptr, sizeof(user_account_t));

            // Close the file descriptor.
            close(fd);

            success = true;
            break;
        case USER_ACCOUNT_ACTION_DELETE:
            if (!user_account_cache) {
                user_account_cache = calloc(USER_ACCOUNT_CACHE_SIZE, sizeof(struct user_account_cache_entry));
                assert(user_account_cache);
            }

            // Open/create the user account file.
            fd = open("user_accounts", O_RDWR | O_CREAT, 0644);
            if (fd == -1) {
                perror("open");
                return;
            }

            // Mmap the file to memory.
            ptr = mmap(NULL, sizeof(user_account_t), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
            if (ptr == MAP_FAILED) {
                perror("mmap");
                return;
            }

            // Delete the user account from memory.
            offset = lseek(fd, sizeof(user_account_t) * account->id, SEEK_SET);
            memset(ptr, 0, sizeof(user_account_t));

            // Close the file descriptor.
            close(fd);

            success = true;
            break;
        default:
            break;
    }

    if (success) {
        // Update the cache with the new user account information.
        struct user_account_cache_entry *entry = NULL;
        for (int i = 0; i < USER_ACCOUNT_CACHE_SIZE; i++) {
            if (!user_account_cache[i].expiry || user_account_cache[i].expiry < time(NULL)) {
                entry = &user_account_cache[i];
                break;
            }
        }
        if (entry) {
            memcpy(&entry->account, account, sizeof(user_account_t));
            entry->expiry = time(NULL) + USER_ACCOUNT_CACHE_EXPIRY_SECS;
        } else {
            // Cache is full, discard oldest entry.
            for (int i = 0; i < USER_ACCOUNT_CACHE_SIZE - 1; i++) {
                if (!user_account_cache[i].expiry || user_account_cache[i].expiry < time(NULL)) {
                    memcpy(&user_account_cache[i], &user_account_cache[i + 1], sizeof(struct user_account_cache_entry));
                }
            }
            memcpy(&user_account_cache[USER_ACCOUNT_CACHE_SIZE - 1], account, sizeof(user_account_t));
            user_account_cache[USER_ACCOUNT_CACHE_SIZE - 1].expiry = time(NULL) + USER_ACCOUNT_CACHE_EXPIRY_SECS;
        }
    }

    return success;
}
