  size_t size;
  size_t capacity;
  NFAPI_RRC_CCO_REQUEST *data;
} NFAPI_RRC_CCO_REQUEST_LIST;

// Define the error codes for the function
#define NFAPI_OK 0
#define NFAPI_ERROR -1
#define NFAPI_INVALID_UE_ID -2
#define NFAPI_DUPLICATE_UE_ID -3
#define NFAPI_OUT_OF_MEMORY -4
#define NFAPI_SERIALIZATION_ERROR -5
#define NFAPI_DESERIALIZATION_ERROR -6

// Define the function for managing the NFAPI_CRC_INDICATION_PDU_T structures
int manageNfapiCrcIndicationPdu(NFAPI_CRC_INDICATION_PDU_LIST *list, uint16_t RX_UE_INFORMATION_TAG, uint32_t RNTI) {
  // Check if the UE ID is valid
  if (RNTI == 0) {
    return NFAPI_INVALID_UE_ID;
  }

  // Check if the UE ID already exists in the list
  for (size_t i = 0; i < list->size; i++) {
    if (list->data[i].RNTI == RNTI) {
      return NFAPI_DUPLICATE_UE_ID;
    }
  }

  // Allocate memory for the new structure
  NFAPI_CRC_INDICATION_PDU_T *newStruct = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
  if (newStruct == NULL) {
    return NFAPI_OUT_OF_MEMORY;
  }

  // Initialize the new structure with the given values
  newStruct->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
  newStruct->RNTI = RNTI;
  newStruct->CRCFLAG = rand() % 2; // randomly set CRCFLAG to either 0 or 1

  // Add the new structure to the list
  if (list->size == list->capacity) {
    list->data = realloc(list->data, (list->capacity + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->data == NULL) {
      return NFAPI_OUT_OF_MEMORY;
    }
    list->capacity++;
  }
  list->data[list->size] = *newStruct;
  list->size++;

  // Return success
  return NFAPI_OK;
}

// Define the function for managing the NFAPI_RRC_CCO_REQUEST structures
int manageNfapiRrcCcoRequest(NFAPI_RRC_CCO_REQUEST_LIST *list, uint32_t UE_ID, uint8_t frequencyBands[], char timestamp[]) {
  // Check if the UE ID is valid
  if (UE_ID == 0) {
    return NFAPI_INVALID_UE_ID;
  }

  // Check if the frequency bands are valid
  for (size_t i = 0; i < sizeof(frequencyBands); i++) {
    if (frequencyBands[i] == 0) {
      return NFAPI_INVALID_FREQUENCY_BAND;
    }
  }

  // Check if the timestamp is valid
  if (strlen(timestamp) != 24) {
    return NFAPI_INVALID_TIMESTAMP;
  }

  // Allocate memory for the new structure
  NFAPI_RRC_CCO_REQUEST *newStruct = malloc(sizeof(NFAPI_RRC_CCO_REQUEST));
  if (newStruct == NULL) {
    return NFAPI_OUT_OF_MEMORY;
  }

  // Initialize the new structure with the given values
  newStruct->UE_ID = UE_ID;
  memcpy(newStruct->frequencyBands, frequencyBands, sizeof(frequencyBands));
  strcpy(newStruct->timestamp, timestamp);
  newStruct->statusFlags = false; // set initial status flag to false

  // Add the new structure to the list
  if (list->size == list->capacity) {
    list->data = realloc(list->data, (list->capacity + 1) * sizeof(NFAPI_RRC_CCO_REQUEST));
    if (list->data == NULL) {
      return NFAPI_OUT_OF_MEMORY;
    }
    list->capacity++;
  }
  list->data[list->size] = *newStruct;
  list->size++;

  // Return success
  return NFAPI_OK;
}

// Define the function for serializing the NFAPI_CRC_INDICATION_PDU_LIST and NFAPI_RRC_CCO_REQUEST_LIST
int serialize(NFAPI_CRC_INDICATION_PDU_LIST *crcList, NFAPI_RRC_CCO_REQUEST_LIST *ccoList) {
  // Check if the list is empty
  if (crcList->size == 0 && ccoList->size == 0) {
    return NFAPI_EMPTY_LIST;
  }

  // Allocate memory for the serialized data
  size_t bufferSize = crcList->size + ccoList->size;
  uint8_t *buffer = malloc(bufferSize);
  if (buffer == NULL) {
    return NFAPI_OUT_OF_MEMORY;
  }

  // Serialize the list of CRC indication PDUs
  buffer[0] = crcList->size;
  for (int i = 1; i <= crcList->size; i++) {
    memcpy(&buffer[i], &crcList->data[i - 1], sizeof(NFAPI_CRC_INDICATION_PDU));
  }

  // Serialize the list of RRC CCO requests
  buffer[bufferSize] = ccoList->size;
  for (int i = crcList->size + 2; i <= bufferSize; i++) {
    memcpy(&buffer[i], &ccoList->data[i - crcList->size - 1], sizeof(NFAPI_RRC_CCO_REQUEST));
  }

  // Return success
  return NFAPI_OK;
}

// Define the function for deserializing the serialized data
int deserialize(uint8_t *buffer, size_t bufferSize) {
  // Check if the buffer is empty
  if (buffer == NULL || bufferSize == 0) {
    return NFAPI_EMPTY_BUFFER;
  }

  // Allocate memory for the deserialized data
  size_t crcListSize = buffer[0];
  size_t ccoListSize = buffer[bufferSize];
  NFAPI_CRC_INDICATION_PDU_LIST *crcList = malloc(crcListSize * sizeof(NFAPI_CRC_INDICATION_PDU));
  NFAPI_RRC_CCO_REQUEST_LIST *ccoList = malloc(ccoListSize * sizeof(NFAPI_RRC_CCO_REQUEST));
  if (crcList == NULL || ccoList == NULL) {
    return NFAPI_OUT_OF_MEMORY;
  }

  // Deserialize the list of CRC indication PDUs
  for (int i = 1; i <= crcListSize; i++) {
    memcpy(&crcList->data[i - 1], &buffer[i], sizeof(NFAPI_CRC_INDICATION_PDU));
  }

  // Deserialize the list of RRC CCO requests
  for (int i = crcListSize + 2; i <= bufferSize; i++) {
    memcpy(&ccoList->data[i - crcListSize - 1], &buffer[i], sizeof(NFAPI_RRC_CCO_REQUEST));
  }

  // Return success
  return NFAPI_OK;
}
