// Define the hash table for storing session contexts
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int hash_table[1024];

// Function to add a new PDU to an existing session
int add_pdu(SessionContext* session, NAS_MESSAGE_T_PDU pdu) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the session already exists
    int index = get_session_index(session->UE_ID);
    if (index < 0) {
        // If the session does not exist, create a new one
        SessionContext* new_session = malloc(sizeof(SessionContext));
        memset(new_session, 0, sizeof(SessionContext));
        new_session->UE_ID = session->UE_ID;
        new_session->NAS_MESSAGE_T_PDUs = NULL;
        new_session->timestamp = pdu.timestamp;
        hash_table[new_session->UE_ID] = new_session;
    } else {
        // If the session already exists, update it
        SessionContext* existing_session = hash_table[index];
        existing_session->NAS_MESSAGE_T_PDUs = realloc(existing_session->NAS_MESSAGE_T_PDUs, sizeof(NAS_MESSAGE_T_PDU) * (existing_session->PDU_count + 1));
        existing_session->NAS_MESSAGE_T_PDUs[existing_session->PDU_count] = pdu;
        existing_session->timestamp = pdu.timestamp;
        existing_session->PDU_count++;
