    if (existing_session == NULL) {
        // If the session does not exist, return an error
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Update the PDU at the specified index
    existing_session->NAS_MESSAGE_T_PDUs[index] = pdu;
    existing_session->timestamp = pdu.timestamp;

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to retrieve all PDUs for a given UE_ID
