    if (index < 0) {
        // If the session does not exist, return NULL
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Retrieve the PDUs for the specified UE_ID
    SessionContext* existing_session = hash_table[index];
    NAS_MESSAGE_T_PDU* pdu_list = malloc(sizeof(NAS_MESSAGE_T_PDU) * existing_session->PDU_count);
    memcpy(pdu_list, existing_session->NAS_MESSAGE_T_PDUs, sizeof(NAS_MESSAGE_T_PDU) * existing_session->PDU_count);

    // Unlock the mutex and return the PDU list
    pthread_mutex_unlock(&mutex);
    return pdu_list;
}

// Function to remove a session from the hash table
int remove_session(SessionContext* session) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the session exists
    int index = get_session_index(session->UE_ID);
    if (index < 0) {
        // If the session does not exist, return an error
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Remove the session from the hash table
    free(hash_table[index]);
    hash_table[index] = NULL;

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to get the index of a session in the hash table
