#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    RX_UE_INFORMATION_TAG *rxUeInformation;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8;
} NFAPI_CRC_INDICATION_PDU_T;

void createAndPopulateList(int maxCapacity, int range) {
    // Create a lock-free queue to handle incoming CRC indications asynchronously
    sem_t *crcIndicationQueue = sem_open("/CRC_INDICATION_QUEUE", O_CREAT, 0644, 1);

    // Initialize the list with a maximum capacity
    NFAPI_CRC_INDICATION_PDU_T **list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T *) * maxCapacity);

    // Set up a semaphore to signal when the list needs to be resized
    sem_t *resizeSemaphore = sem_open("/RESIZE_SEMAPHORE", O_CREAT, 0644, 1);

    // Create a new thread for handling CRC indications and managing the list
    pthread_t crcIndicationHandler;
    pthread_create(&crcIndicationHandler, NULL, handleCRCIndications, NULL);

    while (1) {
        sem_wait(crcIndicationQueue);

        // Check if the list needs to be resized
        if (sem_trywait(resizeSemaphore) == 0) {
            int oldCapacity = maxCapacity;
            maxCapacity *= 2;
            NFAPI_CRC_INDICATION_PDU_T **newList = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * maxCapacity);

            if (newList == NULL) {
                fprintf(stderr, "Error resizing list: out of memory\n");
                exit(1);
            } else {
                // Replace the old list with the new one and signal the handler to update its capacity
                list = newList;
                sem_post(resizeSemaphore);
            }
        }

        // Populate a new structure in the list
        NFAPI_CRC_INDICATION_PDU_T *newEntry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        newEntry->rxUeInformation = getRXUEInformation();
        newEntry->rnti = generateRNTI();
        newEntry->crcIndicationRel8.crflag = generateCRCFlag();
        list[newEntry->crcIndicationRel8.crcSequenceNumber % maxCapacity] = newEntry;
    }
}

void *handleCRCIndications(void *args) {
    while (1) {
        sem_wait(resizeSemaphore);

        // Update the capacity of the list
        maxCapacity *= 2;

        // Update the queue size
        sem_post(crcIndicationQueue);
    }
}
