        }
    }

    // If there are no remaining elements, decrease the size of the memory pool by a factor of 2
    if (j == MAX_N) {
        int newSize = MAX_N / 2;

        // Allocate new memory for the shrunk memory pool
        void **newMemPool = malloc(sizeof(void *) * newSize);
        if (newMemPool == NULL) {
