        }

        // Copy the existing elements from the old memory pool to the new one
        for (int k = 0; k < MAX_N; k++) {
            if (memPool[k] != NULL) {
                newMemPool[k / 2] = memPool[k];
            }
        }

        // Free the old memory pool and update the reference to the new one
        free(memPool);
        memPool = newMemPool;
        MAX_N = newSize;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&memPoolMutex);
