// Dynamic List of LTE PHY Layer Test PDUs
typedef struct {
    size_t capacity;
    size_t count;
    lte_phy_layer_test_pdu_t *data;
} lte_phy_layer_test_list_t;

// Initialize a new dynamic list of LTE PHY Layer Test PDUs with the given capacity.
void init_lte_phy_layer_test_list(lte_phy_layer_test_list_t *list, size_t capacity) {
    list->capacity = capacity;
    list->count = 0;
    list->data = malloc(sizeof(lte_phy_layer_test_pdu_t) * capacity);
}

// Deinitialize a dynamic list of LTE PHY Layer Test PDUs.
void deinit_lte_phy_layer_test_list(lte_phy_layer_test_list_t *list) {
    free(list->data);
    memset(list, 0, sizeof(lte_phy_layer_test_list_t));
}

// Append a new LTE PHY Layer Test PDU to the end of the dynamic list.
void append_lte_phy_layer_test_pdu(lte_phy_layer_test_list_t *list, lte_phy_layer_test_pdu_t pdu) {
    if (list->count == list->capacity) {
        // Increase the capacity of the list if it's full.
        size_t new_capacity = list->capacity * 2;
        lte_phy_layer_test_pdu_t *new_data = realloc(list->data, sizeof(lte_phy_layer_test_pdu_t) * new_capacity);
        if (!new_data) {
            // Reallocation failed.
            return;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    list->data[list->count++] = pdu;
}

// Remove the last LTE PHY Layer Test PDU from the dynamic list.
