// Define a function to insert a new UE context into the linked list
void insert_ue_context(struct ue_context_list *list, int id, char *params, char *radio_state) {
    struct ue_context *new_ctx = malloc(sizeof(struct ue_context));
    new_ctx->id = id;
    new_ctx->params = strdup(params);
    new_ctx->radio_state = strdup(radio_state);

    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = new_ctx;
        list->tail = new_ctx;
    } else {
        list->tail->next = new_ctx;
        list->tail = new_ctx;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Define a function to remove an UE context from the linked list
void remove_ue_context(struct ue_context_list *list, int id) {
    struct ue_context *ctx = NULL;

    pthread_mutex_lock(&list->mutex);
    for (ctx = list->head; ctx != NULL; ctx = ctx->next) {
        if (ctx->id == id) {
            break;
        }
    }
    if (ctx == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    if (ctx == list->head) {
        list->head = ctx->next;
    } else {
        struct ue_context *prev = NULL;
        for (prev = list->head; prev != NULL && prev->next != ctx; prev = prev->next);
        if (prev == NULL) {
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        prev->next = ctx->next;
    }
    free(ctx->params);
    free(ctx->radio_state);
    free(ctx);
    pthread_mutex_unlock(&list->mutex);
}

