    struct ue_context *ctx = NULL;

    pthread_mutex_lock(&list->mutex);
    for (ctx = list->head; ctx != NULL; ctx = ctx->next) {
        if (ctx->id == id) {
            break;
        }
    }
    if (ctx == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    free(ctx->params);
    ctx->params = strdup(params);
    free(ctx->radio_state);
    ctx->radio_state = strdup(radio_state);
    pthread_mutex_unlock(&list->mutex);
}

