// Define a hash table to store the mapping between small keys and large data structures
typedef struct {
    struct large_data **table;
    size_t capacity;
} hash_table_t;

// Initialize a hash table with the given capacity
static void init_hash_table(hash_table_t *ht, size_t capacity) {
    ht->capacity = capacity;
    ht->table = (struct large_data **)calloc(capacity, sizeof(struct large_data *));
}

// Insert a mapping between the given small key and the given large data structure into the hash table
static void insert_into_hash_table(hash_table_t *ht, int small_key, struct large_data *large_data) {
    // Calculate the index of the hash table where the mapping should be stored
    size_t index = small_key % ht->capacity;

    // Check if there is already a mapping at the calculated index
    if (ht->table[index] != NULL) {
        // If there is, check if the small key of the existing mapping matches the given small key
        if (ht->table[index]->small_keys[0] == small_key) {
            // If it does, update the existing mapping with the new large data structure
            ht->table[index]->large_data = large_data;
            return;
        } else {
            // If not, linearly probe until an empty slot is found
            while (ht->table[index] != NULL) {
                index = (index + 1) % ht->capacity;
            }
        }
    }

    // Allocate memory for the new mapping and initialize it with the given small key and large data structure
    struct large_data *new_mapping = (struct large_data *)malloc(sizeof(struct large_data));
    new_mapping->small_keys = (int *)malloc(sizeof(int) * 1);
    new_mapping->num_small_keys = 1;
    new_mapping->large_data = large_data;
    ht->table[index] = new_mapping;
}

// Initialize a nested records array with the given capacity and fill it with empty mappings
static struct nested_records *initialize_nested_records(size_t capacity) {
    // Allocate memory for the nested records array
    struct nested_records *nested_records = (struct nested_records *)calloc(capacity, sizeof(struct nested_records));

    // Initialize each mapping in the nested records array with an empty large data structure and a value of 0 for the additional field
    for (size_t i = 0; i < capacity; ++i) {
        struct large_data *large_data = (struct large_data *)malloc(sizeof(struct large_data));
        large_data->small_keys = NULL;
        large_data->num_small_keys = 0;
        nested_records[i].large_data = large_data;
        nested_records[i].additional_field = 0;
    }

    return nested_records;
}

// Initialize the three data structures: large_data, small_keys, and nested_records
void initialize(struct large_data *large_data, int *small_keys, struct nested_records *nested_records) {
    // Allocate memory for the large_data structure
