#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <limits.h>

struct file_system {
    struct node *root;
};

struct node {
    char name[PATH_MAX];
    int permissions;
    time_t timestamp;
    enum type {FILE, DIRECTORY, SYMLINK} type;
    union {
        struct file {
            void *data;
            size_t size;
        } file;
        struct directory {
            struct node **children;
            int num_children;
        } directory;
        struct symlink {
            char target[PATH_MAX];
        } symlink;
    };
};

struct file_system *create_file_system() {
    struct file_system *fs = malloc(sizeof(struct file_system));
    fs->root = NULL;
    return fs;
}

void destroy_file_system(struct file_system *fs) {
    free(fs);
}

int add_node(struct file_system *fs, const char *path, enum type type) {
    struct node *parent = get_parent(fs->root, path);
    if (!parent) {
        return -1;
    }
    int index = get_index(parent, path);
    if (index < 0) {
        return -1;
    }
    struct node *node = malloc(sizeof(struct node));
    strcpy(node->name, path);
    node->type = type;
    node->timestamp = time(NULL);
    if (parent->children[index]) {
        free(parent->children[index]);
    }
    parent->children[index] = node;
    return 0;
}

int remove_node(struct file_system *fs, const char *path) {
    struct node *parent = get_parent(fs->root, path);
    if (!parent) {
        return -1;
    }
    int index = get_index(parent, path);
    if (index < 0) {
        return -1;
    }
    free(parent->children[index]);
    parent->children[index] = NULL;
    return 0;
}

struct node *get_node(struct file_system *fs, const char *path) {
    struct node *parent = get_parent(fs->root, path);
    if (!parent) {
        return NULL;
    }
    int index = get_index(parent, path);
    if (index < 0) {
        return NULL;
    }
    return parent->children[index];
}

struct node *get_parent(struct node *node, const char *path) {
    struct node *current = node;
    int i;
    for (i = 0; i < strlen(path); i++) {
        if (path[i] == '/') {
            current = get_child(current, &path[i+1]);
            if (!current) {
                return NULL;
            }
        }
    }
    return current;
}

struct node *get_child(struct node *node, const char *name) {
    int i;
    for (i = 0; i < node->num_children; i++) {
        if (!strcmp(node->children[i]->name, name)) {
            return node->children[i];
        }
    }
    return NULL;
}

int get_index(struct node *parent, const char *path) {
    int i;
    for (i = 0; i < parent->num_children; i++) {
        if (!strcmp(parent->children[i]->name, path)) {
            return i;
        }
    }
    return -1;
}
```
