struct NFAPI_CRC_INDICATION_ARRAY {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    pthread_mutex_t mutex;
};

void nfapi_crc_indication_array_init(NFAPI_CRC_INDICATION_ARRAY *array) {
    array->size = 0;
    array->array = NULL;
}

int nfapi_crc_indication_array_alloc(NFAPI_CRC_INDICATION_ARRAY *array, size_t num_elements) {
    if (num_elements == 0) {
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_elements);
    if (new_array == NULL) {
        return -1;
    }

    for (size_t i = 0; i < num_elements; ++i) {
        new_array[i].RX_UE_INFORMATION_TAG = rand();
        new_array[i].RNTI = rand();
        new_array[i].CRCFLAG = (char)rand() & 0x1;
    }

    pthread_mutex_lock(&array->mutex);
    if (array->array != NULL) {
        free(array->array);
    }
    array->array = new_array;
    array->size = num_elements;
    pthread_mutex_unlock(&array->mutex);

    return 0;
}

int nfapi_crc_indication_array_resize(NFAPI_CRC_INDICATION_ARRAY *array, size_t num_elements) {
    if (num_elements == array->size) {
        // No change in size
        return 0;
    } else if (num_elements < array->size) {
        // Shrink the array
        pthread_mutex_lock(&array->mutex);
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(array->array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_elements);
        if (new_array == NULL) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->array = new_array;
        array->size = num_elements;
        pthread_mutex_unlock(&array->mutex);
    } else {
        // Grow the array
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(array->array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_elements);
        if (new_array == NULL) {
            return -1;
        }
        for (size_t i = array->size; i < num_elements; ++i) {
            new_array[i].RX_UE_INFORMATION_TAG = rand();
            new_array[i].RNTI = rand();
            new_array[i].CRCFLAG = (char)rand() & 0x1;
        }
        pthread_mutex_lock(&array->mutex);
        array->array = new_array;
        array->size = num_elements;
        pthread_mutex_unlock(&array->mutex);
    }

    return 0;
}

int nfapi_crc_indication_array_add(NFAPI_CRC_INDICATION_ARRAY *array, NFAPI_CRC_INDICATION_PDU_T new_element) {
    if (array->size == 0) {
        // Initial allocation
        pthread_mutex_lock(&array->mutex);
        array->array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (array->array == NULL) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        memcpy(array->array, &new_element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        array->size = 1;
        pthread_mutex_unlock(&array->mutex);
    } else {
        // Grow the array by one element
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(array->array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (array->size + 1));
        if (new_array == NULL) {
            return -1;
        }
        memcpy(&new_array[array->size], &new_element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        array->array = new_array;
        array->size++;
    }

    return 0;
