// Define structure for UE context record
typedef struct {
    int ue_id;
    char mac_addr[6];
    char ip_addr[16];
} ue_context_t;

// Define array of UE context records
ue_context_t *ue_array = NULL;
size_t num_ues = 0;
pthread_mutex_t mutex;

// Function to update IP configuration for a specific UE ID
void update_ip_config(int ue_id, char *new_ip_addr) {
    // Lock the mutex to synchronize access from multiple threads
    pthread_mutex_lock(&mutex);

    // Find the corresponding UE context record
    int i;
    for (i = 0; i < num_ues; i++) {
        if (ue_array[i].ue_id == ue_id) {
            break;
        }
    }

    // Check if the UE ID was found
    if (i == num_ues) {
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Update the IP address in the corresponding record
    strcpy(ue_array[i].ip_addr, new_ip_addr);

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to add a new UE context record
void add_ue(int ue_id, char *mac_addr, char *ip_addr) {
    // Lock the mutex to synchronize access from multiple threads
    pthread_mutex_lock(&mutex);

    // Allocate memory for the new UE context record
    ue_context_t *new_ue = malloc(sizeof(ue_context_t));
    if (!new_ue) {
        fprintf(stderr, "Failed to allocate memory for new UE\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Initialize the fields of the new UE context record
    new_ue->ue_id = ue_id;
    strcpy(new_ue->mac_addr, mac_addr);
    strcpy(new_ue->ip_addr, ip_addr);

    // Add the new UE context record to the array
    ue_array = realloc(ue_array, (num_ues + 1) * sizeof(ue_context_t));
    if (!ue_array) {
        fprintf(stderr, "Failed to allocate memory for updated UE array\n");
        free(new_ue);
        pthread_mutex_unlock(&mutex);
        return;
    }
    ue_array[num_ues++] = *new_ue;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to delete a UE context record by ID
void del_ue(int ue_id) {
    // Lock the mutex to synchronize access from multiple threads
    pthread_mutex_lock(&mutex);

    // Find the corresponding UE context record
    int i;
    for (i = 0; i < num_ues; i++) {
        if (ue_array[i].ue_id == ue_id) {
            break;
        }
    }

    // Check if the UE ID was found
    if (i == num_ues) {
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Remove the UE context record from the array
    for (int j = i; j < num_ues - 1; j++) {
        ue_array[j] = ue_array[j + 1];
    }
    num_ues--;

    // Free the memory of the deleted UE context record
    free(ue_array[i].ip_addr);
    free(ue_array[i].mac_addr);
    free(ue_array[i]);

    // Reallocate the memory of the updated array to remove the gap caused by the deleted record
    ue_array = realloc(ue_array, num_ues * sizeof(ue_context_t));
    if (!ue_array) {
        fprintf(stderr, "Failed to allocate memory for updated UE array\n");
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to safely delete the entire array structure and free all associated resources
void del_all() {
    // Lock the mutex to synchronize access from multiple threads
    pthread_mutex_lock(&mutex);

    // Free the memory of each UE context record in the array
    for (int i = 0; i < num_ues; i++) {
        free(ue_array[i].ip_addr);
        free(ue_array[i].mac_addr);
        free(ue_array[i]);
    }

    // Free the memory of the array structure
    free(ue_array);

    // Set the array to NULL and the number of UE contexts to 0
    ue_array = NULL;
    num_ues = 0;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}
