void init_list(size_t num_init) {
    // Allocate memory for the array
    connections = (tcp_connection_t *)malloc(sizeof(tcp_connection_t) * num_init);
    if (!connections) {
        fprintf(stderr, "Failed to allocate memory for TCP connection records\n");
