        int j = 0;
        while (j != i) {
            key_arr[i].key = min_val + ((int)(rand() % (max_val - min_val + 1)));
            for (int k = 0; k < i; k++) {
                if (key_arr[k].key == key_arr[i].key) {
                    j++;
                    break;
                }
            }
        }
    }

    // Implement dynamic resizing mechanism for the record array
    struct record *temp = realloc(records, n * sizeof(struct record));
    if (temp == NULL) {
