        printf("offset_arr[%d] = %ld\n", i, offset_arr[i].offset);
        printf("key_arr[%d] = %d\n", i, key_arr[i].key);
        printf("records[%d] = %d\n", i, records[i].value);
    }
    #endif

    // Free memory for the three arrays
    free(offset_arr);
    free(key_arr);
    free(records);
}
