// Function to read a potentially large list of integers from standard input, ensuring the input does not exceed 10,000 integers.
int read_input(LINKED_LIST_NFAPI_CRC_INDICATION_PDU_T *list, unsigned int seed) {
    // Initialize the linked list
    list->head = NULL;
    list->tail = NULL;

    // Check if the input exceeds 10,000 integers
