            NFAPI_CRC_INDICATION_PDU_T *new_structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            new_structure->RX_UE_INFORMATION_TAG = input;
            new_structure->RNTI = rand_r(&seed) % 10000; // Generate a random RNTI between 0 and 9999 using the given seed
            new_structure->CRCFLAG = rand_r(&seed) % 2 ? 1 : 0; // Generate a random CRCFLAG value using the given seed
            new_structure->timestamp = time(NULL);
            list->tail = list->head = new_structure;
        } else {
            printf("Error: Invalid input detected. Please enter a valid integer.\n");
            return -1;
        }

        // Increment the global counter for tracking the number of valid structures created
        num_valid_structures++;
    }

    // Check if the input was empty or exceeded 10,000 integers
    if (num_valid_structures == 0) {
        printf("Error: Input was empty or exceeded maximum limit of 10,000 integers\n");
        return -1;
    }

    // Print the largest integer in the array using a helper function
    unsigned int max = find_largest(list);
    printf("Largest integer in the input: %d\n", max);

    // Validate that each RNTI corresponds to a unique value
    for (NFAPI_CRC_INDICATION_PDU_T *current = list->head; current != NULL; current = current->next) {
        if (current->RNTI == 0 || current->RNTI >= 10000) {
            printf("Error: Duplicate RNTI detected. Please enter a valid integer.\n");
            return -1;
        }
    }

    return 0;
}

// Helper function to find the largest integer in the linked list of NFAPI_CRC_INDICATION_PDU_T structures
unsigned int find_largest(LINKED_LIST_NFAPI_CRC_INDICATION_PDU_T *list) {
    unsigned int max = 0;
    for (NFAPI_CRC_INDICATION_PDU_T *current = list->head; current != NULL; current = current->next) {
        if (current->RX_UE_INFORMATION_TAG > max) {
            max = current->RX_UE_INFORMATION_TAG;
        }
    }
    return max;
}

// Function to gracefully terminate with an appropriate error message and return an error code if an invalid integer or duplicate RNTI is encountered
int handle_error(LINKED_LIST_NFAPI_CRC_INDICATION_PDU_T *list, unsigned int seed) {
    // Free all the structures allocated in the linked list
    for (NFAPI_CRC_INDICATION_PDU_T *current = list->head; current != NULL; current = current->next) {
        free(current);
