	// Check if there are any changes in the size of either list
	if (pduCount != ccoRequestCount) {
		// If so, resize both lists to match each other
		resizeCollections(pduList, ccoRequestList, pduCount, ccoRequestCount);
	}

	// Add new structures to the appropriate lists as necessary
	for (int i = 0; i < pduCount; i++) {
		NFAPI_CRC_INDICATION_PDU_T *pdu = getCollectionElement(pduList, i);

		if (pdu != NULL) {
			// Check if the RX_UE_INFORMATION_TAG is valid
			if (isValidRxUeInformationTag(pdu->rx_ue_information.tag)) {
				// Add the new structure to the CRC indication list
				addCrcIndicationPduToList(ccoRequestList, pdu);
			}
		}
	}

	for (int i = 0; i < ccoRequestCount; i++) {
		NFAPI_RRC_CCO_REQUEST *ccoRequest = getCollectionElement(ccoRequestList, i);

