				// Add the new structure to the RRC CCO request list
				addRrcCcoRequestToList(pduList, ccoRequest);
			}
		}
	}

	// Serialize and deserialize both lists using a specified file format
	serializeCollections(pduList, ccoRequestList, getFileFormat());
	deserializeCollections(pduList, ccoRequestList, getFileFormat());

	// Free all resources promptly in case of errors
	freeCollection(pduList);
	freeCollection(ccoRequestList);
