NFAPI_RRC_CU_TRANSPORT_PDU_T* arr = NULL;
size_t arr_capacity = 0; // Current capacity of the array
size_t arr_length = 0; // Current length of the array

// Initialize and populate the array with random data
void init_and_populate(size_t num_elements) {
    if (arr != NULL) {
        free(arr);
        arr = NULL;
    }

    // Dynamically allocate memory for the array based on the requested size
    arr_capacity = num_elements * sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T);
    arr = (NFAPI_RRC_CU_TRANSPORT_PDU_T*)malloc(arr_capacity);
    if (arr == NULL) {
        printf("Error: Failed to allocate memory for the array\n");
        return;
    }

    // Populate the array with random data
    for (size_t i = 0; i < num_elements; i++) {
        arr[i].message_type = rand() % NFAPI_RRC_MAX_MESSAGE_TYPE;
        arr[i].transport_channel = rand() % RRC_TRANSPORT_CHANNEL_MAX;
        arr[i].pdcp_sn = rand();
        arr[i].rnti = rand() % 65536;
        arr[i].last_updated = time(NULL);
    }

    // Set the length of the array to the requested size
    arr_length = num_elements;
}

// Add a new element to the array with random data and update the length
void add_element() {
    if (arr == NULL) {
        init_and_populate(1);
    } else if (arr_length >= arr_capacity / 2) {
        // Reallocate memory for the array to double its capacity
        size_t new_capacity = arr_capacity * 2;
        NFAPI_RRC_CU_TRANSPORT_PDU_T* new_arr = (NFAPI_RRC_CU_TRANSPORT_PDU_T*)realloc(arr, new_capacity);
        if (new_arr == NULL) {
            printf("Error: Failed to reallocate memory for the array\n");
            return;
        }
        arr = new_arr;
        arr_capacity = new_capacity;
    }

    // Add a new element with random data at the end of the array
    size_t index = arr_length++;
    arr[index].message_type = rand() % NFAPI_RRC_MAX_MESSAGE_TYPE;
    arr[index].transport_channel = rand() % RRC_TRANSPORT_CHANNEL_MAX;
    arr[index].pdcp_sn = rand();
    arr[index].rnti = rand() % 65536;
    arr[index].last_updated = time(NULL);
}

// Remove an element from the array and update the length
void remove_element(size_t index) {
    if (index >= arr_length || arr == NULL) {
        printf("Error: Invalid index or empty array\n");
        return;
    }

    // Shift all elements after the removed element to fill the gap
    for (size_t i = index + 1; i < arr_length; i++) {
        arr[i - 1] = arr[i];
    }

    // Decrement the length of the array
    arr_length--;
}

// Serialize and deserialize the array for inter-process communication
void serialize(char* buffer, size_t buf_size) {
    if (arr == NULL || buffer == NULL) {
        printf("Error: Invalid input\n");
        return;
    }

    // Write the length of the array to the beginning of the buffer
    memcpy(buffer, &arr_length, sizeof(size_t));

    // Write each element of the array to the buffer
    for (size_t i = 0; i < arr_length; i++) {
        NFAPI_RRC_CU_TRANSPORT_PDU_T* elem = &arr[i];
        memcpy(buffer + sizeof(size_t) + i * sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T), elem, sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T));
    }
}

void deserialize(char* buffer, size_t buf_size) {
    if (buffer == NULL) {
        printf("Error: Invalid input\n");
        return;
    }

    // Read the length of the array from the beginning of the buffer
    memcpy(&arr_length, buffer, sizeof(size_t));

    // Reallocate memory for the array based on the read length
    if (arr != NULL) {
        free(arr);
        arr = NULL;
    }
    arr_capacity = arr_length * sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T);
    arr = (NFAPI_RRC_CU_TRANSPORT_PDU_T*)malloc(arr_capacity);
    if (arr == NULL) {
        printf("Error: Failed to allocate memory for the array\n");
        return;
    }

    // Read each element of the array from the buffer
    size_t index = 0;
    while (index < arr_length) {
        NFAPI_RRC_CU_TRANSPORT_PDU_T* elem = &arr[index];
        memcpy(elem, buffer + sizeof(size_t) + index * sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T), sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T));
        index++;
    }
}

// Logging system for detailed information about each operation
void log_operation(char* message, size_t length) {
    printf("%s\n", message);
    // Log additional details such as the time, thread ID, etc.
}

int main() {
    char buffer[4096];
    while (true) {
        // Read a command from the user
        scanf("%d", &cmd);
        switch(cmd) {
            case 1: add_element(); break;
            case 2: remove_element(); break;
            case 3: serialize(buffer, sizeof(buffer)); break;
            case 4: deserialize(buffer, sizeof(buffer)); break;
        }
    }
    return 0;
}
