    int32_t header;
    int32_t tlv[1];
};

int main() {
    // Create an instance of the HttpClient class
    HttpClient http = HttpClient();

    // Define a list to hold the PNF Discovery Request messages
    vector<pfn_discovery_request> requests;

    // Generate a PNF Discovery Request message and add it to the list
    pfn_discovery_request request;
    request.header = { NFAPI_PNF_DISCOVERY_REQUEST, 0, 0 };
    request.tlv[0] = { NFAPI_TLV_TYPE_UNSIGNED8, NFAPI_PNF_DISCOVERY_REQUEST_ADDRESS_TLV_TYPE, 123456789 };
    requests.push_back(request);

    // Iterate over the list of PNF Discovery Request messages and send each one to the server using the HttpClient object
    for (auto& request : requests) {
        // Create a JSON string representation of the PNF Discovery Request message
        Json json = json::parse(request);
        string json_string = json.dump();

        // Serialize the JSON string to a byte array and send it to the server using the HttpClient object
        std::vector<char> data;
        data.resize(json_string.size());
        memcpy(data.data(), json_string.c_str(), json_string.size());
        http.Send("http://localhost:8080/nfapi", "POST", data);
    }

    // Return success
    return 0;
}
