// Custom message structure
typedef struct {
    time_t timestamp;
    int userID;
    int priorityLevel;
    char* metadata;
} Message;

// Dynamic array of messages
static Message* messages = NULL;
static size_t numMessages = 0;

// TTL configuration
#define DEFAULT_TTL (60 * 60) // 1 hour in seconds
static int ttl = DEFAULT_TTL;

// Mutex for thread-safe operations
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Periodic flushing mechanism
#define FLUSH_INTERVAL (60 * 10) // 10 minutes in seconds
static struct timespec lastFlushTime = {0, 0};

// Batch processing feature
#define MAX_BATCH_SIZE 1024
static int batchSize = 0;
static Message* batchMessages[MAX_BATCH_SIZE];

// Dynamic adjustment of TTL based on user activity patterns
static double avgUserActivity = 0;
static double avgUserActivityVariance = 0;
static double currentUserActivity = 0;
static struct timespec lastActivityTime = {0, 0};

// Serialization and deserialization mechanism for persisting messages to disk
#define MESSAGES_FILE "messages.dat"

// Serialize the message collection to disk
void serializeMessages() {
    FILE* fp = fopen(MESSAGES_FILE, "wb");
    if (!fp) {
        perror("fopen");
        return;
    }
    for (size_t i = 0; i < numMessages; ++i) {
        Message* message = &messages[i];
        fwrite(&message->timestamp, sizeof(time_t), 1, fp);
        fwrite(&message->userID, sizeof(int), 1, fp);
        fwrite(&message->priorityLevel, sizeof(int), 1, fp);
        fwrite(&message->metadata, sizeof(char*), 1, fp);
    }
    fclose(fp);
}

// Deserialize the message collection from disk
void deserializeMessages() {
    FILE* fp = fopen(MESSAGES_FILE, "rb");
    if (!fp) {
        perror("fopen");
        return;
    }
    while (!feof(fp)) {
        Message message;
        fread(&message.timestamp, sizeof(time_t), 1, fp);
        fread(&message.userID, sizeof(int), 1, fp);
        fread(&message.priorityLevel, sizeof(int), 1, fp);
        fread(&message.metadata, sizeof(char*), 1, fp);
        addMessage(&message);
    }
    fclose(fp);
}

// Add a message to the dynamic array of messages
void addMessage(const Message* message) {
    pthread_mutex_lock(&mutex);
    if (numMessages == 0) {
        messages = malloc(sizeof(Message));
    } else {
        messages = realloc(messages, (++numMessages) * sizeof(Message));
    }
    memcpy(&messages[numMessages - 1], message, sizeof(Message));
    pthread_mutex_unlock(&mutex);
}

// Remove a message from the dynamic array of messages
void removeMessage(const Message* message) {
    pthread_mutex_lock(&mutex);
    size_t i = 0;
    while (i < numMessages && memcmp(&messages[i], message, sizeof(Message)) != 0) {
        ++i;
    }
    if (i < numMessages) {
        for (size_t j = i + 1; j < numMessages; ++j) {
            memcpy(&messages[j - 1], &messages[j], sizeof(Message));
        }
        --numMessages;
    }
    pthread_mutex_unlock(&mutex);
}

// Set the TTL for messages
void setTTL(int ttl) {
    this->ttl = ttl;
}

// Get the TTL for messages
int getTTL() {
    return ttl;
}

// Periodically flush expired messages to a log file
void flushMessages() {
    struct timespec now = {0, 0};
    clock_gettime(CLOCK_REALTIME, &now);
    if (difftime(now.tv_sec, lastFlushTime.tv_sec) >= FLUSH_INTERVAL) {
        FILE* fp = fopen("messages.log", "a");
        for (size_t i = 0; i < numMessages; ++i) {
            Message* message = &messages[i];
            if (difftime(now.tv_sec, message->timestamp) >= ttl) {
                fprintf(fp, "Message expired: %ld\n", message->timestamp);
            } else {
                fwrite(&message->timestamp, sizeof(time_t), 1, fp);
                fwrite(&message->userID, sizeof(int), 1, fp);
                fwrite(&message->priorityLevel, sizeof(int), 1, fp);
                fwrite(&message->metadata, sizeof(char*), 1, fp);
            }
        }
        fclose(fp);
        lastFlushTime = now;
    }
}

// Batch process messages for atomic transactions
void batchProcessMessages() {
    pthread_mutex_lock(&mutex);
    size_t i = 0;
    while (i < numMessages && batchSize < MAX_BATCH_SIZE) {
        Message* message = &messages[i];
        memcpy(&batchMessages[batchSize++], message, sizeof(Message));
        ++i;
    }
    pthread_mutex_unlock(&mutex);
}

// Adjust TTL based on user activity patterns
void adjustTTL() {
    struct timespec now = {0, 0};
    clock_gettime(CLOCK_REALTIME, &now);
    if (difftime(now.tv_sec, lastActivityTime.tv_sec) >= 10) { // 10 seconds
        double avgUserActivity = 0;
        for (size_t i = 0; i < numMessages; ++i) {
            Message* message = &messages[i];
            if (message->priorityLevel > 2) {
                avgUserActivity += 1.0 / (double)(numMessages - i);
            }
        }
        double avgUserActivityVariance = 0;
        for (size_t i = 0; i < numMessages; ++i) {
            Message* message = &messages[i];
            if (message->priorityLevel > 2) {
                double delta = fabs(avgUserActivity - 1.0 / (double)(numMessages - i));
                avgUserActivityVariance += delta * delta;
            }
        }
        setTTL((int)(3600 * sqrt(avgUserActivityVariance))); // 1 hour
        lastActivityTime = now;
    }
}
