// Define the messages array and its size
message_t *messages[MESSAGES_SIZE];
size_t num_messages = 0;

// Define the records array and its size for each message
record_t **records[MAX_RECORDS];

// Function to add a new message
void add_message(const message_t *msg) {
  // Lock the messages array to prevent concurrent access
  pthread_mutex_lock(&messages_lock);

  // Check if the maximum number of messages has been reached
  if (num_messages >= MESSAGES_SIZE) {
    // Unlock the messages array and return
    pthread_mutex_unlock(&messages_lock);
    return;
  }

  // Add the new message to the end of the messages array
  messages[num_messages] = msg;

  // Initialize the records array for the new message
  records[num_messages] = malloc(MAX_RECORDS * sizeof(record_t));
  if (records[num_messages] == NULL) {
    perror("malloc");
    return;
  }

  // Increment the number of messages
  num_messages++;

  // Unlock the messages array
  pthread_mutex_unlock(&messages_lock);
}

// Function to remove a message that has exceeded its TTL
void remove_message(const message_t *msg) {
  // Lock the messages array to prevent concurrent access
  pthread_mutex_lock(&messages_lock);

  // Find the index of the message in the messages array
  int i;
  for (i = 0; i < num_messages; i++) {
    if (msg == messages[i]) {
      break;
    }
  }

  // Check if the message was found
  if (i >= num_messages) {
    // Unlock the messages array and return
    pthread_mutex_unlock(&messages_lock);
    return;
  }

  // Remove the message from the messages array
  messages[i] = NULL;

  // Decrement the number of messages
  num_messages--;

  // Free the records array for the removed message
  free(records[i]);
  records[i] = NULL;

  // Unlock the messages array
  pthread_mutex_unlock(&messages_lock);
}

// Function to add a new record to a message
void add_record(const message_t *msg, const record_t *rec) {
  // Lock the records array for the message to prevent concurrent access
  pthread_mutex_lock(&messages_lock);

