  if (i >= num_messages) {
    // Unlock the records array and return
    pthread_mutex_unlock(&messages_lock);
    return;
  }

  // Check if the maximum number of records has been reached for the message
  if (records[i] == NULL || num_records >= MAX_RECORDS) {
    // Unlock the records array and return
    pthread_mutex_unlock(&messages_lock);
    return;
  }

  // Add the new record to the end of the records array for the message
  records[i][num_records] = rec;

  // Increment the number of records for the message
  num_records++;

  // Unlock the records array
  pthread_mutex_unlock(&messages_lock);
}

// Function to remove a record from a message
void remove_record(const message_t *msg, const int key) {
  // Lock the records array for the message to prevent concurrent access
  pthread_mutex_lock(&messages_lock);

