    if (key == records[i][j].key) {
      break;
    }
  }

  // Check if the record was found
  if (j >= num_records) {
    // Unlock the records array and return
    pthread_mutex_unlock(&messages_lock);
    return;
  }

  // Remove the record from the records array for the message
  records[i][j] = NULL;

  // Decrement the number of records for the message
  num_records--;

  // Unlock the records array
  pthread_mutex_unlock(&messages_lock);
}

// Function to log a message and its records
