#include "mac_event_struct.h"

// Define the maximum number of events to store in the list
#define MAX_EVENTS 1000

// Define the struct for storing event data
typedef struct mac_event {
    MAC_EVENT_TAG tag;
    VLAN_ID vlan_id;
    pcap_pkthdr *header;
} mac_event_t;

// Define a linked list to store the events
struct event_list {
    mac_event_t *head;
    mac_event_t *tail;
};

// Function to add an event to the list
void add_event(mac_event_t *event) {
    // Check if the list is full
    if (event_list->size == MAX_EVENTS) {
        // If so, prune the least relevant events first
        prune_events();
    }

    // Add the event to the tail of the list
    event_list->tail = event;
    event_list->tail->next = NULL;

    // Update the size of the list
    event_list->size++;
}

// Function to prune events from the list based on user-defined criteria
void prune_events() {
    // Define a threshold for the minimum number of packets in an event
    #define MIN_PACKETS 50

    // Define a weighting factor for each event's relevance
    #define RELEVANCE_WEIGHT 2

    // Initialize a temporary list to store the relevant events
    struct event_list temp_list;
    temp_list.head = NULL;
    temp_list.tail = NULL;
    temp_list.size = 0;

    // Iterate through the events in the main list
    mac_event_t *current = event_list->head;
    while (current != NULL) {
        // Check if the current event has enough packets to be relevant
        if (current->header->len >= MIN_PACKETS) {
            // If so, add it to the temporary list
            temp_list.tail = current;
            temp_list.tail->next = NULL;
            temp_list.size++;

            // Update the size of the main list
            event_list->size--;
        } else {
            // If not, move on to the next event
            current = current->next;
        }
    }

    // Swap the temporary list with the main list
    struct event_list *temp = event_list;
    event_list = &temp_list;

    // Clean up the memory for the pruned events
    current = temp_list.head;
    while (current != NULL) {
        mac_event_t *next = current->next;
        free(current);
        current = next;
    }
}

// Function to log an event addition
void log_addition(mac_event_t *event) {
    // Define a timestamp for the addition
    time_t now = time(NULL);

    // Log the addition with the relevant information
    printf("[%s] Added event (tag: %d, vlan_id: %d)\n", ctime(&now), event->tag, event->vlan_id);
}

// Function to log an error during an event addition
void log_error(const char *message) {
    // Define a timestamp for the error
    time_t now = time(NULL);

    // Log the error with the relevant information
    printf("[%s] ERROR: %s\n", ctime(&now), message);
}

// Function to securely write logs to a designated file
void log_to_file(const char *message) {
    // Define a buffer for the message
    char buffer[1024];

    // Write the message to the buffer
    snprintf(buffer, 1024, "%s", message);

    // Open the log file in append mode
    FILE *log_file = fopen("log.txt", "a");

    // Check if the file was opened successfully
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return;
    }

    // Write the buffer to the log file
    fputs(buffer, log_file);

    // Close the log file
    fclose(log_file);
}
