// Define a struct for holding the integer value
struct record {
    int value;
};

// Function to dynamically allocate memory for and initialize
// arrays of 'long' offset values, 'int' keys, and 'record' structures
void init_arrays(size_t n) {
    // Allocate memory for the array of long offsets
    long *offsets = malloc(n * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offset array\n");
        return;
    }
    // Initialize the array of long offsets with random values within a specified range
    srand(time(NULL));
    for (size_t i = 0; i < n; i++) {
        offsets[i] = rand() % (10 * n);
    }
    // Allocate memory for the array of integer keys
    int *keys = malloc(n * sizeof(int));
    if (!keys) {
        printf("Error: Failed to allocate memory for key array\n");
        free(offsets);
        return;
    }
    // Initialize the array of integer keys with random values within a specified range
    srand(time(NULL));
    for (size_t i = 0; i < n; i++) {
        keys[i] = rand() % (10 * n);
    }
    // Allocate memory for the array of record structures
    struct record *records = malloc(n * sizeof(struct record));
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return;
    }
    // Initialize the array of record structures with random integer values within a specified range
    srand(time(NULL));
    for (size_t i = 0; i < n; i++) {
        records[i].value = rand() % (10 * n);
    }
    // Align all memory allocations to 8-byte boundaries
    offsets = (long *)(((uintptr_t)offsets + 7) & ~7);
    keys = (int *)(((uintptr_t)keys + 7) & ~7);
    records = (struct record *)(((uintptr_t)records + 7) & ~7);
}

// Function to deallocate memory for the arrays of 'long' offset values, 'int' keys, and 'record' structures
void free_arrays() {
    // Free the memory allocated for the array of long offsets
    free((void *)offsets);
    // Free the memory allocated for the array of integer keys
    free((void *)keys);
    // Free the memory allocated for the array of record structures
    free((void *)records);
}
