    size_t size;
} TRANSMIT_BUFFER_CONFIG;

typedef struct {
    TRANSPORT_FORMAT_CONFIG format;
    TRANSMIT_BUFFER_CONFIG buffer;
} TX_MESSAGE_PDU_T;

TX_MESSAGE_PDU_T* populate_array(int num_requests, int initial_capacity) {
    // Initialize the array with random values within the permissible range
    srand(time(NULL));
    TX_MESSAGE_PDU_T* array = (TX_MESSAGE_PDU_T*)malloc(initial_capacity * sizeof(TX_MESSAGE_PDU_T));
    for (int i = 0; i < initial_capacity; i++) {
        TX_MESSAGE_PDU_T pdu = { .format = { .transmit_power_level = rand() % MAX_TRANSMIT_POWER_LEVEL,
                                          .channel_bandwidth = rand() % MAX_CHANNEL_BANDWIDTH },
                                .buffer = { .size = rand() % MAX_BUFFER_SIZE,
                                            .buffer = (char*)malloc(rand() % MAX_BUFFER_SIZE * sizeof(char)) } };
        array[i] = pdu;
    }
    return array;
}

void resize_array(TX_MESSAGE_PDU_T** array, int new_capacity) {
    TX_MESSAGE_PDU_T* new_array = (TX_MESSAGE_PDU_T*)realloc(*array, new_capacity * sizeof(TX_MESSAGE_PDU_T));
    if (!new_array) {
        fprintf(stderr, "Failed to resize array: %s\n", strerror(errno));
        return;
    }
    *array = new_array;
}

TX_MESSAGE_PDU_T* manage_array(int num_requests, int initial_capacity) {
    TX_MESSAGE_PDU_T* array = populate_array(num_requests, initial_capacity);
    if (!array) {
        fprintf(stderr, "Failed to allocate memory for array: %s\n", strerror(errno));
        return NULL;
    }
    // Handle concurrent access and potential errors
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
    int num_threads = 0;
    while (1) {
        // Wait for a request to be added to the queue
        pthread_mutex_lock(&mutex);
        while (!array->format.transmit_power_level || !array->buffer.size) {
            pthread_cond_wait(&cond, &mutex);
        }
        // Handle error conditions and resize the array if necessary
        int current_capacity = initial_capacity;
        while (num_threads >= current_capacity) {
            resize_array(&array, current_capacity * 2);
            current_capacity = current_capacity * 2;
        }
        // Add the request to the queue and signal other threads
        array->format.transmit_power_level++;
        array->buffer.size++;
        pthread_cond_broadcast(&cond);
        num_threads++;
        pthread_mutex_unlock(&mutex);
    }
    return array;
}
```
