void handle_duplicate_rnti(NFAPI_RRC_PDU_T *rx_frame, NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu) {
    // Check if the RNTI is already present in the array
    for (int i = 0; i < rx_frame->rx_frame.num_rnti; i++) {
