    if (rnti < 1 || rnti > 65535) {
        return -1;
    }

    // Lock the mutex to ensure thread safety during write operations on the list
    pthread_mutex_lock(&list_mutex);

    // Check if the list is full and needs to be resized
    if (list->num_elements == MAX_LIST_SIZE) {
        // Resize the list by doubling its size
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list->list, 2 * list->num_elements);

        if (new_list == NULL) {
