    // Lock the mutex to ensure thread safety during write operations on the list
    pthread_mutex_lock(&list_mutex);

    // Check if the RNTI is in the list and remove it
    for (int i = 0; i < list->num_elements; i++) {
        if (list->list[i].rnti == rnti) {
            // Shift the remaining elements to fill the gap
            memmove(list->list + i, list->list + i + 1, (list->num_elements - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

            // Decrement the list size
            list->num_elements--;

            // Unlock the mutex and return success
            pthread_mutex_unlock(&list_mutex);
            return 0;
        }
