    pthread_mutex_unlock(&list->lock);
}

// Function to remove a specific NFAPI_CRC_INDICATION_PDU_T structure from the list by RNTI value
bool removeFromDynamicList(DynamicList* list, int RNTI) {
    if (!list || list->size == 0) {
        return false;
    }
    for (int i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI == RNTI) {
            pthread_mutex_lock(&list->lock);
            --list->size;
            memmove(&list->data[i], &list->data[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->size - i));
            pthread_mutex_unlock(&list->lock);
            return true;
        }
    }
    return false;
}

// Function to query the number of unique RNTIs currently in the list
int getDynamicListSize(DynamicList* list) {
    if (!list || list->size == 0) {
        return 0;
    }
