}

// Function to handle memory deallocation failures gracefully by logging an error message and returning NULL
void safeFree(void* ptr) {
    if (ptr) {
        free(ptr);
    } else {
        printf("Error: Unable to free memory\n");
    }
}

// Function to handle mutex unlocking failures gracefully by logging an error message and returning NULL
void safeUnlockMutex(pthread_mutex_t* mutex) {
