  if (!pdu_array) {
    printf("Memory allocation failed\n");
    return NULL;
  }

  // Initialize memory pool for efficient allocation and deallocation of PDU structures
  MemoryPool* mem_pool = (MemoryPool*)malloc(sizeof(MemoryPool));
  if (!mem_pool) {
    free(pdu_array);
    printf("Memory allocation failed\n");
    return NULL;
  }
  mem_pool->size = array_size;
  mem_pool->used_size = 0;
  mem_pool->next_free = pdu_array;

  // Populate the PDU array with random values
  for (int i = 0; i < n; ++i) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = &pdu_array[i];
    pdu->rx_ue_information_tag = seed + i * 23;
    pdu->rnti = seed + i * 17;
