    } else {
      pdu->crc_indication_rel8_tag &= ~(1 << 31);
    }
  }

  // Log memory usage and allocation failures for debugging purposes
  printf("Memory usage: %d bytes\n", mem_pool->used_size);
  if (mem_pool->used_size > mem_pool->size) {
    printf("Memory pool overflow!\n");
  }

  // Return the populated PDU array
  return pdu_array;
}

