static LTE_UE_CONTEXT_T *lte_ue_contexts = NULL;

void manage_crc_and_ue_contexts(size_t n) {
    assert(n > 0);

    // reallocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures if necessary
    if (n != lte_ue_contexts) {
        lte_ue_contexts = realloc(lte_ue_contexts, n * sizeof(*lte_ue_contexts));
        assert(lte_ue_contexts);
    }

    // initialize the new elements of the array with default values
    for (size_t i = lte_ue_contexts->num; i < n; ++i) {
        LTE_UE_CONTEXT_T *ctx = &lte_ue_contexts[i];
        ctx->rnti = 0;
        ctx->reports = malloc(M * sizeof(*ctx->reports));
        assert(ctx->reports);
        for (size_t j = 0; j < M; ++j) {
            MEASUREMENT_REPORT_T *report = &ctx->reports[j];
            report->timestamp = 0;
            report->cell_id = 0;
            report->signal_strength = 0;
        }
    }
}

