    LTE_UE_CONTEXT_T *ctx = NULL;
    for (size_t i = 0; i < lte_ue_contexts->num; ++i) {
        if (lte_ue_contexts[i].rnti == rnti) {
            ctx = &lte_ue_contexts[i];
            break;
        }
    }

    // update the CRCFLAG value in the context if it exists
    if (ctx) {
        ctx->crc_indication_rel8_tag = crc_indication_rel8_tag;
    }
}

void add_measurement_report(uint32_t rx_ue_information_tag, uint16_t rnti, uint64_t timestamp, uint16_t cell_id, int8_t signal_strength) {
    // find the context for the given RNTI
    LTE_UE_CONTEXT_T *ctx = NULL;
    for (size_t i = 0; i < lte_ue_contexts->num; ++i) {
        if (lte_ue_contexts[i].rnti == rnti) {
            ctx = &lte_ue_contexts[i];
            break;
        }
    }

    // add a new measurement report to the context if it exists, otherwise create a new one
    if (ctx) {
        ctx->reports[ctx->num].timestamp = timestamp;
        ctx->reports[ctx->num].cell_id = cell_id;
        ctx->reports[ctx->num].signal_strength = signal_strength;
        ++ctx->num;
    } else {
        LTE_UE_CONTEXT_T new_ctx = {.rnti = rnti, .reports = malloc(M * sizeof(*new_ctx.reports))};
        for (size_t i = 0; i < M; ++i) {
            MEASUREMENT_REPORT_T *report = &new_ctx.reports[i];
            report->timestamp = timestamp;
            report->cell_id = cell_id;
            report->signal_strength = signal_strength;
        }
        new_ctx.num = 1;
        lte_ue_contexts = realloc(lte_ue_contexts, (n + 1) * sizeof(*lte_ue_contexts));
        assert(lte_ue_contexts);
        memcpy(&lte_ue_contexts[n], &new_ctx, sizeof(LTE_UE_CONTEXT_T));
    }
}

void remove_measurement_report(uint32_t rx_ue_information_tag, uint16_t rnti) {
    // find the context for the given RNTI
    LTE_UE_CONTEXT_T *ctx = NULL;
    for (size_t i = 0; i < lte_ue_contexts->num; ++i) {
        if (lte_ue_contexts[i].rnti == rnti) {
            ctx = &lte_ue_contexts[i];
            break;
        }
    }

    // remove the measurement report from the context if it exists
    if (ctx) {
        --ctx->num;
        for (size_t i = 0; i < ctx->num; ++i) {
            memcpy(&ctx->reports[i], &ctx->reports[i + 1], sizeof(MEASUREMENT_REPORT_T));
        }
    }
}
