        pthread_mutex_unlock(&mutex);
        return;
    }

    // Reallocate memory for the list of SDUs
    *sdus = realloc(*sdus, (*sdu_count - 1) * sizeof(**sdus));
    if (*sdus == NULL) {
        fprintf(stderr, "Failed to allocate memory for LTE PDCP SDUs\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Decrement the SDU count
    *sdu_count -= 1;

    pthread_mutex_unlock(&mutex);
}
```
