void initArray(struct Array* array, size_t initialCapacity) {
    array->capacity = initialCapacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    array->elements = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void destroyArray(struct Array* array) {
    free(array->elements);
    pthread_mutex_destroy(&array->mutex);
    array->capacity = 0;
    array->size = 0;
}

int addElement(struct Array* array, NFAPI_CRC_INDICATION_PDU_T element) {
    int result = -1;
    pthread_mutex_lock(&array->mutex);
    if (array->size < array->capacity) {
        array->elements[array->size++] = element;
        result = 0;
    }
    pthread_mutex_unlock(&array->mutex);
    return result;
}

int removeElement(struct Array* array, size_t index) {
    int result = -1;
    if (index >= 0 && index < array->size) {
        pthread_mutex_lock(&array->mutex);
        NFAPI_CRC_INDICATION_PDU_T temp = array->elements[index];
        for (int i = index; i < array->size - 1; i++) {
            array->elements[i] = array->elements[i + 1];
