        pthread_mutex_lock(&array->mutex);
        array->elements[index] = element;
        result = 0;
        pthread_mutex_unlock(&array->mutex);
    }
    return result;
}

void growArray(struct Array* array, size_t newCapacity) {
    if (newCapacity > array->capacity) {
        NFAPI_CRC_INDICATION_PDU_T* newElements = malloc(newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
