    }
    pthread_mutexattr_t mutex_attr;
    pthread_mutexattr_init(&mutex_attr);
    pthread_mutexattr_settype(&mutex_attr, PTHREAD_MUTEX_RECURSIVE);
    for (int i = 0; i < MAX_NUM_SESSIONS; i++) {
        table->nodes[i] = malloc(sizeof(struct HashTableNode));
        if (table->nodes[i] == NULL) {
            printf("Error: failed to allocate memory for hash table node %d\n", i);
            free(table->nodes);
            free(table);
            exit(1);
        }
        pthread_mutex_init(&(table->nodes[i]->mutex), &mutex_attr);
    }
    pthread_mutexattr_destroy(&mutex_attr);
    return table;
}

void destroy_hash_table(HashTable* table) {
    for (int i = 0; i < MAX_NUM_SESSIONS; i++) {
        if (table->nodes[i] != NULL) {
            pthread_mutex_destroy(&(table->nodes[i]->mutex));
            free(table->nodes[i]);
        }
    }
    free(table->nodes);
    free(table);
}

SessionData* add_session(HashTable* table, char* session_id) {
