        pthread_mutex_unlock(&(table->lock));
        return NULL;
    }
    SessionData* data = malloc(sizeof(SessionData));
    if (data == NULL) {
        printf("Error: failed to allocate memory for session data\n");
        pthread_mutex_unlock(&(table->lock));
        exit(1);
    }
    strcpy(data->session_id, session_id);
    data->connection_state = 0;
    data->last_active_timestamp = time(NULL);
    pthread_mutex_lock(&(table->nodes[hash]->mutex));
    table->num_sessions++;
    table->nodes[hash]->data = data;
    pthread_mutex_unlock(&(table->nodes[hash]->mutex));
    pthread_mutex_unlock(&(table->lock));
    return data;
}

SessionData* get_session(HashTable* table, char* session_id) {
    pthread_mutex_lock(&(table->lock));
    int hash = get_hash(session_id);
    SessionData* data = NULL;
    if (table->nodes[hash] != NULL) {
        pthread_mutex_lock(&(table->nodes[hash]->mutex));
        if (strcmp(table->nodes[hash]->data->session_id, session_id) == 0) {
            data = table->nodes[hash]->data;
        }
        pthread_mutex_unlock(&(table->nodes[hash]->mutex));
    }
    pthread_mutex_unlock(&(table->lock));
    return data;
}

int get_hash(char* session_id) {
    int hash = 0;
    for (int i = 0; i < strlen(session_id); i++) {
        hash += session_id[i];
    }
    return hash % MAX_NUM_SESSIONS;
}

void update_session(HashTable* table, char* session_id, int connection_state) {
    pthread_mutex_lock(&(table->lock));
    SessionData* data = get_session(table, session_id);
    if (data != NULL) {
        data->connection_state = connection_state;
    }
    pthread_mutex_unlock(&(table->lock));
}

void delete_session(HashTable* table, char* session_id) {
