typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Dynamic array for storing allocated structures
NFAPI_CRC_INDICATION_PDU_T* structureArray = NULL;

// Cache size for minimizing repeated allocations
int cacheSize = 0;

// Request rate average over the last 60 seconds
double requestRateAverage = 0.0;

// Maximum cache size allowed
#define MAX_CACHE_SIZE 1024

// Minimum cache size required to optimize performance
#define MIN_CACHE_SIZE 32

// Time window for monitoring request rates (in seconds)
#define REQUEST_RATE_WINDOW 60

// Logging verbosity level
int loggingLevel = 1;

void resetSystem() {
    // Zero out all allocated structures to their initial state
    for (int i = 0; i < cacheSize; ++i) {
        structureArray[i].RX_UE_INFORMATION_TAG = 0;
        structureArray[i].RNTI = 0;
        structureArray[i].CRCFLAG = 0;
    }
}

void initializeSystem() {
    // Allocate the initial cache size
    cacheSize = MIN_CACHE_SIZE;
    structureArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(cacheSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize the structures with default values
    for (int i = 0; i < cacheSize; ++i) {
        structureArray[i].RX_UE_INFORMATION_TAG = 0;
        structureArray[i].RNTI = 0;
        structureArray[i].CRCFLAG = 0;
    }
}

void updateCacheSize(int requestRate) {
    // Update the cache size based on the request rate
    if (requestRate > 1.25 * requestRateAverage) {
        // Increase cache size if the request rate is high
        ++cacheSize;
    } else if (requestRate < 0.75 * requestRateAverage) {
        // Decrease cache size if the request rate is low
        --cacheSize;
    }
}

void manageCache() {
    // Check if the cache size needs to be updated
    int currentTime = time(NULL);
    if (currentTime - REQUEST_RATE_WINDOW > lastRequestRateUpdate) {
        updateCacheSize(requestRateAverage);
        lastRequestRateUpdate = currentTime;
    }
}

void allocateStructures(int N) {
    // Check if the cache is empty and needs to be refilled
    if (cacheSize == 0) {
        initializeSystem();
    }

    // Ensure that the requested number of structures is not greater than the maximum cache size
    if (N > MAX_CACHE_SIZE - cacheSize) {
        N = MAX_CACHE_SIZE - cacheSize;
    }

    // Allocate the new structures and update the cache size
    structureArray = realloc(structureArray, (cacheSize + N) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = cacheSize; i < cacheSize + N; ++i) {
        structureArray[i].RX_UE_INFORMATION_TAG = 0;
        structureArray[i].RNTI = 0;
        structureArray[i].CRCFLAG = 0;
    }
    cacheSize += N;
}

void deallocateStructures(int N) {
    // Check if the requested number of structures is not greater than the maximum cache size
    if (N > MAX_CACHE_SIZE - cacheSize) {
        N = MAX_CACHE_SIZE - cacheSize;
    }

    // Deallocate the structures and update the cache size
    structureArray = realloc(structureArray, (cacheSize - N) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    cacheSize -= N;
}

void allocateAndInitializeStructures(int N) {
    // Allocate and initialize the structures
    allocateStructures(N);
    for (int i = 0; i < N; ++i) {
        structureArray[cacheSize - N + i].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        structureArray[cacheSize - N + i].RNTI = RNTI;
        structureArray[cacheSize - N + i].CRCFLAG = (rand() % 2) ? 1 : 0;
    }
}

void deallocateAndDeinitializeStructures(int N) {
