#define N_FRAMES 10000 // maximum number of frames per second

struct NFAPI_UL_TDD_FRAME {
    unsigned char UE_ID;
    float UL_TX_POWER_LEVEL_TAG;
    float UL_RX_QUALITY_TAG;
};

struct NFAPI_UL_TDD_FRAME_STATS {
    int n_frames; // number of frames processed so far
    float average_signal_strength; // average signal strength over all frames
    struct NFAPI_UL_TDD_FRAME *frames; // array of NFAPI_UL_TDD_FRAME structures
};

void init_stats(struct NFAPI_UL_TDD_FRAME_STATS *stats) {
    stats->n_frames = 0;
    stats->average_signal_strength = 0.0f;
    stats->frames = NULL;
}

void destroy_stats(struct NFAPI_UL_TDD_FRAME_STATS *stats) {
    if (stats->frames != NULL) {
        free(stats->frames);
    }
}

int allocate_memory(struct NFAPI_UL_TDD_FRAME_STATS *stats, size_t n_frames) {
    stats->frames = malloc(n_frames * sizeof(*stats->frames));
    if (stats->frames == NULL) {
        return -1; // error allocating memory
    }
    return 0; // successful allocation
}

void free_memory(struct NFAPI_UL_TDD_FRAME_STATS *stats) {
    if (stats->frames != NULL) {
        free(stats->frames);
    }
}

void add_frame(struct NFAPI_UL_TDD_FRAME_STATS *stats, struct NFAPI_UL_TDD_FRAME frame) {
    stats->frames[stats->n_frames] = frame;
    ++stats->n_frames;
}

float compute_average_signal_strength(struct NFAPI_UL_TDD_FRAME_STATS *stats) {
    if (stats->n_frames == 0) {
        return 0.0f; // no frames to compute average from
    }
    float sum = 0.0f;
    for (size_t i = 0; i < stats->n_frames; ++i) {
        sum += stats->frames[i].UL_TX_POWER_LEVEL_TAG;
    }
    return sum / stats->n_frames; // average signal strength
}

void compute_and_store_average_signal_strength(struct NFAPI_UL_TDD_FRAME_STATS *stats) {
    if (stats->n_frames > 0) {
        stats->average_signal_strength = compute_average_signal_strength(stats);
    } else {
        stats->average_signal_strength = 0.0f;
    }
}

int main() {
    // create a new set of statistics
    struct NFAPI_UL_TDD_FRAME_STATS stats;
    init_stats(&stats);

    // simulate channel conditions and generate frames with UL_TX_POWER_LEVEL_TAG and UL_RX_QUALITY_TAG
    for (size_t i = 0; i < N_FRAMES; ++i) {
        struct NFAPI_UL_TDD_FRAME frame;
        // populate frame with UL_TX_POWER_LEVEL_TAG and UL_RX_QUALITY_TAG derived from channel conditions
        add_frame(&stats, frame);
    }

