// Define the structure for the list itself
typedef struct NFAPI_CRC_INDICATION_LIST {
    NFAPI_CRC_INDICATION_PDU_T* head;
    NFAPI_CRC_INDICATION_PDU_T* tail;
    int size;
} NFAPI_CRC_INDICATION_LIST_T;

// Define the function to create a new node in the list
NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_pdu_create(uint16_t RX_UE_INFORMATION_TAG, uint32_t RNTI, bool CRCFLAG) {
    NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) {
        return NULL;
    }
    node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    node->RNTI = RNTI;
    node->CRCFLAG = CRCFLAG;
    node->next = NULL;
    node->prev = NULL;
    return node;
}

// Define the function to insert a new node into the list
bool nfapi_crc_indication_pdu_insert(NFAPI_CRC_INDICATION_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T* node) {
    if (!list || !node) {
        return false;
    }
    pthread_mutex_lock(&list->mutex);
    node->next = list->head;
    node->prev = NULL;
    if (list->head) {
        list->head->prev = node;
    } else {
        list->tail = node;
    }
    list->head = node;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
    return true;
}

// Define the function to remove a node from the list
NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_pdu_remove(NFAPI_CRC_INDICATION_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T* node) {
    if (!list || !node) {
        return NULL;
    }
    pthread_mutex_lock(&list->mutex);
    if (node == list->head) {
        list->head = node->next;
    }
    if (node == list->tail) {
        list->tail = node->prev;
    }
    if (node->next) {
        node->next->prev = node->prev;
    }
    if (node->prev) {
        node->prev->next = node->next;
    }
    list->size--;
    pthread_mutex_unlock(&list->mutex);
    return node;
}

// Define the function to iterate over the list and retrieve RX_UE_INFORMATION_TAG and RNTI values
void nfapi_crc_indication_pdu_iterate(NFAPI_CRC_INDICATION_LIST_T* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!list || !callback) {
        return;
    }
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T* node = list->head;
    while (node) {
        callback(node);
        node = node->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Define the function to garbage collect unused memory
void nfapi_crc_indication_pdu_garbage_collect(NFAPI_CRC_INDICATION_LIST_T* list) {
    if (!list) {
        return;
    }
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T* node = list->head;
    while (node) {
        if (!node->CRCFLAG) {
            nfapi_crc_indication_pdu_remove(list, node);
        } else {
            node->CRCFLAG = false;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&list->mutex);
}
