class NetworkClient {
public:
  NetworkClient(const string& ip, const int port) : io_service(), resolver(io_service), socket(io_service) {
    endpoint = resolver.resolve(ip, to_string(port));
  }

  void sendGetRequests(vector<string>& urls, vector<int>& responseCodes) {
    for (const string& url : urls) {
      try {
        socket.connect(endpoint);
        boost::system::error_code error;
        http::request<http::empty_body> request;
        request.set(http::field::host, endpoint->address().to_string());
        request.set(http::field::user_agent, "Sample HTTP Client");
        auto response = http::request<http::string_body>(request);
        response.body() = "";
        socket.send(response.prepare(), error);
        if (error) {
          throw error;
        }
        auto responseMessage = response.recv(socket, error);
        if (error) {
          throw error;
        }
        responseCodes.push_back(responseMessage->status());
      } catch (const boost::system::system_error& e) {
        cerr << "Error: " << e.what() << endl;
      }
    }
  }

private:
