// Array to store the list of NFAPI_RRC_CCO_REQUEST structures
struct NFAPI_RRC_CCO_REQUEST* requests;

// Number of elements in the list
int num_requests = 0;

// Maximum number of elements that can be stored in the list
const int max_num_requests = 1000;

// Mutex to protect the list from concurrent access
pthread_mutex_t request_lock;

void init_list() {
    // Initialize the list with a single element
    requests = malloc(sizeof(struct NFAPI_RRC_CCO_REQUEST));
    num_requests = 1;
}

void add_request(int UE_ID, char* frequency_bands[10]) {
    // Acquire the lock before modifying the list
    pthread_mutex_lock(&request_lock);

    // Check if the list needs to be resized
    if (num_requests == max_num_requests) {
        resize_list();
    }

    // Add a new element to the end of the list
    struct NFAPI_RRC_CCO_REQUEST* new_request = malloc(sizeof(struct NFAPI_RRC_CCO_REQUEST));
    new_request->UE_ID = UE_ID;
    memcpy(new_request->frequency_bands, frequency_bands, sizeof(char*) * 10);
    requests[num_requests++] = new_request;

    // Release the lock after modifying the list
    pthread_mutex_unlock(&request_lock);
}

void resize_list() {
    // Double the size of the list
    int old_size = max_num_requests * 2;
    struct NFAPI_RRC_CCO_REQUEST* new_requests = malloc(sizeof(struct NFAPI_RRC_CCO_REQUEST) * old_size);

    // Copy the existing elements to the new list
    for (int i = 0; i < num_requests; i++) {
        new_requests[i] = requests[i];
    }

    // Update the list and release the old memory
    free(requests);
    requests = new_requests;
    max_num_requests = old_size;
}

void prune_list() {
    // Acquire the lock before modifying the list
    pthread_mutex_lock(&request_lock);

    // Prune the list by removing elements that are inactive for a specified time period
    struct NFAPI_RRC_CCO_REQUEST* new_requests = malloc(sizeof(struct NFAPI_RRC_CCO_REQUEST) * num_requests);
    int count = 0;
    for (int i = 0; i < num_requests; i++) {
        if (is_inactive(requests[i])) {
            free(requests[i]);
        } else {
            new_requests[count++] = requests[i];
        }
    }

    // Update the list and release the old memory
    free(requests);
    requests = new_requests;
    num_requests = count;

    // Release the lock after modifying the list
    pthread_mutex_unlock(&request_lock);
}

void serialize_list(char* buffer, int size) {
    // Acquire the lock before reading the list
    pthread_mutex_lock(&request_lock);

    // Write the number of elements in the list to the buffer
    int num_bytes = sizeof(int);
    memcpy(buffer, &num_requests, num_bytes);

    // Write each element of the list to the buffer
    for (int i = 0; i < num_requests; i++) {
        struct NFAPI_RRC_CCO_REQUEST* request = requests[i];
        num_bytes += sizeof(struct NFAPI_RRC_CCO_REQUEST);
        memcpy(buffer + num_bytes, &request->UE_ID, sizeof(int));
        memcpy(buffer + num_bytes, request->frequency_bands, sizeof(char*) * 10);
    }

    // Release the lock after reading the list
    pthread_mutex_unlock(&request_lock);
}

void deserialize_list(char* buffer, int size) {
    // Acquire the lock before modifying the list
    pthread_mutex_lock(&request_lock);

    // Read the number of elements in the list from the buffer
    int num_bytes = sizeof(int);
    memcpy(&num_requests, buffer, num_bytes);

    // Create a new list with the correct size
    struct NFAPI_RRC_CCO_REQUEST* requests = malloc(sizeof(struct NFAPI_RRC_CCO_REQUEST) * num_requests);

    // Read each element of the list from the buffer
    for (int i = 0; i < num_requests; i++) {
        struct NFAPI_RRC_CCO_REQUEST* request = requests[i];
        num_bytes += sizeof(struct NFAPI_RRC_CCO_REQUEST);
        memcpy(&request->UE_ID, buffer + num_bytes, sizeof(int));
        memcpy(request->frequency_bands, buffer + num_bytes, sizeof(char*) * 10);
    }

    // Update the list and release the old memory
    free(this.requests);
    this.requests = requests;
    this.num_requests = num_requests;

    // Release the lock after modifying the list
    pthread_mutex_unlock(&request_lock);
}

void handle_external_data() {
    // Acquire the lock before updating the list
    pthread_mutex_lock(&request_lock);

    // Update the list with external data
    for (int i = 0; i < num_requests; i++) {
        struct NFAPI_RRC_CCO_REQUEST* request = requests[i];
        update_frequency_bands(request->UE_ID, request->frequency_bands);
    }

    // Release the lock after updating the list
    pthread_mutex_unlock(&request_lock);
}

void update_frequency_bands(int UE_ID, char* frequency_bands[10]) {
    // Acquire the lock before modifying the list
    pthread_mutex_lock(&request_lock);

    // Find the element in the list with the matching UE_ID
    struct NFAPI_RRC_CCO_REQUEST* request = NULL;
    for (int i = 0; i < num_requests; i++) {
        if (requests[i]->UE_ID == UE_ID) {
            request = requests[i];
            break;
        }
    }

    // Update the frequency bands of the element in the list
    if (request != NULL) {
        for (int i = 0; i < 10; i++) {
            free(request->frequency_bands[i]);
            request->frequency_bands[i] = strdup(frequency_bands[i]);
        }
    } else {
        // Add a new element to the list if it is not found in the existing one
        struct NFAPI_RRC_CCO_REQUEST* new_request = malloc(sizeof(struct NFAPI_RRC_CCO_REQUEST));
        new_request->UE_ID = UE_ID;
        for (int i = 0; i < 10; i++) {
            new_request->frequency_bands[i] = strdup(frequency_bands[i]);
        }
        requests = realloc(requests, sizeof(struct NFAPI_RRC_CCO_REQUEST) * (num_requests + 1));
        requests[num_requests++] = new_request;
    }

    // Release the lock after modifying the list
    pthread_mutex_unlock(&request_lock);
}

void is_inactive(struct NFAPI_RRC_CCO_REQUEST* request) {
    // Check if the element in the list has been inactive for a specified time period
    return (time(NULL) - request->last_used) > 60;
}
