typedef struct {
    long* offsets;
    int* keys;
    record* records;
} memory_allocations_t;

memory_allocations_t* manage_memory(int num_offsets, int num_keys, int num_records) {
    memory_allocations_t* allocations = malloc(sizeof(memory_allocations_t));
    if (!allocations) {
        free(allocations);
        return NULL;
    }

    // Allocate memory for the offset array
    allocations->offsets = calloc(num_offsets, sizeof(long));
    if (!allocations->offsets) {
        free(allocations);
        return NULL;
    }

    // Allocate memory for the key array
    allocations->keys = calloc(num_keys, sizeof(int));
    if (!allocations->keys) {
        free(allocations->offsets);
        free(allocations);
        return NULL;
    }

    // Allocate memory for the record array
    allocations->records = calloc(num_records, sizeof(record));
    if (!allocations->records) {
        free(allocations->keys);
        free(allocations->offsets);
        free(allocations);
        return NULL;
    }

    // Initialize the offset array with values from offsets.txt
    FILE* fp = fopen("offsets.txt", "r");
    if (fp == NULL) {
        perror("Failed to open offsets.txt");
        free(allocations->records);
        free(allocations->keys);
        free(allocations->offsets);
        free(allocations);
        return NULL;
    }

    int i = 0;
    while (fscanf(fp, "%ld", &allocations->offsets[i]) == 1) {
        i++;
    }

    // Ensure that num_offsets is not exceeded by the number of valid entries in offsets.txt
    if (i > num_offsets) {
        perror("Number of offsets exceeds maximum");
        fclose(fp);
        free(allocations->records);
        free(allocations->keys);
        free(allocations->offsets);
        free(allocations);
        return NULL;
    }

    // Generate random unique keys within the range [0, 10000]
    for (int j = 0; j < num_keys; j++) {
        allocations->keys[j] = rand() % 10000;
    }

    // Set each record value to a random integer within the range [0, 100000]
    for (int k = 0; k < num_records; k++) {
        allocations->records[k].value = rand() % 100000;
    }

    fclose(fp);
    return allocations;
}
