#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <pthread.h>
#include <time.h>

// Define a structure to represent an NFAPI_CRC_INDICATION_PDU_T with valid RX_UE_INFORMATION_TAG, RNTI and CRC_INDICATION_REL8_TAG
typedef struct {
    int sequence_number; // unique sequence number within the specified range
    char *rx_ue_information_tag;
    char *rnti;
    char *crc_indication_rel8_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a linked list to store the dynamically allocated structures
struct linked_list {
    struct linked_list *next;
    NFAPI_CRC_INDICATION_PDU_T *data;
};

// Define a function to manage the dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
void manage_nfapi_crc_indication(struct linked_list **head, int sequence_number, char *rx_ue_information_tag, char *rnti, char *crc_indication_rel8_tag, int crcflag) {
    // Check if the list is NULL and allocate memory for it if necessary
    if (*head == NULL) {
        *head = malloc(sizeof(struct linked_list));
        assert(*head != NULL);
        (*head)->next = NULL;
    }

    // Allocate memory for a new structure and initialize it with the given values
    NFAPI_CRC_INDICATION_PDU_T *new_data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    assert(new_data != NULL);
    new_data->sequence_number = sequence_number;
    new_data->rx_ue_information_tag = strdup(rx_ue_information_tag);
    new_data->rnti = strdup(rnti);
    new_data->crc_indication_rel8_tag = strdup(crc_indication_rel8_tag);
    new_data->crcflag = crcflag;

    // Check if the sequence number is already present in the list and handle accordingly
    struct linked_list *current = *head;
    while (current != NULL) {
        if (current->data->sequence_number == sequence_number) {
            free(new_data);
            return; // duplicate sequence number found, discard new data
        }
        current = current->next;
    }

    // Add the new structure to the list and maintain a consistent sequence number
    struct linked_list *last = (*head)->next;
    while (last != NULL) {
        if (last->data->sequence_number > new_data->sequence_number) {
            break;
        }
        last = last->next;
    }
    if (last == NULL) {
        // add to the end of the list
        (*head)->next = malloc(sizeof(struct linked_list));
        assert((*head)->next != NULL);
        (*head)->next->data = new_data;
        (*head)->next->next = NULL;
    } else {
        // add to the beginning of the list
        last->next = malloc(sizeof(struct linked_list));
        assert(last->next != NULL);
        last->next->data = new_data;
        last->next->next = last;
    }
}

// Define a function to validate the sequence number consistency across the list
void validate_sequence_number(struct linked_list *head) {
    struct linked_list *current = head;
    while (current != NULL) {
        if (current->next != NULL && current->data->sequence_number == current->next->data->sequence_number - 1) {
            // sequence number inconsistency found, print error message
            printf("Sequence number inconsistency: %d\n", current->data->sequence_number);
        }
        current = current->next;
    }
}

// Define a function to handle high-load conditions and ensure thread safety without significant performance degradation
void handle_high_load(struct linked_list **head) {
    // add locking mechanism here
}

// Define a function to clean up the allocated memory when the list is no longer needed
void cleanup_memory(struct linked_list *head) {
    while (head != NULL) {
        struct linked_list *current = head;
        head = head->next;
        free(current);
    }
}
```
The function `manage_nfapi_crc_indication` takes a pointer to the linked list as an argument, and adds a new structure to the end of the list if the sequence number is not already present. It also maintains a consistent sequence number by adding the new structure either at the beginning or end of the list, depending on its value. The function checks for duplicate sequence numbers and discards any new data that has the same sequence number as an existing structure in the list.

The function `validate_sequence_number` is used to validate the sequence number consistency across the list. It iterates through the list and checks if there are any gaps or duplicate sequence numbers. If it finds any inconsistency, it prints an error message.

The function `handle_high_load` is not implemented yet, but it will be used to handle high-load conditions and ensure thread safety without significant performance degradation. It should use a locking mechanism to protect the linked list from concurrent access.

Finally, the function `cleanup_memory` frees all the allocated memory for the linked list when it is no longer needed. It iterates through the list and frees each structure individually before freeing the head pointer.

The function `manage_nfapi_crc_indication` should be called with the address of the linked list as an argument, like this:
```c
struct linked_list *head = NULL;
manage_nfapi_crc_indication(&head, sequence_number, rx_ue_information_tag, rnti, crc_indication_rel8_tag, crcflag);
```
Note that the function does not handle memory allocation failures or invalid input parameters, and it assumes that the input parameters are valid. It is the responsibility of the caller to ensure that the linked list is properly initialized before passing it to this function.']

