struct NFAPI_CRC_INDICATION_PDU_T {
    struct RX_UE_INFORMATION_TAG* rx_ue_info;
    struct CRC_INDICATION_REL8_TAG* crc_indication;
};

// Thread-safe NICB management functions
static pthread_mutex_t nicb_lock = PTHREAD_MUTEX_INITIALIZER;
void lock_nicb(struct NICB* nicb) {
    pthread_mutex_lock(&nicb_lock);
}
void unlock_nicb(struct NICB* nicb) {
    pthread_mutex_unlock(&nicb_lock);
}

// Function to initialize the NICB structure
static struct NICB* init_nicb(char* ipv4_address, char* subnet_mask, int mac_count) {
    // Allocate memory for the NICB structure and its associated MAC addresses
    struct NICB* nicb = malloc(sizeof(struct NICB));
    if (!nicb) {
        return NULL;
    }

    // Initialize the IPv4 address, subnet mask, and MAC count
    nicb->ipv4_address = strdup(ipv4_address);
    nicb->subnet_mask = strdup(subnet_mask);
    nicb->mac_count = mac_count;

    // Allocate memory for the MAC addresses and initialize them
    nicb->macs = malloc(sizeof(struct MACAddr) * mac_count);
    if (!nicb->macs) {
        free(nicb);
        return NULL;
    }
    for (int i = 0; i < mac_count; i++) {
        nicb->macs[i].addr = malloc(sizeof(char) * 18); // 18 bytes for an Ethernet MAC address
        if (!nicb->macs[i].addr) {
            free(nicb->macs);
            free(nicb);
            return NULL;
        }
        nicb->macs[i].allocated = false;
    }

    // Initialize the NFAPI_CRC_INDICATION_PDU_T list
    nicb->crc_indication_list = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T) * mac_count);
    if (!nicb->crc_indication_list) {
        free(nicb->macs);
        free(nicb);
        return NULL;
    }

    // Randomly set the CRCFLAG in the CRC_INDICATION_REL8_TAG struct
    for (int i = 0; i < mac_count; i++) {
        nicb->crc_indication_list[i].crc_indication->crcfalg = rand() % 2 == 0;
    }

    return nicb;
}

// Function to allocate a MAC address from the pool
static char* alloc_mac(struct NICB* nicb) {
    // Iterate over the MAC addresses in the NICB structure and find an available one
    for (int i = 0; i < nicb->mac_count; i++) {
        if (!nicb->macs[i].allocated) {
            nicb->macs[i].allocated = true;
            return strdup(nicb->macs[i].addr);
        }
    }

    // If no available MAC address is found, allocate a new one from the pool
    if (nicb->mac_count < 500) {
        char* mac = malloc(sizeof(char) * 18); // 18 bytes for an Ethernet MAC address
        if (!mac) {
            return NULL;
        }
        snprintf(mac, 18, "%02X-%02X-%02X-%02X-%02X-%02X", rand() % 256, rand() % 256, rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        nicb->macs[nicb->mac_count].addr = mac;
        nicb->macs[nicb->mac_count].allocated = true;
        return strdup(mac);
    } else {
        // No available MAC address is found, and the pool is full, return NULL
        return NULL;
    }
}

// Function to deallocate a MAC address from the pool
static void dealloc_mac(struct NICB* nicb, char* mac) {
    // Iterate over the MAC addresses in the NICB structure and find the one to be deallocated
    for (int i = 0; i < nicb->mac_count; i++) {
        if (strcmp(nicb->macs[i].addr, mac) == 0) {
            nicb->macs[i].allocated = false;
            break;
        }
    }
}

// Function to release the memory allocated for the NICB structure
static void destroy_nicb(struct NICB* nicb) {
    // Free the memory allocated for the IPv4 address, subnet mask, and MAC addresses
    free(nicb->ipv4_address);
    free(nicb->subnet_mask);
    for (int i = 0; i < nicb->mac_count; i++) {
        free(nicb->macs[i].addr);
    }
    // Free the memory allocated for the MAC addresses and the NFAPI_CRC_INDICATION_PDU list
    free(nicb->macs);
    free(nicb->crc_indication_list);
    // Finally, free the memory allocated for the NICB structure itself
    free(nicb);
}

int main() {
    struct NICB* nicb = init_nicb("192.168.100.1", "255.255.255.0", 10);
    if (!nicb) {
        printf("Error initializing the NICB structure\n");
        return -1;
    }

    // Allocate 5 MAC addresses from the pool
    char* macs[5];
    for (int i = 0; i < 5; i++) {
        macs[i] = alloc_mac(nicb);
        if (!macs[i]) {
            printf("Error allocating a MAC address from the pool\n");
            return -1;
        }
    }

    // Deallocate the first 3 MAC addresses from the pool
    for (int i = 0; i < 3; i++) {
        dealloc_mac(nicb, macs[i]);
    }

    // Reallocate the first 2 MAC addresses from the pool
    char* mac1 = alloc_mac(nicb);
    if (!mac1) {
        printf("Error reallocating a MAC address from the pool\n");
        return -1;
    }
    char* mac2 = alloc_mac(nicb);
    if (!mac2) {
        printf("Error reallocating a MAC address from the pool\n");
        return -1;
    }

    // Print the allocated MAC addresses and the CRCFLAG for each one
    for (int i = 0; i < 5; i++) {
        if (macs[i]) {
            printf("MAC address %d: %s\n", i, macs[i]);
        } else {
            printf("MAC address %d: Not allocated\n", i);
        }
    }
    printf("\n");

    // Release the memory allocated for the NICB structure
    destroy_nicb(nicb);

    return 0;
}
