struct crc_indication_list* create_crc_indication_list(size_t initial_capacity) {
    struct crc_indication_list *list = malloc(sizeof(struct crc_indication_list));
    if (!list) {
        return NULL;
    }
    list->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

int push_crc_indication(struct crc_indication_list *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->capacity == 0) {
        list->capacity = 1;
        list->data = realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    } else if (list->capacity == list->size) {
        list->capacity *= 2;
        list->data = realloc(list->data, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    memcpy(&list->data[list->size++], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int pop_crc_indication(struct crc_indication_list *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == 0) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    memcpy(pdu, &list->data[--list->size], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int get_crc_indication(struct crc_indication_list *list, size_t index, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->mutex);
    if (index >= list->size) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    memcpy(pdu, &list->data[index], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void destroy_crc_indication_list(struct crc_indication_list *list) {
    free(list->data);
    list->data = NULL;
    pthread_mutex_destroy(&list->mutex);
    free(list);
}
