#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/shm.h>
#include <sys/sem.h>
#include <stdbool.h>

typedef struct {
    NFAPI_RRC_CU_TRANSPORT_PDU_T *pdu;
    size_t pdu_size;
} PDU_BUFFER_T;

typedef struct {
    int channel_id;
    int rnti;
    int pdcp_sn;
} PDU_INFO_T;

typedef struct {
    size_t capacity;
    size_t num_entries;
    PDU_BUFFER_T *buffer;
    pthread_mutex_t mutex;
} PDU_STORE_T;

void init_pdu_store(PDU_STORE_T *store, size_t capacity) {
    store->capacity = capacity;
    store->num_entries = 0;
    store->buffer = (PDU_BUFFER_T *)malloc(sizeof(PDU_BUFFER_T) * capacity);
    pthread_mutex_init(&store->mutex, NULL);
}

void destroy_pdu_store(PDU_STORE_T *store) {
    free(store->buffer);
    pthread_mutex_destroy(&store->mutex);
}

int add_pdu(PDU_STORE_T *store, NFAPI_RRC_CU_TRANSPORT_PDU_T *pdu) {
    pthread_mutex_lock(&store->mutex);
    if (store->num_entries >= store->capacity) {
        printf("PDU buffer overflow\n");
        return -1;
    }

    size_t index = store->num_entries++;
    store->buffer[index].pdu = pdu;
    store->buffer[index].pdu_size = sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T);

    pthread_mutex_unlock(&store->mutex);
    return 0;
}

int remove_pdu(PDU_STORE_T *store, int index) {
    if (index < 0 || index >= store->num_entries) {
        printf("Invalid PDU index\n");
        return -1;
    }

    NFAPI_RRC_CU_TRANSPORT_PDU_T *pdu = store->buffer[index].pdu;
    size_t pdu_size = store->buffer[index].pdu_size;

    if (store->num_entries > 0) {
        memmove(store->buffer + index, store->buffer + index + 1,
                sizeof(PDU_BUFFER_T) * (store->num_entries - index - 1));
    }

    store->num_entries--;

    return pdu_size;
}

void serialize_pdu_store(PDU_STORE_T *store, unsigned char *buffer, size_t buffer_size) {
    pthread_mutex_lock(&store->mutex);

    size_t num_bytes = store->num_entries * sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T);
    if (num_bytes > buffer_size) {
        printf("Buffer overflow\n");
        return;
    }

    memcpy(buffer, store->buffer, num_bytes);

    pthread_mutex_unlock(&store->mutex);
}

void deserialize_pdu_store(PDU_STORE_T *store, unsigned char *buffer, size_t buffer_size) {
    pthread_mutex_lock(&store->mutex);

    if (buffer_size % sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T)) {
        printf("Invalid buffer size\n");
        return;
    }

    store->num_entries = buffer_size / sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T);

    for (int i = 0; i < store->num_entries; i++) {
        NFAPI_RRC_CU_TRANSPORT_PDU_T *pdu = (NFAPI_RRC_CU_TRANSPORT_PDU_T *)(buffer + i * sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T));
        add_pdu(store, pdu);
    }

    pthread_mutex_unlock(&store->mutex);
}

void init_pdus(PDU_STORE_T *store) {
    for (int i = 0; i < store->capacity; i++) {
        NFAPI_RRC_CU_TRANSPORT_PDU_T *pdu = (NFAPI_RRC_CU_TRANSPORT_PDU_T *)malloc(sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T));
        memset(pdu, 0, sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T));
        pdu->header.message_id = NFAPI_RRC_CU_TRANSPORT;
        store->buffer[i].pdu = pdu;
    }
}

void destroy_pdus(PDU_STORE_T *store) {
    for (int i = 0; i < store->capacity; i++) {
        free(store->buffer[i].pdu);
    }
}

void init_pdu_info(PDU_INFO_T *info, int channel_id, int rnti) {
    info->channel_id = channel_id;
    info->rnti = rnti;
    info->pdcp_sn = 0;
}

int allocate_pdu(PDU_STORE_T *store, PDU_INFO_T *info) {
    pthread_mutex_lock(&store->mutex);
    int index = -1;
    for (int i = 0; i < store->capacity && index == -1; i++) {
        if (!store->buffer[i].pdu) {
            index = i;
        }
    }

    if (index != -1) {
        info->channel_id = store->buffer[index].channel_id;
        info->rnti = store->buffer[index].rnti;
        info->pdcp_sn = 0;
        store->buffer[index].pdu = NULL;
    }

    pthread_mutex_unlock(&store->mutex);

    return index;
}

int deallocate_pdu(PDU_STORE_T *store, int channel_id) {
    pthread_mutex_lock(&store->mutex);

    int index = -1;
    for (int i = 0; i < store->capacity && index == -1; i++) {
        if (store->buffer[i].channel_id == channel_id) {
            index = i;
        }
    }

    if (index != -1) {
        free(store->buffer[index].pdu);
        store->buffer[index].pdu = NULL;
    }

    pthread_mutex_unlock(&store->mutex);

    return index;
}
