// Define a function to allocate memory from the memory pool
static void *allocate_memory(size_t size) {
    // Calculate the number of bytes needed for allocation
    size_t num_bytes = (size + MEMORY_POOL_GRANULARITY - 1) / MEMORY_POOL_GRANULARITY;

    // Find a contiguous block of memory in the pool that is large enough to hold the allocation
    uint8_t *ptr = NULL;
    for (uint8_t *p = memory_pool; p < memory_pool + MEMORY_POOL_SIZE - num_bytes; p++) {
        if (*(int *)p == 0) {
            ptr = p;
            break;
