void AddNFAPIL2PDU(int type, char* buffer) {
    // Check if the array is full and needs to be reallocated
    if (nfa.size == MAX_NFAPI_L2_PDU) {
        nfa = (NFAPI_L2_PDU_T*)realloc(nfa, (MAX_NFAPI_L2_PDU + 1000) * sizeof(NFAPI_L2_PDU_T));
    }

    // Add the new PDU to the array
    nfa[nfa.size].type = type;
    nfa[nfa.size].buffer = buffer;
    nfa.size++;
}

// Function to remove a PDU from the array by index
void RemoveNFAPIL2PDU(int index) {
    // Check if the index is valid
    if (index < 0 || index >= nfa.size) {
        return;
    }

    // Shift all the PDUs to the left of the removed one
    for (int i = index; i < nfa.size - 1; i++) {
        nfa[i].type = nfa[i + 1].type;
        nfa[i].buffer = nfa[i + 1].buffer;
    }

    // Decrement the size of the array by one
    nfa.size--;
}

