fn create_directories(files: &[FileRecord], max_directory_name_length: usize) -> Result<(), Box<dyn Error>> {
    let mut directories = HashSet::new();
    let mut start = Instant::now();

    for file in files {
        // Check if directory already exists
        if directories.contains(&file.path[..max_directory_name_length]) {
            continue;
        }

        // Create directory and log any errors
