            Ok(_) => {
                directories.insert(file.path[..max_directory_name_length].to_string());
                println!("Created directory for file {}", file.path);
            }
            Err(err) => {
                println!("Error creating directory for file {}: {}", file.path, err);
            }
        }
    }

    // Log time taken to create directories
    let end = Instant::now();
    println!("Time taken to create directories: {:?}", Duration::between(start, end));

    Ok(())
}
