    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening file");
        return NULL;
    }

    offset_range_t *offset_range = malloc(sizeof(offset_range_t));
    if (offset_range == NULL) {
        fclose(fp);
        perror("Error allocating memory for offset range");
        return NULL;
    }

    int min_offset = INT_MAX;
    int max_offset = INT_MIN;

    // Read the offsets from the file and validate them
    size_t i;
    for (i = 0; i < num_offsets; i++) {
        long offset = strtol(fp, NULL, 10);
        if (errno == EINVAL || errno == ERANGE) {
            fprintf(stderr, "Error reading offset %lu\n", i);
            return NULL;
        }

        if (offset < min_offset) {
            min_offset = offset;
        } else if (offset > max_offset) {
            max_offset = offset;
        }
    }

    // Close the file and allocate memory for the offsets
    fclose(fp);
    offset_range->min_offset = min_offset;
    offset_range->max_offset = max_offset;
    offsets_t *offsets = malloc(sizeof(offsets_t));
