// Define the structure for holding CRC indication information
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int32_t RX_UE_INFORMATION_TAG;
    int32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the hash table for storing CRC indication information
typedef struct {
    // Key: RX_UE_INFORMATION_TAG
    int32_t RX_UE_INFORMATION_TAG;
    // Value: NFAPI_CRC_INDICATION_PDU_T
    NFAPI_CRC_INDICATION_PDU_T *pdu;
} CRC_HASH_TABLE;

// Define the mutex for protecting access to the hash table
static pthread_mutex_t crc_table_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function for safely adding a new entry to the hash table
int32_t add_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Acquire the mutex
    pthread_mutex_lock(&crc_table_mutex);

    // Generate a random CRCFLAG for the new entry
    uint8_t crcf = (uint8_t) rand() % 256;

    // Create a new hash table entry with the new RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG
    CRC_HASH_TABLE *new_entry = malloc(sizeof(CRC_HASH_TABLE));
    new_entry->RX_UE_INFORMATION_TAG = pdu->RX_UE_INFORMATION_TAG;
    new_entry->RNTI = pdu->RNTI;
    new_entry->pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(new_entry->pdu, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_entry->pdu->CRCFLAG = crcf;

    // Add the new entry to the hash table
    HASH_ADD_KEYPTR(hh, crc_table, &new_entry->RX_UE_INFORMATION_TAG, sizeof(int32_t), new_entry);

    // Release the mutex
    pthread_mutex_unlock(&crc_table_mutex);

    return 0;
}

// Function for safely retrieving a CRC indication from the hash table by RNTI
NFAPI_CRC_INDICATION_PDU_T *get_crc_indication(int32_t rnti) {
    // Acquire the mutex
    pthread_mutex_lock(&crc_table_mutex);

    CRC_HASH_TABLE *entry;
    HASH_FIND_INT(crc_table, &rnti, entry);
    if (entry != NULL) {
        // Return a copy of the found entry's CRC indication information
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memcpy(pdu, entry->pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        return pdu;
    } else {
        // No matching entry found
        return NULL;
    }

    // Release the mutex
    pthread_mutex_unlock(&crc_table_mutex);
}

// Function for safely removing an entry from the hash table by RNTI
int32_t remove_crc_indication(int32_t rnti) {
    // Acquire the mutex
    pthread_mutex_lock(&crc_table_mutex);

    CRC_HASH_TABLE *entry;
    HASH_FIND_INT(crc_table, &rnti, entry);
    if (entry != NULL) {
        // Remove the found entry from the hash table
        HASH_DEL(crc_table, entry);
        free(entry->pdu);
        free(entry);
        return 0;
    } else {
        // No matching entry found
        return -1;
    }

    // Release the mutex
    pthread_mutex_unlock(&crc_table_mutex);
}
