#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>
#include <errno.h>
#include <time.h>

#define MAX_CONNECTIONS 100000
#define MAX_MESSAGES 100000
#define MESSAGE_TAG_LENGTH 256
#define LOGGING_VERBOSITY_LEVEL 3

typedef struct {
    int client_id;
    int socket_fd;
    char message_tags[MAX_MESSAGES][MESSAGE_TAG_LENGTH];
} TCP_CONNECTION_PDU_T;

typedef struct {
    int client_id;
    int socket_fd;
    char message_tag[MESSAGE_TAG_LENGTH];
} MESSAGE_TAG_PDU_T;

static pthread_mutex_t connections_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t messages_lock = PTHREAD_MUTEX_INITIALIZER;

void *create_tcp_connections(int num_connections, int num_messages) {
    TCP_CONNECTION_PDU_T *tcp_connections = malloc(num_connections * sizeof(TCP_CONNECTION_PDU_T));
    if (tcp_connections == NULL) {
        return NULL;
    }

    MESSAGE_TAG_PDU_T *messages = malloc(num_messages * sizeof(MESSAGE_TAG_PDU_T));
    if (messages == NULL) {
        free(tcp_connections);
        return NULL;
    }

    // Populate the TCP connections and messages arrays
    for (int i = 0; i < num_connections; ++i) {
        int client_id = get_random_client_id();
        int socket_fd = get_random_socket_fd(client_id);
        if (socket_fd == -1) {
            continue;
        }

        tcp_connections[i].client_id = client_id;
        tcp_connections[i].socket_fd = socket_fd;
        for (int j = 0; j < num_messages; ++j) {
            char *message_tag = get_random_message_tag();
            if (message_tag == NULL) {
                continue;
            }

            strcpy(tcp_connections[i].message_tags[j], message_tag);
        }
    }

    // Initialize the logging system
    init_logging();

    return tcp_connections;
}

int get_random_client_id() {
    int client_id = -1;
    while (client_id < 0) {
        client_id = rand() % MAX_CONNECTIONS;
        if (get_tcp_connection(client_id) != NULL) {
            client_id = -1;
        }
    }
    return client_id;
}

int get_random_socket_fd(int client_id) {
    int socket_fd = -1;
    while (socket_fd < 0) {
        socket_fd = rand() % 65535;
        if (get_tcp_connection(client_id, socket_fd) != NULL) {
            socket_fd = -1;
        }
    }
    return socket_fd;
}

char *get_random_message_tag() {
    char *message_tag = malloc(MESSAGE_TAG_LENGTH);
    if (message_tag == NULL) {
        return NULL;
    }

    for (int i = 0; i < MESSAGE_TAG_LENGTH - 1; ++i) {
        message_tag[i] = 'a' + rand() % ('z' - 'a');
    }
    message_tag[MESSAGE_TAG_LENGTH - 1] = '\0';

    return message_tag;
}

