    return max;
}

// Define a function to iterate over the list in both forward and reverse order
void traverse(LIST_T* list, bool forward) {
    // Check if the list is empty
    if (list->size == 0) {
        printf("List is empty!\n");
        return;
    }
    size_t i = 0;
    while (i < list->size) {
        if (forward) {
            // Print the element at the current index
            printf("%d\n", list->elements[i].rx_ue_information);
            i++;
        } else {
            // Print the element at the current index
            printf("%d\n", list->elements[list->size-1-i].rx_ue_information);
            i++;
        }
    }
}

// Define a function to clean up memory when the list is no longer needed
void free_list(LIST_T* list) {
    // Check if the list is empty
    if (list->size == 0) {
        printf("List is empty!\n");
        return;
    }
    // Free the allocated memory for the elements in the list
    free(list->elements);
}

int main() {
    LIST_T* list = create_list();
    push_back(list, 10);
    push_back(list, 20);
    push_back(list, 30);
    push_front(list, 40);
    printf("Maximum element in the list is %d\n", get_max(list).rx_ue_information);
    traverse(list, true);
    traverse(list, false);
    free_list(list);
    return 0;
}
