// Thread pool for async request processing
class RequestThreadPool {
public:
    RequestThreadPool(int numThreads) : numThreads_(numThreads) {}

    void start() {
        for (int i = 0; i < numThreads_; ++i) {
            threads_.push_back(std::thread([this]() { this->processRequest(); }));
        }
    }

    void stop() {
        for (auto& t : threads_) {
            if (t.joinable()) {
                t.join();
            }
        }
    }

