// Dynamic array of NFAPI_CRC_INDICATION_PDU_T structures with thread safety and atomic writes

#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    RX_UE_INFORMATION_TAG rxUeInformationTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
    unsigned char crcFlag;
} NFAPI_CRC_INDICATION_PDU_T;

struct DynamicArray {
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T* elements;
};

void dynamicArrayInit(DynamicArray* array, size_t initialCapacity) {
    // Initialize the dynamic array with the specified capacity and a mutex for thread safety
    array->capacity = initialCapacity;
    array->count = 0;
    pthread_mutexattr_init(&array->mutex);
    pthread_mutex_init(&array->mutex, NULL);
}

void dynamicArrayAdd(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T element) {
    // Add a new element to the end of the array, growing the capacity if necessary
    pthread_mutex_lock(&array->mutex);
    if (array->count == array->capacity) {
        size_t newCapacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* newElements = realloc(array->elements, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (newElements == NULL) {
            // Memory allocation failed, handle error and return
            pthread_mutex_unlock(&array->mutex);
            return;
        }
        array->elements = newElements;
        array->capacity = newCapacity;
    }
    array->elements[array->count++] = element;
    pthread_mutex_unlock(&array->mutex);
}

NFAPI_CRC_INDICATION_PDU_T dynamicArrayGet(DynamicArray* array, RNTI rnti) {
    // Find and return the element with the specified RNTI, or an empty element if not found
    NFAPI_CRC_INDICATION_PDU_T result;
    memset(&result, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->count; i++) {
        if (array->elements[i].rnti == rnti) {
            result = array->elements[i];
            break;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return result;
}

void dynamicArrayClear(DynamicArray* array) {
    // Clear all elements in the array, deallocating any memory that can be freed
    pthread_mutex_lock(&array->mutex);
    free(array->elements);
    array->count = 0;
    pthread_mutex_unlock(&array->mutex);
}

void dynamicArrayLog(DynamicArray* array, char* logBuffer) {
    // Write a log of all operations performed on the array to the specified buffer
    pthread_mutex_lock(&array->mutex);
    snprintf(logBuffer, 1024, "Dynamic Array Log: Capacity = %zu, Count = %zu\n", array->capacity, array->count);
    for (size_t i = 0; i < array->count; i++) {
        snprintf(logBuffer + strlen(logBuffer), 1024 - strlen(logBuffer), "Element %zu: RX Ue Information Tag = %u, RNTI = %u, CRC Indication Rel8 Tag = %u, CRCFlag = %hhu\n", i, array->elements[i].rxUeInformationTag, array->elements[i].rnti, array->elements[i].crcIndicationRel8Tag, array->elements[i].crcFlag);
    }
    pthread_mutex_unlock(&array->mutex);
}

void dynamicArrayExport(DynamicArray* array, FILE* outputFile) {
    // Export the contents of the array to a file in a specified format, atomic and thread-safe
    fprintf(outputFile, "Dynamic Array Export\n");
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->count; i++) {
        fprintf(outputFile, "%u %u %u %hhu\n", array->elements[i].rxUeInformationTag, array->elements[i].rnti, array->elements[i].crcIndicationRel8Tag, array->elements[i].crcFlag);
    }
    pthread_mutex_unlock(&array->mutex);
}

void dynamicArrayMonitor(DynamicArray* array) {
    // Monitor the memory usage of the array and notify the user or system administrator when it approaches 90% capacity
    pthread_mutex_lock(&array->mutex);
    if (((float)array->count / array->capacity) > 0.9) {
        fprintf(stderr, "Memory pool of dynamic array is approaching 90%% capacity\n");
    }
    pthread_mutex_unlock(&array->mutex);
}

void dynamicArrayFlush(DynamicArray* array, FILE* secondaryStorageFile) {
    // Flush any elements that can be freed from the array to a file for persistence
    pthread_mutex_lock(&array->mutex);
    size_t freeCount = 0;
    for (size_t i = 0; i < array->count; i++) {
        if (free(array->elements[i].rxUeInformationTag, array->elements[i].rnti, array->elements[i].crcIndicationRel8Tag, array->elements[i].crcFlag)) {
            freeCount++;
        }
    }
    if (freeCount > 0) {
        fprintf(stderr, "Flushed %zu elements from dynamic array to secondary storage\n", freeCount);
    }
    pthread_mutex_unlock(&array->mutex);
}

int main() {
    // Test code for the dynamic array class
    DynamicArray* array = newDynamicArray();
    dynamicArrayLog(array, "Initial Log");
    dynamicArrayExport(array, stdout);

    // Add elements to the array and log updates
    dynamicArrayAdd(array, 1, 2, 3, 4);
    dynamicArrayLog(array, "Updated Log");
    dynamicArrayExport(array, stdout);

    // Get an element from the array by RNTI and update its CRCFlag
    NFAPI_CRC_INDICATION_REL8_T crcFlag = 1;
    dynamicArraySetCrcFlag(dynamicArrayGet(array, 2), crcFlag);
    dynamicArrayLog(array, "Updated Log");
    dynamicArrayExport(array, stdout);

    // Clear the array and log updates
    dynamicArrayClear(array);
    dynamicArrayLog(array, "Cleared Log");
    dynamicArrayExport(array, stdout);

    // Monitor memory usage of the array and flush any elements that can be freed to secondary storage
    FILE* secondaryStorageFile = fopen("secondary_storage.dat", "w+");
    if (secondaryStorageFile == NULL) {
        perror("Failed to open secondary storage file for writing");
        return 1;
    }
    dynamicArrayMonitor(array);
    dynamicArrayFlush(array, secondaryStorageFile);

    // Clean up memory and close files
    deleteDynamicArray(array);
    fclose(secondaryStorageFile);
    return 0;
}

