// Define the maximum number of elements in the array
#define MAX_ELEMENTS 1024

// Define the structure to store the NFAPI_CRC_INDICATION_PDU_T and NFAPI_L2_RX_PDU_T structures
typedef struct {
    union {
        NFAPI_CRC_INDICATION_PDU_T crc_indication;
        NFAPI_L2_RX_PDU_T l2_rx_pdu;
    } data;
} element_t;

// Define the array to store the elements
element_t* elements[MAX_ELEMENTS];

// Define the mutex and semaphore for synchronizing access to the array
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
semaphore_t semaphore = SEMAPHORE_INITIALIZER;

// Define the function to add a new element to the array
bool add_element(void* data, size_t length) {
    // Acquire the mutex
    pthread_mutex_lock(&mutex);

    // Check if there is space in the array for the new element
    if (length > MAX_ELEMENTS - num_elements) {
        // Release the mutex and return false
        pthread_mutex_unlock(&mutex);
        return false;
    }

    // Allocate memory for the new element
    element_t* new_element = (element_t*) malloc(sizeof(element_t));
    if (!new_element) {
        // Release the mutex and return false
        pthread_mutex_unlock(&mutex);
        return false;
    }

    // Initialize the new element with the provided data
    memcpy(&new_element->data, data, length);

    // Add the new element to the array
    elements[num_elements++] = new_element;

    // Release the mutex
    pthread_mutex_unlock(&mutex);

    return true;
}

// Define the function to retrieve an element from the array by ID
bool get_element(void* id, size_t id_length, void** data, size_t* length) {
    // Acquire the mutex
    pthread_mutex_lock(&mutex);

    // Check if there is any element in the array with the provided ID
    for (size_t i = 0; i < num_elements; i++) {
        element_t* element = elements[i];
        if (element->data.id == id) {
            // Copy the data and length of the element to the output parameters
            *data = &element->data;
            *length = sizeof(element->data);

            // Release the mutex and return true
            pthread_mutex_unlock(&mutex);
            return true;
        }
    }

    // No element with the provided ID was found, release the mutex and return false
    pthread_mutex_unlock(&mutex);
    return false;
}

// Define the function to clear all elements in the array
void clear_elements(void) {
    // Acquire the mutex
    pthread_mutex_lock(&mutex);

    // Free all elements in the array
    for (size_t i = 0; i < num_elements; i++) {
        element_t* element = elements[i];
        free(element);
    }

    // Reset the number of elements to zero
    num_elements = 0;

    // Release the mutex
    pthread_mutex_unlock(&mutex);
}

// Define the function to reset all structures in the array to their initial state
void reset_structures(void) {
    // Acquire the mutex
    pthread_mutex_lock(&mutex);

    // Reset all elements in the array to their initial state
    for (size_t i = 0; i < num_elements; i++) {
        element_t* element = elements[i];
        memset(&element->data, 0, sizeof(element->data));
    }

    // Release the mutex
    pthread_mutex_unlock(&mutex);
}

// Define the function to evaluate and choose appropriate synchronization primitives for a given scenario
void choose_synchronization_primitives(void) {
    // Acquire the mutex
    pthread_mutex_lock(&mutex);

    // Choose appropriate synchronization primitives based on the load pattern
    if (load_pattern == HIGH_LOAD_PATTERN) {
        semaphore = SEMAPHORE_INITIALIZER;
    } else {
        mutex = PTHREAD_MUTEX_INITIALIZER;
    }

    // Release the mutex
    pthread_mutex_unlock(&mutex);
}
