        if (!records[i].name[0]) {
            return NULL;
        }
    }

    // free any unused memory in the arrays
    int used_capacity = key_count / offset_count * capacity;
    for (int i = used_capacity; i < capacity; ++i) {
        record_t* record = &records[i];
        record->name[0] = '\0';
        record->active = false;
    }

    // return a pointer to the first element of the records array
    return records;
}

// function to free the arrays
