    size_t size;
    size_t capacity;
    UE_Status_Report* array;
};

void init_UE_Status_Report_Array(struct UE_Status_Report_Array* arr) {
    arr->size = 0;
    arr->capacity = 8; // start with a default capacity of 8 elements
    arr->array = malloc(sizeof(UE_Status_Report) * arr->capacity);
}

void add_UE_Status_Report(struct UE_Status_Report_Array* arr, unsigned int UE_ID, char RNTI[16], bool CRC_Status) {
    if (arr->size == arr->capacity) {
        // reallocate the array to make room for new entries
        arr->capacity *= 2;
        arr->array = realloc(arr->array, sizeof(UE_Status_Report) * arr->capacity);
    }

    UE_Status_Report* entry = &arr->array[arr->size];
    entry->UE_ID = UE_ID;
    strcpy(entry->RNTI, RNTI);
    entry->CRC_Status = CRC_Status;
    arr->size++;
}

bool remove_UE_Status_Report(struct UE_Status_Report_Array* arr, char RNTI[16]) {
    for (int i = 0; i < arr->size; i++) {
        if (strcmp(arr->array[i].RNTI, RNTI) == 0) {
            // remove the entry by shifting all subsequent entries to the left
            for (int j = i; j < arr->size - 1; j++) {
                arr->array[j] = arr->array[j + 1];
            }
            arr->size--;
            return true;
        }
    }
    return false;
}

void update_UE_Status_Report(struct UE_Status_Report_Array* arr, unsigned int UE_ID, bool CRC_Status) {
    for (int i = 0; i < arr->size; i++) {
        if (arr->array[i].UE_ID == UE_ID) {
            // update the entry with the new CRC status
            arr->array[i].CRC_Status = CRC_Status;
            return;
        }
    }
}

void free_UE_Status_Report_Array(struct UE_Status_Report_Array* arr) {
    if (arr->array != NULL) {
        free(arr->array);
    }
    arr->size = 0;
    arr->capacity = 0;
}
