##### C. Implementing a dynamic array using linked lists

In this implementation, we use a linked list to implement the dynamic array. Each element in the array is represented by a node in the linked list, and the head of the linked list is used as the pointer to the first element in the array. To add an element to the array, we create a new node and link it to the end of the linked list. Similarly, to remove an element from the array, we find the corresponding node and unlink it from the linked list.

Here is the implementation:
```c
#include <stdio.h>
#include <stdlib.h>

// Linked list node for representing elements in the dynamic array
typedef struct LtePhyRxPrachInfoNode {
    struct LtePhyRxPrachInfoNode* next;
    LTE_PHY_RX_PRACH_INFO prachInfo;
} LtePhyRxPrachInfoNode;

// Dynamic array of PRACH information
LtePhyRxPrachInfoNode* LtePhyRxPrachInfoArray = NULL;

// Function to add an element to the dynamic array
void addElementToDynamicArray(LTE_PHY_RX_PRACH_INFO prachInfo) {
    // Create a new node for the element
    LtePhyRxPrachInfoNode* newNode = malloc(sizeof(LtePhyRxPrachInfoNode));
    newNode->prachInfo = prachInfo;

    // If the array is empty, set the head to the new node and return
    if (LtePhyRxPrachInfoArray == NULL) {
        LtePhyRxPrachInfoArray = newNode;
        return;
    }

    // Find the last node in the linked list and add the new node after it
    LtePhyRxPrachInfoNode* lastNode = LtePhyRxPrachInfoArray;
    while (lastNode->next != NULL) {
        lastNode = lastNode->next;
    }
    lastNode->next = newNode;
}

// Function to remove an element from the dynamic array
void removeElementFromDynamicArray(LTE_PHY_RX_PRACH_INFO prachInfo) {
    // Find the node containing the element
    LtePhyRxPrachInfoNode* currentNode = LtePhyRxPrachInfoArray;
    while (currentNode != NULL && currentNode->prachInfo != prachInfo) {
        currentNode = currentNode->next;
    }

    // If the node is found, remove it from the linked list
    if (currentNode != NULL) {
        LtePhyRxPrachInfoNode* previousNode = currentNode->previous;
        if (previousNode == NULL) {
            LtePhyRxPrachInfoArray = currentNode->next;
        } else {
            previousNode->next = currentNode->next;
        }
        free(currentNode);
    }
}
