static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void populateNFAPICRCIndicationList(int num_elements) {
    // Randomly generate RNTI values for each element
    int RNTIs[num_elements];
    for (int i = 0; i < num_elements; i++) {
        RNTIs[i] = rand() % 10000 + 1;
    }

    // Iterate through the list and check for existing RNTI values
    struct nfapi_crc_indication_node *node = list;
    while (node != NULL) {
        if (RNTIs[i] == node->data->RNTI) {
            // If an existing RNTI value is found, regenerate a new value
            i--;
            RNTIs[i] = rand() % 10000 + 1;
        }
        node = node->next;
    }

    // Create a new list node for each element and populate it with the generated data
    for (int i = 0; i < num_elements; i++) {
        struct nfapi_crc_indication_pdu *data = malloc(sizeof(struct nfapi_crc_indication_pdu));
        data->RX_UE_INFORMATION_TAG = 0;
        data->RNTI = RNTIs[i];
        data->CRC_INDICATION_REL8_TAG = rand() % 10 + 1;
        data->CRCFLAG = (rand() % 2) ? 1 : 0;
        struct nfapi_crc_indication_node *node = malloc(sizeof(struct nfapi_crc_indication_node));
        node->data = data;
        node->next = list;
        if (list != NULL) {
            list->prev = node;
        }
        list = node;
    }
}

int getNFAPICRCIndicationListSize() {
    int size = 0;
    struct nfapi_crc_indication_node *node = list;
    while (node != NULL) {
        size++;
        node = node->next;
    }
    return size;
}

struct nfapi_crc_indication_pdu *getNFAPICRCIndicationPDU(int index) {
    struct nfapi_crc_indication_node *node = list;
    for (int i = 0; i < index; i++) {
        node = node->next;
    }
    return node->data;
}

void deleteNFAPICRCIndicationPDU(struct nfapi_crc_indication_pdu *data) {
    struct nfapi_crc_indication_node *node = list;
    while (node != NULL && node->data != data) {
        node = node->next;
    }
    if (node == NULL) {
        // Data not found in the list, return
        return;
    }
    struct nfapi_crc_indication_node *prev = node->prev;
    struct nfapi_crc_indication_node *next = node->next;
    if (prev == NULL) {
        list = next;
    } else {
        prev->next = next;
    }
    if (next != NULL) {
        next->prev = prev;
    }
    free(node);
}
