// maximum capacity of the hash map
#define MAP_CAPACITY 10000

void manage_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, uint32_t num_ues) {
    // acquire lock to ensure thread safety
    pthread_mutex_lock(&mutex);

    // initialize hash map if not initialized yet
    if (rnti_to_crc_map == NULL) {
        rnti_to_crc_map = malloc(sizeof(rnti_to_crc_map_t) * MAP_CAPACITY);
        memset(rnti_to_crc_map, 0, sizeof(rnti_to_crc_map_t) * MAP_CAPACITY);
    }

    // populate the list of CRC indication PDUs based on input parameters
    for (uint32_t i = 0; i < num_ues && i < MAP_CAPACITY; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *curr_pdu = &(pdu[i]);
        // check if the RNTI is already present in the hash map
        bool found = false;
        for (uint32_t j = 0; j < i && !found; ++j) {
            NFAPI_CRC_INDICATION_PDU_T *prev_pdu = &(pdu[j]);
            if (prev_pdu->rx_ue_information.rnti == curr_pdu->rx_ue_information.rnti) {
                found = true;
                // handle collision detection and update the hash map accordingly
                uint32_t prev_crc_flag = prev_pdu->crc_indication_rel8.crc_flag;
                if (prev_crc_flag != curr_pdu->crc_indication_rel8.crc_flag) {
                    // log information about the collision detection
                    printf("Collision detected for RNTI %d: previous CRC flag was %d, current CRC flag is %d\n",
                           curr_pdu->rx_ue_information.rnti, prev_crc_flag, curr_pdu->crc_indication_rel8.crc_flag);
                }
            }
        }
        // update the hash map if not present or add a new entry
        if (!found) {
            uint16_t rnti = curr_pdu->rx_ue_information.rnti;
            uint32_t crc_flag = curr_pdu->crc_indication_rel8.crc_flag;
            rnti_to_crc_map[i].rnti = rnti;
            rnti_to_crc_map[i].crc_flag = crc_flag;
        }
    }

    // release lock after populating the list and updating the hash map
    pthread_mutex_unlock(&mutex);
}
