void add_tcp_connection_stats(tcp_connection_list_t* head, tcp_connection_stats_t* stats) {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&list_lock);

    // Iterate through the list until we find a node with a lower connection ID than the new one
    tcp_connection_list_t current = *head;
