    long TIME_STAMP;
    float TX_POWER_LEVEL;
} TX_POWER_RECORD_T;

// Define the global array of TX power records
TX_POWER_RECORD_T *tx_power_records = NULL;

// Define the lock for synchronizing access to the array
pthread_mutex_t tx_power_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the TX power record array
void init_tx_power_records() {
    // Allocate memory for the array
    tx_power_records = (TX_POWER_RECORD_T *) malloc(sizeof(TX_POWER_RECORD_T) * 50000);
    if (tx_power_records == NULL) {
        log_error("Failed to allocate memory for TX power record array");
    } else {
        memset(tx_power_records, 0, sizeof(TX_POWER_RECORD_T) * 50000);
    }
}

// Function to add a new TX power record to the array
void add_tx_power_record(int UE_ID, long TIME_STAMP, float TX_POWER_LEVEL) {
    // Lock the mutex before modifying the array
    pthread_mutex_lock(&tx_power_lock);

    // Check if the array has reached its capacity limit
    if (tx_power_records == NULL || num_tx_power_records >= 50000) {
        log_error("Cannot add new TX power record: array is full");
        pthread_mutex_unlock(&tx_power_lock);
        return;
    }

    // Add the new record to the end of the array
    tx_power_records[num_tx_power_records].UE_ID = UE_ID;
    tx_power_records[num_tx_power_records].TIME_STAMP = TIME_STAMP;
    tx_power_records[num_tx_power_records].TX_POWER_LEVEL = TX_POWER_LEVEL;

    // Increment the number of records and unlock the mutex
    num_tx_power_records++;
    pthread_mutex_unlock(&tx_power_lock);
}

// Function to update a TX power record in the array
void update_tx_power_record(int index, int UE_ID, long TIME_STAMP, float TX_POWER_LEVEL) {
    // Lock the mutex before modifying the array
    pthread_mutex_lock(&tx_power_lock);

    // Check if the index is within the bounds of the array
    if (index < 0 || index >= num_tx_power_records) {
        log_error("Cannot update TX power record: invalid index");
        pthread_mutex_unlock(&tx_power_lock);
        return;
    }

    // Update the record in the array
    tx_power_records[index].UE_ID = UE_ID;
    tx_power_records[index].TIME_STAMP = TIME_STAMP;
    tx_power_records[index].TX_POWER_LEVEL = TX_POWER_LEVEL;

    // Unlock the mutex
    pthread_mutex_unlock(&tx_power_lock);
}

// Function to remove a TX power record from the array
void remove_tx_power_record(int index) {
    // Lock the mutex before modifying the array
    pthread_mutex_lock(&tx_power_lock);

    // Check if the index is within the bounds of the array
    if (index < 0 || index >= num_tx_power_records) {
        log_error("Cannot remove TX power record: invalid index");
        pthread_mutex_unlock(&tx_power_lock);
        return;
    }

    // Shift the remaining records in the array over to fill the gap
    for (int i = index + 1; i < num_tx_power_records; i++) {
        tx_power_records[i - 1] = tx_power_records[i];
    }

    // Decrement the number of records and unlock the mutex
    num_tx_power_records--;
    pthread_mutex_unlock(&tx_power_lock);
}

// Function to export the TX power record array to a CSV file
void export_tx_power_records(FILE *file) {
    // Lock the mutex before modifying the array
    pthread_mutex_lock(&tx_power_lock);

    // Write the header row for the CSV file
    fprintf(file, "UE ID,TIME STAMP,TX POWER LEVEL\n");

    // Iterate over each record in the array and write it to the CSV file
    for (int i = 0; i < num_tx_power_records; i++) {
        fprintf(file, "%d,%ld,%f\n", tx_power_records[i].UE_ID, tx_power_records[i].TIME_STAMP, tx_power_records[i].TX_POWER_LEVEL);
    }

    // Unlock the mutex
    pthread_mutex_unlock(&tx_power_lock);
}

// Function to free the memory used by the TX power record array
void free_tx_power_records() {
    // Lock the mutex before modifying the array
    pthread_mutex_lock(&tx_power_lock);

    // Free the memory used by the array
    free(tx_power_records);

    // Reset the number of records to 0
    num_tx_power_records = 0;

    // Unlock the mutex
    pthread_mutex_unlock(&tx_power_lock);
}
```

This code uses a mutex to ensure that only one thread can modify the array at a time, which is necessary because multiple threads may try to access the array concurrently. The `add_tx_power_record()`, `update_tx_power_record()`, and `remove_tx_power_record()` functions all lock the mutex before modifying the array, while the `export_tx_power_records()` function locks it only for reading. The `free_tx_power_records()` function locks it for writing, because it needs to free the memory used by the array.

This code also uses a variable called `num_tx_power_records` to keep track of how many records are currently in the array. This is necessary because the array may be modified concurrently by multiple threads, and we need to make sure that we don't try to access an index that is outside the bounds of the array when we write it to a CSV file or free its memory.

In addition to using a mutex to ensure thread-safety, this code also uses a data structure called a "circular buffer" to store the TX power records in the array. This allows us to easily add new records to the end of the array, update existing records, and remove records from the beginning of the array without having to shift the remaining records over every time we do any of these operations.

This code also uses a `FILE *` pointer to write the TX power records to a CSV file. This allows us to easily open the file for writing and write the contents of the array to it, while also making it easy to close the file again when we're done with it.']

