    // Check if the CRC flag is set
    if (!pdu->crc_flag) {
        return false;
    }

    // Check if the RX timestamp is valid
    if (pdu->rx_timestamp < 0 || pdu->rx_timestamp > MAX_TIMESTAMP) {
        return false;
    }

    // Check if the RX frequency offset is valid
    if (pdu->rx_frequency_offset < 0 || pdu->rx_frequency_offset > MAX_FREQUENCY_OFFSET) {
        return false;
    }

    return true;
}

// Function to send a confirmation message to the UE
void send_confirmation_message(int sockfd, uint16_t rnti) {
    // Create the confirmation message
    NFAPI_CRC_INDICATION_CONFIRMATION_T msg;
    memset(&msg, 0, sizeof(msg));
    msg.header.message_id = NFAPI_CRC_INDICATION_CONFIRMATION;
    msg.header.subsystem_id = NFAPI_SUBSYSTEM_UE;
    msg.pdu = (NFAPI_CRC_INDICATION_PDU_T *) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(&msg.pdu, &rnti, sizeof(uint16_t));

    // Send the confirmation message to the UE
    sendto(sockfd, &msg, sizeof(msg), 0, (struct sockaddr *) &remote_addr, addrlen);
}
