void nfapi_crc_indication_queue_add(struct NFAPI_CRC_INDICATION_QUEUE_T *queue, struct NFAPI_CRC_INDICATION_PDU_T *crc_indication) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->tail == NULL) {
        queue->head = crc_indication;
        queue->tail = crc_indication;
    } else {
        queue->tail->next = crc_indication;
        queue->tail = crc_indication;
