// Function to manage memory allocation for four distinct data structures: an array of 'double' values, an array of 'struct timestamp', a linked list of 'node' structures, and an array of 'string' pointers.
void initialize_data_structures(int num_double_values, int num_timestamp_values, int num_node_values, int log_message_max_length) {
    // Initialize double values array with user-specified values
    double* double_values = (double*)malloc(sizeof(double) * num_double_values);
    for (int i = 0; i < num_double_values; i++) {
        double_values[i] = 0.0; // Initialize with user-specified values
    }

    // Initialize timestamp array with user-specified values
