    for (int i = 0; i < num_timestamp_values; i++) {
        timestamp_values[i].seconds = rand() % 1000; // Initialize with random values within a specified range
        timestamp_values[i].nanoseconds = rand() % 1000000000;
        timestamp_values[i].timezone_offset = rand() % 24;
    }

    // Initialize linked list of node structures with user-specified values
    struct node* nodes = (struct node*)malloc(sizeof(struct node) * num_node_values);
    for (int i = 0; i < num_node_values; i++) {
        nodes[i].priority_level = rand() % 100; // Initialize with random values within a specified range
        nodes[i].next = NULL;
    }

    // Initialize array of string pointers with user-specified values
    char** log_messages = (char**)malloc(sizeof(char*) * num_log_message_values);
    for (int i = 0; i < num_log_message_values; i++) {
        log_messages[i] = (char*)malloc(log_message_max_length + 1); // Allocate memory for each string
        sprintf(log_messages[i], "Log message %d", i); // Populate with unique identifiers based on timestamps
    }

    // Interface with external logging service that imposes specific formatting requirements for log messages
