#include <stdlib.h>
#include <time.h>
#include <assert.h>
#include "nfapi_crc_indication_pdu.h"

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *arr;
    size_t count;
} CrcIndicationPduArray;

static void generateRandomRnti(uint16_t *rnti) {
    // Generate a random RNTI value between 0 and 65535
    uint16_t min = 0, max = 65535;
    *rnti = (uint16_t)(min + (max - min + 1) * rand() / (RAND_MAX + 1.0));
}

static void populateCrcIndicationPdu(NFAPI_CRC_INDICATION_PDU_T *pdu, uint8_t crcflag) {
    pdu->rx_ue_information_tag = RX_UE_INFORMATION_TAG;
    generateRandomRnti(&pdu->rnti);
    pdu->crc_indication_rel8_tag = CRC_INDICATION_REL8_TAG;
    pdu->crc_flag = crcflag;
}

CrcIndicationPduArray *createCrcIndicationPduArray(size_t size) {
    CrcIndicationPduArray *arr = malloc(sizeof(CrcIndicationPduArray));
    if (arr == NULL) {
        return NULL;
    }

    arr->count = 0;
    arr->arr = calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (arr->arr == NULL) {
        free(arr);
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        populateCrcIndicationPdu(&arr->arr[i], rand() % 2);
        arr->count++;
    }

    return arr;
}

void freeCrcIndicationPduArray(CrcIndicationPduArray *arr) {
    if (arr == NULL) {
        return;
    }

    for (size_t i = 0; i < arr->count; ++i) {
        free(arr->arr[i].rnti);
    }

    free(arr->arr);
    free(arr);
}

void iterateCrcIndicationPduArray(CrcIndicationPduArray *arr, void (*fn)(NFAPI_CRC_INDICATION_PDU_T *)) {
    for (size_t i = 0; i < arr->count; ++i) {
        fn(&arr->arr[i]);
    }
}
