// Ensure all LOGICAL_CHANNEL_GROUP values are unique within the array
void ensure_unique_channel_groups(MAC_ARRAY_T *array) {
    // Array of already seen channel groups for each element
    bool **seen_channels = calloc(array->capacity, sizeof(bool*));

    // For each element in the array, check if its channel group is already present in any other element's seen channels
    for (size_t i = 0; i < array->capacity; i++) {
        MAC_CONTEXT_T *context = &array->array[i];
        bool *seen = seen_channels[i];
        int group = context->LOGICAL_CHANNEL_GROUP;

        for (size_t j = 0; j < array->capacity; j++) {
            if (j == i) continue; // skip current element
            MAC_CONTEXT_T *other = &array->array[j];
            if (seen[other->LOGICAL_CHANNEL_GROUP]) {
                // If the other element's channel group is already present in any other element's seen channels, then
