    // acquire the lock on the linked list
    pthread_mutex_lock(&request_list_lock);

    // allocate memory for the new node
    REQUEST_NODE *new_node = (REQUEST_NODE *)malloc(sizeof(REQUEST_NODE));
    if (!new_node) {
