        node = node->next;
    }

    // return the metadata for the request, or NULL if not found
    NFAPI_RRC_CCO_REQUEST *request = (node) ? &node->request : NULL;

    // release the lock on the linked list
    pthread_mutex_unlock(&request_list_lock);

    return request;
}

