        pdu->crcflag = crcflag ? 1 : 0;

        pthread_mutex_lock(&mutex);
        nfaapi_crc_indication->pdus[nfaapi_crc_indication->num_pdu++] = pdu;
        pthread_mutex_unlock(&mutex);
    }

    fclose(fp);

    if (output) {
        FILE *ofp = fopen(output, "w");
        if (!ofp) {
            perror("fopen");
            return;
        }

        for (int i = 0; i < nfaapi_crc_indication->num_pdu; i++) {
