void generate_and_process_nfaapi_crc_indication(char *input_file, char *output_file, bool suppress_output, bool enable_metrics, int num_threads) {
    // Initialize the list to store the NFAPI CRC indication information
    struct NFAPI_CRC_INDICATION_PDU_T **list = NULL;

    // Load the input file and parse each JSON object
    json_t *root = json_load_file(input_file, 0, NULL);
