    if (rnti == NULL) {
        return false;
    }
    pdu->RNTI = json_integer_value(rnti);

    // Parse the CRC_INDICATION_REL8_TAG field
    json_t *crc_indication_rel8_tag = json_object_get(obj, "CRC_INDICATION_REL8_TAG");
    if (crc_indication_rel8_tag == NULL) {
        return false;
    }
    pdu->CRC_INDICATION_REL8_TAG = json_integer_value(crc_indication_rel8_tag);

    // Parse the CRCFLAG field
    json_t *crcflag = json_object_get(obj, "CRCFLAG");
    if (crcflag == NULL) {
        return false;
    }
    pdu->CRCFLAG = json_boolean_value(crcflag);

    // Validate the data
    if (!json_validate_rx_ue_information(pdu)) {
        return false;
    }

    return true;
}

// Define the function to validate the NFAPI CRC indication PDU data
bool json_validate_rx_ue_information(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Check if the RX_UE_INFORMATION_TAG field is valid
    if (pdu->RX_UE_INFORMATION_TAG < 0 || pdu->RX_UE_INFORMATION_TAG > 255) {
        return false;
    }

    // Check if the RNTI field is valid
    if (pdu->RNTI < 0 || pdu->RNTI > 65535) {
        return false;
    }

    // Check if the CRC_INDICATION_REL8_TAG field is valid
    if (pdu->CRC_INDICATION_REL8_TAG < 0 || pdu->CRC_INDICATION_REL8_TAG > 255) {
        return false;
    }

    // Check if the CRCFLAG field is valid
    if (pdu->CRCFLAG != true && pdu->CRCFLAG != false) {
        return false;
    }

    return true;
}
