// Struct to represent a record with an integer value and long pointer to offset
typedef struct {
    int value;
    long *offset;
} record_t;

// Function to manage dynamic data structure of records with associated offsets and keys
record_t* manage_records(int num_records, int range_start, int range_end) {
    // Allocate memory for array of 'num_records' number of records
    record_t *records = (record_t *)malloc(sizeof(record_t) * num_records);
    if (!records) {
        printf("Failed to allocate memory for records\n");
        return NULL;
    }

    // Initialize each record's integer value with a random number within specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        int random_value = rand() % (range_end - range_start + 1) + range_start;
        records[i].value = random_value;
    }

    // Allocate memory for array of 'num_records' number of long pointers
    long *offsets = (long *)malloc(sizeof(long) * num_records);
    if (!offsets) {
        printf("Failed to allocate memory for offsets\n");
        free(records);
        return NULL;
    }

    // Initialize each record's long pointer to point to the corresponding offset in the offsets array
    for (int i = 0; i < num_records; i++) {
        records[i].offset = &offsets[i];
    }

    // Generate random keys for each record
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        int key = rand() % num_records;
        records[i].key = key;
    }

    // Ensure that the long pointer accurately references the corresponding offset based on the key
    for (int i = 0; i < num_records; i++) {
        int key = records[i].key;
        records[i].offset = &offsets[key];
    }

    return records;
}
```
