#include <nfapi_pdcp_sn_generation_util.h>
#include <nfapi_rnti_allocation_util.h>

#define MAX_PDCP_SN 10000 // maximum value for PDCP_SN
#define MIN_RNTI 100000 // minimum value for RNTI
#define LOGGING_LEVEL_DEBUG 3
#define LOGGING_LEVEL_RELEASE 2

typedef struct {
    NFAPI_RRC_CU_TRANSPORT_PDU_T* pdu;
    uint16_t pdcp_sn;
    uint16_t rnti;
} PDU_INFO;

static bool initialize_pdu(NFAPI_RRC_CU_TRANSPORT_PDU_T* pdu) {
    memset(pdu, 0, sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T));
    return true;
}

static bool populate_pdu(NFAPI_RRC_CU_TRANSPORT_PDU_T* pdu, uint16_t pdcp_sn, uint16_t rnti) {
    // check if PDCP_SN is within range
    if (pdcp_sn > MAX_PDCP_SN) {
        return false;
    }

    // check if RNTI is within range
    if (rnti < MIN_RNTI || rnti >= MAX_RNTI) {
        return false;
    }

    // generate random RNTI
    rnti = nfapi_rnti_allocation_util_get_random(MAX_RNTI);

    // populate PDU with values
    pdu->messageType.messageType = NFAPI_RRC_MESSAGE_TYPE_TAG;
    pdu->transportChannel.transportChannelId = RRC_TRANSPORT_CHANNEL_TAG;
    pdu->pdcpSn.pdcpsn = pdcp_sn;
    pdu->rnti.rnti = rnti;

    return true;
}

static bool allocate_and_populate_array(uint32_t size, NFAPI_RRC_CU_TRANSPORT_PDU_T** arr) {
    // allocate array for PDUS
    *arr = malloc(size * sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T));

    if (*arr == NULL) {
        return false;
    }

    memset(*arr, 0, size * sizeof(NFAPI_RRC_CU_TRANSPORT_PDU_T));

    // populate array with random PDUS
    for (uint32_t i = 0; i < size; i++) {
        uint16_t pdcp_sn = nfapi_pdcp_sn_generation_util_get_random(MAX_PDCP_SN);
        uint16_t rnti = nfapi_rnti_allocation_util_get_random(MAX_RNTI);

        if (!populate_pdu(&(*arr)[i], pdcp_sn, rnti)) {
            free(*arr);
            *arr = NULL;
            return false;
        }
    }

    return true;
}

static bool deallocate_array(NFAPI_RRC_CU_TRANSPORT_PDU_T** arr) {
    free(*arr);
    *arr = NULL;
    return true;
}

void* initialize_and_populate_array(uint32_t size, uint16_t max_pdcp_sn, uint16_t min_rnti) {
    NFAPI_RRC_CU_TRANSPORT_PDU_T** arr = NULL;

    // initialize array with random PDUS
    if (!allocate_and_populate_array(size, &arr)) {
        return NULL;
    }

    // check for potential overflows in the array
    if (size > 0 && size < max_pdcp_sn) {
        deallocate_array(&arr);
        return NULL;
    }

    // check for potential underflows in the RNTIs
    if (min_rnti >= MAX_RNTI || min_rnti < MIN_RNTI) {
        deallocate_array(&arr);
        return NULL;
    }

    return arr;
}

void* initialize_and_populate_array_threadsafe(uint32_t size, uint16_t max_pdcp_sn, uint16_t min_rnti) {
    NFAPI_RRC_CU_TRANSPORT_PDU_T** arr = NULL;

    // initialize array with random PDUS
    if (!allocate_and_populate_array(size, &arr)) {
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // wait for other threads to finish using the array
    while (true) {
        pthread_mutex_lock(&mutex);

        if (arr == NULL) {
            pthread_cond_wait(&cond, &mutex);
        } else {
            break;
        }

        pthread_mutex_unlock(&mutex);
    }

    // check for potential overflows in the array
    if (size > 0 && size < max_pdcp_sn) {
        deallocate_array(&arr);
        arr = NULL;
    }

    // check for potential underflows in the RNTIs
    if (min_rnti >= MAX_RNTI || min_rnti < MIN_RNTI) {
        deallocate_array(&arr);
        arr = NULL;
    }

    pthread_mutex_unlock(&mutex);
    return arr;
}
