// Structure to represent a NICB (Network Interface Control Block)
typedef struct {
    int packet_processing_state;
    void* incoming_packet_buffer;
    time_t last_packet_processing_time;
} nicb_t;

// Function to initialize and populate an array of NICBs
nicb_t* init_and_populate_nicbs(size_t num_nicbs, size_t incoming_packet_buffer_size) {
    // Check for valid input parameters
    if (num_nicbs <= 0 || incoming_packet_buffer_size <= 0) {
        return NULL;
    }

    // Allocate memory for the NICB array and initialize its fields
    nicb_t* nicbs = malloc(sizeof(nicb_t) * num_nicbs);
    if (!nicbs) {
        return NULL;
    }
    memset(nicbs, 0, sizeof(nicb_t) * num_nicbs);

    // Allocate memory for the incoming packet buffer in each NICB
    size_t i;
    for (i = 0; i < num_nicbs; ++i) {
        nicbs[i].incoming_packet_buffer = malloc(incoming_packet_buffer_size);
        if (!nicbs[i].incoming_packet_buffer) {
            break;
        }
    }

    // If memory allocation failed for any NICB, free all allocated memory and return NULL
    if (i < num_nicbs) {
        free(nicbs);
        return NULL;
    }

    // Initialize the packet processing state and timestamp fields for each NICB
    for (i = 0; i < num_nicbs; ++i) {
        nicbs[i].packet_processing_state = -1;
        time(&nicbs[i].last_packet_processing_time);
    }

    // Return the populated NICB array
    return nicbs;
}
