    num_records = 0;

    // Read each line from the CSV file and parse it into a record
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Skip empty lines or lines that start with '#'
        if (strlen(line) == 0 || line[0] == '#') continue;

        // Split the line into tokens using a comma as a separator
        char *token = strtok(line, ",");
        while (token != NULL) {
            int cell_id = atoi(token);
            token = strtok(NULL, ",");
            int time_slot = atoi(token);
            token = strtok(NULL, ",");
            float transmission_power = atof(token);

            // Check if the record is a duplicate and skip it if so
            int i;
            for (i = 0; i < num_records; i++) {
                if (records[i].cell_id == cell_id) break;
            }
            if (i < num_records) continue;

            // Add the record to the array and increment the number of records
            records[num_records].cell_id = cell_id;
            records[num_records].time_slot = time_slot;
            records[num_records++].transmission_power = transmission_power;
        }
    }

    // Free the memory allocated for the line buffer
    free(line);

    // Close the CSV file and return the number of records read
    fclose(fp);
    return num_records;
}

// Define a function to deallocate the memory allocated for the records array
void destroy_records() {
    if (records != NULL) free(records);
}
```
