typedef struct RadioFrame {
    // ... Other fields
} RadioFrame;

int get_random_value(int min, int max) {
    return min + (rand() % (max - min));
}

UeSessionData *initialize_ue_session_data(int ueId, struct RadioFrame *frame) {
    UeSessionData *data = malloc(sizeof(UeSessionData));
    if (!data) {
        // Handle memory allocation error
        return NULL;
    }
    data->ueId = ueId;
    data->frame = frame;
    data->isGood = true;
    data->record = malloc(sizeof(Record) * 10); // Dynamically allocated array of Records
    if (!data->record) {
        free(data);
        // Handle memory allocation error
        return NULL;
    }
    for (int i = 0; i < 10; ++i) {
        data->record[i].value = get_random_value(min, max);
    }
    return data;
}

void destroy_ue_session_data(UeSessionData *data) {
    free(data->record);
    free(data);
}

void update_ue_session_data(UeSessionData *data, struct RadioFrame *frame) {
    data->isGood = false; // Mark as bad frame
    data->frame = frame; // Update frame pointer
}

int get_record_value(UeSessionData *data, int index) {
    return data->record[index].value;
}

bool is_ue_session_good(UeSessionData *data) {
    return data->isGood;
}

