pthread_mutex_t batchSizeLock; // Mutex to protect access to batch size variable and ensure thread safety
pthread_cond_t batchCondition; // Condition variable used to signal when a new batch is available
pthread_t *batchProcessingThreads = NULL; // Array of threads for concurrent packet processing
int numActiveThreads = 0; // Number of active threads for concurrent packet processing

