// Initialize and populate an array of custom packet header structures for a network processing application.
// Each structure should include fields for SourceIP, DestinationIP, ProtocolType, and Checksum.
void initializePacketHeaders(struct PacketHeader *packetHeaders, int numPackets) {
    // Validate input parameters
    if (numPackets < 0 || packetHeaders == NULL) {
        return;
    }

    // Initialize the batch size variable to its default value if no external configuration is provided
    pthread_mutex_lock(&batchSizeLock);
    if (currentBatchSize == DEFAULT_BATCH_SIZE) {
        currentBatchSize = MIN_BATCH_SIZE;
    }
    pthread_mutex_unlock(&batchSizeLock);

    // Create threads for concurrent packet processing if necessary
    int numThreadsToCreate = (numPackets - 1) / currentBatchSize + 1;
    if (numActiveThreads < numThreadsToCreate) {
        pthread_mutex_lock(&batchSizeLock);
        batchProcessingThreads = realloc(batchProcessingThreads, sizeof(pthread_t) * numThreadsToCreate);
        for (int i = 0; i < numThreadsToCreate - numActiveThreads; i++) {
            pthread_create(&batchProcessingThreads[i], NULL, processBatch, NULL);
        }
        numActiveThreads += numThreadsToCreate - numActiveThreads;
        pthread_mutex_unlock(&batchSizeLock);
    }

    // Populate the packet headers array
    for (int i = 0; i < numPackets; i++) {
        // Initialize the packet header structure with default values
        struct PacketHeader *header = &packetHeaders[i];
        header->SourceIP = 0;
        header->DestinationIP = 0;
        header->ProtocolType = 0;
        header->Checksum = 0;

        // Validate the packet header structure and calculate the checksum if necessary
        if (header->SourceIP < 1 || header->DestinationIP < 1) {
            printf("Invalid IP address in packet header: %d\n", i);
        } else if (header->ProtocolType != TCP && header->ProtocolType != UDP && header->ProtocolType != ICMP && header->ProtocolType != IGMP) {
            printf("Unsupported protocol type in packet header: %d\n", i);
        } else {
            // Calculate the checksum if necessary
            uint16_t checksum = 0;
            switch (header->ProtocolType) {
                case TCP:
                    checksum = calculateTCPChecksum(header, i);
                    break;
                case UDP:
                    checksum = calculateUDPChecksum(header, i);
                    break;
                case ICMP:
                    checksum = calculateICMPChecksum(header, i);
                    break;
                case IGMP:
                    checksum = calculateIGMPChecksum(header, i);
                    break;
            }
            header->Checksum = checksum;
        }
    }
}

// Process a batch of packet headers concurrently using multiple threads.
void *processBatch(void *arg) {
    // Loop until there are no more packets to process
    while (1) {
        // Acquire the mutex and wait for the next batch size update if necessary
        pthread_mutex_lock(&batchSizeLock);
        while (currentBatchSize == 0) {
            pthread_cond_wait(&batchCondition, &batchSizeLock);
        }

        // Update the current batch size variable and signal that a new batch is available if necessary
        int oldBatchSize = currentBatchSize;
        if (oldBatchSize > MIN_BATCH_SIZE) {
            currentBatchSize -= BATCH_SIZE_STEP;
            pthread_cond_signal(&batchCondition);
        } else {
            currentBatchSize = 0;
        }
        pthread_mutex_unlock(&batchSizeLock);

        // Process the next batch of packet headers
        if (oldBatchSize > 0) {
            for (int i = 0; i < oldBatchSize; i++) {
                struct PacketHeader *header = &packetHeaders[i];

                // Validate the packet header structure and calculate the checksum if necessary
                if (header->SourceIP < 1 || header->DestinationIP < 1) {
                    printf("Invalid IP address in packet header: %d\n", i);
                } else if (header->ProtocolType != TCP && header->ProtocolType != UDP && header->ProtocolType != ICMP && header->ProtocolType != IGMP) {
                    printf("Unsupported protocol type in packet header: %d\n", i);
                } else {
                    // Calculate the checksum if necessary
                    uint16_t checksum = 0;
                    switch (header->ProtocolType) {
                        case TCP:
                            checksum = calculateTCPChecksum(header, i);
                            break;
                        case UDP:
                            checksum = calculateUDPChecksum(header, i);
                            break;
                        case ICMP:
                            checksum = calculateICMPChecksum(header, i);
                            break;
                        case IGMP:
                            checksum = calculateIGMPChecksum(header, i);
                            break;
                    }
                    header->Checksum = checksum;
                }
            }
        }

        // Release the mutex and exit if there are no more packets to process
        pthread_mutex_unlock(&batchSizeLock);
        if (oldBatchSize == 0) {
            break;
        }
    }
}

// Calculate the TCP checksum for a packet header.
uint16_t calculateTCPChecksum(struct PacketHeader *header, int index) {
    // Initialize the checksum with the IP addresses and port numbers
    uint32_t checksum = header->SourceIP + header->DestinationIP;
    checksum += (header->SourcePort << 16) + header->DestinationPort;

    // Calculate the TCP checksum for the packet data
    int numBytes = header->DataLength - (4 * index);
    uint32_t tcpChecksum = calculateChecksum(header->Data, numBytes);
    checksum += tcpChecksum;

    return checksum & 0xFFFF;
}

// Calculate the UDP checksum for a packet header.
uint16_t calculateUDPChecksum(struct PacketHeader *header, int index) {
    // Initialize the checksum with the IP addresses and port numbers
    uint32_t checksum = header->SourceIP + header->DestinationIP;
    checksum += (header->SourcePort << 16) + header->DestinationPort;

    // Calculate the UDP checksum for the packet data
    int numBytes = header->DataLength - (4 * index);
    uint32_t udpChecksum = calculateChecksum(header->Data, numBytes);
    checksum += udpChecksum;

    return checksum & 0xFFFF;
}

// Calculate the ICMP checksum for a packet header.
uint16_t calculateICMPChecksum(struct PacketHeader *header, int index) {
    // Initialize the checksum with the IP addresses and port numbers
    uint32_t checksum = header->SourceIP + header->DestinationIP;
    checksum += (header->Type << 16) + header->Code;

    // Calculate the ICMP checksum for the packet data
    int numBytes = header->DataLength - (4 * index);
    uint32_t icmpChecksum = calculateChecksum(header->Data, numBytes);
    checksum += icmpChecksum;

    return checksum & 0xFFFF;
}

// Calculate the IGMP checksum for a packet header.
uint16_t calculateIGMPChecksum(struct PacketHeader *header, int index) {
    // Initialize the checksum with the IP addresses and port numbers
    uint32_t checksum = header->SourceIP + header->DestinationIP;
    checksum += (header->Type << 16) + header->Code;

    // Calculate the IGMP checksum for the packet data
    int numBytes = header->DataLength - (4 * index);
    uint32_t igmpChecksum = calculateChecksum(header->Data, numBytes);
    checksum += igmpChecksum;

    return checksum & 0xFFFF;
}

// Calculate the checksum for a block of data.
uint16_t calculateChecksum(void *data, int numBytes) {
    // Initialize the checksum with the number of bytes in the block
    uint32_t checksum = numBytes;

    // Sum the 16-bit words in the block
    for (int i = 0; i < numBytes - 1; i += 2) {
        checksum += ((uint8_t *)data)[i] + ((uint8_t *)data)[i + 1];
    }

    // If there are an odd number of bytes, add them to the checksum
    if (numBytes % 2 == 1) {
        checksum += ((uint8_t *)data)[numBytes - 1];
    }

    return checksum & 0xFFFF;
}']

