// Structure to store a linked list node
typedef struct nfapi_crc_indication_node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct nfapi_crc_indication_node* next;
} nfapi_crc_indication_node_t;

// Function to dynamically generate and populate a linked list of NFAPI_CRC_INDICATION_PDU_T structures
nfapi_crc_indication_node_t* generate_crc_indications(int num_elements) {
    // Initialize the head node and current node pointers to NULL
    nfapi_crc_indication_node_t* head = NULL;
    nfapi_crc_indication_node_t* curr = NULL;

    // Loop for the specified number of elements
    for (int i = 0; i < num_elements; ++i) {
        // Allocate memory for a new node
        curr = (nfapi_crc_indication_node_t*)malloc(sizeof(nfapi_crc_indication_node_t));
        if (curr == NULL) {
            printf("Memory allocation failed\n");
            break;
        }

        // Initialize the fields of the new node
        curr->pdu.rx_ue_information.tag = RX_UE_INFORMATION_TAG;
        curr->pdu.rx_ue_information.rnti = rand() % 1000;
        curr->pdu.crc_indication_rel8.tag = CRC_INDICATION_REL8_TAG;
        curr->pdu.crc_indication_rel8.crcfailure = (rand() % 2) ? true : false;

        // If this is the first node, set the head pointer to point to it
        if (head == NULL) {
            head = curr;
        } else {
            // Otherwise, set the next pointer of the current node to point to the new node
            curr->next = head;
        }
    }

    return head;
}

// Function to serialize a linked list of NFAPI_CRC_INDICATION_PDU_T structures to a file
void serialize_crc_indications(nfapi_crc_indication_node_t* head, char* filename) {
    // Open the output file for writing
    FILE* fp = fopen(filename, "wb");
    if (fp == NULL) {
        printf("Error opening output file: %s\n", strerror(errno));
        return;
    }

    // Loop through each node in the list
    nfapi_crc_indication_node_t* curr = head;
    while (curr != NULL) {
        // Serialize the current node to the output file
        fwrite(&curr->pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp);

        // Move on to the next node in the list
        curr = curr->next;
    }

    // Close the output file
    fclose(fp);
}

// Function to validate CRC flags against a predefined set of test cases
bool validate_crc_flags(nfapi_crc_indication_node_t* head, int num_test_cases) {
    // Loop through each node in the list and compare the CRC flag with the corresponding test case
    nfapi_crc_indication_node_t* curr = head;
    while (curr != NULL) {
        if ((curr->pdu.crc_indication_rel8.crcfailure && !strcmp(curr->pdu.rx_ue_information.rnti, "Test Case 1")) ||
            (!curr->pdu.crc_indication_rel8.crcfailure && !strcmp(curr->pdu.rx_ue_information.rnti, "Test Case 2"))) {
            // If a match is found, return false to indicate that the validation has failed
            printf("CRC flag validation failed\n");
            return false;
        }

        // Move on to the next node in the list
        curr = curr->next;
    }

    // If no matches are found, return true to indicate that the validation has passed
    printf("CRC flag validation passed\n");
    return true;
}

// Function to handle potential issues during memory allocation, serialization, and validation
void error_handling(int errno, char* filename) {
    switch (errno) {
        case ENOMEM:
            printf("Memory allocation failed\n");
            break;
        case EACCES:
            printf("Error opening output file: %s\n", strerror(errno));
            break;
        default:
            printf("Unknown error occurred\n");
    }
}

int main() {
    // Generate and populate a linked list of NFAPI_CRC_INDICATION_PDU_T structures
    nfapi_crc_indication_node_t* head = generate_crc_indications(10000);

    // Serialize the linked list to a file
    serialize_crc_indications(head, "output.dat");

    // Validate the CRC flags against a predefined set of test cases
    validate_crc_flags(head, 2);

    return 0;
}
