// Structure to represent each element in the linked list
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct node *next, *prev;
} node;

// Function to create a new node with the given RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
node* create_node(RX_UE_INFORMATION_TAG tag, uint16_t rnti, uint8_t crc_indication) {
    node *new_node = (node*)malloc(sizeof(node));
    if (new_node == NULL) {
        return NULL;
    }
    new_node->pdu.tag = tag;
    new_node->pdu.rnti = rnti;
    new_node->pdu.crc_indication = crc_indication;
    new_node->next = NULL;
    new_node->prev = NULL;
    return new_node;
}

// Function to insert a new node at the end of the linked list
void insert_end(node *head, node *new_node) {
    if (head == NULL) {
        head = new_node;
        return;
    }
    node *current = head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = new_node;
    new_node->prev = current;
}

// Function to delete a node from the linked list
void delete(node *head, int index) {
    if (index == 0) {
        head = head->next;
        return;
    }
    node *current = head;
    for (int i = 0; i < index - 1; i++) {
        current = current->next;
    }
    current->prev->next = current->next;
    if (current->next != NULL) {
        current->next->prev = current->prev;
    }
}

// Function to search for a specific node in the linked list
node* search(node *head, RX_UE_INFORMATION_TAG tag, uint16_t rnti, uint8_t crc_indication) {
    node *current = head;
    while (current != NULL) {
        if (current->pdu.tag == tag && current->pdu.rnti == rnti && current->pdu.crc_indication == crc_indication) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

// Function to serialize the linked list to a file
void serialize(node *head, FILE *fptr) {
    node *current = head;
    while (current != NULL) {
        fprintf(fptr, "%d %d %d\n", current->pdu.tag, current->pdu.rnti, current->pdu.crc_indication);
        current = current->next;
    }
}

// Function to deserialize the linked list from a file
node* deserialize(FILE *fptr) {
    node *head = NULL;
    while (1) {
        int tag, rnti, crc_indication;
        if (fscanf(fptr, "%d %d %d\n", &tag, &rnti, &crc_indication) == EOF) {
            break;
        }
        node *new_node = create_node((RX_UE_INFORMATION_TAG)tag, rnti, crc_indication);
        if (head == NULL) {
            head = new_node;
        } else {
            insert_end(head, new_node);
        }
    }
    return head;
}
